import React from 'react';
import { FileWarning, FileCode, FileText, File as FileIcon } from 'lucide-react';

export interface FileStat {
    name: string;
    size: number;
}

interface TopFilesProps {
    files: FileStat[];
}

const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

const getFileIcon = (name: string) => {
    const ext = name.split('.').pop()?.toLowerCase();
    if (['rs', 'js', 'ts', 'tsx', 'cpp', 'py'].includes(ext || '')) return FileCode;
    if (['txt', 'md', 'doc', 'pdf'].includes(ext || '')) return FileText;
    return FileIcon;
};

const TopFiles: React.FC<TopFilesProps> = ({ files }) => {
    const maxSize = (files && files.length > 0) ? Math.max(...files.map(f => f.size)) : 0;

    return (
        <div className="cad-card h-full p-6">
            <div className="mb-6 flex items-center justify-between">
                <h3 className="text-sm font-semibold uppercase tracking-wider text-cad-text-secondary">Top Largest Files</h3>
                <FileWarning size={16} className="text-amber-400/70" />
            </div>

            <div className="space-y-5">
                {files.length === 0 ? (
                    <div className="py-10 text-center text-cad-text-muted/60 italic text-sm">No data available</div>
                ) : (
                    files.map((file, index) => {
                        const Icon = getFileIcon(file.name);
                        const percentage = maxSize > 0 ? (file.size / maxSize) * 100 : 0;

                        return (
                            <div key={index} className="group flex flex-col gap-2">
                                <div className="flex items-center justify-between gap-3">
                                    <div className="flex min-w-0 items-center gap-3">
                                        <div className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-md border border-cad-border bg-cad-bg text-cad-text-muted transition-colors group-hover:text-cad-text-primary">
                                            <Icon size={16} />
                                        </div>
                                        <span className="truncate text-sm font-medium text-cad-text-primary transition-colors group-hover:text-white">
                                            {file.name}
                                        </span>
                                    </div>
                                    <span className="font-mono text-xs tabular-nums text-cad-text-muted">
                                        {formatSize(file.size)}
                                    </span>
                                </div>
                                <div className="h-1.5 w-full overflow-hidden rounded-full bg-cad-bg">
                                    <div
                                        className="h-full rounded-full bg-gradient-to-r from-cad-accent/45 to-cad-active transition-all duration-1000 ease-out"
                                        style={{ width: `${percentage}%` }}
                                    />
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
};

export default TopFiles;

import { useRef, useEffect, useState } from "react";
import { MapLayer } from "@DESIGN/features/map/MapLayer";
import { CoordinatePanel } from "@DESIGN/components/core/CoordinatePanel";
import { useDesignSync } from "@IMPLEMENT/stores/useDesignSync";
import { useCanvasInteraction } from "@IMPLEMENT/hooks/useCanvasInteraction";
import { MapSearchBar } from "@DESIGN/features/map/MapLayerComponents/MapSearchBar";
import { CADNavigation } from "@DESIGN/components/core/CADNavigation";
import { useDrawingInteraction } from "@DESIGN/hooks/useDrawingInteraction";

export function CADCanvas() {
  const containerRef = useRef<HTMLDivElement>(null);
  const triggerZoomExtend = useDesignSync(s => s.triggerZoomExtend);
  const [isMeasureActive, setIsMeasureActive] = useState(false);

  useEffect(() => {
    // Trigger auto-zoom on mount (when entering Design tab)
    triggerZoomExtend();
  }, [triggerZoomExtend]);

  useCanvasInteraction();
  const { handleLocationChange, finalizePolyline, finishDrawingSession } = useDrawingInteraction();

  const handleLocateMe = () => {
    if (!navigator.geolocation) return;
    navigator.geolocation.getCurrentPosition(
      (pos) => console.log("GPS Location:", pos.coords.latitude, pos.coords.longitude),
      (err) => console.error("Geolocation error:", err.message),
      { enableHighAccuracy: true, timeout: 5000 }
    );
  };

  return (
    <div ref={containerRef} className="relative flex-1 overflow-hidden group">
      <div className="absolute inset-0 z-0 pointer-events-auto">
        <MapLayer
          center={[21.0285, 105.8542]}
          zoom={13}
          onLocationChange={handleLocationChange}
          onFinishDrawing={finalizePolyline}
          onFinishDrawingSession={finishDrawingSession}
          isMeasureActive={isMeasureActive}
          onMeasureDeactivate={() => setIsMeasureActive(false)}
        />
      </div>

      <MapSearchBar />

      <CADNavigation
        onLocateMe={handleLocateMe}
        onZoomIn={() => {/* Leaflet handles zoom via container if needed, or we use map instance */ }}
        onZoomOut={() => { }}
        onZoomExtend={triggerZoomExtend}
        isMeasureActive={isMeasureActive}
        onToggleMeasure={() => setIsMeasureActive((active) => !active)}
      />

      <CoordinatePanel />
    </div>
  );
}

