import React from "react";
import { Type, RefreshCw } from "lucide-react";
import { cn } from "@TOOL/utils/cn";

interface ExplorerFilterBarProps {
    filterType: string | null;
    setFilterType: (type: string | null) => void;
    sortField: 'name' | 'stt';
    setSortField: (field: 'name' | 'stt') => void;
    reverseOrder: boolean;
    setReverseOrder: (reverse: boolean) => void;
}

export const ExplorerFilterBar = React.memo(({
    filterType,
    setFilterType,
    sortField,
    setSortField,
    reverseOrder,
    setReverseOrder
}: ExplorerFilterBarProps) => {
    return (
        <div className="flex items-center gap-1">
            <select
                value={filterType || ""}
                onChange={(e) => setFilterType(e.target.value || null)}
                className="flex-1 bg-cad-surface border border-cad-border text-[8px] font-mono py-0.5 px-1 outline-none text-cad-text-muted focus:border-cad-accent rounded-sm"
            >
                <option value="">TẤT CẢ LOẠI</option>
                <option value="INTERSECTION">NÚT GIAO</option>
                <option value="POLYLINE">TUYẾN</option>
                <option value="CCTV">CAMERA CCTV</option>
                <option value="PTZ">CAMERA PTZ</option>
                <option value="SPEED">CAMERA SPEED</option>
                <option value="LPR">CAMERA LPR</option>
                <option value="FOLDER">THƯ MỤC</option>
            </select>

            <div className="flex items-center gap-0.5 ml-auto">
                <button
                    onClick={() => setSortField(sortField === 'name' ? 'stt' : 'name')}
                    className={cn(
                        "p-1 border border-cad-border rounded-sm transition-all flex items-center gap-1 text-[8px] font-mono h-6",
                        sortField === 'stt' ? "bg-cad-accent text-black border-cad-accent" : "hover:border-cad-accent text-cad-text-muted"
                    )}
                    title="Sắp xếp theo Tên/STT"
                >
                    <Type size={10} />
                    {sortField === 'stt' ? "STT" : "NAME"}
                </button>

                <button
                    onClick={() => setReverseOrder(!reverseOrder)}
                    className={cn(
                        "p-1 border border-cad-border rounded-sm transition-all flex items-center gap-1 text-[8px] font-mono h-6",
                        reverseOrder ? "bg-cad-accent text-black border-cad-accent" : "hover:border-cad-accent text-cad-text-muted"
                    )}
                    title="Đảo ngược thứ tự"
                >
                    <RefreshCw size={10} className={cn(reverseOrder && "rotate-180")} />
                    {reverseOrder ? "DESC" : "ASC"}
                </button>
            </div>
        </div>
    );
});

import { ThemeModal } from "@DESIGN/components/ui/ThemeModal";
import { MappingDialog } from "@DESIGN/components/core/CADPanels/MappingDialog";
import { DeleteConfirmationModal } from "@DESIGN/components/ui/DeleteConfirmationModal";
import { ImportMapping } from "@IMPLEMENT/services/importService";

interface MappingDialogData {
  headers: string[];
  filename: string;
  groupId: string;
  filePath: string;
}

interface ExplorerModalsProps {
    themeGroupId: string | null;
    setThemeGroupId: (id: string | null) => void;
    groupName?: string;
    themeTargetFeatureIds?: string[];
    mappingData: MappingDialogData | null;
    setMappingData: (data: MappingDialogData | null) => void;
    handleMappingConfirm: (mapping: ImportMapping) => Promise<void>;
    deleteModal: {
        isOpen: boolean;
        type: 'region' | 'group' | 'layer' | 'feature' | 'featureChildren' | null;
        id: string;
        name: string;
    };
    setDeleteModal: (updater: (prev: ExplorerModalsProps['deleteModal']) => ExplorerModalsProps['deleteModal']) => void;
    confirmDelete: () => Promise<void>;
}

export function ExplorerModals({
    themeGroupId,
    setThemeGroupId,
    groupName,
    themeTargetFeatureIds,
    mappingData,
    setMappingData,
    handleMappingConfirm,
    deleteModal,
    setDeleteModal,
    confirmDelete
}: ExplorerModalsProps) {
    return (
        <>
            {themeGroupId && (
                <ThemeModal
                    groupId={themeGroupId}
                    groupName={groupName || 'Group'}
                    onClose={() => setThemeGroupId(null)}
                    targetFeatureIds={themeTargetFeatureIds}
                />
            )}

            {mappingData && (
                <MappingDialog
                    headers={mappingData.headers}
                    filename={mappingData.filename}
                    onConfirm={handleMappingConfirm}
                    onClose={() => setMappingData(null)}
                />
            )}

            <DeleteConfirmationModal
                isOpen={deleteModal.isOpen}
                onClose={() => setDeleteModal((prev) => ({ ...prev, isOpen: false }))}
                onConfirm={confirmDelete}
                title={`Xóa ${deleteModal.type === 'feature' ? 'Đối tượng' : deleteModal.type === 'region' ? 'Dự án' : deleteModal.type === 'featureChildren' ? 'Đối tượng trong nút giao' : 'Nhóm'}`}
                message={`Bạn có chắc chắn muốn xóa ${deleteModal.type === 'feature' ? 'đối tượng' : deleteModal.type === 'featureChildren' ? 'toàn bộ đối tượng trong nút giao' : 'thư mục'} "${deleteModal.name}"${deleteModal.type !== 'feature' && deleteModal.type !== 'featureChildren' ? ' và toàn bộ nội dung bên trong' : ''}? Hành động này không thể hoàn tác.`}
                itemName={deleteModal.name}
            />
        </>
    );
}

import { useMemo, useCallback } from "react";
import { getFeatureDisplayInfo, getParsedMetadata, calculateFeatureNumbers, isMatchSearch, isNetworkLinkFeature } from "@TOOL/utils/featureUtils";
import type { RegionState, LayerState, FeatureGroupState, FeatureState } from "@CONTRACT/types";

type TreeNodeData = RegionState | FeatureGroupState | FeatureState;

const getGroupKind = (group: FeatureGroupState): string =>
    group.group_type || group.type || 'default';

const hasStringId = (value: unknown): value is string =>
    typeof value === 'string' && value.length > 0;

export interface FlatTreeItem {
    type: 'region' | 'group' | 'feature' | 'intersection-children-group';
    id: string;
    level: number;
    levelOffset: number;
    data: TreeNodeData | { id: string; name: string; parentFeatureId: string };
}

interface UseFlattenedTreeProps {
    regionsMap: Record<string, RegionState>;
    layersMap: Record<string, LayerState>;
    groupsMap: Record<string, FeatureGroupState>;
    featuresMap: Record<string, FeatureState>;
    expanded: Record<string, boolean>;
    treeSearchQuery: string;
    filterType: string | null;
    reverseOrder: boolean;
    sortField: 'name' | 'stt';
}

export function useFlattenedTree({
    regionsMap,
    layersMap,
    groupsMap,
    featuresMap,
    expanded,
    treeSearchQuery,
    filterType,
    reverseOrder,
    sortField
}: UseFlattenedTreeProps) {
    const designs = useMemo(() => Object.values(featuresMap), [featuresMap]);
    const featureNumbers = useMemo(() => calculateFeatureNumbers(designs, featuresMap), [designs, featuresMap]);

    const matchesSearch = useCallback((item: TreeNodeData) => {
        if (!treeSearchQuery || !treeSearchQuery.trim()) return true;
        return isMatchSearch(item, treeSearchQuery, featureNumbers);
    }, [treeSearchQuery, featureNumbers]);

    const {
        regionGroupsMap,
        groupFeaturesMap,
        regionIndependentFeaturesMap,
        featureChildrenMap,
        groupParentMap,
        allGroupsMap
    } = useMemo(() => {
        const lRegionMap: Record<string, string> = {};
        const rGroupsMap: Record<string, FeatureGroupState[]> = {};
        const gFeaturesMap: Record<string, FeatureState[]> = {};
        const rIndependentFeaturesMap: Record<string, FeatureState[]> = {};
        const fChildrenMap: Record<string, FeatureState[]> = {};
        const gParentMap: Record<string, FeatureGroupState[]> = {};

        const layers = Object.values(layersMap);
        const groups = Object.values(groupsMap);
        const features = Object.values(featuresMap).filter(feature => !isNetworkLinkFeature(feature));

        layers.forEach(l => {
            lRegionMap[l.id] = l.region_id;
        });

        const compareItems = (a: FeatureGroupState | FeatureState, b: FeatureGroupState | FeatureState) => {
            const aStt = featureNumbers[a.id] || getParsedMetadata(a).display_order;
            const bStt = featureNumbers[b.id] || getParsedMetadata(b).display_order;

            if (sortField === 'stt' && (aStt !== undefined || bStt !== undefined)) {
                if (aStt === undefined) return 1;
                if (bStt === undefined) return -1;
                const aStr = (typeof aStt === 'string' || typeof aStt === 'number') ? String(aStt) : '';
                const bStr = (typeof bStt === 'string' || typeof bStt === 'number') ? String(bStt) : '';
                return aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });
            }

            const nameA = a.name || '';
            const nameB = b.name || '';
            if (nameA !== nameB) {
                return nameA.localeCompare(nameB, undefined, { numeric: true, sensitivity: 'base' });
            }
            return a.id.localeCompare(b.id);
        };

        const sortedGroups = [...groups].sort(compareItems);
        sortedGroups.forEach(g => {
            const regionId = lRegionMap[g.layer_id];
            if (regionId && !g.parent_id) {
                if (!rGroupsMap[regionId]) rGroupsMap[regionId] = [];
                rGroupsMap[regionId].push(g);
            }

            const parentId = g.parent_id || 'root';
            if (!gParentMap[parentId]) gParentMap[parentId] = [];
            gParentMap[parentId].push(g);
        });

        const allGroupsMap = { ...groupsMap };

        const sortedFeatures = [...features].sort(compareItems);
        sortedFeatures.forEach(f => {
            const meta = getParsedMetadata(f);
            const parentFeatureId = hasStringId(meta.parent_feature_id) ? meta.parent_feature_id : null;

            if (parentFeatureId) {
                if (!fChildrenMap[parentFeatureId]) fChildrenMap[parentFeatureId] = [];
                fChildrenMap[parentFeatureId].push(f);
            } else if (f.group_id && groupsMap[f.group_id]) {
                if (!gFeaturesMap[f.group_id]) gFeaturesMap[f.group_id] = [];
                gFeaturesMap[f.group_id].push(f);
            } else {
                const regionId = lRegionMap[f.layer_id];
                if (regionId) {
                    // Restore: Automatic grouping for Intersections (Nút giao)
                    const displayInfo = getFeatureDisplayInfo(f);
                    if (displayInfo.isIntersection) {
                        const vGroupId = `virtual-intersection-${regionId}`;
                        if (!gFeaturesMap[vGroupId]) {
                            gFeaturesMap[vGroupId] = [];
                            // Ensure the virtual group is added to the region's group list if not already there
                            if (!rGroupsMap[regionId]) rGroupsMap[regionId] = [];
                            // Create a virtual group object
                            const virtualGroup = {
                                id: vGroupId,
                                name: "Danh sách Nút giao",
                                group_type: 'INTERSECTION',
                                layer_id: f.layer_id,
                                is_visible: true,
                                is_virtual: true,
                                metadata: ''
                            } satisfies FeatureGroupState;
                            allGroupsMap[vGroupId] = virtualGroup; // Add to augmented map
                            if (!rGroupsMap[regionId].some(g => g.id === vGroupId)) {
                                rGroupsMap[regionId].push(virtualGroup);
                            }
                        }
                        gFeaturesMap[vGroupId].push(f);
                    } else {
                        if (!rIndependentFeaturesMap[regionId]) rIndependentFeaturesMap[regionId] = [];
                        rIndependentFeaturesMap[regionId].push(f);
                    }
                }
            }
        });

        return {
            regionGroupsMap: rGroupsMap,
            groupFeaturesMap: gFeaturesMap,
            regionIndependentFeaturesMap: rIndependentFeaturesMap,
            featureChildrenMap: fChildrenMap,
            groupParentMap: gParentMap,
            allGroupsMap: allGroupsMap
        };
    }, [layersMap, groupsMap, featuresMap, sortField, featureNumbers]);

    const groupVisibilityMap = useMemo(() => {
        const map: Record<string, boolean> = {};
        if (!treeSearchQuery?.trim() && !filterType) return null;

        const isDescendantOfIntersection = (f: FeatureState): boolean => {
            const meta = getParsedMetadata(f);
            const parentId = hasStringId(meta.parent_feature_id) ? meta.parent_feature_id : null;
            if (!parentId) return false;
            const parent = featuresMap[parentId];
            if (!parent) return false;
            if (getFeatureDisplayInfo(parent).isIntersection) return true;
            return isDescendantOfIntersection(parent);
        };

        const matchesFilter = (f: FeatureState): boolean => {
            if (!filterType) return true;

            if (filterType === 'INTERSECTION') {
                return getFeatureDisplayInfo(f).isIntersection || isDescendantOfIntersection(f);
            }

            const ownInfo = getFeatureDisplayInfo(f);
            if (filterType === 'POLYLINE' && ownInfo.isLine) return true;
            if (['CCTV', 'PTZ', 'SPEED', 'LPR'].includes(filterType) && ownInfo.label === filterType) return true;

            const group = f.group_id ? allGroupsMap[f.group_id] || (f.group_id.startsWith('virtual-') ? allGroupsMap[f.group_id] : null) : null;
            if (group) {
                const gType = getGroupKind(group);
                if (gType === filterType) return true;
                const info = getFeatureDisplayInfo(f, gType, group.name);
                if (filterType === 'POLYLINE' && info.isLine) return true;
                if (['CCTV', 'PTZ', 'SPEED', 'LPR'].includes(filterType) && info.label === filterType) return true;
            }
            return false;
        };

        const matchesFilterOrHasMatchingDescendant = (f: FeatureState): boolean => {
            if (matchesFilter(f)) return true;
            const children = featureChildrenMap[f.id] || [];
            return children.some(child => matchesFilterOrHasMatchingDescendant(child));
        };

        const matchesSearchOrHasMatchingDescendant = (f: FeatureState): boolean => {
            if (matchesSearch(f)) return true;
            const children = featureChildrenMap[f.id] || [];
            return children.some(child => matchesSearchOrHasMatchingDescendant(child));
        };

        const checkGroup = (groupId: string): boolean => {
            if (map[groupId] !== undefined) return map[groupId];

            const group = allGroupsMap[groupId];
            if (!group) return false;

            const selfMatches = matchesSearch(group) && (
                !filterType ||
                (filterType === 'FOLDER' && getGroupKind(group) === 'default') ||
                getGroupKind(group) === filterType
            );

            const gFeatures = groupFeaturesMap[groupId];
            const featureMatches = gFeatures?.some(f => {
                if (!matchesSearchOrHasMatchingDescendant(f)) return false;
                if (!filterType) return true;
                if (filterType === 'FOLDER') return false;
                return matchesFilterOrHasMatchingDescendant(f);
            });

            const subGroups = groupParentMap[groupId];
            const subgroupMatches = subGroups?.some(sg => checkGroup(sg.id));

            const isVisible = !!(selfMatches || featureMatches || subgroupMatches);
            map[groupId] = isVisible;
            return isVisible;
        };

        Object.keys(allGroupsMap).forEach(checkGroup);
        return map;
    }, [allGroupsMap, groupFeaturesMap, groupParentMap, treeSearchQuery, filterType, matchesSearch, featureChildrenMap, featuresMap]);

    const filteredRegions = useMemo(() => {
        let list = Object.values(regionsMap);
        if (treeSearchQuery || filterType) {
            const layerRegionMap: Record<string, string> = {};
            Object.values(layersMap).forEach(layer => {
                layerRegionMap[layer.id] = layer.region_id;
            });

            list = list.filter(r => {
                if (matchesSearch(r) && !filterType) return true;
                const rGroups = regionGroupsMap[r.id] || [];
                if (!groupVisibilityMap) return true;
                const hasMatchingGroup = rGroups.some(g => groupVisibilityMap[g.id]);
                if (hasMatchingGroup) return true;

                return Object.values(featuresMap).filter(feature => !isNetworkLinkFeature(feature)).some(f => {
                    if (layerRegionMap[f.layer_id] !== r.id) return false;
                    if (!matchesSearch(f)) return false;
                    if (!filterType) return true;
                    const info = getFeatureDisplayInfo(f);
                    return (filterType === 'INTERSECTION' && info.isIntersection) ||
                        (filterType === 'POLYLINE' && info.isLine) ||
                        info.label === filterType;
                });
            });
        }
        if (reverseOrder) list = [...list].reverse();
        return list;
    }, [regionsMap, layersMap, featuresMap, treeSearchQuery, filterType, reverseOrder, regionGroupsMap, groupVisibilityMap, matchesSearch]);

    const flattenedItems = useMemo(() => {
        const result: FlatTreeItem[] = [];
        const visited = new Set<string>();

        const isDescendantOfIntersection = (f: FeatureState): boolean => {
            const meta = getParsedMetadata(f);
            const parentId = hasStringId(meta.parent_feature_id) ? meta.parent_feature_id : null;
            if (!parentId) return false;
            const parent = featuresMap[parentId];
            if (!parent) return false;
            if (getFeatureDisplayInfo(parent).isIntersection) return true;
            return isDescendantOfIntersection(parent);
        };

        const matchesFilter = (f: FeatureState): boolean => {
            if (!filterType) return true;

            if (filterType === 'INTERSECTION') {
                if (getFeatureDisplayInfo(f).isIntersection || isDescendantOfIntersection(f)) {
                    return true;
                }
            }

            const ownInfo = getFeatureDisplayInfo(f);
            if (filterType === 'POLYLINE' && ownInfo.isLine) return true;
            if (['CCTV', 'PTZ', 'SPEED', 'LPR'].includes(filterType) && ownInfo.label === filterType) return true;

            const group = f.group_id ? allGroupsMap[f.group_id] || (f.group_id.startsWith('virtual-') ? allGroupsMap[f.group_id] : null) : null;
            if (group) {
                const gType = getGroupKind(group);
                if (gType === filterType) return true;
                const info = getFeatureDisplayInfo(f, gType, group.name);
                if (filterType === 'POLYLINE' && info.isLine) return true;
                if (['CCTV', 'PTZ', 'SPEED', 'LPR'].includes(filterType) && info.label === filterType) return true;
            }
            return false;
        };

        const matchesFilterOrHasMatchingDescendant = (f: FeatureState): boolean => {
            if (matchesFilter(f)) return true;
            const children = featureChildrenMap[f.id] || [];
            return children.some(child => matchesFilterOrHasMatchingDescendant(child));
        };

        const matchesSearchOrHasMatchingDescendant = (f: FeatureState): boolean => {
            if (matchesSearch(f)) return true;
            const children = featureChildrenMap[f.id] || [];
            return children.some(child => matchesSearchOrHasMatchingDescendant(child));
        };

        const collectFeatures = (featureList: FeatureState[], level: number, levelOffset: number) => {
            let currentFeats = featureList;
            if (reverseOrder) currentFeats = [...currentFeats].reverse();

            currentFeats.forEach(f => {
                const show = matchesSearchOrHasMatchingDescendant(f) && matchesFilterOrHasMatchingDescendant(f);
                if (!show) return;

                result.push({ type: 'feature', id: f.id, level, levelOffset, data: f });

                const children = featureChildrenMap[f.id] || [];
                const isSearchOrFilterActive = !!(treeSearchQuery && treeSearchQuery.trim()) || !!filterType;

                if (children.length > 0) {
                    const hasMatchingChild = children.some(child => 
                        matchesSearchOrHasMatchingDescendant(child) && 
                        matchesFilterOrHasMatchingDescendant(child)
                    );
                    const isExpanded = expanded[`feature-${f.id}`] || (isSearchOrFilterActive && hasMatchingChild);
                    if (isExpanded) {
                        collectFeatures(children, level, levelOffset + 1);
                    }
                }
            });
        };

        const collectGroups = (parentId: string | null, level: number, regionId?: string) => {
            if (level > 20) return;
            let currentGroups: FeatureGroupState[] = [];
            if (!parentId && regionId) {
                currentGroups = (regionGroupsMap[regionId] || []);
            } else {
                currentGroups = (groupParentMap[parentId || 'root'] || []);
            }

            currentGroups.forEach(group => {
                if (visited.has(group.id)) return;
                visited.add(group.id);

                const groupFeatures = (groupFeaturesMap[group.id] || []);
                const hasVisibleContent = groupFeatures.length > 0 || (groupParentMap[group.id] || []).length > 0;

                const searchMatch = !treeSearchQuery || matchesSearch(group);
                if (!searchMatch && !hasVisibleContent) return;

                result.push({ type: 'group', id: group.id, level, levelOffset: 0, data: group });

                const shouldCollectGroup = expanded[group.id] || (!!groupVisibilityMap && groupVisibilityMap[group.id]);
                if (shouldCollectGroup) {
                    collectGroups(group.id, level + 1);
                    collectFeatures(groupFeatures, level, 0);
                }
            });
        };

        filteredRegions.forEach(region => {
            const searchMatch = !treeSearchQuery || matchesSearch(region);
            const regionGroups = regionGroupsMap[region.id] || [];
            if (!searchMatch && regionGroups.length === 0) return;

            result.push({ type: 'region', id: region.id, level: 0, levelOffset: 0, data: region });

            const shouldCollectRegion = expanded[region.id] || !!treeSearchQuery || !!filterType;
            if (shouldCollectRegion) {
                const independentFeatures = (regionIndependentFeaturesMap[region.id] || []);
                collectFeatures(independentFeatures, 1, 0);
                collectGroups(null, 1, region.id);
            }
        });

        return result;
    }, [filteredRegions, expanded, treeSearchQuery, filterType, reverseOrder, allGroupsMap, featureChildrenMap, groupParentMap, regionGroupsMap, regionIndependentFeaturesMap, groupFeaturesMap, matchesSearch, featuresMap, groupVisibilityMap]);

    return {
        flattenedItems,
        featureNumbers,
        filteredRegions,
        featureChildrenMap
    };
}

import { useState, useRef, useEffect, useCallback } from "react";
import { DesignEventType } from "@IMPLEMENT/stores/useDesignSync";
import { getFeatureDisplayInfo, getNextFeatureDisplayOrder, getParsedMetadata, syncDisplayOrderAliases } from "@TOOL/utils/featureUtils";
import type { FeatureGroupState, FeatureState } from "@CONTRACT/types";

interface UseVirtualDragProps {
    featuresRef: React.MutableRefObject<Record<string, FeatureState>>;
    groupsRef: React.MutableRefObject<Record<string, FeatureGroupState>>;
    regionsRef: React.MutableRefObject<Record<string, { id: string; region_id: string; layer_id?: string; layers?: Array<{ id: string }> }>>;
    dispatchEvents: (events: DesignEventType[]) => Promise<void>;
    selectionSet: Set<string>;
    clearSelection: () => void;
}

const buildMovedFeatureMetadata = (
    feature: FeatureState,
    featuresMap: Record<string, FeatureState>,
    groupId: string | null,
    parentFeatureId?: string | null
) => {
    const metadata = { ...getParsedMetadata(feature) };
    const displayOrder = getNextFeatureDisplayOrder(featuresMap, groupId, parentFeatureId);

    if (parentFeatureId) {
        metadata.parent_feature_id = parentFeatureId;
    } else {
        delete metadata.parent_feature_id;
    }

    return syncDisplayOrderAliases(metadata, displayOrder, feature.properties);
};

const logDragDrop = (step: string, details?: Record<string, unknown>) => {
    console.debug(`[ExplorerDragDrop] ${step}`, details || {});
};

const getDragTargetInfo = (
    x: number,
    y: number,
    fallbackTarget?: HTMLElement | null
) => {
    const elements = document.elementsFromPoint(x, y);
    const validFallback = fallbackTarget?.isConnected &&
        fallbackTarget.hasAttribute('data-drag-id') &&
        fallbackTarget.hasAttribute('data-drag-type')
        ? fallbackTarget
        : null;
    const target = elements
        .map(el => el.closest('[data-drag-id][data-drag-type]') as HTMLElement | null)
        .find(Boolean) || validFallback || null;
    const targetId = target?.getAttribute('data-drag-id') || null;
    const targetType = target?.getAttribute('data-drag-type') as 'region' | 'group' | 'feature' | null;

    return {
        elementsCount: elements.length,
        fallbackUsed: Boolean(validFallback && target === validFallback),
        target,
        targetId,
        targetType
    };
};

export function useVirtualDrag({
    featuresRef,
    groupsRef,
    regionsRef,
    dispatchEvents,
    selectionSet,
    clearSelection
}: UseVirtualDragProps) {
    const [isVirtualDragging, setIsVirtualDragging] = useState(false);
    const virtualDragRef = useRef<{
        type: string;
        ids: string[];
        startX: number;
        startY: number;
        lastTarget: HTMLElement | null;
    } | null>(null);

    const draggingIdsRef = useRef<string[]>([]);
    useEffect(() => {
        draggingIdsRef.current = virtualDragRef.current?.ids || [];
    }, [isVirtualDragging]);

    const handleExecuteMove = useCallback((currentDrag: { type: string; ids: string[] }, targetType: 'region' | 'group' | 'feature', targetId: string) => {
        logDragDrop("execute:start", { dragType: currentDrag?.type, ids: currentDrag?.ids, targetType, targetId });
        if (!currentDrag) {
            logDragDrop("execute:skip:no-current-drag");
            return;
        }
        if (currentDrag.ids.includes(targetId)) {
            logDragDrop("execute:skip:self-target", { targetId, ids: currentDrag.ids });
            return;
        }

        const fMap = featuresRef.current;
        const nextFeaturesMap = { ...fMap };
        const gMap = groupsRef.current;
        const rMap = regionsRef.current;

        const events: DesignEventType[] = [];
        const timestamp = Date.now();

        currentDrag.ids.forEach((id, index) => {
            const feature = fMap[id];
            const group = gMap[id];
            if (!feature && !group) {
                logDragDrop("execute:skip:missing-source", { id, dragType: currentDrag.type });
                return;
            }

            if (currentDrag.type === 'feature' && feature) {
                if (targetType === 'region') {
                    const region = rMap[targetId];
                    const targetLayerId = region?.layers?.[0]?.id || region?.layer_id;
                    logDragDrop("execute:feature-to-region", { id, targetId, targetLayerId });
                    if (targetLayerId) {
                        const nextMetadata = buildMovedFeatureMetadata(feature, nextFeaturesMap, null, null);
                        events.push({
                            type: 'FeatureUpdated',
                            payload: {
                                id,
                                layer_id: targetLayerId,
                                group_id: "",
                                metadata: JSON.stringify(nextMetadata)
                            }
                        });
                        nextFeaturesMap[id] = {
                            ...feature,
                            layer_id: targetLayerId,
                            group_id: "",
                            metadata: nextMetadata
                        };
                    }
                } else if (targetType === 'group') {
                    const targetGroup = gMap[targetId];
                    logDragDrop("execute:feature-to-group", { id, targetId, targetLayerId: targetGroup?.layer_id });
                    if (targetGroup) {
                        const nextMetadata = buildMovedFeatureMetadata(feature, nextFeaturesMap, targetId, null);
                        events.push({
                            type: 'FeatureUpdated',
                            payload: {
                                id,
                                layer_id: targetGroup.layer_id,
                                group_id: targetId,
                                metadata: JSON.stringify(nextMetadata)
                            }
                        });
                        nextFeaturesMap[id] = {
                            ...feature,
                            layer_id: targetGroup.layer_id,
                            group_id: targetId,
                            metadata: nextMetadata
                        };
                    }
                } else if (targetType === 'feature' && id !== targetId) {
                    const targetFeature = fMap[targetId];
                    logDragDrop("execute:feature-to-feature", { id, targetId, targetExists: Boolean(targetFeature) });
                    if (targetFeature) {
                        const targetMeta = getParsedMetadata(targetFeature);
                        const parentFeatureId = getFeatureDisplayInfo(targetFeature).isIntersection
                            ? targetFeature.id
                            : (typeof targetMeta.parent_feature_id === 'string' || typeof targetMeta.parent_feature_id === 'number') ? String(targetMeta.parent_feature_id) : null;
                        if (parentFeatureId && currentDrag.ids.includes(parentFeatureId)) {
                            logDragDrop("execute:skip:would-create-cycle", { id, parentFeatureId, ids: currentDrag.ids });
                            return;
                        }
                        const nextMetadata = buildMovedFeatureMetadata(
                            feature,
                            nextFeaturesMap,
                            targetFeature.group_id,
                            parentFeatureId
                        );
                        events.push({
                            type: 'FeatureUpdated',
                            payload: {
                                id,
                                layer_id: targetFeature.layer_id,
                                group_id: targetFeature.group_id,
                                metadata: JSON.stringify(nextMetadata)
                            }
                        });
                        nextFeaturesMap[id] = {
                            ...feature,
                            layer_id: targetFeature.layer_id,
                            group_id: targetFeature.group_id,
                            metadata: nextMetadata
                        };
                    }
                }
            } else if (currentDrag.type === 'group' && group && id !== targetId) {
                const currentMeta = getParsedMetadata(group);
                const newOrder = timestamp + (index * 0.001);

                if (targetType === 'region') {
                    const region = rMap[targetId];
                    const targetLayerId = region?.layers?.[0]?.id || region?.layer_id;
                    logDragDrop("execute:group-to-region", { id, targetId, targetLayerId });
                    if (targetLayerId) {
                        events.push({
                            type: 'FeatureGroupUpdated',
                            payload: {
                                id,
                                name: group.name,
                                is_visible: group.is_visible,
                                metadata: JSON.stringify({ ...currentMeta, parent_id: null, layer_id: targetLayerId, display_order: newOrder })
                            }
                        });
                    }
                } else if (targetType === 'group') {
                    const targetGroup = gMap[targetId];
                    logDragDrop("execute:group-to-group", { id, targetId, targetLayerId: targetGroup?.layer_id });
                    if (targetGroup) {
                        events.push({
                            type: 'FeatureGroupUpdated',
                            payload: {
                                id,
                                name: group.name,
                                is_visible: group.is_visible,
                                metadata: JSON.stringify({ ...currentMeta, parent_id: targetId, layer_id: targetGroup.layer_id, display_order: newOrder })
                            }
                        });
                    }
                }
            }
        });

        if (events.length > 0) {
            logDragDrop("execute:dispatch", { eventCount: events.length, events });
            dispatchEvents(events);
            clearSelection();
        } else {
            logDragDrop("execute:skip:no-events", { dragType: currentDrag.type, ids: currentDrag.ids, targetType, targetId });
        }
    }, [featuresRef, groupsRef, regionsRef, dispatchEvents, clearSelection]);

    useEffect(() => {
        const handleGlobalMouseMove = (e: MouseEvent) => {
            const ctx = virtualDragRef.current;
            if (!ctx) return;

            if (!isVirtualDragging) {
                const dist = Math.sqrt(Math.pow(e.clientX - ctx.startX, 2) + Math.pow(e.clientY - ctx.startY, 2));
                if (dist > 5) {
                    logDragDrop("threshold:passed", { dragType: ctx.type, ids: ctx.ids, startX: ctx.startX, startY: ctx.startY, x: e.clientX, y: e.clientY, dist });
                    const resolved = getDragTargetInfo(e.clientX, e.clientY);
                    logDragDrop("target-resolve:threshold", {
                        elementsCount: resolved.elementsCount,
                        targetId: resolved.targetId,
                        targetType: resolved.targetType,
                        fallbackUsed: resolved.fallbackUsed,
                        draggingIds: draggingIdsRef.current
                    });
                    if (resolved.target && resolved.targetId && !draggingIdsRef.current.includes(resolved.targetId)) {
                        resolved.target.style.outline = "2px solid #10B981";
                        resolved.target.style.background = "rgba(16, 185, 129, 0.1)";
                        ctx.lastTarget = resolved.target;
                    }
                    setIsVirtualDragging(true);
                    document.body.style.cursor = "grabbing";
                    document.body.style.userSelect = "none";
                }
                return;
            }

            const resolved = getDragTargetInfo(e.clientX, e.clientY);
            const target = resolved.target;

            if (target && target !== ctx.lastTarget) {
                if (ctx.lastTarget) {
                    ctx.lastTarget.style.outline = "";
                    ctx.lastTarget.style.background = "";
                }
                logDragDrop("target-resolve:hover", {
                    elementsCount: resolved.elementsCount,
                    targetId: resolved.targetId,
                    targetType: resolved.targetType,
                    fallbackUsed: resolved.fallbackUsed,
                    draggingIds: draggingIdsRef.current
                });
                if (resolved.targetId && !draggingIdsRef.current.includes(resolved.targetId)) {
                    target.style.outline = "2px solid #10B981";
                    target.style.background = "rgba(16, 185, 129, 0.1)";
                    ctx.lastTarget = target;
                } else {
                    ctx.lastTarget = null;
                }
            } else if (!target && ctx.lastTarget) {
                logDragDrop("hover-target:clear", { x: e.clientX, y: e.clientY });
                ctx.lastTarget.style.outline = "";
                ctx.lastTarget.style.background = "";
                ctx.lastTarget = null;
            }
        };

        const handleGlobalMouseUp = (e: MouseEvent) => {
            const ctx = virtualDragRef.current;
            if (!ctx) return;

            if (isVirtualDragging) {
                const resolved = getDragTargetInfo(e.clientX, e.clientY, ctx.lastTarget);
                logDragDrop("drop:mouseup", {
                    x: e.clientX,
                    y: e.clientY,
                    hasTarget: Boolean(resolved.target),
                    targetId: resolved.targetId,
                    targetType: resolved.targetType
                });
                logDragDrop("target-resolve:mouseup", {
                    elementsCount: resolved.elementsCount,
                    targetId: resolved.targetId,
                    targetType: resolved.targetType,
                    fallbackUsed: resolved.fallbackUsed
                });
                if (resolved.target) {
                    if (resolved.targetId && resolved.targetType) {
                        handleExecuteMove(ctx, resolved.targetType, resolved.targetId);
                    } else {
                        logDragDrop("drop:skip:missing-target-attrs", { targetId: resolved.targetId, targetType: resolved.targetType });
                    }
                } else {
                    logDragDrop("drop:skip:no-target", { x: e.clientX, y: e.clientY });
                }
            } else {
                logDragDrop("drop:mouseup-before-dragging", { dragType: ctx.type, ids: ctx.ids, x: e.clientX, y: e.clientY });
            }

            if (ctx.lastTarget) {
                ctx.lastTarget.style.outline = "";
                ctx.lastTarget.style.background = "";
            }
            virtualDragRef.current = null;
            setIsVirtualDragging(false);
            document.body.style.cursor = "";
            document.body.style.userSelect = "";
        };

        window.addEventListener('mousemove', handleGlobalMouseMove, true);
        window.addEventListener('mouseup', handleGlobalMouseUp, true);
        return () => {
            window.removeEventListener('mousemove', handleGlobalMouseMove, true);
            window.removeEventListener('mouseup', handleGlobalMouseUp, true);
        };
    }, [isVirtualDragging, handleExecuteMove]);

    const handleVirtualDragStart = (e: React.MouseEvent, type: string, id: string) => {
        if (e.button !== 0) {
            logDragDrop("start:skip:non-left-button", { button: e.button, type, id });
            return;
        }
        const ids = selectionSet.has(id) ? Array.from(selectionSet) : [id];
        logDragDrop("start", { type, id, ids, selectedCount: selectionSet.size, x: e.clientX, y: e.clientY });
        virtualDragRef.current = {
            type,
            ids,
            startX: e.clientX,
            startY: e.clientY,
            lastTarget: null
        };
    };

    return {
        isVirtualDragging,
        handleVirtualDragStart
    };
}

import React from "react";
import { ChevronDown, ChevronRight, Eye, EyeOff, Trash2 } from "lucide-react";
import { cn } from "@TOOL/utils/cn";
import { FeatureIcon } from "@DESIGN/components/core/CADPanels/FeatureIcon";
import { getCleanName, getParsedMetadata } from "@TOOL/utils/featureUtils";
import type { FeatureState } from "@CONTRACT/types";

export interface FeatureItemProps {
  feature: FeatureState;
  index: number | string;
  level: number;
  levelOffset: number;
  selected: boolean;
  expanded: boolean;
  hasChildren: boolean;
  onSelect: (e: React.MouseEvent) => void;
  onToggleExpand: () => void;
  onZoomTo: () => void;
  onDragStart?: (e: React.DragEvent) => void;
  onDragEnd?: (e: React.DragEvent) => void;
  onContextMenu: (e: React.MouseEvent) => void;
  onDelete: () => void;
  onMouseDown?: (e: React.MouseEvent) => void;
  groupType?: string;
  groupName?: string;
  children?: React.ReactNode;
  checked?: boolean;
  onToggleCheck?: () => void;
  visible?: boolean;
  onToggleVisible?: (e: React.MouseEvent) => void;
