export const TreeItem = React.memo(({
  name,
  expanded,
  onClick,
  children,
  onRename,
  visible = true,
  onToggleVisible,
  customAction,
  level = 0,
  icon,
  className,
  draggable: _draggable = false,
  dragType,
  dragId,
  onDragStart: _onDragStart,
  onDragEnd: _onDragEnd,
  onDragOver: _onDragOver,
  onDragLeave: _onDragLeave,
  onDrop: _onDrop,
  isDropTarget,
  onDoubleClick,
  onContextMenu,
  checked,
  indeterminate,
  onToggleCheck,
  onMouseDown,
  hasChildren
}: TreeItemProps) => {
  const checkboxRef = React.useRef<HTMLInputElement>(null);

  React.useEffect(() => {
    if (checkboxRef.current) {
      checkboxRef.current.indeterminate = !!indeterminate;
    }
  }, [indeterminate]);

  return (
    <div
      className="mb-0.5"
      data-drag-id={dragId}
      data-drag-type={dragType}
    >
