        const isCamera = (
            feature.properties?.iconKey === 'cctv' ||
            getFeatureMetadataValue(feature, 'type', 'type', metadata) === 'camera' ||
            getFeatureMetadataValue(feature, 'specs.focal_length', 'focal_length', metadata) ||
            getFeatureMetadataValue(feature, 'specs.hfov', 'hfov', metadata) ||
            getFeatureMetadataValue(feature, 'specs.resolution_x', 'resolution_x', metadata)
        );

        if (!isCamera) return null;

        const coords = getPointCoordinates(feature);
        if (!coords) return null;

        const { focalLength, sensorSize, resolutionX } = getEffectiveCameraSpecs(feature, state.settings, metadata);
        const installHeight = getEffectiveMountingHeight(feature, state.settings, metadata);
        const sensor = SENSOR_SIZES[sensorSize as keyof typeof SENSOR_SIZES] || SENSOR_SIZES['1/2.8"'];
        const calculatedHfov = calculateHFOV(sensor.width, focalLength);
        const hfov = metadataNumber(getFeatureMetadataValue(feature, 'specs.hfov', 'hfov', metadata), calculatedHfov);
        const targetHeight = metadataNumber(getFeatureMetadataValue(feature, 'specs.target_height', 'targetHeight', metadata), 1.7);

        return {
            lat: coords[1] as number,
            lng: coords[0] as number,
            resolutionX: Number(resolutionX),
            hfov: Number(hfov),
            installHeight: Number(installHeight),
            targetHeight: Number(targetHeight)
        };
    }, [selectedFeatureId, state, previewMetadata]);

    useMapEvents({
        mousemove(e) {
            if (!showDORILayers) {
                if (ppmInfo) setPpmInfo(null);
                return;
            }

            const camera = getCameraData();
            if (!camera) {
                if (ppmInfo) setPpmInfo(null);
                return;
            }

            const ppm = calculatePPMAtPoint(
                camera.lat, camera.lng,
                e.latlng.lat, e.latlng.lng,
                camera.resolutionX,
                camera.hfov,
                camera.installHeight,
                camera.targetHeight
            );

            setPpmInfo({
                ppm,
                lat: e.latlng.lat,
                lng: e.latlng.lng,
                x: e.originalEvent.clientX,
                y: e.originalEvent.clientY
            });
        },
        mouseout() {
            setPpmInfo(null);
        }
    });

    if (!ppmInfo || !showDORILayers) return null;

    const category = getDORICategory(ppmInfo.ppm);

    return createPortal(
        <div
            className="fixed pointer-events-none z-[10000] flex flex-col items-center gap-1 -translate-x-1/2 -translate-y-[calc(100%+15px)] animate-in fade-in duration-200"
            style={{ left: ppmInfo.x, top: ppmInfo.y }}
        >
            <div className="bg-black/80 backdrop-blur-sm border border-white/20 px-2 py-1 rounded shadow-2xl flex flex-col items-center min-w-[80px]">
                <div className="flex gap-2 items-baseline">
                    <span className="text-[14px] font-black font-mono text-white">
                        {Math.round(ppmInfo.ppm)}
                    </span>
                    <span className="text-[8px] font-bold text-white/60 uppercase">PPM</span>
                </div>
                <div
                    className="w-full h-1 rounded-full mt-1"
                    style={{ backgroundColor: category.color }}
                />
                <span className="text-[7px] font-black uppercase tracking-wider mt-0.5" style={{ color: category.color }}>
                    {category.label}
                </span>
            </div>
            {/* Pointer arrow */}
            <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[8px] border-t-black/80 shadow-lg" />
        </div>,
        document.body
    );
};

import { useState, useRef, useEffect } from 'react';
import L from 'leaflet';
import { invoke } from '@tauri-apps/api/core';
import { useMapEvents } from 'react-leaflet';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';
import { useSnap } from '@IMPLEMENT/hooks/useSnap';

interface LocationMarkerProps {
    onLocationChange: (lat: number, lng: number, snapId?: string | null) => void;
    onFinishDrawing?: () => void;
    onFinishDrawingSession?: () => void;
    isMeasureActive?: boolean;
}

type CoordinatePopupState = {
    lat: number;
    lng: number;
    x: number;
    y: number;
    copied: boolean;
} | null;

const formatCoordinate = (value: number) => value.toFixed(7);
const CLIPBOARD_RETRY_ATTEMPTS = 4;
const CLIPBOARD_RETRY_DELAY_MS = 120;

const wait = (ms: number) => new Promise(resolve => window.setTimeout(resolve, ms));

const copyTextToClipboard = async (text: string): Promise<boolean> => {
    try {
        await invoke('copy_text_to_system_clipboard', { text });
        return true;
    } catch {
        console.error('[Clipboard] copy_text_to_system_clipboard failed');
        // Fall back to the browser clipboard path below.
    }

    const hasClipboardApi = typeof navigator !== 'undefined' && typeof navigator.clipboard?.writeText === 'function';

    if (hasClipboardApi) {
        for (let attempt = 0; attempt < CLIPBOARD_RETRY_ATTEMPTS; attempt += 1) {
            try {
                await navigator.clipboard.writeText(text);
                return true;
            } catch {
                // Retry briefly when the OS clipboard is temporarily busy with another payload.
            }

            if (attempt < CLIPBOARD_RETRY_ATTEMPTS - 1) {
                await wait(CLIPBOARD_RETRY_DELAY_MS);
            }
        }
    }

    if (typeof document === 'undefined' || typeof document.execCommand !== 'function') {
        return false;
    }

    for (let attempt = 0; attempt < CLIPBOARD_RETRY_ATTEMPTS; attempt += 1) {
        const textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.setAttribute('readonly', 'true');
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        textarea.style.pointerEvents = 'none';
        document.body.appendChild(textarea);
        textarea.select();
        textarea.setSelectionRange(0, textarea.value.length);

        try {
            if (document.execCommand('copy')) {
                return true;
            }
        } finally {
            document.body.removeChild(textarea);
        }

        if (attempt < CLIPBOARD_RETRY_ATTEMPTS - 1) {
            await wait(CLIPBOARD_RETRY_DELAY_MS);
        }
    }

    return false;
};

export function LocationMarker({
    onLocationChange,
    onFinishDrawing,
    onFinishDrawingSession,
    isMeasureActive = false
}: LocationMarkerProps) {
    const drawingMode = useDesignSync(s => s.drawingMode);
    const editingFeatureId = useDesignSync(s => s.editingFeatureId);
    const [coordinatePopup, setCoordinatePopup] = useState<CoordinatePopupState>(null);
    const { performSnap, snapNow, clearSnap, snappedPointRef } = useSnap();
    const popupRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const el = popupRef.current;
        if (el) {
            L.DomEvent.disableClickPropagation(el);
            L.DomEvent.disableScrollPropagation(el);
        }
    }, [coordinatePopup]);

    const handleCopyCoordinates = async () => {
        if (!coordinatePopup) return;
        const text = `${formatCoordinate(coordinatePopup.lat)}, ${formatCoordinate(coordinatePopup.lng)}`;
        const copied = await copyTextToClipboard(text);
        if (!copied) return;
        setCoordinatePopup({ ...coordinatePopup, copied: true });
    };

    useMapEvents({
        async click(e) {
            setCoordinatePopup(null);
            if (drawingMode === 'none') return;
            console.log("[MapClick] Handling click at", e.latlng.lat, e.latlng.lng);

            // Use snapped point from Ref, but if null, try a quick real-time check to overcome race conditions
            let snappedPoint = snappedPointRef.current;
            if (!snappedPoint) {
                // Remove buffer: only snap if strictly within visual threshold (2.2m)
                snappedPoint = await snapNow(e.latlng.lat, e.latlng.lng, 0.00002);
            }

            const finalLng = snappedPoint ? snappedPoint.x : e.latlng.lng;
            const finalLat = snappedPoint ? snappedPoint.y : e.latlng.lat;
            const snapId = snappedPoint?.id || null;

            onLocationChange(finalLat, finalLng, snapId);
        },
        dblclick() {
            if (drawingMode === 'polyline') {
                onFinishDrawing?.();
            }
        },
        contextmenu(e) {
            e.originalEvent?.preventDefault();
            if (drawingMode !== 'none') {
                onFinishDrawingSession?.();
                return;
            }
            if (editingFeatureId || isMeasureActive) return;
            setCoordinatePopup({
                lat: e.latlng.lat,
                lng: e.latlng.lng,
                x: e.containerPoint.x,
                y: e.containerPoint.y,
                copied: false,
            });
        },
        mousemove(e) {
            if (drawingMode === 'none' && !editingFeatureId) return;
            performSnap(e.latlng.lat, e.latlng.lng);
        },
        mouseout() {
            if (drawingMode === 'none' && !editingFeatureId) return;
            clearSnap();
        }
    });

    if (!coordinatePopup) return null;

    return (
        <div
            ref={popupRef}
            className="absolute z-[1000] min-w-48 -translate-x-1/2 rounded-sm border border-cad-border bg-cad-elevated text-cad-text-primary font-mono shadow-2xl shadow-black/40 pointer-events-auto overflow-hidden"
            style={{
                left: coordinatePopup.x,
                top: coordinatePopup.y,
                transform: 'translate(-50%, calc(-100% - 10px))',
            }}
            onMouseDown={(event) => event.stopPropagation()}
            onClick={(event) => event.stopPropagation()}
            onContextMenu={(event) => event.preventDefault()}
        >
            <div className="border-b border-cad-border/70 px-3 py-2 text-[10px] font-black uppercase text-cad-text-secondary">
                Tọa độ điểm click
            </div>
            <div className="space-y-1 px-3 py-2 text-[11px]">
                <div className="flex justify-between gap-3">
                    <span className="text-cad-text-muted">Lat</span>
                    <span>{formatCoordinate(coordinatePopup.lat)}</span>
                </div>
                <div className="flex justify-between gap-3">
                    <span className="text-cad-text-muted">Lng</span>
                    <span>{formatCoordinate(coordinatePopup.lng)}</span>
                </div>
            </div>
            <button
                type="button"
                className="w-full border-t border-cad-border/70 px-3 py-2 text-left text-[10px] font-black uppercase text-cad-accent hover:bg-cad-accent hover:text-black transition-colors"
                onClick={handleCopyCoordinates}
            >
                {coordinatePopup.copied ? 'Đã copy tọa độ' : 'Copy tọa độ'}
            </button>
        </div>
    );
}

import { useEffect } from 'react';
import { useMap } from 'react-leaflet';
import { listen, emit } from '@tauri-apps/api/event';
import { invoke } from '@tauri-apps/api/core';
import html2canvas from 'html2canvas';
import { validateMapCaptureCanvas } from './mapCaptureValidation';

const MAX_CAPTURE_ZOOM = 36;
const REPORT_CAPTURE_EVENT = 'design-report-map-capture';
const TRANSPARENT_TILE_DATA_URL = 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';
const tileDataUrlCache = new Map<string, string>();

type MapCaptureRequest = {
  captureId?: string;
  printArea: [number, number, number, number] | null;
  scale?: number;
  fitToBounds?: boolean;
  zoom?: number;
};

const waitForMapMove = (map: ReturnType<typeof useMap>, timeoutMs = 1200): Promise<void> => (
  new Promise((resolve) => {
    let resolved = false;
    const finish = () => {
      if (resolved) return;
      resolved = true;
      map.off('moveend', finish);
      window.setTimeout(resolve, 350);
    };
    map.once('moveend', finish);
    window.setTimeout(finish, timeoutMs);
  })
);

const isTransparentPlaceholderTile = (tile: HTMLImageElement): boolean =>
  tile.src === TRANSPARENT_TILE_DATA_URL || (tile.naturalWidth <= 1 && tile.naturalHeight <= 1);

const isFetchableTileUrl = (url: string): boolean => /^https?:\/\//i.test(url);

const waitForTiles = (container: HTMLElement, timeoutMs = 5000): Promise<void> => (
  new Promise((resolve) => {
    const startedAt = Date.now();
    const check = () => {
      const tiles = Array.from(container.querySelectorAll<HTMLImageElement>('img.leaflet-tile'))
        .filter((tile) => !isTransparentPlaceholderTile(tile));
      const loadingTiles = container.querySelectorAll('.leaflet-tile-loading').length;
      const ready = tiles.length > 0
        && loadingTiles === 0
        && tiles.every((tile) => tile.complete && tile.naturalWidth > 0);
      if (ready || Date.now() - startedAt > timeoutMs) {
        window.setTimeout(resolve, 250);
        return;
      }
      window.setTimeout(check, 120);
    };
    check();
  })
);

const delay = (ms: number): Promise<void> => new Promise((resolve) => window.setTimeout(resolve, ms));

const waitForAnimationFrames = (count = 2): Promise<void> => (
  new Promise((resolve) => {
    const tick = (remaining: number) => {
      if (remaining <= 0) {
        resolve();
        return;
      }
      window.requestAnimationFrame(() => tick(remaining - 1));
    };
    tick(count);
  })
);

const inlineVisibleTiles = async (container: HTMLElement): Promise<Array<() => void>> => {
  const tiles = Array.from(container.querySelectorAll<HTMLImageElement>('img.leaflet-tile'))
    .filter((tile) => isFetchableTileUrl(tile.src) && !isTransparentPlaceholderTile(tile));
  const restorers: Array<() => void> = [];
  const queue = [...tiles];

  const inlineTile = async (tile: HTMLImageElement) => {
    const originalSrc = tile.src;
    try {
      let dataUrl = tileDataUrlCache.get(originalSrc);
      if (!dataUrl) {
        dataUrl = await invoke<string>('fetch_url_as_data_url', { url: originalSrc });
        tileDataUrlCache.set(originalSrc, dataUrl);
      }
      if (tile.src === originalSrc) {
        tile.src = dataUrl;
        restorers.push(() => {
          if (tile.src === dataUrl) tile.src = originalSrc;
        });
      }
    } catch (error) {
      console.warn('[MapCaptureHandler] Failed to inline map tile', originalSrc, error);
    }
  };

  await Promise.all(Array.from({ length: Math.min(4, queue.length) }, async () => {
    while (queue.length > 0) {
      const tile = queue.shift();
      if (tile) await inlineTile(tile);
    }
  }));

  return restorers;
};

export function MapCaptureHandler() {
  const map = useMap();

  useEffect(() => {
    const setupListener = async () => {
      const unlisten = await listen<MapCaptureRequest>('request-map-capture', async (event) => {
        console.log('[MapCaptureHandler] Received request-map-capture', event.payload);
        const mapContainer = map.getContainer();
        if (!mapContainer) {
          console.error('[MapCaptureHandler] Map container not found');
          emit('map-capture-error', { captureId: event.payload.captureId, error: 'Map container not found' });
          return;
        }

        const { captureId, printArea, scale, fitToBounds, zoom } = event.payload;
        const captureMaxZoom = Math.min(zoom ?? 19, MAX_CAPTURE_ZOOM);
        const originalCenter = map.getCenter();
        const originalZoom = map.getZoom();
        let restoreTiles: Array<() => void> = [];
        let captureModeEnabled = false;

        try {
          window.dispatchEvent(new CustomEvent(REPORT_CAPTURE_EVENT, { detail: { active: true } }));
          captureModeEnabled = true;
          await delay(120);

          const captureOptions: any = {
            useCORS: false,
            allowTaint: false,
            scale: scale ?? 4,
            logging: false,
            ignoreElements: (el: any) => {
              const className = typeof el.className === 'string' ? el.className : "";
              return className.includes('leaflet-control-container') || 
                     className.includes('leaflet-draw-toolbar');
            }
          };

          if (fitToBounds && printArea) {
            const [minLat, minLng, maxLat, maxLng] = printArea;
            map.invalidateSize(false);
            map.fitBounds([[minLat, minLng], [maxLat, maxLng]], {
              animate: false,
              padding: [5, 5],
              maxZoom: captureMaxZoom,
            });
            await waitForMapMove(map);
          }
          await delay(700);
          await waitForTiles(mapContainer);
          restoreTiles = await inlineVisibleTiles(mapContainer);
          await waitForTiles(mapContainer, 1500);
          await delay(250);
          await waitForAnimationFrames(2);

          // If printArea is provided, calculate crop bounds
          if (printArea && !fitToBounds) {
            const [minLat, minLng, maxLat, maxLng] = printArea;
            // Leaflet uses [lat, lng]
            const nwPoint = map.latLngToContainerPoint([maxLat, minLng]);
            const sePoint = map.latLngToContainerPoint([minLat, maxLng]);

            captureOptions.x = Math.min(nwPoint.x, sePoint.x);
            captureOptions.y = Math.min(nwPoint.y, sePoint.y);
            captureOptions.width = Math.abs(nwPoint.x - sePoint.x);
            captureOptions.height = Math.abs(nwPoint.y - sePoint.y);

            console.log('[MapCaptureHandler] Calculated crop bounds:', {
              x: captureOptions.x,
              y: captureOptions.y,
              width: captureOptions.width,
              height: captureOptions.height
            });
          }

          const canvas = await html2canvas(mapContainer, captureOptions);
          const validation = validateMapCaptureCanvas(canvas);
          if (!validation.valid) {
            throw new Error(validation.reason || 'Ảnh bản đồ không hợp lệ.');
          }

          const dataUrl = canvas.toDataURL('image/png');
          emit('map-capture-result', { captureId, dataUrl });
          console.log('[MapCaptureHandler] Sent map-capture-result');
        } catch (err) {
          console.error('[MapCaptureHandler] Global capture error:', err);
          emit('map-capture-error', { captureId, error: String(err) });
        } finally {
          restoreTiles.forEach((restore) => restore());
          if (captureModeEnabled) {
            window.dispatchEvent(new CustomEvent(REPORT_CAPTURE_EVENT, { detail: { active: false } }));
          }
          if (fitToBounds) {
            map.setView(originalCenter, originalZoom, { animate: false });
          }
        }
      });


      return unlisten;
    };

    const unlistenPromise = setupListener();

    return () => {
      unlistenPromise.then(f => f());
    };
  }, [map]);

  return null;
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { CircleMarker, Polyline, Tooltip, useMap, useMapEvents } from 'react-leaflet';
import type { LatLng, LatLngTuple } from 'leaflet';

interface MeasurementToolProps {
    active: boolean;
    onDeactivate: () => void;
}

const formatDistance = (meters: number) => {
    if (meters >= 1000) return `${(meters / 1000).toFixed(meters >= 10000 ? 1 : 2)} km`;
    return `${Math.round(meters)} m`;
};

const toTuple = (point: LatLng): LatLngTuple => [point.lat, point.lng];

export function MeasurementTool({ active, onDeactivate }: MeasurementToolProps) {
    const map = useMap();
    const [points, setPoints] = useState<LatLng[]>([]);
    const [hoverPoint, setHoverPoint] = useState<LatLng | null>(null);

    const clearMeasure = useCallback(() => {
        setPoints([]);
        setHoverPoint(null);
        onDeactivate();
    }, [onDeactivate]);

    useEffect(() => {
        if (!active) {
            const resetTimer = window.setTimeout(() => {
                setPoints([]);
                setHoverPoint(null);
            }, 0);
            return () => window.clearTimeout(resetTimer);
        }

        map.getContainer().classList.add('measure-tool-active');
        map.doubleClickZoom.disable();
        return () => {
            map.getContainer().classList.remove('measure-tool-active');
            map.doubleClickZoom.enable();
        };
    }, [active, map]);

    useEffect(() => {
        if (!active) return;
        const handleKeyDown = (event: KeyboardEvent) => {
            if (event.key === 'Escape') {
                clearMeasure();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [active, clearMeasure]);

    useMapEvents({
        click(event) {
            if (!active) return;
            event.originalEvent?.preventDefault();
            setPoints((current) => [...current, event.latlng]);
            setHoverPoint(null);
        },
        mousemove(event) {
            if (!active || points.length === 0) return;
            setHoverPoint(event.latlng);
        },
        dblclick(event) {
            if (!active) return;
            event.originalEvent?.preventDefault();
            setHoverPoint(null);
        },
        contextmenu(event) {
            if (!active) return;
            event.originalEvent?.preventDefault();
            clearMeasure();
        },
    });

    const fixedDistance = useMemo(() => {
        return points.reduce((sum, point, index) => {
            if (index === 0) return 0;
            return sum + map.distance(points[index - 1], point);
        }, 0);
    }, [map, points]);

    const previewDistance = useMemo(() => {
        if (!hoverPoint || points.length === 0) return 0;
        return map.distance(points[points.length - 1], hoverPoint);
    }, [hoverPoint, map, points]);

    const totalDistance = fixedDistance + previewDistance;
    const path = useMemo(() => {
        const measured = points.map(toTuple);
        if (hoverPoint) measured.push(toTuple(hoverPoint));
        return measured;
    }, [hoverPoint, points]);

    if (!active) return null;

    return (
        <>
            {path.length >= 2 && (
                <Polyline
                    positions={path}
                    interactive={false}
                    pathOptions={{
                        color: '#38bdf8',
                        weight: 3,
                        opacity: 0.95,
                        dashArray: hoverPoint ? '8 8' : undefined,
                    }}
                />
            )}

            {points.map((point, index) => (
                <CircleMarker
                    key={`${point.lat}-${point.lng}-${index}`}
                    center={toTuple(point)}
                    radius={5}
                    interactive={false}
                    pathOptions={{
                        color: '#e0f2fe',
                        fillColor: '#0284c7',
                        fillOpacity: 1,
                        weight: 2,
                    }}
                />
            ))}

            {hoverPoint && (
                <CircleMarker
                    center={toTuple(hoverPoint)}
                    radius={4}
                    interactive={false}
                    pathOptions={{
                        color: '#bae6fd',
                        fillColor: '#38bdf8',
                        fillOpacity: 0.55,
                        weight: 1,
                    }}
                >
                    <Tooltip permanent direction="top" offset={[0, -8]} opacity={1} className="measure-tooltip">
                        {formatDistance(totalDistance)}
                    </Tooltip>
                </CircleMarker>
            )}

            <div
                className="measure-panel pointer-events-auto"
                onClick={(event) => event.stopPropagation()}
                onMouseDown={(event) => event.stopPropagation()}
                onContextMenu={(event) => event.preventDefault()}
            >
                <div className="text-[9px] font-black uppercase tracking-widest text-cad-text-muted">Đo khoảng cách</div>
                <div className="mt-1 font-mono text-sm font-black text-cad-text-primary">
                    {formatDistance(totalDistance)}
                </div>
                <div className="mt-1 text-[9px] text-cad-text-secondary">
                    Click để thêm điểm, chuột phải hoặc ESC để thoát
                </div>
                <button
                    type="button"
                    onClick={clearMeasure}
                    className="mt-2 w-full border border-cad-border px-2 py-1 text-[9px] font-black uppercase text-cad-text-secondary hover:border-cad-accent hover:text-cad-accent"
                >
                    Kết thúc
                </button>
            </div>
        </>
    );
}

