import { useEffect, useRef } from 'react';
import { useMap } from 'react-leaflet';
import L from 'leaflet';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';

export const isValidLatLng = (lat: number, lng: number) => {
    // Only check basic mathematical validity and non-zero (near origin)
    return Math.abs(lat) > 0.0001 && Math.abs(lng) > 0.0001 &&
        lat >= -90 && lat <= 90 &&
        lng >= -180 && lng <= 180;
};

const canFitBounds = (map: L.Map) => {
    try {
        return Boolean((map as any)?._loaded && map.getPane('mapPane'));
    } catch {
        return false;
    }
};

export function ZoomExtendControl() {
    const map = useMap();
    const state = useDesignSync(s => s.state);
    const zoomExtendTrigger = useDesignSync(s => s.zoomExtendTrigger);
    const lastTrigger = useRef(0);

    useEffect(() => {
        if (!state || zoomExtendTrigger === 0 || zoomExtendTrigger === lastTrigger.current) return;
        lastTrigger.current = zoomExtendTrigger;

        const { features, feature_groups, layers } = state;
        if (!features || !feature_groups || !layers) return;

        const allLatLngs: L.LatLngExpression[] = [];

        Object.values(features).forEach(f => {
            if (!f) return;
            const group = f.group_id ? feature_groups[f.group_id] : null;
            if (!group || !group.is_visible) return;
            const layer = layers[group.layer_id];
            if (!layer || !layer.is_visible) return;

            try {
                const coords = typeof f.coordinates === 'string' ? JSON.parse(f.coordinates) : f.coordinates;
                const type = f.geom_type || 'Point';

                if ((type === 'Point' || type === 'POINT' || type === 'INTERSECTION') && coords && coords.length >= 2) {
                    if (isValidLatLng(coords[1], coords[0])) {
                        allLatLngs.push([coords[1], coords[0]]);
                    }
                } else if ((type === 'LineString' || type === 'POLYLINE') && coords) {
                    coords.forEach((c: any) => {
                        if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]);
                    });
                } else if (type === 'Polygon' && coords && coords[0]) {
                    coords[0].forEach((c: any) => {
                        if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]);
                    });
                }
            } catch (e) {
                console.warn('[ZoomExtendControl] Failed to parse coordinates:', e);
            }
        });

        if (allLatLngs.length > 0) {
            let filteredPoints = allLatLngs;
            if (allLatLngs.length >= 3) {
                const lats = allLatLngs.map(p => (Array.isArray(p) ? (p as number[])[0] : (p as any).lat) as number);
                const lngs = allLatLngs.map(p => (Array.isArray(p) ? (p as number[])[1] : (p as any).lng) as number);

                const avgLat = lats.reduce((a, b) => a + b, 0) / lats.length;
                const avgLng = lngs.reduce((a, b) => a + b, 0) / lngs.length;

                filteredPoints = allLatLngs.filter(p => {
                    const plat = (Array.isArray(p) ? (p as number[])[0] : (p as any).lat) as number;
                    const plng = (Array.isArray(p) ? (p as number[])[1] : (p as any).lng) as number;
                    return Math.abs(plat - avgLat) < 3 && Math.abs(plng - avgLng) < 3;
                });
            }

            if (filteredPoints.length > 0) {
                const bounds = L.latLngBounds(filteredPoints as L.LatLngExpression[]);
                console.log("[ZoomExtend] Points collected:", allLatLngs.length, "Filtered:", filteredPoints.length);
                if (!canFitBounds(map)) {
                    map.whenReady(() => {
                        if (!canFitBounds(map)) return;
                        map.fitBounds(bounds, { padding: [50, 50], maxZoom: 18 });
                    });
                    return;
                }
                map.fitBounds(bounds, { padding: [50, 50], maxZoom: 18 });
            }
        } else {
            console.warn("[ZoomExtend] No valid points found to zoom to.");
        }
    }, [zoomExtendTrigger, state, map]);

    return null;
}

import { useEffect, useRef } from 'react';
import { useMap } from 'react-leaflet';
import L from 'leaflet';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';
import { isValidLatLng } from '@DESIGN/features/map/MapLayerComponents/ZoomExtendControl';
import { getLineCoordinates, getPointCoordinates, getPolygonCoordinates } from '@TOOL/utils/featureUtils';

export function ZoomToHandler() {
    const map = useMap();
    const state = useDesignSync(s => s.state);
    const zoomToTrigger = useDesignSync(s => s.zoomToTrigger);
    const lastTrigger = useRef(0);

    useEffect(() => {
        if (!zoomToTrigger || !state || zoomToTrigger.timestamp === lastTrigger.current) return;
        lastTrigger.current = zoomToTrigger.timestamp;

        const { id, type } = zoomToTrigger;

        if (type === 'feature') {
            const f = state.features[id];
            if (f) {
                try {
                    const point = getPointCoordinates(f);
                    const line = getLineCoordinates(f);
                    const polygon = getPolygonCoordinates(f)?.[0];

                    if (point && isValidLatLng(point[1], point[0])) {
                        console.log(`[Zoom] Zooming to feature ${id} at zoom level 20`);
                        map.setView([point[1], point[0]], 20, { animate: true });
                    } else if (line && line.length > 0) {
                        const bounds: L.LatLngExpression[] = [];
                        line.forEach((c) => {
                            if (isValidLatLng(c[1], c[0])) bounds.push([c[1], c[0]]);
                        });
                        if (bounds.length > 0) {
                            console.log(`[Zoom] Fitting bounds for feature ${id} at max zoom 20`);
                            map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50], maxZoom: 20, animate: true });
                        }
                    } else if (polygon && polygon.length > 0) {
                        const bounds: L.LatLngExpression[] = [];
                        polygon.forEach((c) => {
                            if (isValidLatLng(c[1], c[0])) bounds.push([c[1], c[0]]);
                        });
                        if (bounds.length > 0) {
                            console.log(`[Zoom] Fitting bounds for polygon ${id} at max zoom 20`);
                            map.fitBounds(L.latLngBounds(bounds), { padding: [50, 50], maxZoom: 20, animate: true });
                        }
                    }
                } catch (e) {
                    console.error("[Zoom] Error zooming to feature:", e);
                }
            }
        } else if (type === 'layer') {
            const allLatLngs: L.LatLngExpression[] = [];
            Object.values(state.features).forEach(f => {
                const group = f.group_id ? state.feature_groups[f.group_id] : null;
                if (group && group.layer_id === id) {
                    try {
                        const point = getPointCoordinates(f);
                        const line = getLineCoordinates(f);
                        const polygon = getPolygonCoordinates(f)?.[0];
                        if (point && isValidLatLng(point[1], point[0])) allLatLngs.push([point[1], point[0]]);
                        line?.forEach((c) => { if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]); });
                        polygon?.forEach((c) => { if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]); });
                    } catch (e) {
                        console.warn('[ZoomToHandler] Failed to parse coordinates for feature:', f.id, e);
                    }
                }
            });

            if (allLatLngs.length > 0) {
                map.fitBounds(L.latLngBounds(allLatLngs), { padding: [50, 50], maxZoom: 18 });
            }
        } else if (type === 'region') {
            const allLatLngs: L.LatLngExpression[] = [];
            Object.values(state.features).forEach(f => {
                const group = f.group_id ? state.feature_groups[f.group_id] : null;
                if (group) {
                    const layer = state.layers[group.layer_id];
                    if (layer && layer.region_id === id) {
                        try {
                            const point = getPointCoordinates(f);
                            const line = getLineCoordinates(f);
                            const polygon = getPolygonCoordinates(f)?.[0];
                            if (point && isValidLatLng(point[1], point[0])) allLatLngs.push([point[1], point[0]]);
                            polygon?.forEach((c) => { if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]); });
                            line?.forEach((c) => { if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]); });
                        } catch (e) {
                            console.warn('[ZoomToHandler] Failed to parse coordinates for region:', id, e);
                        }
                    }
                }
            });
            if (allLatLngs.length > 0) {
                map.fitBounds(L.latLngBounds(allLatLngs), { padding: [50, 50], maxZoom: 18 });
            }
        } else if (type === 'group') {
            const featuresInGroup = Object.values(state.features).filter(f => f.group_id === id);
            if (featuresInGroup.length === 0) return;

            const allLatLngs: L.LatLngExpression[] = [];
            featuresInGroup.forEach(f => {
                try {
                    const point = getPointCoordinates(f);
                    const line = getLineCoordinates(f);
                    const polygon = getPolygonCoordinates(f)?.[0];
                    if (point && isValidLatLng(point[1], point[0])) allLatLngs.push([point[1], point[0]]);
                    polygon?.forEach((c) => { if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]); });
                    line?.forEach((c) => { if (isValidLatLng(c[1], c[0])) allLatLngs.push([c[1], c[0]]); });
                } catch (e) {
                    console.warn('[ZoomToHandler] Failed to parse coordinates for group:', id, e);
                }
            });

            if (allLatLngs.length > 0) {
                map.fitBounds(L.latLngBounds(allLatLngs), { padding: [50, 50], maxZoom: 18 });
            }
        } else if (type === 'location' && zoomToTrigger.location) {
            const [lat, lng] = zoomToTrigger.location;
            if (isValidLatLng(lat, lng)) {
                map.setView([lat, lng], 18);
            }
        }
    }, [zoomToTrigger, state, map]);

    return null;
}

import { useEffect, useMemo, useRef, useState } from "react";
import { InvokeArgs, invoke as tauriInvoke } from "@tauri-apps/api/core";
import {
    AlertTriangle,
    Check,
    CheckSquare,
    Cpu,
    Download,
    Globe,
    KeyRound,
    RefreshCw,
    Save,
    Send,
    ShieldAlert,
    Sparkles,
    Square,
    Trash2,
    X,
} from "lucide-react";
import { IS_REAL_TAURI, safeInvoke, safeListen } from "@IMPLEMENT/lib/tauri";
import { useDesignSync } from "@IMPLEMENT/stores/useDesignSync";
import { useSettingsStore } from "@IMPLEMENT/stores/useSettingsStore";
import { cn } from "@TOOL/utils/cn";

type AiPanelTab = "chat" | "config";

interface AiConfig {
    enable_ai: boolean;
    low_power_mode: boolean;
    provider_enabled: boolean;
    provider_base_url: string;
    provider_model: string;
    max_tokens: number;
    timeout_ms: number;
    cloud_confirm_each_request: boolean;
    has_api_key: boolean;
}

interface AiStatusModel {
    id: string;
    role: string;
    version: string;
    fileName?: string;
    file_name?: string;
    installed: boolean;
    sizeBytes?: number;
    size_bytes?: number;
    checksumOk?: boolean | null;
    checksum_ok?: boolean | null;
}

interface AiStatus {
    state: string;
    enabled: boolean;
    localReady?: boolean;
    local_ready?: boolean;
    cloudReady?: boolean;
    cloud_ready?: boolean;
    downloading: boolean;
    loadedSessions?: string[];
    loaded_sessions?: string[];
    models?: AiStatusModel[];
    error?: string | null;
    providerModel?: string;
    provider_model?: string;
    hasApiKey?: boolean;
    has_api_key?: boolean;
}

interface AiCitation {
    sourceTable?: string;
    source_table?: string;
    sourceId?: string;
    source_id?: string;
    title: string;
    snippet: string;
    score: number;
}

interface AiActionProposal {
    id: string;
    actionType?: string;
    action_type?: string;
    targetTable?: string;
    target_table?: string;
    targetId?: string | null;
    target_id?: string | null;
    diff: unknown;
}

interface Message {
    id: string;
    role: "user" | "assistant" | "system";
    content: string;
    provider?: string;
    model?: string;
    citations?: AiCitation[];
    actionProposals?: AiActionProposal[];
}

interface DownloadProgress {
    requestId?: string;
    model?: string;
    bytesDownloaded?: number;
    expectedBytes?: number;
    status?: string;
    checksum?: boolean;
}

const DEFAULT_AI_CONFIG: AiConfig = {
    enable_ai: false,
    low_power_mode: false,
    provider_enabled: false,
    provider_base_url: "https://api.openai.com/v1",
    provider_model: "gpt-4o-mini",
    max_tokens: 1200,
    timeout_ms: 45000,
    cloud_confirm_each_request: true,
    has_api_key: false,
};

const strictInvoke = async <T,>(command: string, args?: InvokeArgs): Promise<T> => {
    if (!IS_REAL_TAURI) {
        throw new Error(`Tauri runtime is not available for ${command}.`);
    }
    return tauriInvoke<T>(command, args);
};

const parseJsonArray = <T,>(value: unknown): T[] => {
    if (Array.isArray(value)) return value as T[];
    if (typeof value === "string") {
        try {
            const parsed = JSON.parse(value);
            return Array.isArray(parsed) ? parsed : [];
        } catch {
            return [];
        }
    }
    return [];
};

const displayBytes = (value?: number) => {
    if (!value || value <= 0) return "-";
    if (value > 1024 * 1024) return `${(value / 1024 / 1024).toFixed(1)} MB`;
    if (value > 1024) return `${(value / 1024).toFixed(1)} KB`;
    return `${value} B`;
};

export function AiAssistantPanel() {
    const projectId = useDesignSync((s) => s.projectId) || "";
    const projectPath = useDesignSync((s) => s.projectPath);
    const featureCount = useDesignSync((s) => Object.keys(s.state?.features || {}).length);
    const { enableAi, setEnableAi } = useSettingsStore();

    const [activeTab, setActiveTab] = useState<AiPanelTab>("chat");
    const [status, setStatus] = useState<AiStatus | null>(null);
    const [config, setConfig] = useState<AiConfig>(DEFAULT_AI_CONFIG);
    const [apiKey, setApiKey] = useState("");
    const [messages, setMessages] = useState<Message[]>([]);
    const [conversationId, setConversationId] = useState("");
    const [inputValue, setInputValue] = useState("");
    const [allowCloud, setAllowCloud] = useState(false);
    const [showCloudConsent, setShowCloudConsent] = useState(false);
    const [pendingCloudText, setPendingCloudText] = useState("");
    const [loading, setLoading] = useState(false);
    const [savingConfig, setSavingConfig] = useState(false);
    const [downloadProgress, setDownloadProgress] = useState<DownloadProgress | null>(null);
    const [apiError, setApiError] = useState<string | null>(null);

    const messagesEndRef = useRef<HTMLDivElement>(null);

    const loadedSessions = status?.loadedSessions || status?.loaded_sessions || [];
    const models = status?.models || [];
    const localReady = !!(status?.localReady || status?.local_ready);
    const cloudReady = !!(status?.cloudReady || status?.cloud_ready);
    const hasApiKey = !!(status?.hasApiKey || status?.has_api_key || config.has_api_key);

    const chatDisabledReason = useMemo(() => {
        if (!projectId) return "Open a project before chatting with AI.";
        if (loading) return "AI is responding.";
        if (status?.downloading || status?.state === "DOWNLOADING") return "Model download is running.";
        if (!enableAi || !status?.enabled) return "Enable AI in Config first.";
        if (allowCloud && !cloudReady) return "Cloud provider or API key is not configured.";
        if (!allowCloud && !localReady && status?.state === "MODEL_REQUIRED") return "Download local models or enable cloud.";
        return null;
    }, [allowCloud, cloudReady, enableAi, loading, localReady, projectId, status]);

    const refreshStatus = async () => {
        const nextStatus = await safeInvoke<AiStatus>("get_ai_status");
        setStatus(nextStatus);
    };

    const refreshConfig = async () => {
        const nextConfig = await safeInvoke<Partial<AiConfig>>("get_ai_config");
        setConfig({ ...DEFAULT_AI_CONFIG, ...(nextConfig || {}) });
    };

    const refreshAi = async () => {
        await Promise.all([refreshStatus(), refreshConfig()]);
    };

    useEffect(() => {
        const refreshTimer = window.setTimeout(() => void refreshAi(), 0);
        const interval = window.setInterval(refreshAi, 8000);
        return () => {
            window.clearTimeout(refreshTimer);
            window.clearInterval(interval);
        };
    }, []);

    useEffect(() => {
        let mounted = true;
        void safeListen<DownloadProgress>("ai-model-progress", (event: { payload: DownloadProgress }) => {
            if (!mounted) return;
            setDownloadProgress(event.payload);
        });
        return () => {
            mounted = false;
        };
    }, []);

    useEffect(() => {
        if (!projectId) {
            const resetTimer = window.setTimeout(() => {
                setConversationId("");
                setMessages([]);
            }, 0);
            return () => window.clearTimeout(resetTimer);
        }

        const initChat = async () => {
            setApiError(null);
            const list = await safeInvoke<any[]>("list_ai_conversations", { projectId });
            if (list && list.length > 0) {
                setConversationId(list[0].id);
                const history = await safeInvoke<any[]>("list_ai_messages", { conversationId: list[0].id });
                setMessages((history || []).map((m) => ({
                    id: m.id,
                    role: m.role,
                    content: m.content,
                    provider: m.provider,
                    model: m.model,
                    citations: parseJsonArray<AiCitation>(m.citations_json),
                    actionProposals: [],
                })));
                return;
            }

            const newConv = await safeInvoke<any>("create_ai_conversation", {
                projectId,
                title: "AI Assistant Thread",
            });
            if (newConv?.id) {
                setConversationId(newConv.id);
                setMessages([]);
            }
        };

        void initChat();
    }, [projectId]);

    useEffect(() => {
        if (typeof messagesEndRef.current?.scrollIntoView === "function") {
            messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
        }
    }, [messages]);

    const getRuntimeLabel = () => {
        if (!status) return "LOADING";
        switch (status.state) {
            case "AI_OFF": return "AI OFF";
            case "MODEL_REQUIRED": return "MODEL REQUIRED";
            case "DOWNLOADING": return "DOWNLOADING";
            case "LOCAL_READY": return "LOCAL READY";
            case "CLOUD_READY": return "CLOUD READY";
            case "ERROR": return "RUNTIME ERROR";
            default: return status.state;
        }
    };

    const updateLocalConfig = <K extends keyof AiConfig>(key: K, value: AiConfig[K]) => {
        setConfig((prev) => ({ ...prev, [key]: value }));
    };

    const handleSaveConfig = async () => {
        setSavingConfig(true);
        setApiError(null);
        try {
            await strictInvoke("update_ai_config", {
                config: {
                    enableAi: config.enable_ai,
                    lowPowerMode: config.low_power_mode,
                    providerEnabled: config.provider_enabled,
                    providerBaseUrl: config.provider_base_url,
                    providerModel: config.provider_model,
                    maxTokens: Number(config.max_tokens),
                    timeoutMs: Number(config.timeout_ms),
                    cloudConfirmEachRequest: config.cloud_confirm_each_request,
                },
            });
            await setEnableAi(config.enable_ai);
            await refreshAi();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to save AI config.");
        } finally {
            setSavingConfig(false);
        }
    };

    const handleSaveApiKey = async () => {
        if (!apiKey.trim()) return;
        setSavingConfig(true);
        setApiError(null);
        try {
            await strictInvoke("set_ai_api_key", { apiKey });
            setApiKey("");
            await refreshAi();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to save API key.");
        } finally {
            setSavingConfig(false);
        }
    };

    const handleDeleteApiKey = async () => {
        setSavingConfig(true);
        setApiError(null);
        try {
            await strictInvoke("delete_ai_api_key");
            await refreshAi();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to delete API key.");
        } finally {
            setSavingConfig(false);
        }
    };

    const handleDownloadModels = async () => {
        setDownloadProgress({ status: "starting" });
        setApiError(null);
        try {
            await strictInvoke("install_ai_models");
            await refreshStatus();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Model installation failed.");
        } finally {
            setDownloadProgress(null);
        }
    };

    const handleCancelDownload = async () => {
        try {
            await strictInvoke("cancel_ai_model_install");
            await refreshStatus();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to cancel model install.");
        }
    };

    const handleRemoveModels = async () => {
        try {
            await strictInvoke("remove_ai_models");
            await refreshStatus();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to remove AI models.");
        }
    };

    const handleReleaseMemory = async () => {
        try {
            await strictInvoke("release_ai_memory");
            await refreshStatus();
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to release AI memory.");
        }
    };

    const sendMessage = async (text: string, confirmedScope: unknown = null) => {
        if (!text.trim() || !conversationId || chatDisabledReason) return;

        setInputValue("");
        setLoading(true);
        setApiError(null);
        setMessages((prev) => [...prev, {
            id: `local-${Date.now()}`,
            role: "user",
            content: text,
        }]);

        try {
            const chatRes = await strictInvoke<any>("send_ai_message", {
                request: {
                    projectId,
                    conversationId,
                    message: text,
                    allowCloud,
                    confirmedScope,
                },
            });

            const assistantMsg: Message = {
                id: chatRes.requestId || `assistant-${Date.now()}`,
                role: "assistant",
                content: chatRes.content,
                provider: chatRes.provider,
                model: chatRes.model,
                citations: chatRes.citations || [],
                actionProposals: chatRes.actionProposals || [],
            };
            setMessages((prev) => [...prev, assistantMsg]);
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to get AI response.");
        } finally {
            setLoading(false);
            await refreshStatus();
        }
    };

    const handleSendMessage = async () => {
        const text = inputValue.trim();
        if (!text || chatDisabledReason) return;
        if (allowCloud && config.cloud_confirm_each_request) {
            setPendingCloudText(text);
            setShowCloudConsent(true);
            return;
        }
        await sendMessage(text);
    };

    const handleConfirmCloudSend = async () => {
        const text = pendingCloudText;
        setShowCloudConsent(false);
        setPendingCloudText("");
        await sendMessage(text, {
            message: text,
            projectContext: {
                projectId,
                projectPath,
                featureCount,
            },
        });
    };

    const handleConfirmAction = async (proposalId: string) => {
        try {
            await strictInvoke("confirm_ai_action", { actionId: proposalId });
            setMessages((prev) => prev.map((m) => ({
                ...m,
                actionProposals: m.actionProposals?.filter((p) => p.id !== proposalId),
            })));
            setApiError(null);
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to confirm AI action.");
        }
    };

    const handleRejectAction = async (proposalId: string) => {
        try {
            await strictInvoke("reject_ai_action", {
                actionId: proposalId,
                note: "User rejected from AI Assistant",
            });
            setMessages((prev) => prev.map((m) => ({
                ...m,
                actionProposals: m.actionProposals?.filter((p) => p.id !== proposalId),
            })));
        } catch (e: any) {
            setApiError(e?.message || e?.toString() || "Failed to reject AI action.");
        }
    };

    const progressPercent = downloadProgress?.expectedBytes && downloadProgress.bytesDownloaded
        ? Math.min(100, Math.round((downloadProgress.bytesDownloaded / downloadProgress.expectedBytes) * 100))
        : null;

    return (
        <div className="flex h-full flex-col bg-cad-surface text-xs text-cad-text-primary select-none">
            <div className="border-b border-cad-border bg-cad-elevated/40 p-2.5">
                <div className="flex items-center justify-between gap-2">
                    <div className="flex min-w-0 items-center gap-2">
                        <Sparkles className={cn("h-4 w-4", enableAi ? "text-cad-accent animate-pulse" : "text-cad-text-muted")} />
                        <span className="truncate font-display font-bold uppercase tracking-wider">{getRuntimeLabel()}</span>
                    </div>
                    <div className="flex items-center gap-1">
                        {loadedSessions.length > 0 && (
                            <button onClick={handleReleaseMemory} title="Unload models and release RAM" className="rounded p-1 text-cad-text-secondary transition-all hover:bg-white/10 hover:text-white">
                                <Cpu className="h-3.5 w-3.5" />
                            </button>
                        )}
                    </div>
                </div>
                <div className="mt-2 grid grid-cols-2 gap-1 rounded border border-cad-border bg-black/20 p-1">
                    {(["chat", "config"] as AiPanelTab[]).map((tab) => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={cn(
                                "rounded px-2 py-1 text-[9px] font-black uppercase tracking-widest transition-all",
                                activeTab === tab ? "bg-cad-accent text-black" : "text-cad-text-secondary hover:text-white"
                            )}
                        >
                            {tab}
                        </button>
                    ))}
                </div>
            </div>

            {apiError && (
                <div className="flex items-start gap-2 border-b border-red-500/20 bg-red-950/40 p-2 text-red-300">
                    <ShieldAlert className="mt-0.5 h-4 w-4 shrink-0" />
                    <div className="min-w-0 break-words"><span className="font-semibold">Error: </span>{apiError}</div>
                </div>
            )}

            {activeTab === "config" ? (
                <div className="custom-scrollbar flex-1 space-y-4 overflow-y-auto p-3">
                    <section className="space-y-2 rounded border border-cad-border bg-black/20 p-3">
                        <div className="flex items-center justify-between gap-3">
                            <div>
                                <div className="text-[10px] font-black uppercase tracking-widest text-white">AI Runtime</div>
                                <div className="mt-1 text-[9px] uppercase tracking-wider text-cad-text-muted">{status?.state || "UNKNOWN"}</div>
                            </div>
                            <button onClick={() => updateLocalConfig("enable_ai", !config.enable_ai)} className="text-cad-accent">
                                {config.enable_ai ? <CheckSquare className="h-5 w-5" /> : <Square className="h-5 w-5" />}
                            </button>
                        </div>
                        <label className="flex items-center gap-2 text-[10px] font-bold uppercase text-cad-text-secondary">
                            <input type="checkbox" checked={config.low_power_mode} onChange={(e) => updateLocalConfig("low_power_mode", e.target.checked)} className="accent-cad-accent" />
                            Low power mode
                        </label>
                    </section>

                    <section className="space-y-3 rounded border border-cad-border bg-black/20 p-3">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-white">
                                <Download className="h-3.5 w-3.5 text-cad-accent" /> Local Models
                            </div>
                            <span className={cn("text-[9px] font-bold uppercase", localReady ? "text-green-400" : "text-yellow-400")}>{localReady ? "Ready" : "Required"}</span>
                        </div>
                        <div className="space-y-1">
                            {models.map((model) => (
                                <div key={model.id} className="flex items-center justify-between gap-2 rounded bg-black/25 px-2 py-1.5 text-[9px]">
                                    <span className="min-w-0 truncate font-bold text-cad-text-secondary">{model.role}: {model.version}</span>
                                    <span className={model.installed ? "text-green-400" : "text-cad-text-muted"}>{model.installed ? displayBytes(model.sizeBytes || model.size_bytes) : "missing"}</span>
                                </div>
                            ))}
                        </div>
                        {downloadProgress && (
                            <div className="rounded border border-cad-accent/20 bg-cad-accent/5 p-2">
                                <div className="flex justify-between text-[9px] font-bold uppercase text-cad-text-secondary">
                                    <span>{downloadProgress.model || "models"}: {downloadProgress.status}</span>
                                    <span>{progressPercent == null ? "" : `${progressPercent}%`}</span>
                                </div>
                                <div className="mt-1 h-1.5 overflow-hidden rounded bg-black/40">
                                    <div className="h-full bg-cad-accent transition-all" style={{ width: `${progressPercent || 15}%` }} />
                                </div>
                            </div>
                        )}
                        <div className="grid grid-cols-3 gap-2">
                            <button onClick={handleDownloadModels} disabled={status?.downloading} className="flex items-center justify-center gap-1 rounded bg-cad-accent px-2 py-1.5 text-[9px] font-black uppercase text-black disabled:opacity-50">
                                <RefreshCw className="h-3 w-3" /> Download
                            </button>
                            <button onClick={handleCancelDownload} disabled={!status?.downloading} className="flex items-center justify-center gap-1 rounded border border-cad-border px-2 py-1.5 text-[9px] font-black uppercase text-cad-text-secondary disabled:opacity-40">
                                <X className="h-3 w-3" /> Cancel
                            </button>
                            <button onClick={handleRemoveModels} className="flex items-center justify-center gap-1 rounded border border-red-800 px-2 py-1.5 text-[9px] font-black uppercase text-red-300">
                                <Trash2 className="h-3 w-3" /> Remove
                            </button>
                        </div>
                    </section>

                    <section className="space-y-3 rounded border border-cad-border bg-black/20 p-3">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-white">
                                <Globe className="h-3.5 w-3.5 text-cad-accent" /> Cloud Provider
                            </div>
                            <span className={cn("text-[9px] font-bold uppercase", cloudReady ? "text-green-400" : "text-cad-text-muted")}>{cloudReady ? "Ready" : "Optional"}</span>
                        </div>
                        <label className="flex items-center gap-2 text-[10px] font-bold uppercase text-cad-text-secondary">
                            <input type="checkbox" checked={config.provider_enabled} onChange={(e) => updateLocalConfig("provider_enabled", e.target.checked)} className="accent-cad-accent" />
                            Enable cloud
                        </label>
                        <input value={config.provider_base_url} onChange={(e) => updateLocalConfig("provider_base_url", e.target.value)} className="w-full rounded border border-cad-border bg-black/30 px-2 py-1.5 text-[10px] text-white outline-none focus:border-cad-accent" />
                        <input value={config.provider_model} onChange={(e) => updateLocalConfig("provider_model", e.target.value)} className="w-full rounded border border-cad-border bg-black/30 px-2 py-1.5 text-[10px] text-white outline-none focus:border-cad-accent" />
                        <div className="grid grid-cols-2 gap-2">
                            <input type="number" value={config.max_tokens} onChange={(e) => updateLocalConfig("max_tokens", Number(e.target.value))} className="w-full rounded border border-cad-border bg-black/30 px-2 py-1.5 text-[10px] text-white outline-none" />
                            <input type="number" value={config.timeout_ms} onChange={(e) => updateLocalConfig("timeout_ms", Number(e.target.value))} className="w-full rounded border border-cad-border bg-black/30 px-2 py-1.5 text-[10px] text-white outline-none" />
                        </div>
                        <label className="flex items-center gap-2 text-[10px] font-bold uppercase text-cad-text-secondary">
                            <input type="checkbox" checked={config.cloud_confirm_each_request} onChange={(e) => updateLocalConfig("cloud_confirm_each_request", e.target.checked)} className="accent-cad-accent" />
                            Confirm every cloud request
                        </label>
                        <div className="flex gap-2">
                            <input type="password" value={apiKey} onChange={(e) => setApiKey(e.target.value)} placeholder={hasApiKey ? "API key stored" : "OpenAI-compatible API key"} className="min-w-0 flex-1 rounded border border-cad-border bg-black/30 px-2 py-1.5 text-[10px] text-white outline-none" />
                            <button aria-label="Save AI API key" onClick={handleSaveApiKey} disabled={!apiKey.trim() || savingConfig} className="rounded bg-cad-accent px-2 text-black disabled:opacity-40"><KeyRound className="h-3.5 w-3.5" /></button>
                            <button aria-label="Delete AI API key" onClick={handleDeleteApiKey} disabled={!hasApiKey || savingConfig} className="rounded border border-red-800 px-2 text-red-300 disabled:opacity-40"><Trash2 className="h-3.5 w-3.5" /></button>
                        </div>
                    </section>
                </div>
            ) : (
                <>
                    {status?.state === "MODEL_REQUIRED" && (
                        <div className="flex flex-col items-center justify-center gap-2.5 border-b border-cad-border bg-cad-elevated p-4 text-center">
                            <AlertTriangle className="h-8 w-8 text-yellow-500" />
                            <div className="font-bold text-white">Local Model Required</div>
                            <button onClick={() => setActiveTab("config")} className="rounded bg-cad-accent px-3 py-1.5 text-[10px] font-black uppercase text-black">Open Config</button>
                        </div>
                    )}

                    <div className="custom-scrollbar min-h-0 flex-1 space-y-4 overflow-y-auto p-3">
                        {messages.length === 0 && (
                            <div className="flex h-full flex-col items-center justify-center gap-2.5 p-6 text-center text-cad-text-muted">
                                <Sparkles className="h-10 w-10 opacity-35" />
                                <div className="font-display text-[10px] font-black uppercase tracking-widest">AI CAD Assistant</div>
                                <p className="max-w-[240px] text-[10px] leading-relaxed">Ask about project metadata, files, features, task estimates, or request proposed updates.</p>
                            </div>
                        )}

                        {messages.map((msg, idx) => (
                            <div key={msg.id || idx} className={cn("flex max-w-[88%] flex-col rounded-lg border p-2.5 transition-all", msg.role === "user" ? "ml-auto border-cad-border/70 bg-cad-elevated text-cad-text-primary" : "mr-auto border-cad-border/30 bg-black/25 text-cad-text-secondary")}>
                                <div className="whitespace-pre-wrap break-words leading-relaxed">{msg.content}</div>
                                {msg.citations && msg.citations.length > 0 && (
                                    <div className="mt-2.5 space-y-1 border-t border-cad-border/30 pt-2">
                                        <div className="text-[9px] font-black uppercase tracking-wider text-cad-text-muted">References</div>
                                        {msg.citations.map((cit, cIdx) => (
                                            <div key={`${cit.sourceId || cit.source_id || cIdx}`} className="rounded border border-cad-border/20 bg-black/15 p-1 text-[9px] leading-snug">
                                                <div className="flex justify-between gap-2 font-bold text-white">
                                                    <span className="truncate">[{cIdx + 1}] {cit.title}</span>
                                                    <span className="text-cad-accent opacity-85">{Math.round((cit.score || 0) * 100)}%</span>
                                                </div>
                                                <div className="mt-0.5 truncate text-cad-text-muted">{cit.snippet}</div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                                {msg.actionProposals && msg.actionProposals.length > 0 && (
                                    <div className="mt-2.5 space-y-2 border-t border-cad-border/30 pt-2.5">
                                        <div className="flex items-center gap-1 text-[9px] font-black uppercase tracking-wider text-yellow-500">
                                            <AlertTriangle className="h-3.5 w-3.5" /> Proposed Action Diff
                                        </div>
                                        {msg.actionProposals.map((prop) => (
                                            <div key={prop.id} className="space-y-2 rounded border border-yellow-600/30 bg-black/20 p-2 text-[9px]">
                                                <div className="flex justify-between gap-2 font-bold uppercase tracking-wider text-white">
                                                    <span>Type: {prop.actionType || prop.action_type}</span>
                                                    <span>Target: {prop.targetTable || prop.target_table}</span>
                                                </div>
                                                <pre className="custom-scrollbar overflow-x-auto rounded bg-black/40 p-1.5 font-mono text-[8px] text-yellow-400/90 select-text">{JSON.stringify(prop.diff, null, 2)}</pre>
                                                <div className="flex justify-end gap-1.5">
                                                    <button onClick={() => handleRejectAction(prop.id)} className="flex items-center gap-0.5 rounded border border-red-800 bg-red-950 px-2 py-1 font-bold text-red-300">
                                                        <X className="h-3 w-3" /> Reject
                                                    </button>
                                                    <button onClick={() => handleConfirmAction(prop.id)} className="flex items-center gap-0.5 rounded border border-green-800 bg-green-950 px-2 py-1 font-bold text-green-300">
                                                        <Check className="h-3 w-3" /> Accept
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        ))}
                        <div ref={messagesEndRef} />
                    </div>

                    {showCloudConsent && (
                        <div className="flex flex-col gap-2.5 border-t border-cad-border bg-cad-elevated p-3">
                            <div className="flex items-center gap-2 font-bold text-yellow-500">
                                <Globe className="h-4 w-4" />
                                <span>Cloud AI Data Scope Consent</span>
                            </div>
                            <p className="text-[10px] leading-normal text-cad-text-secondary">This request will send the message and local citation snippets to the configured OpenAI-compatible endpoint.</p>
                            <pre className="max-h-[90px] overflow-y-auto rounded bg-black/30 p-2 font-mono text-[8px] text-cad-text-muted">{JSON.stringify({ message: pendingCloudText, projectId, projectPath, featureCount }, null, 2)}</pre>
                            <div className="flex justify-end gap-2">
                                <button onClick={() => setShowCloudConsent(false)} className="rounded border border-cad-border px-2.5 py-1.5 text-[10px] font-bold uppercase text-cad-text-secondary">Cancel</button>
                                <button onClick={handleConfirmCloudSend} className="rounded bg-cad-accent px-2.5 py-1.5 text-[10px] font-bold uppercase text-black">Confirm & Send</button>
                            </div>
                        </div>
                    )}

                    {!showCloudConsent && (
                        <div className="space-y-1.5 border-t border-cad-border bg-cad-elevated/40 p-2">
                            <div className="flex items-center justify-between px-1">
                                <button onClick={() => setAllowCloud(!allowCloud)} className="flex items-center gap-1 text-[9px] font-bold text-cad-text-secondary hover:text-white">
                                    {allowCloud ? <CheckSquare className="h-3.5 w-3.5 text-cad-accent" /> : <Square className="h-3.5 w-3.5" />}
                                    <span>ALLOW CLOUD</span>
                                </button>
                                <span className="truncate text-[8px] uppercase text-cad-text-muted" title={chatDisabledReason || undefined}>{chatDisabledReason || "Ready"}</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <input
                                    type="text"
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    onKeyDown={(e) => e.key === "Enter" && void handleSendMessage()}
                                    placeholder="Type a query or command..."
                                    disabled={!!chatDisabledReason}
                                    className="min-w-0 flex-1 rounded-md border border-cad-border bg-black/30 px-2.5 py-2 font-display text-white placeholder-cad-text-muted outline-none transition-all focus:border-cad-accent disabled:opacity-50"
                                />
                                <button aria-label="Send AI message" onClick={handleSendMessage} disabled={!!chatDisabledReason || !inputValue.trim()} className="shrink-0 rounded-md bg-cad-accent p-2 text-white transition-all hover:opacity-90 disabled:opacity-40">
                                    <Send className="h-4 w-4" />
                                </button>
                            </div>
                        </div>
                    )}
                </>
            )}

            {activeTab === "config" && (
                <div className="border-t border-cad-border bg-cad-elevated/40 p-3">
                    <button onClick={handleSaveConfig} disabled={savingConfig} className="flex w-full items-center justify-center gap-2 rounded bg-cad-accent py-2 text-[10px] font-black uppercase tracking-widest text-black transition-all hover:bg-white disabled:opacity-50">
                        {savingConfig ? <RefreshCw className="h-3.5 w-3.5 animate-spin" /> : <Save className="h-3.5 w-3.5" />}
                        Save AI Config
                    </button>
                </div>
            )}
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';
import {
    Settings, Save,
    Video, Ruler, Activity, ChevronDown, ChevronRight, Map as MapIcon, Layers
} from "lucide-react";
import {
    getFeatureDisplayInfo,
    getPointCoordinates,
    getEffectiveMountingHeight,
    getEffectiveCameraSpecs
} from '@TOOL/utils/featureUtils';
import {
    calculateHFOV,
    calculatePPM,
    getDORICategory,
    mapRotationToHeading,
    mapHeadingToRotation,
    calculateDORIDistance
} from '@TOOL/utils/cameraMath';
import { RecognitionSimulator } from '@DESIGN/features/map/Palette/RecognitionSimulator';
import { usePaletteContext } from '@DESIGN/features/map/Palette/PaletteContext';
import { X } from 'lucide-react';
import { useSettingsStore } from '@IMPLEMENT/stores/useSettingsStore';
import { cn } from '@TOOL/utils/cn';
import { DORILegend } from '@DESIGN/features/map/MapLayerComponents/DORILegend';
import { InteractiveStreetViewPreview } from './InteractiveStreetViewPreview';
import { CameraHudFallback } from './CameraHudFallback';
import { normalizeMetadataObject } from '@TOOL/utils/metadataNormalization';
import { buildFeaturePropertiesForPersistence } from '@TOOL/utils/featurePersistence';

const SENSOR_SIZES = {
    '1/3"': { width: 4.8, height: 3.6 },
    '1/2.8"': { width: 5.6, height: 4.2 },
    '1/1.8"': { width: 7.2, height: 5.4 },
    '1/1.2"': { width: 10.6, height: 8.0 },
    'Full Frame': { width: 36.0, height: 24.0 }
} as const;

export const CameraViewPanel: React.FC = () => {
    const { onPin, onClose, isPinned, dragHandleProps } = usePaletteContext();
    const {
        state,
        selectedFeatureId,
        setPreview,
        queueEvent,
        previewMetadata,
        selectionSet
    } = useDesignSync();
    const { lowPowerMode } = useSettingsStore(); // Added
    const showDORILayers = useDesignSync(s => s.showDORILayers);
    const setShowDORILayers = useDesignSync(s => s.setShowDORILayers);

    const feature = selectedFeatureId && state?.features ? state.features[selectedFeatureId] : null;
    const group = feature?.group_id ? state?.feature_groups?.[feature.group_id] : null;
    const displayInfo = feature && group ? getFeatureDisplayInfo(feature, group.type, group.name) : null;

    const [localMeta, setLocalMeta] = useState<any>({});
    const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
        specs: true,
        simulation: true,
        recognition: false
    });
    const [hoveredDori, setHoveredDori] = useState<string | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    const getMetaValue = (path: string, defaultValue: any, source: any = localMeta) => {
        const parts = path.split('.');
        let current = source;
        for (const part of parts) {
            if (current == null) return defaultValue;
            current = current[part];
        }
        return current ?? defaultValue;
    };

    useEffect(() => {
        let cancelled = false;
        const syncTimer = window.setTimeout(() => {
            if (cancelled) return;

            if (!feature) {
                setLocalMeta({});
                return;
            }

            try {
                const parsed = typeof feature.metadata === 'string'
                    ? JSON.parse(feature.metadata || '{}')
                    : (feature.metadata || {});
                setLocalMeta(parsed);
            } catch {
                setLocalMeta({});
            }
        }, 0);

        return () => {
            cancelled = true;
            window.clearTimeout(syncTimer);
        };
    }, [feature?.id, feature?.metadata]);

    // Update localMeta when previewMetadata changes (sync from other palettes)
    useEffect(() => {
        if (previewMetadata?.id === selectedFeatureId && previewMetadata.metadata) {
            const syncTimer = window.setTimeout(() => {
                setLocalMeta((prev: any) => {
                    if (JSON.stringify(prev) !== JSON.stringify(previewMetadata.metadata)) {
                        return previewMetadata.metadata;
                    }
                    return prev;
                });
            }, 0);
            return () => window.clearTimeout(syncTimer);
        }
    }, [previewMetadata, selectedFeatureId]);


    // Effective metadata: use preview override if it matches current feature
    const effectiveMeta = (previewMetadata?.id === selectedFeatureId && previewMetadata.metadata)
        ? previewMetadata.metadata
        : localMeta;

    const rotation = getMetaValue('gis.rotation', 0, effectiveMeta);

    // Verification for multi-selection handled in main return block to avoid hook violations.

    // Verification for multi-selection handled in main return block to avoid hook violations.

    const updateNestedMeta = (path: string, value: any) => {
        const newMeta = { ...localMeta };
        const parts = path.split('.');
        let current = newMeta;
        for (let i = 0; i < parts.length - 1; i++) {
            if (!current[parts[i]]) current[parts[i]] = {};
            current = current[parts[i]];
        }
        current[parts[parts.length - 1]] = value;
        setLocalMeta(newMeta);
        setPreview(selectedFeatureId!, newMeta);
    };

    const toggleSection = (section: string) => {
        setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
    };

    let persistedMetaJson = '{}';
    if (feature) {
        try {
            const parsed = typeof feature.metadata === 'string'
                ? JSON.parse(feature.metadata || '{}')
                : (feature.metadata || {});
            persistedMetaJson = JSON.stringify(parsed);
        } catch {
            persistedMetaJson = '{}';
        }
    }
    const isDirty = !!feature && JSON.stringify(effectiveMeta || {}) !== persistedMetaJson;

    const handleSave = async () => {
        if (!selectedFeatureId || !isDirty || isSaving) return;
        setIsSaving(true);

        try {
            const standardizedMeta = normalizeMetadataObject(effectiveMeta);
            await queueEvent({
                type: 'FeatureUpdated',
                payload: {
                    id: selectedFeatureId,
                    ...(previewMetadata?.id === selectedFeatureId && previewMetadata.name !== undefined
                        ? { name: previewMetadata.name }
                        : {}),
                    metadata: JSON.stringify(standardizedMeta),
                    properties: buildFeaturePropertiesForPersistence(feature?.properties, standardizedMeta),
                },
            });
            setPreview(null, null);
        } catch (error) {
            console.error('[CameraViewPanel] Save failed:', error);
        } finally {
            setIsSaving(false);
        }
    };

    // Verification for multi-selection handled in main return block to avoid hook violations.
    if (!feature || !displayInfo) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-cad-text-muted bg-[#1e1e1e] p-4 text-center border border-[#333] shadow-2xl font-mono">
                <div className="flex items-center justify-between w-full absolute top-0 p-3 border-b border-[#333] bg-[#252525] drag-handle cursor-move rounded-t-xl" {...dragHandleProps}>
                    <div className="flex items-center gap-2">
                        <Video className="w-3.5 h-3.5 text-[#444]" />
                        <span className="text-[10px] font-black tracking-widest uppercase text-cad-text-muted">Camera View</span>
                    </div>
                    <button onClick={onClose} className="p-1 text-cad-text-muted hover:bg-[#333] hover:text-white transition-all rounded"><X size={12} /></button>
                </div>
                <Video className="w-10 h-10 mb-4 text-[#444] animate-pulse" />
                <p className="text-[10px] font-black uppercase tracking-widest text-cad-text-muted">Chưa chọn thiết bị</p>
                <p className="text-[9px] mt-2 text-cad-text-muted max-w-[200px]">
                    Vui lòng chọn một camera để xem mô phỏng hình ảnh tại vị trí lắp đặt.
                </p>
            </div>
        );
    }

    const coords = getPointCoordinates(feature);

    if (selectionSet.size > 1) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-cad-text-muted bg-[#1e1e1e] p-4 text-center opacity-50 border border-[#333] shadow-2xl font-mono">
                <Layers className="w-8 h-8 mb-4 text-cad-accent" />
                <p className="text-[10px] font-black uppercase tracking-widest text-cad-text-muted">Multi-Selection</p>
                <p className="text-[9px] mt-2 text-cad-text-muted">
                    Simulation is disabled for multiple devices.
                </p>
            </div>
        );
    }

    const { focalLength, sensorSize, resolutionX } = getEffectiveCameraSpecs(feature, state?.settings, effectiveMeta);
    const installHeight = getEffectiveMountingHeight(feature, state?.settings, effectiveMeta);
    const targetDistance = getMetaValue('specs.target_distance', 20, effectiveMeta);
    const targetHeight = getMetaValue('specs.target_height', 1.7, effectiveMeta);

    const sensor = SENSOR_SIZES[sensorSize as keyof typeof SENSOR_SIZES] || SENSOR_SIZES['1/2.8"'];
    const hfov = calculateHFOV(sensor.width, focalLength);
    const ppm = calculatePPM(resolutionX, targetDistance, hfov, installHeight, targetHeight);
    const dori = getDORICategory(ppm);

    return (
        <div className={cn(
            "flex flex-col h-full bg-[#1e1e1e] text-white font-mono select-none rounded-xl border border-[#333] shadow-2xl overflow-hidden",
            !lowPowerMode && "backdrop-blur-md"
        )}>
            {/* Header */}
            <div
                {...dragHandleProps}
                className="flex items-center justify-between p-3 border-b border-[#333] bg-[#252525] drag-handle cursor-move sticky top-0"
            >
                <div className="flex items-center gap-2">
                    <Video className="w-3.5 h-3.5 text-cad-accent" />
                    <span className="text-[10px] font-black tracking-widest uppercase text-cad-accent">
                        GÓC NHÌN
                    </span>
                    {(isDirty || isSaving) && <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />}
                </div>
                <div className="flex items-center gap-1">
                    {(isDirty || isSaving) && (
                        <button
                            onClick={handleSave}
                            disabled={isSaving}
                            className="p-1 px-2 flex items-center gap-1.5 rounded transition-colors text-[9px] font-bold uppercase border hover:bg-blue-500/20 text-blue-400 border-blue-500/10 group disabled:opacity-50 disabled:cursor-not-allowed"
                            title="Lưu thay đổi"
                        >
                            <Save className="w-3 h-3" /> Save
                        </button>
                    )}
                    <button
                        onClick={onPin}
                        className={`p-1 px-2 hover:bg-[#333] transition-colors rounded text-[9px] font-bold uppercase ${isPinned ? 'text-cad-accent bg-[#333]' : 'text-cad-text-muted'}`}
                        title={isPinned ? "Auto-hide" : "Pin"}
                    >
                        {isPinned ? 'Unpin' : 'Pin'}
                    </button>
                    <button
                        onClick={onClose}
                        className="p-1 px-2 hover:bg-[#333] text-cad-text-muted rounded transition-colors text-[9px] font-bold uppercase"
                    >
                        Close
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
                {/* 1. Technical Specifications */}
                <section className="space-y-4">
                    <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-[#555] uppercase">
                        <Settings className="w-3 h-3" /> Thông số kỹ thuật
                        <div className="flex-1" />
                        <button onClick={() => toggleSection('specs')} className="p-1 hover:bg-[#333] rounded text-cad-text-muted">
                            {expandedSections.specs ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </button>
                    </div>

                    {expandedSections.specs && (
                        <div className="space-y-4 bg-[#111] p-3 rounded border border-[#333]">
                            <div className="grid grid-cols-2 gap-3">
                                <div className="space-y-1">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Độ phân giải</label>
                                    <select
                                        value={resolutionX}
                                        onChange={(e) => updateNestedMeta('specs.resolution_x', parseInt(e.target.value))}
                                        className="w-full bg-[#111] border border-[#333] rounded px-2 py-1.5 text-xs text-white outline-none focus:border-cad-accent transition-all"
                                    >
                                        <option value={1280}>HD (1.3MP)</option>
                                        <option value={1920}>Full HD (2MP)</option>
                                        <option value={2560}>2K (4MP)</option>
                                        <option value={3840}>4K (8MP)</option>
                                    </select>
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Cảm biến</label>
                                    <select
                                        value={sensorSize}
                                        onChange={(e) => updateNestedMeta('specs.sensor_size', e.target.value)}
                                        className="w-full bg-[#111] border border-[#333] rounded px-2 py-1.5 text-xs text-white outline-none focus:border-cad-accent transition-all"
                                    >
                                        {Object.keys(SENSOR_SIZES).map(s => <option key={s} value={s}>{s}</option>)}
                                    </select>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-3">
                                <div className="space-y-1">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Tiêu cự (mm)</label>
                                    <input
                                        type="number"
                                        step="0.1"
                                        value={focalLength}
                                        onChange={(e) => updateNestedMeta('specs.focal_length', Number(e.target.value))}
                                        className="w-full bg-[#111] border border-[#333] rounded px-2 py-1.5 text-xs text-white outline-none focus:border-cad-accent transition-all"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Độ cao lắp (m)</label>
                                    <input
                                        type="number"
                                        step="0.5"
                                        value={installHeight}
                                        onChange={(e) => updateNestedMeta('specs.install_height', parseFloat(e.target.value))}
                                        className="w-full bg-[#111] border border-[#333] rounded px-2 py-1.5 text-xs text-white outline-none focus:border-cad-accent transition-all"
                                    />
                                </div>
                            </div>
                            <div className="flex justify-between items-center py-2 px-1 border-t border-[#333] mt-2">
                                <span className="text-[9px] text-cad-text-muted uppercase font-bold tracking-tighter ml-1">Góc nhìn ngang (HFOV)</span>
                                <span className="text-[10px] font-mono font-bold text-cad-accent mr-1">
                                    {hfov.toFixed(1)}°
                                </span>
                            </div>
                        </div>
                    )}
                </section>

                {/* 2. Simulated View */}
                <section className="space-y-4">
                    <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-[#555] uppercase">
                        <MapIcon className="w-3 h-3 text-green-400" /> Mô phỏng Góc nhìn
                        <div className="flex-1" />
                        <button onClick={() => toggleSection('simulation')} className="p-1 hover:bg-[#333] rounded text-cad-text-muted">
                            {expandedSections.simulation ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </button>
                    </div>

                    {expandedSections.simulation && (
                        <div className="bg-[#111] p-3 rounded border border-[#333]">
                            <InteractiveStreetViewPreview
                                lat={coords?.[1] ?? NaN}
                                lng={coords?.[0] ?? NaN}
                                heading={mapRotationToHeading(rotation)}
                                fov={hfov}
                                onHeadingChange={(newHeading) => {
                                    const newRotation = mapHeadingToRotation(newHeading);
                                    updateNestedMeta('gis.rotation', newRotation);
                                }}
                                fallback={
                                    <CameraHudFallback
                                        hfov={hfov}
                                        targetDistance={targetDistance}
                                        installHeight={installHeight}
                                        targetHeight={targetHeight}
                                        rotation={rotation}
                                        ppm={ppm}
                                        statusLabel={ppm < 25 ? 'Không đạt' : ppm < 125 ? 'Tổng quan' : 'Chi tiết'}
                                        statusColor={dori.color}
                                    />
                                }
                            />
                        </div>
                    )}
                </section>

                {/* 3. Simulated Recognition (DORI) */}
                <section className="space-y-4">
                    <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-[#555] uppercase">
                        <Activity className="w-3 h-3 text-purple-400" /> Chất lượng Nhận diện
                        <div className="flex-1" />
                        <button onClick={() => toggleSection('recognition')} className="p-1 hover:bg-[#333] rounded text-cad-text-muted">
                            {expandedSections.recognition ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </button>
                    </div>

                    {expandedSections.recognition && (
                        <div className="space-y-6 bg-[#111] p-3 rounded border border-[#333]">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-1">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Mục tiêu (m)</label>
                                    <input
                                        type="number"
                                        step="0.1"
                                        value={targetHeight}
                                        onChange={(e) => updateNestedMeta('specs.target_height', parseFloat(e.target.value))}
                                        className="w-full bg-[#111] border border-[#333] rounded px-2 py-1.5 text-xs text-white outline-none focus:border-cad-accent transition-all"
                                    />
                                </div>
                                <div className="space-y-1">
                                    <div className="flex justify-between items-center h-full pt-4">
                                        <span className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">PPM</span>
                                        <span className="text-[12px] font-mono font-bold text-white mr-1">{Math.round(ppm)}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="space-y-2 pt-2">
                                <div className="flex justify-between items-end">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase flex items-center gap-1 tracking-tighter ml-1">
                                        <Ruler className="w-3 h-3" /> Khoảng cách
                                    </label>
                                    <div className="text-[10px] font-mono text-cad-text-muted mr-1">
                                        {targetDistance}m
                                    </div>
                                </div>
                                <input
                                    type="range" min="1" max="200" step="1"
                                    value={targetDistance}
                                    onChange={(e) => updateNestedMeta('specs.target_distance', parseInt(e.target.value))}
                                    className="w-full h-1.5 bg-[#333] rounded-lg appearance-none cursor-pointer accent-purple-400"
                                />
                            </div>

                            {/* 2D Cross Section */}
                            <div className="space-y-2 pt-4 border-t border-[#333]">
                                <div className="flex justify-between items-center">
                                    <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Mặt cắt dọc</label>
                                    <button
                                        onClick={() => setShowDORILayers(!showDORILayers)}
                                        className={`px-2 py-0.5 rounded text-[8px] font-bold uppercase transition-all border ${showDORILayers ? 'bg-purple-500/20 border-purple-500/30 text-purple-400' : 'bg-transparent border-[#333] text-gray-500'}`}
                                    >
                                        DORI Map
                                    </button>
                                </div>
                                <div className="h-32 bg-[#161616] rounded-lg border border-[#333] overflow-hidden relative flex items-center justify-center p-1">
                                    <svg viewBox="0 0 300 125" className="w-full h-full overflow-visible">
                                        <defs>
                                            <linearGradient id="groundGrad" x1="0" y1="0" x2="0" y2="1">
                                                <stop offset="0%" stopColor="#222" />
                                                <stop offset="100%" stopColor="#111" />
                                            </linearGradient>
                                        </defs>

                                        {(() => {
                                            const camX = 25;
                                            const camY = 90 - (installHeight * 14.5);
                                            const scaleX = 4.2;

                                            const doriLevels = [
                                                { id: 'DET', ppm: 25, color: '#06b6d4', label: 'D' },
                                                { id: 'OBS', ppm: 62, color: '#10b981', label: 'O' },
                                                { id: 'REC', ppm: 125, color: '#f59e0b', label: 'R' },
                                                { id: 'ID', ppm: 250, color: '#ef4444', label: 'I' }
                                            ];

                                            const ranges = doriLevels.map(l => ({
                                                ...l,
                                                d: calculateDORIDistance(resolutionX, hfov, l.ppm, installHeight, targetHeight)
                                            })).sort((a, b) => b.d - a.d);

                                            return (
                                                <g>
                                                    {/* Background Grid Lines */}
                                                    {[0, 20, 40, 60].map(d => (
                                                        <g key={d}>
                                                            <line x1={camX + d * scaleX} y1="10" x2={camX + d * scaleX} y2="90" stroke="#333" strokeWidth="0.5" strokeDasharray="2, 4" />
                                                            <text x={camX + d * scaleX} y="112" textAnchor="middle" fill="#888" fontSize="7" fontWeight="bold">{d}m</text>
                                                        </g>
                                                    ))}

                                                    <rect x="0" y="90" width="300" height="35" fill="url(#groundGrad)" />
                                                    <line x1="0" y1="90" x2="300" y2="90" stroke="#444" strokeWidth="1" />

                                                    {showDORILayers && (
                                                        <g>
                                                            <defs>
                                                                {doriLevels.map(l => (
                                                                    <linearGradient key={`grad-${l.id}`} id={`grad-${l.id}`} x1="0%" y1="0%" x2="100%" y2="100%">
                                                                        <stop offset="0%" stopColor={l.color} stopOpacity="0.4" />
                                                                        <stop offset="100%" stopColor={l.color} stopOpacity="0.05" />
                                                                    </linearGradient>
                                                                ))}
                                                            </defs>
                                                            {ranges.map((range, i) => {
                                                                const nextD = i < ranges.length - 1 ? ranges[i + 1].d : 0;
                                                                const p1 = Math.min(295, camX + range.d * scaleX);
                                                                const p2 = Math.min(295, camX + nextD * scaleX);
                                                                const isActive = hoveredDori === range.id;

                                                                return (
                                                                    <g key={range.id}>
                                                                        <path
                                                                            d={`M ${camX} ${camY} L ${p1} 90 L ${p2} 90 Z`}
                                                                            fill={`url(#grad-${range.id})`}
                                                                            onMouseEnter={() => setHoveredDori(range.id)}
                                                                            onMouseLeave={() => setHoveredDori(null)}
                                                                            style={{
                                                                                opacity: (hoveredDori && !isActive) ? 0.2 : 0.8,
                                                                                stroke: isActive ? range.color : 'none',
                                                                                strokeWidth: 1,
                                                                                cursor: 'pointer'
                                                                            }}
                                                                            className="transition-all duration-300"
                                                                        />
                                                                        {/* DORI Markers at the top */}
                                                                        <line x1={p1} y1={camY - 5} x2={p1} y2="90" stroke={range.color} strokeWidth="0.5" strokeDasharray="1, 2" opacity="0.3" />
                                                                        <text x={p1} y={Math.max(10, camY - 8)} textAnchor="middle" fill={range.color} fontSize="8" fontWeight="black" opacity="0.8">{range.label}</text>
                                                                        <text x={p1} y="102" textAnchor="middle" fill={range.color} fontSize="7" fontWeight="bold" opacity="0.6">{Math.round(range.d)}m</text>
                                                                    </g>
                                                                );
                                                            })}
                                                        </g>
                                                    )}

                                                    {/* Camera Pole & Height Label */}
                                                    <g>
                                                        <line x1={camX} y1="90" x2={camX} y2={camY} stroke="#666" strokeWidth="1.5" />
                                                        <circle cx={camX} cy={camY} r="3" fill="#fb923c" />
                                                        <text x={camX - 4} y={(camY + 90) / 2} textAnchor="end" fill="#fb923c" fontSize="8" fontWeight="bold" className="tabular-nums">
                                                            {installHeight}m
                                                        </text>
                                                    </g>

                                                    {/* Target Indicator */}
                                                    {(() => {
                                                        const tx = camX + targetDistance * scaleX;
                                                        const ty = 90 - (targetHeight * 14.5);
                                                        if (tx > 300) return null;
                                                        return (
                                                            <g>
                                                                <line x1={tx} y1="90" x2={tx} y2={ty} stroke="#f472b6" strokeWidth="1.5" strokeDasharray="2, 2" />
                                                                <rect x={tx - 2} y={ty - 12} width="4" height="12" fill="#f472b6" rx="1" />
                                                                <circle cx={tx} cy={ty - 14} r="2" fill="#f472b6" />
                                                                <text x={tx + 5} y={ty - 10} fill="#f472b6" fontSize="8" fontWeight="bold">{targetDistance}m</text>
                                                            </g>
                                                        );
                                                    })()}
                                                </g>
                                            );
                                        })()}
                                    </svg>
                                </div>
                            </div>

                            {/* Recognition Simulator - Simplified in low power mode */}
                            <div className="pt-4 border-t border-[#333]">
                                {lowPowerMode ? (
                                    <div className="flex items-center gap-2 p-2 bg-[#252525] rounded text-[9px] text-cad-text-muted italic border border-[#333]">
                                        <Activity className="w-3 h-3 text-cad-accent" />
                                        Mô phỏng nhận diện đã được đơn giản hóa trong chế độ tiết kiệm điện.
                                    </div>
                                ) : (
                                    <RecognitionSimulator ppm={ppm} />
                                )}
                            </div>

                            {/* DORI Legend Integration */}
                            <div className="mt-4 pt-4 border-t border-[#333]">
                                <DORILegend />
                            </div>
                        </div>
                    )}
                </section>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';
import {
    Eye, EyeOff, Compass, Settings, Save, Wand2,
    ChevronDown, ChevronRight, Layers, X, Check
} from "lucide-react";
import { usePaletteContext } from '@DESIGN/features/map/Palette/PaletteContext';
import {
    getFeatureDisplayInfo,
        getPointCoordinates,
        calculateNearestRoadAngle,
} from '@TOOL/utils/featureUtils';
import { normalizeMetadataObject } from '@TOOL/utils/metadataNormalization';
import { buildFeaturePropertiesForPersistence } from '@TOOL/utils/featurePersistence';


export const DeviceConfigPanel: React.FC = () => {
    const { onPin, onClose, isPinned, dragHandleProps } = usePaletteContext();
    const {
        state,
        selectedFeatureId,
        setPreview,
        queueEvent,
        previewMetadata,
        selectionSet
    } = useDesignSync();

    const showDORILayers = useDesignSync(s => s.showDORILayers);
    const setShowDORILayers = useDesignSync(s => s.setShowDORILayers);

    const feature = selectedFeatureId && state?.features ? state.features[selectedFeatureId] : null;
    const group = feature?.group_id ? state?.feature_groups?.[feature.group_id] : null;
    const displayInfo = feature && group ? getFeatureDisplayInfo(feature, group.type, group.name) : null;

    const [localMeta, setLocalMeta] = useState<any>({});
    const [showSuccess, setShowSuccess] = useState(false);
    const [expandedSections, setExpandedSections] = useState<Record<string, boolean>>({
        gis: true,
        sim: true
    });

    useEffect(() => {
        let cancelled = false;
        const syncTimer = window.setTimeout(() => {
            if (cancelled) return;

            if (!feature) {
                setLocalMeta({});
                return;
            }

            try {
                const parsed = typeof feature.metadata === 'string'
                    ? JSON.parse(feature.metadata || '{}')
                    : (feature.metadata || {});
                setLocalMeta(parsed);
            } catch (e) {
                console.warn('[DeviceConfigPanel] Failed to parse feature metadata:', e);
                setLocalMeta({});
            }
        }, 0);

        return () => {
            cancelled = true;
            window.clearTimeout(syncTimer);
        };
    }, [feature?.id, feature?.metadata]);

    // Sync with previewMetadata (from other palettes)
    useEffect(() => {
        if (previewMetadata?.id === selectedFeatureId && previewMetadata.metadata) {
            const syncTimer = window.setTimeout(() => {
                setLocalMeta((prev: any) => {
                    const incoming = previewMetadata.metadata;
                    if (JSON.stringify(prev) !== JSON.stringify(incoming)) {
                        return incoming;
                    }
                    return prev;
                });
            }, 0);
            return () => window.clearTimeout(syncTimer);
        }
    }, [previewMetadata, selectedFeatureId]);

    // Debounced Preview for Map rendering
    useEffect(() => {
        if (!selectedFeatureId || !localMeta) return;

        // Skip preview if matching persisted state to avoid re-render loops
        const currentMetaJson = JSON.stringify(localMeta);
        const featureMeta = typeof feature?.metadata === 'string'
            ? feature.metadata
            : JSON.stringify(feature?.metadata || {});

        if (currentMetaJson === featureMeta) return;

        const timer = setTimeout(() => {
            setPreview(selectedFeatureId, localMeta);
        }, 50); // Small debounce to avoid jank on sliders

        return () => clearTimeout(timer);
    }, [localMeta, selectedFeatureId, setPreview]);

    // Multi-selection check moved below hooks to avoid violation.



    const getMetaValue = (path: string, defaultValue: any) => {
        const parts = path.split('.');
        let current = localMeta;
        for (const part of parts) {
            if (current == null) return defaultValue;
            current = current[part];
        }
        return current ?? defaultValue;
    };

    const updateNestedMeta = (path: string, value: any) => {
        const newMeta = { ...localMeta };
        const parts = path.split('.');
        let current = newMeta;
        for (let i = 0; i < parts.length - 1; i++) {
            const part = parts[i];
            const nextLevel = current[part];
            current[part] = nextLevel && typeof nextLevel === 'object'
                ? { ...nextLevel }
                : {};
            current = current[part];
        }
        current[parts[parts.length - 1]] = value;
        setLocalMeta(newMeta);
        if (selectedFeatureId) {
            setPreview(selectedFeatureId, newMeta);
        }
        return newMeta;
    };

    const handleAutoOrient = () => {
        const coords = getPointCoordinates(feature);
        if (!coords) return;

        const [lng, lat] = coords as [number, number];
        const angle = calculateNearestRoadAngle([lng, lat], Object.values(state?.features || {}));
        if (angle !== null) {
            updateNestedMeta('gis.rotation', Math.round(angle));
        }
    };

    const toggleSection = (section: string) => {
        setExpandedSections(prev => ({ ...prev, [section]: !prev[section] }));
    };

    let persistedMetaJson = '{}';
    if (feature) {
        try {
            const parsed = typeof feature.metadata === 'string'
                ? JSON.parse(feature.metadata || '{}')
                : (feature.metadata || {});
            persistedMetaJson = JSON.stringify(parsed);
        } catch (e) {
            console.warn('[DeviceConfigPanel] Failed to parse persisted metadata:', e);
            persistedMetaJson = '{}';
        }
    }
    const [isSaving, setIsSaving] = useState(false);
    const draftMeta = (previewMetadata?.id === selectedFeatureId && previewMetadata.metadata)
        ? previewMetadata.metadata
        : localMeta;
    const isDirty = !!feature && JSON.stringify(draftMeta || {}) !== persistedMetaJson;
    const rotation = getMetaValue('gis.rotation', 0);
    const showFov = getMetaValue('gis.show_fov', true);

    const handleSave = async () => {
        if (!selectedFeatureId || !isDirty || isSaving) return;
        setIsSaving(true);
        setShowSuccess(false);

        try {
            const standardizedMeta = normalizeMetadataObject(draftMeta);
            await queueEvent({
                type: 'FeatureUpdated',
                payload: {
                    id: selectedFeatureId,
                    ...(previewMetadata?.id === selectedFeatureId && previewMetadata.name !== undefined
                        ? { name: previewMetadata.name }
                        : {}),
                    metadata: JSON.stringify(standardizedMeta),
                    properties: buildFeaturePropertiesForPersistence(feature?.properties, standardizedMeta),
                },
            });
            setShowSuccess(true);
            setPreview(null, null);
            setTimeout(() => setShowSuccess(false), 1500);
        } catch (error) {
            console.error('[DeviceConfigPanel] Save failed:', error);
        } finally {
            setIsSaving(false);
        }
    };

    if (!feature || !displayInfo) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-cad-text-muted bg-[#1e1e1e] p-4 text-center border border-[#333] shadow-2xl font-mono">
                <div className="flex items-center justify-between w-full absolute top-0 p-3 border-b border-[#333] bg-[#252525] drag-handle cursor-move" {...dragHandleProps}>
                    <div className="flex items-center gap-2">
                        <Settings className="w-3.5 h-3.5 text-[#444]" />
                        <span className="text-[10px] font-black tracking-widest uppercase text-cad-text-muted">Device Configure</span>
                    </div>
                    <button onClick={onClose} className="p-1 text-cad-text-muted hover:bg-[#333] hover:text-white transition-all rounded"><X size={12} /></button>
                </div>
                <Compass className="w-10 h-10 mb-4 text-[#444] animate-pulse" />
                <p className="text-[10px] font-black uppercase tracking-widest text-cad-text-muted">Chưa chọn thiết bị</p>
                <p className="text-[9px] mt-2 text-cad-text-muted max-w-[200px]">
                    Vui lòng chọn một thiết bị trên bản đồ hoặc trong cây thư mục để chỉnh sửa hướng và thông số GIS.
                </p>
            </div>
        );
    }
    if (selectionSet.size > 1) {
        return (
            <div className="flex flex-col items-center justify-center h-full text-cad-text-muted bg-[#1e1e1e] p-4 text-center opacity-50 border border-[#333] shadow-2xl font-mono">
                <Layers className="w-8 h-8 mb-4 text-cad-accent" />
                <p className="text-[10px] font-black uppercase tracking-widest text-cad-text-muted">Chọn nhiều đối tượng</p>
                <p className="text-[9px] mt-2 text-cad-text-muted max-w-[200px]">
                    Vui lòng chỉ chọn một thiết bị để thay đổi thông số cấu hình.
                </p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full bg-[#1e1e1e] text-white font-mono select-none rounded-xl border border-[#333] shadow-2xl overflow-hidden">
            {/* Header */}
            <div
                {...dragHandleProps}
                className="flex items-center justify-between p-3 border-b border-[#333] bg-[#252525] drag-handle cursor-move sticky top-0"
            >
                <div className="flex items-center gap-2">
                    <Settings className="w-3.5 h-3.5 text-blue-400" />
                    <span className="text-[10px] font-black tracking-widest uppercase text-cad-accent">
                        Device Configure
                    </span>
                    {(isDirty || isSaving || showSuccess) && (
                        <div className={`w-1.5 h-1.5 rounded-full ${showSuccess ? 'bg-green-500' : 'bg-blue-500'} animate-pulse`} />
                    )}
                </div>
                <div className="flex gap-1">
                    {(isDirty || isSaving || showSuccess) && (
                        <button
                            onClick={handleSave}
                            disabled={isSaving || showSuccess}
                            className={`p-1 px-2 flex items-center gap-1.5 rounded transition-colors text-[9px] font-bold uppercase border ${showSuccess ? 'bg-green-500/20 text-green-400 border-green-500/30' : 'hover:bg-blue-500/20 text-blue-400 border-blue-500/10'
                                }`}
                            title="Lưu thay đổi"
                        >
                            {showSuccess ? <Check size={12} /> : <Save size={12} />}
                            {showSuccess ? 'Done' : 'Save'}
                        </button>
                    )}
                    <button
                        onClick={onPin}
                        className={`p-1 px-2 hover:bg-[#333] transition-colors rounded text-[9px] font-bold uppercase ${isPinned ? 'text-cad-accent bg-[#333]' : 'text-cad-text-muted'}`}
                        title={isPinned ? "Auto-hide" : "Pin"}
                    >
                        {isPinned ? 'Unpin' : 'Pin'}
                    </button>
                    <button
                        onClick={onClose}
                        className="p-1 px-2 hover:bg-[#333] text-cad-text-muted rounded transition-colors text-[9px] font-bold uppercase"
                    >
                        Close
                    </button>
                </div>
            </div>

            <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
                {/* 1. GIS Location & Orientation */}
                <section className="space-y-4">
                    <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-[#555] uppercase">
                        <Compass className="w-3 h-3" /> Tọa độ & Hướng
                        <div className="flex-1" />
                        <button onClick={() => toggleSection('gis')} className="p-1 hover:bg-[#333] rounded text-cad-text-muted">
                            {expandedSections.gis ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                        </button>
                    </div>

                    {expandedSections.gis && (
                        <div className="space-y-4 bg-[#111] p-3 rounded border border-[#333]">
                            {/* Layer Toggles */}
                            <div className="grid grid-cols-2 gap-2">
                                <button
                                    onClick={() => updateNestedMeta('gis.show_fov', !showFov)}
                                    className={`flex items-center justify-center gap-1.5 py-1.5 rounded text-[9px] font-bold uppercase transition-all border ${showFov
                                        ? 'bg-blue-500/20 text-blue-400 border-blue-500/30'
                                        : 'bg-[#252525] border-[#333] text-cad-text-muted hover:bg-[#333]'
                                        }`}
                                >
                                    {showFov ? <Eye size={12} /> : <EyeOff size={12} />}
                                    FOV
                                </button>
                                <button
                                    onClick={() => setShowDORILayers(!showDORILayers)}
                                    className={`flex items-center justify-center gap-1.5 py-1.5 rounded text-[9px] font-bold uppercase transition-all border ${showDORILayers
                                        ? 'bg-purple-500/20 text-purple-400 border-purple-500/30'
                                        : 'bg-[#252525] border-[#333] text-cad-text-muted hover:bg-[#333]'
                                        }`}
                                >
                                    {showDORILayers ? <Eye size={12} /> : <EyeOff size={12} />}
                                    DORI
                                </button>
                            </div>

                            <div className="space-y-4 pt-2">
                                <div className="space-y-2">
                                    <div className="flex justify-between items-center">
                                        <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Góc xoay (360°)</label>
                                        <span className="text-[10px] font-mono text-cad-orange font-bold mr-1">{rotation}°</span>
                                    </div>
                                    <div className="flex gap-2">
                                        <input
                                            type="range" min="0" max="359" step="1"
                                            value={rotation}
                                            onChange={(e) => updateNestedMeta('gis.rotation', parseInt(e.target.value))}
                                            className="flex-1 h-1.5 bg-[#333] rounded-lg appearance-none cursor-pointer accent-cad-orange my-auto"
                                        />
                                        <button
                                            onClick={handleAutoOrient}
                                            className="p-1.5 bg-[#252525] border border-[#333] hover:bg-[#333] hover:border-cad-accent rounded text-cad-text-muted hover:text-white transition-all group"
                                            title="Tự động hướng ra đường"
                                        >
                                            <Wand2 size={12} className="group-hover:text-blue-400" />
                                        </button>
                                    </div>
                                </div>

                                <div className="space-y-2 pt-4 border-t border-[#333]/50">
                                    <div className="flex justify-between items-center">
                                        <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Góc nhìn (FOV)</label>
                                        <span className="text-[10px] font-mono text-blue-400 font-bold mr-1">{getMetaValue('gis.fov_angle', 90)}°</span>
                                    </div>
                                    <div className="flex gap-2">
                                        <input
                                            type="range" min="10" max="180" step="1"
                                            value={getMetaValue('gis.fov_angle', 90)}
                                            onChange={(e) => updateNestedMeta('gis.fov_angle', parseInt(e.target.value))}
                                            className="flex-1 h-1.5 bg-[#333] rounded-lg appearance-none cursor-pointer accent-blue-500 my-auto"
                                        />
                                    </div>
                                </div>

                                <div className="space-y-2 pt-2">
                                    <div className="flex justify-between items-center">
                                        <label className="text-[9px] font-bold text-cad-text-muted uppercase tracking-tighter ml-1">Chiều dài (Radius)</label>
                                        <span className="text-[10px] font-mono text-purple-400 font-bold mr-1">{getMetaValue('gis.fov_radius', 100)}m</span>
                                    </div>
                                    <div className="flex gap-2">
                                        <input
                                            type="range" min="1" max="1000" step="1"
                                            value={getMetaValue('gis.fov_radius', 100)}
                                            onChange={(e) => updateNestedMeta('gis.fov_radius', parseInt(e.target.value))}
                                            className="flex-1 h-1.5 bg-[#333] rounded-lg appearance-none cursor-pointer accent-purple-500 my-auto"
                                        />
                                    </div>
                                </div>
                            </div>
                        </div>
                    )}
                </section>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { Route, Share2 } from 'lucide-react';
import type { Equipment, FeatureState, FiberCablePoint, FiberInventory } from '@CONTRACT/types';
import { getFeatureLabel } from '@DESIGN/features/map/network/fiberUiModel';
import { OneEndEquipmentUI } from './EquipmentUI/OneEndEquipmentUI';
import { TwoEndEquipmentUI } from './EquipmentUI/TwoEndEquipmentUI';

interface EquipmentPanelProps {
  projectId: string | null;
  selectedFeatureId: string | null;
  inventory: FiberInventory | null;
  featuresById: Record<string, FeatureState> | undefined;
}

export const EquipmentPanel: React.FC<EquipmentPanelProps> = ({
  projectId,
  selectedFeatureId,
  inventory,
  featuresById,
}) => {
  const nodeEquipmentData = useMemo(() => {
    if (!selectedFeatureId || !inventory) return null;

    const connectedPoints = (inventory.cable_points || []).filter(point => point.feature_id === selectedFeatureId);
    const equipment = (inventory.equipment || []).filter(item => item.feature_id === selectedFeatureId);

    if (connectedPoints.length === 0 && equipment.length === 0) {
      return { type: 'none' as const, cables: [], points: [], equipment };
    }

    const cablesMap = new Map<string, FiberCablePoint[]>();
    connectedPoints.forEach(point => {
      const list = cablesMap.get(point.cable_id) || [];
      list.push(point);
      cablesMap.set(point.cable_id, list);
    });

    const uniqueCables = Array.from(cablesMap.keys());
    const hasInlineEnclosure = connectedPoints.some(point => point.point_kind === 'splice_enclosure');
    const hasEnclosureEquipment = equipment.some(item => item.equipment_type === 'splice_enclosure');
    const type = uniqueCables.length === 2 || hasInlineEnclosure || hasEnclosureEquipment ? 'two-end' as const : 'one-end' as const;

    return { type, cables: uniqueCables, points: connectedPoints, equipment };
  }, [selectedFeatureId, inventory]);

  if (!selectedFeatureId || !inventory) {
    return (
      <div className="rounded-lg border border-white/5 bg-black/20 p-3 text-[10px] text-zinc-400">
        Vui lòng chọn một Point trên bản đồ để xem thiết bị.
      </div>
    );
  }

  const featureLabel = getFeatureLabel(featuresById, selectedFeatureId);
  const equipment = nodeEquipmentData?.equipment as Equipment[] | undefined;
  const isOdf = equipment?.some(item => item.equipment_type === 'odf') || false;
  const odfPorts = (inventory.ports || [])
    .filter(port => port.feature_id === selectedFeatureId)
    .sort((a, b) => a.port_label.localeCompare(b.port_label, undefined, { numeric: true }));
  const odfTerminations = inventory.port_terminations || [];
  const odfPatches = inventory.port_patches || [];
  const terminationsByPort = new Map(odfTerminations.map(item => [item.port_id, item]));
  const patchesByPort = new Map<string, number>();
  odfPatches.forEach(patch => {
    patchesByPort.set(patch.from_port_id, (patchesByPort.get(patch.from_port_id) || 0) + 1);
    patchesByPort.set(patch.to_port_id, (patchesByPort.get(patch.to_port_id) || 0) + 1);
  });

  return (
    <div className="space-y-3">
      <div className="rounded-lg border border-white/5 bg-black/20 p-3 text-[10px] text-zinc-400">
        <div className="space-y-2">
          <div className="font-semibold text-zinc-300">
            Thiết bị tại: {featureLabel}
          </div>

          {equipment && equipment.length > 0 && (
            <div className="grid grid-cols-2 gap-1">
              {equipment.map(item => (
                <div key={item.id} className="rounded border border-white/5 bg-black/25 px-2 py-1">
                  <div className="font-semibold text-zinc-200">{item.equipment_type}</div>
                  <div className="text-zinc-500">{item.status}</div>
                </div>
              ))}
            </div>
          )}

          {isOdf && (
            <div className="rounded border border-emerald-500/10 bg-emerald-500/5 p-2">
              <div className="mb-2 font-semibold text-emerald-200">ODF ports</div>
              {odfPorts.length === 0 ? (
                <div className="text-zinc-500">Chưa khai báo số cổng quang cho ODF này.</div>
              ) : (
                <div className="grid grid-cols-2 gap-1">
                  {odfPorts.map(port => {
                    const termination = terminationsByPort.get(port.id);
                    const patchCount = patchesByPort.get(port.id) || 0;
                    const status = termination ? patchCount > 0 ? 'Thông tuyến' : 'Một hướng' : 'Trống';
                    return (
                      <div key={port.id} className="rounded border border-white/5 bg-black/25 px-2 py-1">
                        <div className="flex items-center justify-between gap-2">
                          <span className="font-semibold text-zinc-200">{port.port_label}</span>
                          <span className={status === 'Thông tuyến' ? 'text-emerald-300' : status === 'Một hướng' ? 'text-amber-300' : 'text-zinc-500'}>{status}</span>
                        </div>
                        {termination && (
                          <div className="truncate text-zinc-500">
                            {termination.side.toUpperCase()} · {termination.strand_direction}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          )}

          {nodeEquipmentData?.type === 'none' && (
            <div>Nút này chưa có cáp quang nào kết nối tới.</div>
          )}

          {nodeEquipmentData?.type === 'one-end' && (
            <div>
              <div className="mb-2 flex items-center gap-1.5 text-zinc-300">
                <Share2 size={12} /> <span>ODF / Điểm cuối cáp</span>
              </div>
              <OneEndEquipmentUI
                projectId={projectId}
                featureId={selectedFeatureId}
                cables={nodeEquipmentData.cables}
                inventory={inventory}
                featuresById={featuresById}
              />
            </div>
          )}

          {nodeEquipmentData?.type === 'two-end' && (
            <div>
              <div className="mb-2 flex items-center gap-1.5 text-zinc-300">
                <Route size={12} /> <span>Măng xông / điểm nối tuyến</span>
              </div>
              <TwoEndEquipmentUI
                projectId={projectId}
                featureId={selectedFeatureId}
                cables={nodeEquipmentData.cables}
                inventory={inventory}
                featuresById={featuresById}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import type { FeatureState, FiberInventory } from '@CONTRACT/types';
import { getFeatureLabel } from '@DESIGN/features/map/network/fiberUiModel';

interface OneEndEquipmentUIProps {
  projectId: string | null;
  featureId: string;
  cables: string[];
  inventory: FiberInventory;
  featuresById: Record<string, FeatureState> | undefined;
}

export const OneEndEquipmentUI: React.FC<OneEndEquipmentUIProps> = ({
  projectId: _projectId,
  featureId,
  cables,
  inventory,
  featuresById,
}) => {
  const points = (inventory.cable_points || []).filter(point => point.feature_id === featureId);
  const ports = inventory.ports.filter(port => port.feature_id === featureId);

  return (
    <div className="mt-2 space-y-2">
      <div className="rounded border border-white/5 bg-black/30 p-2 text-[10px] text-zinc-400">
        <p className="mb-2 font-semibold text-zinc-300">Cáp kết nối tại điểm này:</p>
        <ul className="list-inside list-disc space-y-1">
          {cables.map(cableId => {
            const cable = inventory.cables.find(item => item.id === cableId);
            const label = getFeatureLabel(featuresById, cable?.feature_id);
            const pointKinds = points
              .filter(point => point.cable_id === cableId)
              .map(point => point.point_kind)
              .join(', ');

            return (
              <li key={cableId}>
                <span className="text-cyan-400">{label}</span> ({cable?.fiber_count || 0} FO)
                {pointKinds && <span className="text-zinc-500"> · {pointKinds}</span>}
              </li>
            );
          })}
        </ul>
      </div>

      <div className="rounded border border-white/5 bg-black/30 p-2 text-[10px] text-zinc-400">
        <div className="mb-1 font-semibold text-zinc-300">Port</div>
        {ports.length === 0 ? (
          <div>Chưa có port được khai báo cho thiết bị này.</div>
        ) : (
          <div className="grid grid-cols-2 gap-1">
            {ports.map(port => (
              <div key={port.id} className="rounded bg-black/30 px-2 py-1">
                <div className="font-semibold text-zinc-200">{port.port_label}</div>
                <div>{port.port_kind} · {port.direction} · {port.status}</div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import type { FeatureState, FiberInventory } from '@CONTRACT/types';
import { getFeatureLabel } from '@DESIGN/features/map/network/fiberUiModel';

interface TwoEndEquipmentUIProps {
  projectId: string | null;
  featureId: string;
  cables: string[];
