        <div className="mb-1 font-semibold text-zinc-300">Mối nối</div>
        {splices.length === 0 ? (
          <div>Chưa có mối nối được ghi nhận tại điểm này.</div>
        ) : (
          <div className="space-y-1">
            {splices.map(splice => (
              <div key={splice.id} className="rounded bg-black/30 px-2 py-1">
                <span className="text-cyan-300">{splice.from_strand_id}</span>
                <span className="text-zinc-500"> {splice.from_direction} ↔ {splice.to_direction} </span>
                <span className="text-pink-300">{splice.to_strand_id}</span>
                <span className="text-zinc-500"> · {splice.loss_db ?? 0} dB</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { TriangleAlert } from 'lucide-react';
import type { FiberCapacitySummary } from '@CONTRACT/types';
import type { FiberCableRow } from '@DESIGN/features/map/network/fiberUiModel';

interface FiberCapacityPanelProps {
  rows?: FiberCableRow[];
  items?: FiberCapacitySummary[];
  selectedCableId?: string | null;
  onSelectCable?: (cableId: string) => void;
  onInitializeCable?: (cableId: string, fiberCount: number) => void | Promise<void>;
}

const percent = (value: number | undefined) => Math.round((value || 0) * 100);

export const FiberCapacityPanel: React.FC<FiberCapacityPanelProps> = ({
  rows,
  items = [],
  selectedCableId,
  onSelectCable,
  onInitializeCable,
}) => {
  const displayRows: FiberCableRow[] = rows || items.map(item => ({
    cable: {
      id: item.cable_id,
      project_id: '',
      feature_id: item.feature_id,
      cable_type: item.cable_type,
      fiber_count: item.fiber_count,
      owner: null,
      status: 'planned' as const,
      source: 'manual' as const,
      created_at: '',
      updated_at: '',
    },
    label: item.cable_id,
    initialized: (item.available_count + item.reserved_count + item.active_count + item.damaged_count) > 0,
    strandCount: item.available_count + item.reserved_count + item.active_count + item.damaged_count,
    points: [],
    enclosureCount: 0,
    capacity: item,
  }));

  if (displayRows.length === 0) {
    return (
      <div className="rounded-lg border border-white/5 bg-black/20 p-3 text-[10.5px] text-zinc-500">
        Chưa có cáp fiber. Hãy nhận diện tuyến từ polyline hoặc vẽ tuyến Network trước.
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {displayRows.map(row => {
        const { cable, capacity } = row;
        const isSelected = selectedCableId && cable.id === selectedCableId;
        const free = capacity?.available_count || 0;
        const reserved = capacity?.reserved_count || 0;
        const active = capacity?.active_count || 0;
        const damaged = capacity?.damaged_count || 0;
        const defaultFiberCount = cable.fiber_count || row.strandCount || 12;
        const pointSummary = row.points.length > 0
          ? `Đầu ${row.startPoint ? '✓' : '—'} · Cuối ${row.endPoint ? '✓' : '—'} · Măng xông ${row.enclosureCount}`
          : 'Chưa materialize điểm tuyến';

        return (
          <div
            key={cable.id}
            className={isSelected
              ? 'rounded-lg border border-cyan-500/30 bg-cyan-500/10 p-3'
              : 'rounded-lg border border-white/5 bg-black/20 p-3 hover:border-white/15 hover:bg-white/[0.03]'}
          >
            <button
              type="button"
              onClick={() => onSelectCable?.(cable.id)}
              className="w-full text-left"
            >
              <div className="flex items-center justify-between gap-2">
                <div className="min-w-0">
                  <div className="truncate text-[11px] font-semibold text-zinc-100 flex items-center gap-1">
                    {row.diagnostics && row.diagnostics.length > 0 && (
                      <TriangleAlert size={12} className="text-amber-500" />
                    )}
                    {row.label}
                  </div>
                  <div className="truncate text-[9px] text-zinc-500">
                    {cable.cable_type || 'Cáp'} · {row.initialized ? `${row.strandCount} sợi đã khởi tạo` : 'Chưa khởi tạo sợi'}
                  </div>
                  <div className="truncate text-[9px] text-cyan-200/80">{pointSummary}</div>
                </div>
                <div className="text-right text-[10px]">
                  <div className="font-semibold text-zinc-100">{cable.fiber_count ?? row.strandCount} sợi</div>
                  <div className="text-zinc-500">{percent(capacity?.utilization)}%</div>
                </div>
              </div>
            </button>
            <div className="mt-2 grid grid-cols-4 gap-1 text-[9px] text-zinc-400">
              <span>Khả dụng {free}</span>
              <span>Giữ chỗ {reserved}</span>
              <span>Đang dùng {active}</span>
              <span>Lỗi {damaged}</span>
            </div>
            {!row.initialized && onInitializeCable && (
              <button
                type="button"
                onClick={() => onInitializeCable(cable.id, defaultFiberCount)}
                className="mt-2 rounded border border-cyan-500/25 px-2 py-1 text-[9px] font-semibold text-cyan-200 hover:bg-cyan-500/10"
              >
                Khởi tạo sợi
              </button>
            )}
          </div>
        );
      })}
    </div>
  );
};

import React from 'react';
import type { FiberCircuit, FiberTraceResult } from '@CONTRACT/types';

interface FiberCircuitPanelProps {
  circuits: FiberCircuit[];
  selectedCircuitId?: string | null;
  traceResult?: FiberTraceResult | null;
  getFeatureLabel?: (featureId: string) => string;
  onSelectCircuit?: (circuitId: string) => void;
  onTraceCircuit?: (circuitId: string) => void | Promise<void>;
  onFocusFeature?: (featureId: string) => void;
}

export const FiberCircuitPanel: React.FC<FiberCircuitPanelProps> = ({
  circuits,
  selectedCircuitId,
  traceResult,
  getFeatureLabel = id => id,
  onSelectCircuit,
  onTraceCircuit,
  onFocusFeature,
}) => {
  if (circuits.length === 0) {
    return (
      <div className="rounded-lg border border-white/5 bg-black/20 p-3 text-[10.5px] text-zinc-500">
        Chưa có tuyến A–Z. Tạo tuyến mới bằng form bên trên.
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {circuits.map(circuit => {
        const selected = selectedCircuitId === circuit.id;
        return (
          <div
            key={circuit.id}
            className={selected
              ? 'rounded-lg border border-cyan-500/30 bg-cyan-500/10 p-3'
              : 'rounded-lg border border-white/5 bg-black/20 p-3'}
          >
            <div className="flex items-center justify-between gap-2">
              <button
                type="button"
                onClick={() => onSelectCircuit?.(circuit.id)}
                className="min-w-0 text-left"
              >
                <div className="truncate text-[11px] font-semibold text-zinc-100">{circuit.name}</div>
                <div className="truncate text-[9px] text-zinc-500">
                  {circuit.service_type} · {circuit.status}
                </div>
              </button>
              <button
                type="button"
                onClick={() => onTraceCircuit?.(circuit.id)}
                className="rounded border border-white/10 px-2 py-1 text-[9px] font-semibold text-zinc-300 hover:bg-white/10"
              >
                Trace A–Z
              </button>
            </div>
            <div className="mt-2 grid grid-cols-2 gap-1 text-[9px] text-zinc-500">
              <button
                type="button"
                onClick={() => onFocusFeature?.(circuit.a_feature_id)}
                className="truncate rounded bg-black/25 px-2 py-1 text-left hover:text-cyan-200"
              >
                A · {getFeatureLabel(circuit.a_feature_id)}
              </button>
              <button
                type="button"
                onClick={() => onFocusFeature?.(circuit.z_feature_id)}
                className="truncate rounded bg-black/25 px-2 py-1 text-left hover:text-cyan-200"
              >
                Z · {getFeatureLabel(circuit.z_feature_id)}
              </button>
            </div>
            {selected && traceResult && (
              <div className="mt-3 rounded border border-white/5 bg-black/25 p-2 text-[9px] text-zinc-400">
                <div className="mb-1 font-semibold text-zinc-300">Kết quả trace</div>
                <div className="grid grid-cols-4 gap-1">
                  <span>Hop {traceResult.hops.length}</span>
                  <span>Sợi {traceResult.strands.length}</span>
                  <span>Port {traceResult.ports.length}</span>
                  <span>Nối {traceResult.splices.length}</span>
                </div>
                {traceResult.hops.length > 0 && (
                  <div className="mt-2 max-h-24 space-y-1 overflow-auto">
                    {traceResult.hops.map(hop => (
                      <div key={`${hop.circuit_id}-${hop.sequence_no}`} className="rounded bg-black/30 px-2 py-1">
                        #{hop.sequence_no} · {hop.strand_id || 'Chưa chọn sợi'} · {hop.port_id || 'Chưa chọn port'}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

