/**
 * Map Selection Manager
 * Centralized selection logic for all map feature types (Point, Polyline, Polygon)
 * Ensures consistent behavior across all feature types:
 * - Click to select
 * - Zoom to center with level 18
 * - Update DrawingExplorer to highlight and scroll to selected feature
 */

import L from 'leaflet';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';

/**
 * Handles feature selection from map click events
 * This is the unified selection handler for ALL feature types
 * 
 * When a user clicks on a feature on the map:
 * 1. The feature is selected (highlighted on map)
 * 2. Map zooms to center the feature (Points: zoom level 18)
 * 3. DrawingExplorer auto-expands and scrolls to show the feature
 * 
 * @param featureId - The ID of the feature to select
 * @param groupId - The group ID of the feature
 * @param originalEvent - The original click event (for detecting shiftKey)
 */
export function handleFeatureSelection(
    featureId: string,
    groupId: string,
    originalEvent?: any
) {
    const store = useDesignSync.getState();

    // Only allow selection in 'none' or 'move' drawing modes
    if (store.drawingMode !== 'none' && store.drawingMode !== 'move') {
        console.log(`[Selection] Blocked - drawingMode is '${store.drawingMode}' (must be 'none' or 'move')`);
        return;
    }

    console.log(`[Selection] Selecting feature: ${featureId}, group: ${groupId}`);

    // Detect shift key for multi-select
    const keepSelection = !!originalEvent?.shiftKey;

    // Capture click location for popups (especially for Lines/Polygons)
    let clickLocation: [number, number] | undefined = undefined;
    if (originalEvent && 'latlng' in originalEvent) {
        const ev = originalEvent as any;
        clickLocation = [ev.latlng.lat, ev.latlng.lng];
    }

    // Select the feature - this triggers DrawingExplorer auto-expand & scroll
    store.selectFeature(featureId, keepSelection, clickLocation);
    store.setSelectedGroup(groupId);

    // Record marker click time to prevent BoxSelectionHandler from deselecting immediately
    (store as any)._lastMarkerClickTime = Date.now();

    console.log(`[Selection] Feature ${featureId} selected, keepSelection: ${keepSelection}`);

    // Auto-zoom on single select (not multi-select)
    // This triggers ZoomToHandler which centers the map:
    // - Points: map.setView([lat, lng], 20)
    // - Lines/Polygons: map.fitBounds(bounds, { maxZoom: 20 })
    if (!keepSelection) {
        console.log(`[Selection] Triggering zoom to feature ${featureId}`);
        store.zoomTo(featureId, 'feature');
    }
}

/**
 * Stops event propagation to prevent map background from receiving the click
 * Use this in feature click handlers
 * 
 * @param event - The Leaflet or DOM event to stop
 */
export function stopFeatureEventPropagation(event: any) {
    // Stop Leaflet event propagation
    if (event && typeof event === 'object') {
        L.DomEvent.stopPropagation(event);

        // Also stop the original DOM event if it exists
        const originalEvent = event.originalEvent || event;
        if (originalEvent && typeof originalEvent.stopPropagation === 'function') {
            originalEvent.stopPropagation();
        }
    }
}

/**
 * Checks if a DOM element is a map feature element
 * Used to distinguish feature clicks from background clicks
 * 
 * @param target - The DOM element to check
 * @returns true if the element is a feature
 */
export function isFeatureElement(target: HTMLElement | EventTarget | null): boolean {
    if (!target || !(target instanceof HTMLElement)) {
        return false;
    }

    const element = target as HTMLElement;

    return (
        element.tagName === 'path' ||
        element.tagName === 'IMG' ||
        element.classList.contains('leaflet-interactive') ||
        element.classList.contains('custom-map-marker') ||
        element.classList.contains('selected-marker') ||
        !!element.closest('.leaflet-marker-icon') ||
        !!element.closest('.leaflet-interactive') ||
        !!element.closest('.custom-map-marker') ||
        !!element.closest('.selected-marker')
    );
}

/**
 * SmoothZoomController - Google Maps Style Zoom Animations
 * 
 * Provides smooth zoom animations matching Google Maps behavior:
 * - Duration: 800ms (Google Maps default)
 * - Easing: ease-out quad (t * (2 - t))
 * - Smooth panning with no jarring jumps
 * 
 * Usage:
 * ```typescript
 * import { smoothZoomToFeature, smoothPanTo } from '@DESIGN/feature/map/SmoothZoomController';
 * 
 * // Zoom to point with Google Maps-style animation
 * smoothZoomToFeature(map, feature, 18);
 * 
 * // Pan to location smoothly
 * smoothPanTo(map, [lat, lng]);
 * ```
 */

import L from 'leaflet';

/**
 * Google Maps Easing Function
 * ease-out quad: t * (2 - t)
 * This creates a smooth deceleration curve
 */
export function googleMapsEasing(t: number): number {
    return t * (2 - t);
}

/**
 * Smooth Zoom To Location
 * Google Maps-style zoom animation
 * 
 * @param map - Leaflet map instance
 * @param latlng - Target location [lat, lng]
 * @param zoom - Target zoom level
 * @param options - Animation options
 */
export function smoothZoomTo(
    map: L.Map,
    latlng: [number, number],
    zoom: number = 18,
    options?: {
        duration?: number;
        easeLinearity?: number;
    }
) {
    const {
        duration = 0.8,  // Google Maps default: 800ms
        easeLinearity = 0.15  // Smoother than Leaflet's 0.25
    } = options || {};

    map.setView(latlng, zoom, {
        animate: true,
        duration,
        easeLinearity,
        noMoveStart: true  // Don't fire 'movestart' event
    });
}

/**
 * Smooth Pan To Location
 * Google Maps-style pan animation (keeps current zoom)
 * 
 * @param map - Leaflet map instance
 * @param latlng - Target location [lat, lng]
 * @param options - Animation options
 */
export function smoothPanTo(
    map: L.Map,
    latlng: [number, number],
    options?: {
        duration?: number;
        easeLinearity?: number;
    }
) {
    const currentZoom = map.getZoom();

    map.setView(latlng, currentZoom, {
        animate: true,
        duration: options?.duration || 0.5,
        easeLinearity: options?.easeLinearity || 0.15,
        noMoveStart: true
    });
}

/**
 * Smooth Zoom To Feature
 * Automatically detects geometry type and zooms appropriately
 * 
 * @param map - Leaflet map instance
 * @param feature - Feature object with coordinates and geom_type
 * @param defaultZoom - Default zoom level for points
 */
export function smoothZoomToFeature(
    map: L.Map,
    feature: {
        coordinates: string | number[];
        geom_type?: string;
    },
    defaultZoom: number = 18
) {
    try {
        const coords = typeof feature.coordinates === 'string'
            ? JSON.parse(feature.coordinates)
            : feature.coordinates;

        if (!coords) {
            console.warn('[SmoothZoom] No coordinates');
            return;
        }

        const geomType = feature.geom_type || 'Point';

        switch (geomType) {
            case 'Point':
                if (coords.length >= 2) {
                    smoothZoomTo(map, [coords[1], coords[0]], defaultZoom);
                }
                break;

            case 'LineString':
            case 'Polyline':
                if (coords.length > 0) {
                    const bounds: L.LatLngExpression[] = coords
                        .filter((c: any) => c.length >= 2)
                        .map((c: any) => [c[1], c[0]]);

                    if (bounds.length > 0) {
                        map.fitBounds(L.latLngBounds(bounds), {
                            padding: [50, 50],
                            maxZoom: defaultZoom,
                            animate: true,
                            duration: 0.8,
                            easeLinearity: 0.15
                        });
                    }
                }
                break;

            case 'Polygon':
                if (coords[0] && coords[0].length > 0) {
                    const bounds: L.LatLngExpression[] = coords[0]
                        .filter((c: any) => c.length >= 2)
                        .map((c: any) => [c[1], c[0]]);

                    if (bounds.length > 0) {
                        map.fitBounds(L.latLngBounds(bounds), {
                            padding: [50, 50],
                            maxZoom: defaultZoom,
                            animate: true,
                            duration: 0.8,
                            easeLinearity: 0.15
                        });
                    }
                }
                break;

            default:
                console.warn(`[SmoothZoom] Unknown geometry type: ${geomType}`);
        }
    } catch (error) {
        console.error('[SmoothZoom] Error:', error);
    }
}

/**
 * Fit Bounds With Google Maps Style Animation
 * 
 * @param map - Leaflet map instance
 * @param bounds - Array of lat/lng coordinates
 * @param options - Fit bounds options
 */
export function smoothFitBounds(
    map: L.Map,
    bounds: L.LatLngExpression[],
    options?: L.FitBoundsOptions
) {
    map.fitBounds(L.latLngBounds(bounds), {
        padding: [50, 50],
        maxZoom: 18,
        animate: true,
        duration: 0.8,
        easeLinearity: 0.15,
        ...options
    });
}

/**
 * Fly To Location
 * Leaflet's flyTo with Google Maps-style duration
 *
 * @param map - Leaflet map instance
 * @param latlng - Target location [lat, lng]
 * @param zoom - Target zoom level
 * @param options - FlyTo options
 */
export function flyToLocation(
    map: L.Map,
    latlng: [number, number],
    zoom?: number,
    options?: {
        duration?: number;
        easeLinearity?: number;
        noMoveStart?: boolean;
    }
) {
    map.flyTo(latlng, zoom, {
        duration: 0.8,
        easeLinearity: 0.15,
        noMoveStart: true,
        ...options
    });
}

import type { DesignEventType, FeatureGroupState, FeatureProperties, FeatureState } from '@CONTRACT/types';
import type { DisplayNetworkNode } from './NetworkGraphAggregation';
import type { NetworkConnectionDraft } from './NetworkEndpoint';
import { getNextFeatureDisplayOrder, syncDisplayOrderAliases } from '@TOOL/utils/featureMapping';
import { getParsedMetadata } from '@TOOL/utils/featureMetadata';
import { inferNetworkRole, isSourceRole } from './networkTopology';
import { getRepresentativeFeatureIdForEndpoint } from './NetworkEndpoint';

export interface BuildNetworkConnectionCreateEventsArgs {
    sourceNode: DisplayNetworkNode;
    targetNode: DisplayNetworkNode;
    draft: NetworkConnectionDraft;
    group: FeatureGroupState;
    selectedGroupId: string;
    activeParentFeatureId: string | null;
    featuresById: Record<string, FeatureState>;
    createId?: () => string;
}

export interface BuildNetworkConnectionCreateEventsResult {
    events: DesignEventType[];
    createdFeatureId: string;
    activeParentFeatureId: string | null;
}

export const buildNetworkConnectionCreateEvents = ({
    sourceNode,
    targetNode,
    draft,
    group,
    selectedGroupId,
    activeParentFeatureId,
    featuresById,
    createId = () => crypto.randomUUID(),
}: BuildNetworkConnectionCreateEventsArgs): BuildNetworkConnectionCreateEventsResult => {
    const events: DesignEventType[] = [];
    const createdFeatureId = createId();
    const fromEndpoint = draft.fromEndpoint;
    const toEndpoint = draft.toEndpoint;
    const fromFeatureId = fromEndpoint.type === 'feature'
        ? fromEndpoint.id
        : getRepresentativeFeatureIdForEndpoint(fromEndpoint, featuresById);
    const toFeatureId = toEndpoint.type === 'feature'
        ? toEndpoint.id
        : getRepresentativeFeatureIdForEndpoint(toEndpoint, featuresById);

    const metadata: Record<string, unknown> = syncDisplayOrderAliases({
        color: '#EF4444',
        infrastructure: {
            type: 'NetworkLink',
            line_style: 'dashed',
            icon_type: 'signal',
        },
        network: {
            from_feature_id: fromFeatureId,
            to_feature_id: toFeatureId,
            from_endpoint: fromEndpoint,
            to_endpoint: toEndpoint,
            direction_mode: 'auto',
        },
    }, getNextFeatureDisplayOrder(
        featuresById,
        selectedGroupId,
        activeParentFeatureId
    ));

    const sourceFeature = sourceNode.representative.feature;
    const targetFeature = targetNode.representative.feature;
    const sourceMeta = { ...(getParsedMetadata(sourceFeature) as Record<string, any>) };
    const targetMeta = { ...(getParsedMetadata(targetFeature) as Record<string, any>) };
    const sourceRole = inferNetworkRole(sourceFeature, sourceMeta as any);
    const targetRole = inferNetworkRole(targetFeature, targetMeta as any);
    const sourceFeatureIsSource = isSourceRole(sourceRole);
    const targetFeatureIsSource = isSourceRole(targetRole);

    const parentSourceFeature = sourceFeatureIsSource && !targetFeatureIsSource
        ? sourceFeature
        : targetFeatureIsSource && !sourceFeatureIsSource
            ? targetFeature
            : null;
    const parentDeviceFeature = parentSourceFeature?.id === sourceFeature.id
        ? targetFeature
        : parentSourceFeature?.id === targetFeature.id
            ? sourceFeature
            : null;

    if (parentSourceFeature && parentDeviceFeature) {
        const deviceMeta = { ...(getParsedMetadata(parentDeviceFeature) as Record<string, any>) };
        if (deviceMeta.parent_feature_id !== parentSourceFeature.id) {
            deviceMeta.parent_feature_id = parentSourceFeature.id;
            events.push({
                type: 'FeatureUpdated',
                payload: {
                    id: parentDeviceFeature.id,
                    metadata: JSON.stringify(deviceMeta),
                },
            });
        }
    }

    events.push({
        type: 'FeatureCreated',
        payload: {
            id: createdFeatureId,
            layer_id: group.layer_id,
            group_id: selectedGroupId,
            name: 'Tuyen Network Moi',
            geom_type: 'NetworkLink',
            coordinates: null,
            metadata: JSON.stringify(metadata),
            properties: {} as FeatureProperties,
        },
    });

    return {
        events,
        createdFeatureId,
        activeParentFeatureId: activeParentFeatureId || null,
    };
};

import type { DisplayNetworkNode } from './NetworkGraphAggregation';
import type { NetworkConnectionDraft } from './NetworkEndpoint';

export interface PrepareNetworkConnectionDraftResult {
    draft: NetworkConnectionDraft;
    groupId: string | null;
    activeParentFeatureId: string | null;
}

export const prepareNetworkConnectionDraft = (
    sourceNode: DisplayNetworkNode | null | undefined,
    targetNode: DisplayNetworkNode | null | undefined,
    tab: 'intersection' | 'route' | 'fiber'
): PrepareNetworkConnectionDraftResult | null => {
    if (!sourceNode || !targetNode) return null;

    const groupId = sourceNode.groupId || targetNode.groupId || null;
    const activeParentFeatureId = tab === 'intersection'
        ? sourceNode.ownerIntersectionId || targetNode.ownerIntersectionId || null
        : null;

    return {
        draft: {
            fromEndpoint: sourceNode.endpointRef,
            toEndpoint: targetNode.endpointRef,
        },
        groupId,
        activeParentFeatureId,
    };
};

import type {
    NetworkEndpointMetadata,
    NetworkFeatureEndpointMetadata,
    NetworkSharedPointEndpointMetadata,
} from '@CONTRACT/designTypes';
import type { FeatureState, FeatureMetadata } from '@CONTRACT/types';
import { getPointCoordinates } from '@TOOL/utils/featureMapping';

export type NetworkEndpointRef = NetworkEndpointMetadata;
export type NetworkFeatureEndpointRef = NetworkFeatureEndpointMetadata;
export type NetworkSharedPointEndpointRef = NetworkSharedPointEndpointMetadata;

export interface NetworkConnectionDraft {
    fromEndpoint: NetworkEndpointRef;
    toEndpoint: NetworkEndpointRef;
}

const isCoordinate = (value: unknown): value is [number, number] =>
    Array.isArray(value) &&
    value.length === 2 &&
    typeof value[0] === 'number' &&
    typeof value[1] === 'number';

export const isNetworkFeatureEndpoint = (value: unknown): value is NetworkFeatureEndpointRef =>
    !!value &&
    typeof value === 'object' &&
    (value as NetworkFeatureEndpointRef).type === 'feature' &&
    typeof (value as NetworkFeatureEndpointRef).id === 'string';

export const isNetworkSharedPointEndpoint = (value: unknown): value is NetworkSharedPointEndpointRef =>
    !!value &&
    typeof value === 'object' &&
    (value as NetworkSharedPointEndpointRef).type === 'shared-point' &&
    typeof (value as NetworkSharedPointEndpointRef).id === 'string' &&
    typeof (value as NetworkSharedPointEndpointRef).intersection_id === 'string' &&
    Array.isArray((value as NetworkSharedPointEndpointRef).member_ids) &&
    (value as NetworkSharedPointEndpointRef).member_ids.every((memberId: unknown) => typeof memberId === 'string') &&
    isCoordinate((value as NetworkSharedPointEndpointRef).coordinate);

export const parseNetworkEndpointRef = (value: unknown): NetworkEndpointRef | null => {
    if (isNetworkFeatureEndpoint(value)) return value;
    if (isNetworkSharedPointEndpoint(value)) return value;
    return null;
};

export const createFeatureEndpointRef = (featureId: string): NetworkFeatureEndpointRef => ({
    type: 'feature',
    id: featureId,
});

export const getNetworkEndpointKey = (endpoint: NetworkEndpointRef): string =>
    endpoint.type === 'feature'
        ? `feature:${endpoint.id}`
        : `shared-point:${endpoint.id}`;

export const getRepresentativeFeatureIdForEndpoint = (
    endpoint: NetworkEndpointRef,
    featuresById: Record<string, FeatureState>
): string | null => {
    if (endpoint.type === 'feature') {
        return featuresById[endpoint.id] ? endpoint.id : null;
    }

    for (const memberId of endpoint.member_ids) {
        if (featuresById[memberId]) return memberId;
    }

    return null;
};

export const getNetworkEndpointCoordinate = (
    endpoint: NetworkEndpointRef,
    featuresById: Record<string, FeatureState>
): [number, number] | null => {
    if (endpoint.type === 'shared-point') {
        return endpoint.coordinate;
    }

    const feature = featuresById[endpoint.id];
    if (!feature) return null;
    return getPointCoordinates(feature);
};

export const getDraftEndpointLabel = (
    endpoint: NetworkEndpointRef,
    featuresById: Record<string, FeatureState>
): string => {
    if (endpoint.type === 'feature') {
        return featuresById[endpoint.id]?.name || endpoint.id;
    }

    const labels = endpoint.member_ids
        .map((memberId: string) => featuresById[memberId]?.name || memberId)
        .filter(Boolean);
    const leadLabel = labels[0] || endpoint.id;
    return endpoint.member_ids.length > 1
        ? `${leadLabel} +${endpoint.member_ids.length - 1}`
        : leadLabel;
};

export const getNetworkEndpointsFromMetadata = (metadata: FeatureMetadata): {
    fromEndpoint: NetworkEndpointRef | null;
    toEndpoint: NetworkEndpointRef | null;
} => {
    const fromEndpoint = parseNetworkEndpointRef(metadata.network?.from_endpoint) ||
        (typeof metadata.network?.from_feature_id === 'string' ? createFeatureEndpointRef(metadata.network.from_feature_id) : null);
    const toEndpoint = parseNetworkEndpointRef(metadata.network?.to_endpoint) ||
        (typeof metadata.network?.to_feature_id === 'string' ? createFeatureEndpointRef(metadata.network.to_feature_id) : null);

    return { fromEndpoint, toEndpoint };
};

import { getPointCoordinates } from '@TOOL/utils/featureUtils';
import type { NetworkEdge, NetworkNode } from './NetworkGraphService';
import {
    createFeatureEndpointRef,
    getNetworkEndpointKey,
    type NetworkEndpointRef,
} from './NetworkEndpoint';

export interface DisplayNetworkNode {
    id: string;
    representative: NetworkNode;
    memberIds: string[];
    memberLabels: string[];
    memberCount: number;
    groupId: string | null;
    ownerIntersectionId: string | null;
    layerId: string | null;
    endpointRef: NetworkEndpointRef;
    endpointKey: string;
}

export interface DisplayNetworkEdge {
    id: string;
    representative: NetworkEdge;
    from: string;
    to: string;
    memberEdgeIds: string[];
    fromEndpointKey: string;
    toEndpointKey: string;
}

export interface DisplayNetworkGraph {
    nodes: DisplayNetworkNode[];
    edges: DisplayNetworkEdge[];
    displayNodeIdByRawNodeId: Record<string, string>;
    displayNodeIdByEndpointKey: Record<string, string>;
}

const SHARED_POINT_THRESHOLD_METERS = 0.6;

const toRadians = (value: number) => (value * Math.PI) / 180;

const getDistanceMeters = (from: [number, number], to: [number, number]) => {
    const earthRadiusMeters = 6371000;
    const dLat = toRadians(to[1] - from[1]);
    const dLon = toRadians(to[0] - from[0]);
    const lat1 = toRadians(from[1]);
    const lat2 = toRadians(to[1]);
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(lat1) * Math.cos(lat2) * Math.sin(dLon / 2) ** 2;
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return earthRadiusMeters * c;
};

const chooseRepresentativeEdge = (current: DisplayNetworkEdge, candidate: NetworkEdge): DisplayNetworkEdge => {
    if (current.representative.sourceType === 'network-drawn' && candidate.sourceType === 'map-polyline') {
        return {
            ...current,
            representative: candidate,
            id: candidate.id,
        };
    }

    return current;
};

export const buildDisplayNetworkGraph = (
    nodes: NetworkNode[],
    edges: NetworkEdge[],
    scopedIntersectionId: string | null
): DisplayNetworkGraph => {
    const displayNodes = new Map<string, DisplayNetworkNode>();
    const displayNodeIdByRawNodeId: Record<string, string> = {};
    const displayNodeIdByEndpointKey: Record<string, string> = {};
    const deviceClusters = new Map<string, string[]>();

    if (scopedIntersectionId) {
        const candidateDevices = nodes.filter(node =>
            node.role === 'device' &&
            node.parentFeatureId === scopedIntersectionId &&
            !!getPointCoordinates(node.feature)
        );
        const visited = new Set<string>();

        for (const device of candidateDevices) {
            if (visited.has(device.id)) continue;

            const queue = [device];
            const cluster: string[] = [];
            visited.add(device.id);

            while (queue.length > 0) {
                const current = queue.shift();
                if (!current) continue;
                cluster.push(current.id);
                const currentPoint = getPointCoordinates(current.feature);
                if (!currentPoint) continue;

                for (const candidate of candidateDevices) {
                    if (visited.has(candidate.id)) continue;
                    const candidatePoint = getPointCoordinates(candidate.feature);
                    if (!candidatePoint) continue;
                    if (getDistanceMeters(currentPoint, candidatePoint) >= SHARED_POINT_THRESHOLD_METERS) continue;

                    visited.add(candidate.id);
                    queue.push(candidate);
                }
            }

            if (cluster.length > 1) {
                deviceClusters.set(cluster[0], cluster);
            }
        }
    }

    for (const node of nodes) {
        let displayId = node.id;
        let endpointRef: NetworkEndpointRef = createFeatureEndpointRef(node.id);
        const ownerIntersectionId = scopedIntersectionId && node.parentFeatureId === scopedIntersectionId
            ? scopedIntersectionId
            : node.role === 'intersection'
                ? node.id
                : node.parentFeatureId || null;

        if (scopedIntersectionId && node.role === 'device' && node.parentFeatureId === scopedIntersectionId) {
            const clusterEntry = [...deviceClusters.entries()].find(([, memberIds]) => memberIds.includes(node.id));
            if (clusterEntry) {
                displayId = `intersection:${scopedIntersectionId}:distance:${clusterEntry[0]}`;
                const clusterMembers = clusterEntry[1];
                const clusterCoordinates = clusterMembers
                    .map(memberId => nodes.find(item => item.id === memberId))
                    .map(memberNode => memberNode ? getPointCoordinates(memberNode.feature) : null)
                    .filter((coordinate): coordinate is [number, number] => !!coordinate);
                const coordinate = clusterCoordinates.length > 0
                    ? ([
                        clusterCoordinates.reduce((sum, [lng]) => sum + lng, 0) / clusterCoordinates.length,
                        clusterCoordinates.reduce((sum, [, lat]) => sum + lat, 0) / clusterCoordinates.length,
                    ] as [number, number])
                    : getPointCoordinates(node.feature) || [0, 0];
                endpointRef = {
                    type: 'shared-point',
                    id: displayId,
                    intersection_id: scopedIntersectionId,
                    member_ids: clusterMembers,
                    coordinate,
                };
            }
        }

        const endpointKey = getNetworkEndpointKey(endpointRef);

        const existing = displayNodes.get(displayId);

        displayNodeIdByRawNodeId[node.id] = displayId;
        displayNodeIdByEndpointKey[getNetworkEndpointKey(createFeatureEndpointRef(node.id))] = displayId;
        displayNodeIdByEndpointKey[endpointKey] = displayId;

        if (!existing) {
            displayNodes.set(displayId, {
                id: displayId,
                representative: node,
                memberIds: [node.id],
                memberLabels: [node.label],
                memberCount: 1,
                groupId: node.feature.group_id || null,
                ownerIntersectionId,
                layerId: node.feature.layer_id || null,
                endpointRef,
                endpointKey,
            });
            continue;
        }

        existing.memberIds.push(node.id);
        existing.memberLabels.push(node.label);
        existing.memberCount += 1;
    }

    const displayEdges = new Map<string, DisplayNetworkEdge>();

    for (const edge of edges) {
        const from = displayNodeIdByEndpointKey[edge.fromEndpointKey] || displayNodeIdByRawNodeId[edge.from] || edge.from;
        const to = displayNodeIdByEndpointKey[edge.toEndpointKey] || displayNodeIdByRawNodeId[edge.to] || edge.to;
        if (from === to) continue;

        const edgeKey = `${from}->${to}:${edge.kind}:${edge.sourceType}`;
        const existing = displayEdges.get(edgeKey);
        if (!existing) {
            displayEdges.set(edgeKey, {
                id: edge.id,
                representative: edge,
                from,
                to,
                memberEdgeIds: [edge.id],
                fromEndpointKey: edge.fromEndpointKey,
                toEndpointKey: edge.toEndpointKey,
            });
            continue;
        }

        existing.memberEdgeIds.push(edge.id);
        displayEdges.set(edgeKey, chooseRepresentativeEdge(existing, edge));
    }

    return {
        nodes: [...displayNodes.values()],
        edges: [...displayEdges.values()],
        displayNodeIdByRawNodeId,
        displayNodeIdByEndpointKey,
    };
};

