type NetworkComponent = { nodeIds: string[]; edgeIds: string[]; originIds: string[] };
type EdgePairEntry = { id: string; sourceType: NetworkEdge['sourceType'] };

const parseMetadata = (metadata: FeatureState['metadata']): FeatureMetadata => {
    if (!metadata) return {};
    if (typeof metadata === 'string') {
        try {
            return JSON.parse(metadata || '{}') as FeatureMetadata;
        } catch {
            return {};
        }
    }
    return metadata as FeatureMetadata;
};

const getEdgeSourceType = (feature: FeatureState, metadata: FeatureMetadata): NetworkEdge['sourceType'] => {
    if (feature.geom_type === 'NetworkLink' || metadata.infrastructure?.type === 'NetworkLink') return 'network-drawn';
    return 'map-polyline';
};

const getEntityStatus = (
    entityId: string,
    telemetryId: string | undefined,
    statuses: Record<string, NetworkEntityStatus> | undefined
): NetworkEntityStatus => {
    if (!statuses) return 'unknown';
    if (telemetryId && statuses[telemetryId]) return statuses[telemetryId];
    return statuses[entityId] ?? 'unknown';
};

const collectDownstream = (
    startId: string,
    outgoing: Map<string, NetworkEdge[]>,
    excludedEdgeId?: string
): string[] => {
    const affected = new Set<string>();
    const queue = [startId];

    while (queue.length > 0) {
        const current = queue.shift();
        if (!current || affected.has(current)) continue;
        affected.add(current);

        for (const edge of outgoing.get(current) || []) {
            if (edge.id !== excludedEdgeId) queue.push(edge.to);
        }
    }

    return [...affected];
};

const computeDistances = (originId: string, edgeMap: Map<string, NetworkEdge>): Map<string, number> => {
    const adjacency = new Map<string, Set<string>>();
    for (const edge of edgeMap.values()) {
        if (!adjacency.has(edge.from)) adjacency.set(edge.from, new Set());
        if (!adjacency.has(edge.to)) adjacency.set(edge.to, new Set());
        adjacency.get(edge.from)?.add(edge.to);
        adjacency.get(edge.to)?.add(edge.from);
    }

    const distances = new Map<string, number>([[originId, 0]]);
    const queue = [originId];

    while (queue.length > 0) {
        const current = queue.shift();
        if (!current) continue;
        const currentDistance = distances.get(current) ?? 0;
        for (const neighbor of adjacency.get(current) || []) {
            if (distances.has(neighbor)) continue;
            distances.set(neighbor, currentDistance + 1);
            queue.push(neighbor);
        }
    }

    return distances;
};

const buildComponentsFromGraph = (nodes: NetworkNode[], edges: NetworkEdge[]): NetworkComponent[] => {
    const adjacency = new Map<string, Set<string>>();
    const edgeIdsByNode = new Map<string, Set<string>>();

    for (const node of nodes) {
        adjacency.set(node.id, new Set());
        edgeIdsByNode.set(node.id, new Set());
    }

    for (const edge of edges) {
        adjacency.get(edge.from)?.add(edge.to);
        adjacency.get(edge.to)?.add(edge.from);
        edgeIdsByNode.get(edge.from)?.add(edge.id);
        edgeIdsByNode.get(edge.to)?.add(edge.id);
    }

    const nodesById = new Map(nodes.map(node => [node.id, node]));
    const visited = new Set<string>();
    const components: NetworkComponent[] = [];

    for (const node of nodes) {
        if (visited.has(node.id)) continue;

        const queue = [node.id];
        const componentNodeIds: string[] = [];
        const componentEdgeIds = new Set<string>();
        visited.add(node.id);

        while (queue.length > 0) {
            const current = queue.shift();
            if (!current) continue;
            componentNodeIds.push(current);

            for (const edgeId of edgeIdsByNode.get(current) || []) {
                componentEdgeIds.add(edgeId);
            }

            for (const neighbor of adjacency.get(current) || []) {
                if (visited.has(neighbor)) continue;
                visited.add(neighbor);
                queue.push(neighbor);
            }
        }

        components.push({
            nodeIds: componentNodeIds,
            edgeIds: [...componentEdgeIds],
            originIds: componentNodeIds.filter(nodeId => nodesById.get(nodeId)?.isOrigin),
        });
    }

    return components;
};

const mapNodes = (featuresById: Record<string, FeatureState>): NetworkNode[] => {
    const nodes = collectNetworkNodes(featuresById);

    return [...nodes.values()].map(node => {
        const explicitRole = node.metadata.network?.role;
        return {
            id: node.id,
            label: node.feature.name || node.id,
            role: node.role,
            networkRole: node.role,
            isInferredRole: explicitRole !== 'cabinet' && explicitRole !== 'intersection' && explicitRole !== 'device',
            telemetryId: node.metadata.network?.telemetry_id,
            parentFeatureId: node.parentFeatureId,
            isOrigin: node.isOrigin,
            feature: node.feature,
        };
    });
};

export const NetworkGraphService = {
    build(featuresById: Record<string, FeatureState>): NetworkGraph {
        const nodes = mapNodes(featuresById);
        const diagnostics: NetworkDiagnostic[] = [];
        const nodeIds = new Set(nodes.map(node => node.id));
        const edgePairs = new Map<string, EdgePairEntry>();
        const duplicateEdgeIds = new Set<string>();
        const rawEdges = collectNetworkEdges(featuresById, nodeIds);
        const edgeMap = new Map<string, NetworkEdge>();

        for (const feature of Object.values(featuresById)) {
            const metadata = parseMetadata(feature.metadata);
            if (!isNetworkEdgeFeature(feature, metadata)) continue;

            const { fromEndpoint, toEndpoint } = getNetworkEndpointsFromMetadata(metadata);
            if (!fromEndpoint || !toEndpoint) {
                diagnostics.push({
                    type: 'missing-endpoint',
                    edgeId: feature.id,
                    message: `Network link ${feature.id} is missing from_feature_id or to_feature_id.`,
                });
                continue;
            }
            const from = getRepresentativeFeatureIdForEndpoint(fromEndpoint, featuresById);
            const to = getRepresentativeFeatureIdForEndpoint(toEndpoint, featuresById);
            if (!from || !to) {
                diagnostics.push({
                    type: 'unknown-node',
                    edgeId: feature.id,
                    message: `Network link ${feature.id} references unknown node(s).`,
                });
                continue;
            }

            if (getNetworkEndpointKey(fromEndpoint) === getNetworkEndpointKey(toEndpoint)) {
                diagnostics.push({
                    type: 'self-loop',
                    edgeId: feature.id,
                    message: `Network link ${feature.id} points to itself.`,
                });
                continue;
            }

            const missing = [from, to].filter(id => !nodeIds.has(id));
            if (missing.length > 0) {
                diagnostics.push({
                    type: 'unknown-node',
                    edgeId: feature.id,
                    message: `Network link ${feature.id} references unknown node(s): ${missing.join(', ')}.`,
                });
                continue;
            }

            const pairKey = `${getNetworkEndpointKey(fromEndpoint)}->${getNetworkEndpointKey(toEndpoint)}`;
            const sourceType = getEdgeSourceType(feature, metadata);
            const previousEdge = edgePairs.get(pairKey);
            if (previousEdge) {
                const shouldPreferCurrent = previousEdge.sourceType === 'network-drawn' && sourceType === 'map-polyline';
                const duplicateEdgeId = shouldPreferCurrent ? previousEdge.id : feature.id;

                duplicateEdgeIds.add(duplicateEdgeId);
                diagnostics.push({
                    type: 'duplicate-edge',
                    edgeId: duplicateEdgeId,
                    message: shouldPreferCurrent
                        ? `Network link ${previousEdge.id} duplicates ${feature.id}.`
                        : `Network link ${feature.id} duplicates ${previousEdge.id}.`,
                });
                if (shouldPreferCurrent) {
                    edgePairs.set(pairKey, { id: feature.id, sourceType });
                }
                continue;
            }

            edgePairs.set(pairKey, { id: feature.id, sourceType });
        }

        for (const edge of rawEdges) {
            if (duplicateEdgeIds.has(edge.id)) continue;
            edgeMap.set(edge.id, {
                id: edge.id,
                label: edge.feature.name || edge.id,
                from: edge.from,
                to: edge.to,
                kind: 'signal',
                sourceType: getEdgeSourceType(edge.feature, edge.metadata),
                telemetryId: edge.metadata.network?.telemetry_id,
                feature: edge.feature,
                fromEndpoint: edge.fromEndpoint,
                toEndpoint: edge.toEndpoint,
                fromEndpointKey: edge.fromEndpointKey,
                toEndpointKey: edge.toEndpointKey,
                directionMode: edge.directionMode,
                directionState: edge.directionMode === 'legacy' || edge.directionMode === 'manual' ? 'confirmed' : 'pending',
            });
        }

        for (const feature of Object.values(featuresById)) {
            if (edgeMap.has(feature.id) || !isLineFeature(feature)) continue;

            const metadata = parseMetadata(feature.metadata);
            const startSnapId = typeof metadata.start_node_id === 'string' ? metadata.start_node_id : null;
            const endSnapId = typeof metadata.end_node_id === 'string' ? metadata.end_node_id : null;
            if (!startSnapId || !endSnapId) continue;

            const coordinates = Array.isArray(feature.coordinates) ? feature.coordinates : [];
            const startCoordinate = Array.isArray(coordinates[0]) ? coordinates[0] as [number, number] : null;
            const endCoordinate = Array.isArray(coordinates[coordinates.length - 1]) ? coordinates[coordinates.length - 1] as [number, number] : null;
            const resolvedFrom = resolveNetworkNodeIdFromSnap(featuresById, startSnapId, startCoordinate);
            const resolvedTo = resolveNetworkNodeIdFromSnap(featuresById, endSnapId, endCoordinate);

            if (!resolvedFrom || !resolvedTo || resolvedFrom === resolvedTo) continue;
            if (!nodeIds.has(resolvedFrom) || !nodeIds.has(resolvedTo)) continue;

            const fromEndpoint = createFeatureEndpointRef(resolvedFrom);
            const toEndpoint = createFeatureEndpointRef(resolvedTo);
            const pairKey = `${getNetworkEndpointKey(fromEndpoint)}->${getNetworkEndpointKey(toEndpoint)}`;
            const reversePairKey = `${getNetworkEndpointKey(toEndpoint)}->${getNetworkEndpointKey(fromEndpoint)}`;
            if (edgePairs.has(pairKey) || edgePairs.has(reversePairKey)) continue;

            edgePairs.set(pairKey, { id: feature.id, sourceType: 'map-polyline' });
            edgeMap.set(feature.id, {
                id: feature.id,
                label: feature.name || feature.id,
                from: resolvedFrom,
                to: resolvedTo,
                kind: 'signal',
                sourceType: 'map-polyline',
                telemetryId: metadata.network?.telemetry_id,
                feature,
                fromEndpoint,
                toEndpoint,
                fromEndpointKey: getNetworkEndpointKey(fromEndpoint),
                toEndpointKey: getNetworkEndpointKey(toEndpoint),
                directionMode: 'auto',
                directionState: 'pending',
            });
        }

        const builtEdges = [...edgeMap.values()];
        const components = buildComponentsFromGraph(nodes, builtEdges);

        for (const component of components) {
            const componentEdges = component.edgeIds
                .map(edgeId => edgeMap.get(edgeId))
                .filter((edge): edge is NetworkEdge => !!edge);

            const hasAutoEdges = componentEdges.some(edge => edge.directionMode === 'auto');
            if (component.originIds.length === 0 && hasAutoEdges) {
                diagnostics.push({
                    type: 'missing-origin',
                    featureId: component.nodeIds[0],
                    message: 'Connected network component is missing an origin node.',
                });
                for (const edge of componentEdges) {
                    if (edge.directionMode === 'auto') edge.directionState = 'pending';
                }
                continue;
            }

            if (component.originIds.length > 1) {
                diagnostics.push({
                    type: 'multiple-origins',
                    featureId: component.originIds[0],
                    message: `Connected network component has multiple origins: ${component.originIds.join(', ')}.`,
                });
                for (const edge of componentEdges) {
                    if (edge.directionMode === 'auto') edge.directionState = 'conflict';
                }
                continue;
            }

            if (component.originIds.length !== 1) continue;

            const distances = computeDistances(component.originIds[0], new Map(componentEdges.map(edge => [edge.id, edge])));
            for (const edge of componentEdges) {
                if (edge.directionMode !== 'auto') continue;

                const fromDistance = distances.get(edge.from);
                const toDistance = distances.get(edge.to);

                if (fromDistance === undefined || toDistance === undefined) {
                    edge.directionState = 'pending';
                    continue;
                }

                if (fromDistance === toDistance) {
                    edge.directionState = 'pending';
                    diagnostics.push({
                        type: 'ambiguous-direction',
                        edgeId: edge.id,
                        message: `Network link ${edge.id} has equal topology distance on both endpoints and needs manual confirmation.`,
                    });
                    continue;
                }

                if (fromDistance > toDistance) {
                    const currentFrom = edge.from;
                    edge.from = edge.to;
                    edge.to = currentFrom;
                }
                edge.directionState = 'confirmed';
            }
        }

        return { nodes, edges: builtEdges, diagnostics };
    },

    evaluate(featuresById: Record<string, FeatureState>, statusSnapshot: NetworkStatusSnapshot = {}): NetworkEvaluation {
        const graph = NetworkGraphService.build(featuresById);
        const outgoing = new Map<string, NetworkEdge[]>();
        const signalEdges = graph.edges.filter(edge => edge.kind === 'signal' && edge.directionState === 'confirmed');
        const componentByNode = new Map<string, NetworkComponent>();
        const components = buildComponentsFromGraph(graph.nodes, graph.edges);

        for (const component of components) {
            for (const nodeId of component.nodeIds) {
                componentByNode.set(nodeId, component);
            }
        }

        for (const edge of signalEdges) {
            outgoing.set(edge.from, [...(outgoing.get(edge.from) || []), edge]);
        }

        const reachable = new Set<string>();
        const queue: string[] = [];
        const sourceNodes = graph.nodes.filter(node => node.isOrigin);
        const fallbackSourceNodes = sourceNodes.length > 0
            ? sourceNodes
            : graph.nodes.filter(node => {
                const component = componentByNode.get(node.id);
                if (!component) return false;
                const componentHasAutoEdges = graph.edges.some(edge =>
                    component.edgeIds.includes(edge.id) && edge.directionMode === 'auto'
                );
                if (componentHasAutoEdges) return false;

                const hasCabinet = component.nodeIds.some(id => {
                    const n = graph.nodes.find(item => item.id === id);
                    return n && n.role === 'cabinet';
                });

                if (hasCabinet) {
                    return node.role === 'cabinet';
                }

                return isSourceRole(node.role);
            });

        for (const source of fallbackSourceNodes) {
            if (getEntityStatus(source.id, source.telemetryId, statusSnapshot.nodes) === 'online') {
                reachable.add(source.id);
                queue.push(source.id);
            }
        }

        while (queue.length > 0) {
            const current = queue.shift();
            if (!current) continue;

            for (const edge of outgoing.get(current) || []) {
                const edgeStatus = getEntityStatus(edge.id, edge.telemetryId, statusSnapshot.edges);
                if (edgeStatus !== 'online') continue;

                const target = graph.nodes.find(node => node.id === edge.to);
                if (!target) continue;

                const targetStatus = getEntityStatus(target.id, target.telemetryId, statusSnapshot.nodes);
                if (targetStatus !== 'online' || reachable.has(target.id)) continue;

                reachable.add(target.id);
                queue.push(target.id);
            }
        }

        const nodeStates: Record<string, NetworkNodeState> = {};

        for (const node of graph.nodes) {
            const directStatus = getEntityStatus(node.id, node.telemetryId, statusSnapshot.nodes);
            const affectedDownstream = collectDownstream(node.id, outgoing);
            const component = componentByNode.get(node.id);
            const componentDiagnostics = graph.diagnostics.filter(diagnostic =>
                (diagnostic.featureId && component?.nodeIds.includes(diagnostic.featureId)) ||
                (diagnostic.edgeId && component?.edgeIds.includes(diagnostic.edgeId))
            );
            const hasTopologyBlocker = componentDiagnostics.some(diagnostic =>
                diagnostic.type === 'missing-origin' || diagnostic.type === 'multiple-origins'
            );

            if (hasTopologyBlocker) {
                nodeStates[node.id] = {
                    nodeId: node.id,
                    status: 'configuration-error',
                    reason: componentDiagnostics[0]?.message || 'Network component has unresolved origin configuration.',
                    affectedDownstream,
                };
            } else if (directStatus === 'offline') {
                nodeStates[node.id] = {
                    nodeId: node.id,
                    status: 'direct-offline',
                    reason: 'Node telemetry reports offline.',
                    affectedDownstream,
                };
            } else if (directStatus === 'unknown') {
                nodeStates[node.id] = {
                    nodeId: node.id,
                    status: 'unknown',
                    reason: 'Node telemetry is unknown or unavailable.',
                    affectedDownstream,
                };
            } else if (reachable.has(node.id)) {
                nodeStates[node.id] = {
                    nodeId: node.id,
                    status: 'online',
                    reason: node.isOrigin
                        ? 'Node is the selected origin for this network component.'
                        : 'Node has an active path from the selected origin.',
                    affectedDownstream: [],
                };
            } else {
                nodeStates[node.id] = {
                    nodeId: node.id,
                    status: 'upstream-offline',
                    reason: 'No active confirmed path remains to the selected origin.',
                    affectedDownstream,
                };
            }
        }

        return { ...graph, nodeStates };
    },
};

import type { NetworkEntityStatus, NetworkStatusSnapshot } from './NetworkGraphService';

export type NetworkStatusMode = 'realtime' | 'simulation';
export type NetworkEntityType = 'node' | 'edge';

export interface NetworkStatusEvent {
    entityId: string;
    entityType: NetworkEntityType;
    status: NetworkEntityStatus;
    observedAt: string | number | Date;
}

export interface NetworkStatusState {
    mode: NetworkStatusMode;
    realtime: NetworkStatusSnapshot;
    simulation: NetworkStatusSnapshot;
    observedAt: Record<string, number>;
    stale: boolean;
}

const emptySnapshot = (): NetworkStatusSnapshot => ({ nodes: {}, edges: {} });

const toTimestamp = (value: string | number | Date): number => {
    if (value instanceof Date) return value.getTime();
    if (typeof value === 'number') return value;
    const parsed = Date.parse(value);
    return Number.isNaN(parsed) ? 0 : parsed;
};

const cloneSnapshot = (snapshot: NetworkStatusSnapshot): NetworkStatusSnapshot => ({
    nodes: { ...(snapshot.nodes || {}) },
    edges: { ...(snapshot.edges || {}) },
});

export class NetworkStatusAdapter {
    private state: NetworkStatusState = {
        mode: 'realtime',
        realtime: emptySnapshot(),
        simulation: emptySnapshot(),
        observedAt: {},
        stale: false,
    };

    getState(): NetworkStatusState {
        return {
            mode: this.state.mode,
            realtime: cloneSnapshot(this.state.realtime),
            simulation: cloneSnapshot(this.state.simulation),
            observedAt: { ...this.state.observedAt },
            stale: this.state.stale,
        };
    }

    getSnapshot(): NetworkStatusSnapshot {
        return cloneSnapshot(this.state.mode === 'simulation' ? this.state.simulation : this.state.realtime);
    }

    setMode(mode: NetworkStatusMode): void {
        this.state = { ...this.state, mode };
    }

    applyRealtimeEvent(event: NetworkStatusEvent): boolean {
        const observedAt = toTimestamp(event.observedAt);
        const key = `${event.entityType}:${event.entityId}`;
        const previousObservedAt = this.state.observedAt[key] || 0;
        if (observedAt < previousObservedAt) return false;

        const realtime = cloneSnapshot(this.state.realtime);
        const bucket = event.entityType === 'node' ? 'nodes' : 'edges';
        realtime[bucket] = { ...(realtime[bucket] || {}), [event.entityId]: event.status };

        this.state = {
            ...this.state,
            realtime,
            observedAt: { ...this.state.observedAt, [key]: observedAt },
            stale: false,
        };
        return true;
    }

    markRealtimeDisconnected(): void {
        this.state = { ...this.state, stale: true };
    }

    setSimulationStatus(entityType: NetworkEntityType, entityId: string, status: NetworkEntityStatus): void {
        const simulation = cloneSnapshot(this.state.simulation);
        const bucket = entityType === 'node' ? 'nodes' : 'edges';
        simulation[bucket] = { ...(simulation[bucket] || {}), [entityId]: status };
        this.state = { ...this.state, simulation };
    }

    resetSimulation(): void {
        this.state = { ...this.state, simulation: emptySnapshot() };
    }
}

import type { FeatureState, FiberInventory, FiberValidationDiagnostic, LineStringCoordinates, PointCoordinates } from '@CONTRACT/types';

const coordinateKey = (point: PointCoordinates): string => `${point[0].toFixed(7)},${point[1].toFixed(7)}`;

const isPoint = (value: unknown): value is PointCoordinates =>
  Array.isArray(value)
  && value.length >= 2
  && typeof value[0] === 'number'
  && typeof value[1] === 'number';

const getLineCoordinates = (feature: FeatureState): LineStringCoordinates | null => {
  if (!Array.isArray(feature.coordinates) || feature.coordinates.length < 2) return null;
  if (!isPoint(feature.coordinates[0])) return null;
  return feature.coordinates as LineStringCoordinates;
};

const isPolylineFeature = (feature: FeatureState): boolean => {
  const geomType = `${feature.geom_type || feature.geometry_type || ''}`.toLowerCase();
  return geomType.includes('line') || geomType.includes('polyline') || geomType === 'networklink';
};

const parseMetadata = (metadata: FeatureState['metadata'] | undefined): Record<string, any> => {
  if (!metadata) return {};
  if (typeof metadata === 'string') {
    try {
      return JSON.parse(metadata || '{}');
    } catch {
      return {};
    }
  }
  return { ...metadata };
};

const isFiberLineFeature = (feature: FeatureState, cableFeatureIds: Set<string>): boolean => {
  if (cableFeatureIds.has(feature.id)) return true;

  const metadata = parseMetadata(feature.metadata);
  const geomType = `${feature.geom_type || feature.geometry_type || ''}`.toLowerCase();
  const infrastructureType = `${metadata.infrastructure?.type || metadata.type || ''}`.toLowerCase();
  const fiberRole = `${metadata.fiber?.role || metadata.fiber?.kind || ''}`.toLowerCase();

  return geomType === 'networklink'
    || infrastructureType === 'signalline'
    || infrastructureType === 'networklink'
    || fiberRole === 'cable';
};

export const validateFiberGeometry = (
  _projectId: string,
  inventory: FiberInventory | null,
  featuresById: Record<string, FeatureState>
): FiberValidationDiagnostic[] => {
  const diagnostics: FiberValidationDiagnostic[] = [];
  const features = Object.values(featuresById);
  const cables = inventory?.cables || [];
  const cablePoints = inventory?.cable_points || [];
  const cableFeatureIds = new Set(cables.map(cable => cable.feature_id));

  const coordinateUsage = new Map<string, { point: PointCoordinates; featureIds: Set<string>; isEnclosure: boolean }>();

  features.forEach(feature => {
    const metadata = parseMetadata(feature.metadata);
    if (metadata.fiber?.kind === 'splice_enclosure' && isPoint(feature.coordinates)) {
      const key = metadata.fiber.coordinate_key || coordinateKey(feature.coordinates);
      const usage = coordinateUsage.get(key) || { point: feature.coordinates, featureIds: new Set<string>(), isEnclosure: false };
      usage.isEnclosure = true;
      coordinateUsage.set(key, usage);
    }
  });

  features.forEach(feature => {
    if (!isPolylineFeature(feature) || !isFiberLineFeature(feature, cableFeatureIds)) return;

    const metadata = parseMetadata(feature.metadata);
    const hasFromEndpoint = !!metadata.network?.from_endpoint || !!metadata.network?.from_feature_id;
    const hasToEndpoint = !!metadata.network?.to_endpoint || !!metadata.network?.to_feature_id;

    if (!hasFromEndpoint || !hasToEndpoint) {
      diagnostics.push({
        type: 'missing-polyline-endpoint',
        message: 'Tuyến truyền dẫn chưa snap endpoint đầu hoặc cuối',
        feature_id: feature.id,
      });
    }

    const coords = getLineCoordinates(feature);
    if (coords) {
      coords.forEach(point => {
        const key = coordinateKey(point);
        const usage = coordinateUsage.get(key) || { point, featureIds: new Set<string>(), isEnclosure: false };
        usage.featureIds.add(feature.id);
        coordinateUsage.set(key, usage);
      });
    }
  });

  for (const [key, usage] of coordinateUsage.entries()) {
    if (usage.featureIds.size > 1 && !usage.isEnclosure) {
      diagnostics.push({
        type: 'missing-branch-enclosure',
        message: `Phát hiện ${usage.featureIds.size} tuyến giao nhau nhưng chưa có măng xông tại tọa độ ${key}`,
      });
    }
  }

  cablePoints.forEach(cp => {
    if (cp.point_kind !== 'splice_enclosure') return;

    const enclosureFeature = featuresById[cp.feature_id];
    const cableFeature = featuresById[cables.find(c => c.id === cp.cable_id)?.feature_id || ''];
    if (!enclosureFeature || !cableFeature || !isPoint(enclosureFeature.coordinates) || !getLineCoordinates(cableFeature)) return;

    const enclosureKey = coordinateKey(enclosureFeature.coordinates);
    const cableCoords = getLineCoordinates(cableFeature)!;
    const isOnLine = cableCoords.some(pt => coordinateKey(pt) === enclosureKey);

    if (!isOnLine) {
      diagnostics.push({
        type: 'invalid-enclosure-location',
        message: 'Măng xông không nằm trên tọa độ tuyến cáp',
        feature_id: enclosureFeature.id,
        cable_id: cp.cable_id,
      });
    }
  });

  return diagnostics;
};

import type {
  FiberCable,
  FiberCircuit,
  FiberInventory,
  FiberPort,
  FiberSplice,
  FiberStrand,
} from '@CONTRACT/types';

export type FiberGraphNodeKind = 'cable' | 'strand' | 'port' | 'splice' | 'circuit';

export interface FiberGraphNode {
  id: string;
  label: string;
  kind: FiberGraphNodeKind;
  parentId?: string | null;
  status?: string | null;
}

export interface FiberGraphEdge {
  id: string;
  source: string;
  target: string;
  kind: 'contains' | 'routes' | 'spliced';
  label?: string;
}

export interface FiberGraph {
  nodes: FiberGraphNode[];
  edges: FiberGraphEdge[];
}

const mapCableNode = (cable: FiberCable): FiberGraphNode => ({
  id: `cable:${cable.id}`,
  label: cable.cable_type || cable.id,
  kind: 'cable',
  status: cable.status,
});

const mapStrandNode = (strand: FiberStrand): FiberGraphNode => ({
  id: `strand:${strand.id}`,
  label: `S${strand.strand_no}`,
  kind: 'strand',
  parentId: `cable:${strand.cable_id}`,
  status: strand.status,
});

const mapPortNode = (port: FiberPort): FiberGraphNode => ({
  id: `port:${port.id}`,
  label: port.port_label,
  kind: 'port',
  status: port.status,
});

const mapSpliceNode = (splice: FiberSplice): FiberGraphNode => ({
  id: `splice:${splice.id}`,
  label: `Splice ${splice.id.slice(0, 6)}`,
  kind: 'splice',
});

const mapCircuitNode = (circuit: FiberCircuit): FiberGraphNode => ({
  id: `circuit:${circuit.id}`,
  label: circuit.name,
  kind: 'circuit',
  status: circuit.status,
});

export const buildFiberGraph = (inventory: FiberInventory): FiberGraph => {
  const nodes: FiberGraphNode[] = [];
  const edges: FiberGraphEdge[] = [];

  inventory.cables.forEach(cable => {
    nodes.push(mapCableNode(cable));
  });

  inventory.strands.forEach(strand => {
    nodes.push(mapStrandNode(strand));
    edges.push({
      id: `cable-strand:${strand.cable_id}:${strand.strand_no}`,
      source: `cable:${strand.cable_id}`,
      target: `strand:${strand.id}`,
      kind: 'contains',
      label: `#${strand.strand_no}`,
    });
  });

  inventory.ports.forEach(port => {
    nodes.push(mapPortNode(port));
  });

  inventory.splices.forEach(splice => {
    nodes.push(mapSpliceNode(splice));
    edges.push({
      id: `splice-from:${splice.id}`,
      source: `strand:${splice.from_strand_id}`,
      target: `splice:${splice.id}`,
      kind: 'spliced',
      label: 'from',
    });
    edges.push({
      id: `splice-to:${splice.id}`,
      source: `splice:${splice.id}`,
      target: `strand:${splice.to_strand_id}`,
      kind: 'spliced',
      label: 'to',
    });
  });

  inventory.circuits.forEach(circuit => {
    nodes.push(mapCircuitNode(circuit));
    edges.push({
      id: `circuit-a:${circuit.id}`,
      source: `circuit:${circuit.id}`,
      target: `feature:${circuit.a_feature_id}`,
      kind: 'routes',
      label: 'A',
    });
    edges.push({
      id: `circuit-z:${circuit.id}`,
      source: `circuit:${circuit.id}`,
      target: `feature:${circuit.z_feature_id}`,
      kind: 'routes',
      label: 'Z',
    });
  });

  return { nodes, edges };
};

import type {
  DesignEventType,
  FeatureState,
  FiberCable,
  FiberCablePointKind,
  FiberInventory,
  LineStringCoordinates,
  PointCoordinates,
} from '@CONTRACT/types';

interface FiberPointMetadata {
  kind?: string;
  point_kind?: FiberCablePointKind;
  cable_id?: string;
  sequence_no?: number;
  coordinate_key?: string;
}

interface ParsedMetadata {
  infrastructure?: Record<string, any>;
  network?: Record<string, any>;
  fiber?: FiberPointMetadata & Record<string, any>;
  [key: string]: any;
}

export interface FiberPolylineMaterializationOptions {
  createId?: () => string;
  targetFeatureIds?: string[];
}

export interface FiberPolylineMaterializationResult {
  events: DesignEventType[];
  cableCount: number;
  pointCount: number;
  enclosureCount: number;
}

interface LineCandidate {
  feature: FeatureState;
  coordinates: LineStringCoordinates;
}

interface CablePointInput {
  id: string;
  feature_id: string;
  point_kind: FiberCablePointKind;
  sequence_no: number;
  vertex_index: number | null;
}

const newId = () => crypto.randomUUID();

const parseMetadata = (metadata: FeatureState['metadata'] | undefined): ParsedMetadata => {
  if (!metadata) return {};
  if (typeof metadata === 'string') {
    try {
      return JSON.parse(metadata || '{}') as ParsedMetadata;
    } catch {
      return {};
    }
  }
  return { ...(metadata as ParsedMetadata) };
};

const isPoint = (value: unknown): value is PointCoordinates =>
  Array.isArray(value)
  && value.length >= 2
  && typeof value[0] === 'number'
  && typeof value[1] === 'number';

const getLineCoordinates = (feature: FeatureState): LineStringCoordinates | null => {
  if (!Array.isArray(feature.coordinates) || feature.coordinates.length < 2) return null;
  if (!isPoint(feature.coordinates[0])) return null;
  return feature.coordinates as LineStringCoordinates;
};

const isPolylineFeature = (feature: FeatureState): boolean => {
  const geomType = `${feature.geom_type || feature.geometry_type || ''}`.toLowerCase();
  return geomType.includes('line') || geomType.includes('polyline') || geomType === 'networklink';
};

const coordinateKey = (point: PointCoordinates): string => `${point[0].toFixed(7)},${point[1].toFixed(7)}`;

const isReusableFiberPoint = (
  feature: FeatureState,
  reusableFeatureIds: Set<string>,
  pointKind?: FiberCablePointKind
): boolean => {
  if (!isPoint(feature.coordinates)) return false;
  if (reusableFeatureIds.has(feature.id)) return true;

  const metadata = parseMetadata(feature.metadata);
  const fiber = metadata.fiber;
  if (!fiber) return false;
  if (pointKind && fiber.point_kind !== pointKind) return false;

  return fiber.kind === 'cable_endpoint'
    || fiber.kind === 'splice_enclosure'
    || fiber.point_kind === 'cable_start'
    || fiber.point_kind === 'cable_end'
    || fiber.point_kind === 'splice_enclosure';
};

const cloneMetadataWithFiberCable = (
  feature: FeatureState,
  startFeatureId: string | null,
  endFeatureId: string | null
): ParsedMetadata => {
  const metadata = parseMetadata(feature.metadata);
  const infrastructure = metadata.infrastructure && typeof metadata.infrastructure === 'object'
    ? { ...metadata.infrastructure }
    : {};
  const network = metadata.network && typeof metadata.network === 'object'
    ? { ...metadata.network }
    : {};
  const fiber = metadata.fiber && typeof metadata.fiber === 'object'
    ? { ...metadata.fiber }
    : {};

  return {
    ...metadata,
    infrastructure: {
      ...infrastructure,
      type: 'SignalLine',
    },
    network: {
      ...network,
      ...(startFeatureId && !network.from_feature_id ? { from_feature_id: startFeatureId } : {}),
      ...(endFeatureId && !network.to_feature_id ? { to_feature_id: endFeatureId } : {}),
      ...(startFeatureId && !network.from_endpoint ? { from_endpoint: { type: 'feature', id: startFeatureId } } : {}),
      ...(endFeatureId && !network.to_endpoint ? { to_endpoint: { type: 'feature', id: endFeatureId } } : {}),
      direction_mode: network.direction_mode || 'auto',
    },
    fiber: {
      ...fiber,
      role: 'cable',
    },
  };
};

const findExistingCablePoint = (
  features: FeatureState[],
  cableId: string,
  pointKind: FiberCablePointKind,
  reusableFeatureIds: Set<string>,
  coordinate?: PointCoordinates
): FeatureState | undefined => {
  const key = coordinate ? coordinateKey(coordinate) : null;
  return features.find(feature => {
    const metadata = parseMetadata(feature.metadata);
    const fiber = metadata.fiber;
    if (fiber && fiber.cable_id === cableId && fiber.point_kind === pointKind) return true;
    return Boolean(
      key
      && isReusableFiberPoint(feature, reusableFeatureIds, pointKind)
      && isPoint(feature.coordinates)
      && coordinateKey(feature.coordinates) === key
    );
  });
};

const findExistingEnclosure = (
  features: FeatureState[],
  reusableFeatureIds: Set<string>,
  coordinate: PointCoordinates
): FeatureState | undefined => {
  const key = coordinateKey(coordinate);
  return features.find(feature => {
    return isReusableFiberPoint(feature, reusableFeatureIds, 'splice_enclosure')
      && isPoint(feature.coordinates)
      && coordinateKey(feature.coordinates) === key;
  });
};

const buildCablePoint = (
  createId: () => string,
  featureId: string,
  pointKind: FiberCablePointKind,
  sequenceNo: number,
  vertexIndex: number | null
): CablePointInput => ({
  id: createId(),
  feature_id: featureId,
  point_kind: pointKind,
  sequence_no: sequenceNo,
  vertex_index: vertexIndex,
});

const getFiberCount = (feature: FeatureState, existingCable?: FiberCable): number | null => {
  if (typeof existingCable?.fiber_count === 'number') return existingCable.fiber_count;
  const metadata = parseMetadata(feature.metadata);
  const coreCount = metadata.infrastructure?.core_count;
  return typeof coreCount === 'number' ? coreCount : null;
};

const getCableType = (feature: FeatureState, existingCable?: FiberCable): string | null => {
  if (existingCable?.cable_type) return existingCable.cable_type;
  const metadata = parseMetadata(feature.metadata);
  return metadata.infrastructure?.cable_type || metadata.infrastructure?.type || feature.geom_type || null;
};

const getCableStatus = (existingCable?: FiberCable): FiberCable['status'] => {
  if (existingCable?.status) return existingCable.status;
  return 'planned';
};

export const buildFiberPolylineMaterializationEvents = (
  projectId: string,
  featuresById: Record<string, FeatureState>,
  inventory: FiberInventory | null = null,
  options: FiberPolylineMaterializationOptions = {}
): FiberPolylineMaterializationResult => {
  const createId = options.createId || newId;
  const features = Object.values(featuresById);
  const candidates: LineCandidate[] = features
    .filter(isPolylineFeature)
    .map(feature => ({ feature, coordinates: getLineCoordinates(feature) }))
    .filter((item): item is LineCandidate => Boolean(item.coordinates));
  const existingCablesByFeature = new Map((inventory?.cables || []).map(cable => [cable.feature_id, cable]));
  const reusableFeatureIds = new Set<string>([
    ...(inventory?.cable_points || []).map(point => point.feature_id),
    ...(inventory?.equipment || []).map(equipment => equipment.feature_id),
  ]);
  const coordinateUsage = new Map<string, { point: PointCoordinates; cableIds: Set<string>; vertexRefs: Array<{ cableId: string; vertexIndex: number }> }>();

  candidates.forEach(candidate => {
    candidate.coordinates.forEach((point, vertexIndex) => {
      const key = coordinateKey(point);
      const usage = coordinateUsage.get(key) || { point, cableIds: new Set<string>(), vertexRefs: [] };
      usage.cableIds.add(candidate.feature.id);
      usage.vertexRefs.push({ cableId: candidate.feature.id, vertexIndex });
      coordinateUsage.set(key, usage);
    });
  });

  const branchKeys = new Set(
    [...coordinateUsage.entries()]
      .filter(([, usage]) => usage.cableIds.size > 1)
      .map(([key]) => key)
  );

  features.forEach(feature => {
    if (!isPolylineFeature(feature) && isReusableFiberPoint(feature, reusableFeatureIds) && isPoint(feature.coordinates)) {
      branchKeys.add(coordinateKey(feature.coordinates));
    }
  });

  const events: DesignEventType[] = [];
  const emittedEquipmentIds = new Set<string>();
  const countedEnclosureIds = new Set<string>();
  let pointCount = 0;
  let enclosureCount = 0;

  const pushEquipmentEvent = (featureId: string, equipmentType: FiberCablePointKind) => {
    const eventKey = `${featureId}:${equipmentType}`;
    if (emittedEquipmentIds.has(eventKey)) return;
    emittedEquipmentIds.add(eventKey);
    events.push({
      type: 'EquipmentUpserted',
      payload: {
        id: featureId,
        project_id: projectId,
        feature_id: featureId,
        equipment_type: equipmentType,
        status: 'active',
      },
    });
  };

  const targetCandidates = options.targetFeatureIds
    ? candidates.filter(c => options.targetFeatureIds!.includes(c.feature.id))
    : candidates;

  let cablesToMaterialize = new Set(options.targetFeatureIds);
  if (options.targetFeatureIds) {
    targetCandidates.forEach(candidate => {
      candidate.coordinates.forEach(point => {
        const key = coordinateKey(point);
        if (branchKeys.has(key)) {
          const usage = coordinateUsage.get(key);
          if (usage) {
            usage.cableIds.forEach(id => cablesToMaterialize.add(id));
          }
        }
      });
    });
  }

  const finalCandidates = options.targetFeatureIds
    ? candidates.filter(c => cablesToMaterialize.has(c.feature.id))
    : candidates;

  finalCandidates.forEach(candidate => {
    const { feature, coordinates } = candidate;
    const cableId = existingCablesByFeature.get(feature.id)?.id || feature.id;
    const existingCable = existingCablesByFeature.get(feature.id);
    const first = coordinates[0];
    const last = coordinates[coordinates.length - 1];
    const startPoint = findExistingCablePoint(features, cableId, 'cable_start', reusableFeatureIds, first);
    const endPoint = findExistingCablePoint(features, cableId, 'cable_end', reusableFeatureIds, last);
    const startFeatureId = startPoint?.id || null;
    const endFeatureId = endPoint?.id || null;
    const cablePoints: CablePointInput[] = [];

    if (startFeatureId) {
      cablePoints.push(buildCablePoint(createId, startFeatureId, 'cable_start', 0, 0));
      pushEquipmentEvent(startFeatureId, 'cable_start');
    }

    if (endFeatureId) {
      cablePoints.push(buildCablePoint(createId, endFeatureId, 'cable_end', coordinates.length - 1, coordinates.length - 1));
      pushEquipmentEvent(endFeatureId, 'cable_end');
    }

    coordinates.forEach((point, vertexIndex) => {
      const key = coordinateKey(point);
      if (!branchKeys.has(key)) return;
      const existingEnclosure = findExistingEnclosure(features, reusableFeatureIds, point);
      if (!existingEnclosure) return;
      cablePoints.push(buildCablePoint(createId, existingEnclosure.id, 'splice_enclosure', vertexIndex, vertexIndex));
      pushEquipmentEvent(existingEnclosure.id, 'splice_enclosure');
      if (!countedEnclosureIds.has(existingEnclosure.id)) {
        countedEnclosureIds.add(existingEnclosure.id);
        enclosureCount += 1;
        pointCount += 1;
      }
    });

    events.push({
      type: 'FeatureUpdated',
      payload: {
        id: feature.id,
        metadata: JSON.stringify(cloneMetadataWithFiberCable(feature, startFeatureId, endFeatureId)),
      },
    });

    events.push({
      type: 'FiberCableUpserted',
      payload: {
        id: cableId,
        project_id: projectId,
        feature_id: feature.id,
        cable_type: getCableType(feature, existingCable),
        fiber_count: getFiberCount(feature, existingCable),
        owner: null,
        status: getCableStatus(existingCable),
        source: existingCable?.source || 'legacy',
      },
    });

    if (cablePoints.length > 0) {
      events.push({
        type: 'FiberCablePointsMaterialized',
        payload: {
          id: createId(),
          project_id: projectId,
          cable_id: cableId,
          points: cablePoints,
        },
      });
    }
  });

  return {
    events,
    cableCount: finalCandidates.length,
    pointCount,
    enclosureCount,
  };
};

