export const upsertFiberCircuit = async (input: FiberCircuitUpsertInput) => {
  const batch: any[] = [
    {
      type: 'FiberCircuitUpserted',
      payload: {
        id: input.id,
        project_id: input.projectId,
        name: input.name,
        service_type: input.serviceType ?? 'data',
        status: input.status ?? 'planned',
        a_feature_id: input.aFeatureId,
        z_feature_id: input.zFeatureId,
      },
    },
  ];

  if (input.hops) {
    batch.push({
      type: 'FiberCircuitHopsReplaced',
      payload: {
        circuit_id: input.id,
        hops: input.hops.map(hop => ({
          sequence_no: hop.sequenceNo,
          strand_id: hop.strandId ?? null,
          port_id: hop.portId ?? null,
        })),
      },
    });
  }

  return invoke_design_event_batch(input.projectId, batch);
};

export const deleteFiberCircuit = async (projectId: string, circuitId: string) =>
  buildBatchResponse(projectId, {
    type: 'FiberCircuitDeleted',
    payload: { id: circuitId },
  });

export const materializeFiberFromPolylines = async (
  projectId: string,
  featuresById: Record<string, FeatureState>,
  inventory: FiberInventory | null = null,
  options: import('./fiberPolylineMaterializer').FiberPolylineMaterializationOptions = {}
) => {
  const materialization = buildFiberPolylineMaterializationEvents(projectId, featuresById, inventory, options);
  if (materialization.events.length === 0) {
    return {
      success: true,
      last_event_id: '',
      applied_events: [],
      side_effects: [],
    } satisfies DesignBulkActionResponse;
  }
  return invoke_design_event_batch(projectId, materialization.events);
};

import type {
  FeatureState,
  FiberCable,
  FiberCablePoint,
  FiberCapacitySummary,
  FiberInventory,
  FiberSplice,
  FiberStrand,
  FiberStrandStatus,
  FiberValidationDiagnostic,
} from '@CONTRACT/types';
import type { NetworkEdge } from './NetworkGraphService';

export type FiberInspectorTab = 'inventory' | 'strands' | 'equipment' | 'circuits' | 'diagnostics';

export const fiberStrandStatusLabel: Record<FiberStrandStatus, string> = {
  available: 'Khả dụng',
  reserved: 'Giữ chỗ',
  active: 'Đang dùng',
  damaged: 'Lỗi',
};

export const fiberStrandStatusClass: Record<FiberStrandStatus, string> = {
  available: 'border-emerald-500/25 bg-emerald-500/10 text-emerald-300',
  reserved: 'border-amber-500/25 bg-amber-500/10 text-amber-300',
  active: 'border-cyan-500/25 bg-cyan-500/10 text-cyan-300',
  damaged: 'border-red-500/25 bg-red-500/10 text-red-300',
};

export interface FiberCableRow {
  cable: FiberCable;
  label: string;
  initialized: boolean;
  strandCount: number;
  points: FiberCablePoint[];
  startPoint?: FiberCablePoint;
  endPoint?: FiberCablePoint;
  enclosureCount: number;
  capacity?: FiberCapacitySummary;
  diagnostics?: FiberValidationDiagnostic[];
}

export interface FiberLegacyCableCandidate {
  id: string;
  feature_id: string;
  label: string;
  cable_type: string | null;
  fiber_count: number | null;
  source_type: NetworkEdge['sourceType'];
  from: string;
  to: string;
}

export interface FiberSpliceChainItem {
  splice: FiberSplice;
  peerStrand?: FiberStrand;
}

export interface FiberDiagnosticGroup {
  type: FiberValidationDiagnostic['type'];
  count: number;
  diagnostics: FiberValidationDiagnostic[];
}

const getMetadataObject = (metadata: FeatureState['metadata'] | undefined): Record<string, any> => {
  if (!metadata) return {};
  if (typeof metadata === 'string') {
    try {
      return JSON.parse(metadata || '{}') as Record<string, any>;
    } catch {
      return {};
    }
  }
  return metadata as Record<string, any>;
};

export const getFeatureLabel = (
  featuresById: Record<string, FeatureState> | undefined,
  featureId: string | null | undefined
): string => {
  if (!featureId) return 'Chưa chọn';
  const feature = featuresById?.[featureId];
  return feature?.name || featureId;
};

export const buildCableRows = (
  inventory: FiberInventory | null,
  capacity: FiberCapacitySummary[],
  featuresById: Record<string, FeatureState> | undefined,
  diagnostics: FiberValidationDiagnostic[] = []
): FiberCableRow[] => {
  if (!inventory) return [];
  const capacityByCable = new Map(capacity.map(item => [item.cable_id, item]));
  const diagnosticsByCable = new Map<string, FiberValidationDiagnostic[]>();
  diagnostics.forEach(diag => {
    if ('cable_id' in diag && diag.cable_id) {
      const list = diagnosticsByCable.get(diag.cable_id as string) || [];
      list.push(diag);
      diagnosticsByCable.set(diag.cable_id as string, list);
    } else if ('feature_id' in diag && diag.feature_id) {
      // Find cable with this feature_id
      const cable = inventory.cables.find(c => c.feature_id === diag.feature_id);
      if (cable) {
        const list = diagnosticsByCable.get(cable.id) || [];
        list.push(diag);
        diagnosticsByCable.set(cable.id, list);
      }
    }
  });

  const pointsByCable = new Map<string, FiberCablePoint[]>();
  (inventory.cable_points || []).forEach(point => {
    const points = pointsByCable.get(point.cable_id) || [];
    points.push(point);
    pointsByCable.set(point.cable_id, points);
  });

  return inventory.cables.map(cable => {
    const strandCount = inventory.strands.filter(strand => strand.cable_id === cable.id).length;
    const points = pointsByCable.get(cable.id) || [];
    return {
      cable,
      label: getFeatureLabel(featuresById, cable.feature_id),
      initialized: strandCount > 0,
      strandCount,
      points,
      startPoint: points.find(point => point.point_kind === 'cable_start'),
      endPoint: points.find(point => point.point_kind === 'cable_end'),
      enclosureCount: points.filter(point => point.point_kind === 'splice_enclosure').length,
      capacity: capacityByCable.get(cable.id),
      diagnostics: diagnosticsByCable.get(cable.id),
    };
  });
};

export const buildLegacyFiberCableCandidates = (
  edges: NetworkEdge[],
  inventory: FiberInventory | null,
  featuresById: Record<string, FeatureState> | undefined
): FiberLegacyCableCandidate[] => {
  const existingFeatureIds = new Set(inventory?.cables.map(cable => cable.feature_id) || []);

  return edges
    .filter(edge => !existingFeatureIds.has(edge.feature?.id || edge.id))
    .map(edge => {
      const metadata = getMetadataObject(edge.feature?.metadata);
      const infrastructure = metadata.infrastructure && typeof metadata.infrastructure === 'object'
        ? metadata.infrastructure as Record<string, any>
        : {};

      return {
        id: edge.id,
        feature_id: edge.feature?.id || edge.id,
        label: getFeatureLabel(featuresById, edge.feature?.id || edge.id),
        cable_type: infrastructure.cable_type || infrastructure.type || null,
        fiber_count: typeof infrastructure.core_count === 'number' ? infrastructure.core_count : null,
        source_type: edge.sourceType,
        from: edge.from,
        to: edge.to,
      };
    });
};

export const filterFiberStrands = (
  strands: FiberStrand[],
  cableId: string | null,
  status: FiberStrandStatus | 'all',
  query: string
): FiberStrand[] => {
  const normalizedQuery = query.trim().toLowerCase();
  return strands.filter(strand => {
    if (cableId && strand.cable_id !== cableId) return false;
    if (status !== 'all' && strand.status !== status) return false;
    if (!normalizedQuery) return true;
    return [
      strand.id,
      String(strand.strand_no),
      strand.color || '',
      fiberStrandStatusLabel[strand.status],
    ].join(' ').toLowerCase().includes(normalizedQuery);
  });
};

export const getSpliceChainForStrand = (
  strandId: string | null,
  splices: FiberSplice[],
  strands: FiberStrand[]
): FiberSpliceChainItem[] => {
  if (!strandId) return [];
  const strandsById = new Map(strands.map(strand => [strand.id, strand]));
  return splices
    .filter(splice => splice.from_strand_id === strandId || splice.to_strand_id === strandId)
    .map(splice => {
      const peerId = splice.from_strand_id === strandId ? splice.to_strand_id : splice.from_strand_id;
      return { splice, peerStrand: strandsById.get(peerId) };
    });
};

export const groupFiberDiagnostics = (
  diagnostics: FiberValidationDiagnostic[]
): FiberDiagnosticGroup[] => {
  const byType = new Map<FiberValidationDiagnostic['type'], FiberValidationDiagnostic[]>();
  diagnostics.forEach(diagnostic => {
    const items = byType.get(diagnostic.type) || [];
    items.push(diagnostic);
    byType.set(diagnostic.type, items);
  });
  return [...byType.entries()].map(([type, items]) => ({
    type,
    count: items.length,
    diagnostics: items,
  }));
};

import type { DesignEventType, FeatureMetadata, FeatureState, LineStringCoordinates } from '@CONTRACT/types';
import { getLineCoordinates, getParsedCoordinates, getPointCoordinates } from '@TOOL/utils/featureMapping';
import { getParsedMetadata } from '@TOOL/utils/featureMetadata';
import {
    getNetworkEndpointKey,
    getNetworkEndpointsFromMetadata,
    getRepresentativeFeatureIdForEndpoint,
    type NetworkEndpointRef,
} from './NetworkEndpoint';

export type NetworkRole = 'cabinet' | 'intersection' | 'device';
export type StoredDirectionMode = 'auto' | 'manual' | 'legacy';

export interface NetworkNodeDescriptor {
    id: string;
    feature: FeatureState;
    metadata: FeatureMetadata;
    role: NetworkRole;
    parentFeatureId?: string;
    isOrigin: boolean;
}

export interface NetworkEdgeDescriptor {
    id: string;
    feature: FeatureState;
    metadata: FeatureMetadata;
    from: string;
    to: string;
    fromEndpoint: NetworkEndpointRef;
    toEndpoint: NetworkEndpointRef;
    fromEndpointKey: string;
    toEndpointKey: string;
    directionMode: StoredDirectionMode;
}

export interface NetworkComponentDescriptor {
    nodeIds: string[];
    edgeIds: string[];
    originIds: string[];
}

export interface OrientedEdgeDescriptor {
    edgeId: string;
    from: string;
    to: string;
    directionMode: StoredDirectionMode;
    state: 'confirmed' | 'pending' | 'conflict';
}

const normalizeText = (value: unknown): string =>
    (typeof value === 'string' ? value : typeof value === 'number' || typeof value === 'boolean' ? String(value) : '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase();

export const isLineFeature = (feature: FeatureState): boolean => {
    const geomType = (feature.geom_type || feature.geometry_type || '').toLowerCase();
    return geomType.includes('line');
};

export const isNetworkEdgeFeature = (feature: FeatureState, metadata: FeatureMetadata = getParsedMetadata(feature) as FeatureMetadata): boolean => {
    const geomType = (feature.geom_type || feature.geometry_type || '').toLowerCase();
    return geomType.includes('line') || metadata.infrastructure?.type === 'NetworkLink';
};

export const inferNetworkRole = (feature: FeatureState, metadata: FeatureMetadata = getParsedMetadata(feature) as FeatureMetadata): NetworkRole => {
    const explicitRole = metadata.network?.role;
    if (explicitRole === 'cabinet' || explicitRole === 'intersection' || explicitRole === 'device') return explicitRole;

    const icon = normalizeText(metadata.icon);
    const type = normalizeText((metadata as Record<string, unknown>).type);
    const name = normalizeText(feature.name);

    if (icon === 'intersection' || type.includes('intersection') || type.includes('nut giao') || name.includes('nut giao')) {
        return 'intersection';
    }

    if (['cabinet', 'box', 'server'].includes(icon) || type.includes('cabinet') || type.includes('tu thiet bi') || name.includes('tu thiet bi') || name.includes('tu cap')) {
        return 'cabinet';
    }

    return 'device';
};

export const isSourceRole = (role: NetworkRole): boolean => role === 'cabinet' || role === 'intersection';

export const isPointFeature = (feature: FeatureState): boolean => {
    const geomType = (feature.geom_type || feature.geometry_type || '').toLowerCase();
    return geomType === 'point' || (!!getPointCoordinates(feature) && !isLineFeature(feature));
};

export const getStoredDirectionMode = (metadata: FeatureMetadata): StoredDirectionMode => {
    const mode = metadata.network?.direction_mode;
    if (mode === 'auto' || mode === 'manual') return mode;
    return 'legacy';
};

export const collectNetworkNodes = (featuresById: Record<string, FeatureState>): Map<string, NetworkNodeDescriptor> => {
    const nodes = new Map<string, NetworkNodeDescriptor>();

    for (const feature of Object.values(featuresById)) {
        const metadata = getParsedMetadata(feature) as FeatureMetadata;
        if (isLineFeature(feature) || isNetworkEdgeFeature(feature, metadata)) continue;

        const role = inferNetworkRole(feature, metadata);
        nodes.set(feature.id, {
            id: feature.id,
            feature,
            metadata,
            role,
            parentFeatureId: typeof metadata.parent_feature_id === 'string' ? metadata.parent_feature_id : undefined,
            isOrigin: metadata.network?.is_origin === true,
        });
    }

    return nodes;
};

export const collectNetworkEdges = (featuresById: Record<string, FeatureState>, nodeIds?: Set<string>): NetworkEdgeDescriptor[] => {
    const validNodeIds = nodeIds ?? new Set(collectNetworkNodes(featuresById).keys());
    const edges: NetworkEdgeDescriptor[] = [];

    for (const feature of Object.values(featuresById)) {
        const metadata = getParsedMetadata(feature) as FeatureMetadata;
        if (!isNetworkEdgeFeature(feature, metadata)) continue;

        const { fromEndpoint, toEndpoint } = getNetworkEndpointsFromMetadata(metadata);
        if (!fromEndpoint || !toEndpoint) continue;
        const from = getRepresentativeFeatureIdForEndpoint(fromEndpoint, featuresById);
        const to = getRepresentativeFeatureIdForEndpoint(toEndpoint, featuresById);
        if (!from || !to || !validNodeIds.has(from) || !validNodeIds.has(to) || getNetworkEndpointKey(fromEndpoint) === getNetworkEndpointKey(toEndpoint)) continue;

        edges.push({
            id: feature.id,
            feature,
            metadata,
            from,
            to,
            fromEndpoint,
            toEndpoint,
            fromEndpointKey: getNetworkEndpointKey(fromEndpoint),
            toEndpointKey: getNetworkEndpointKey(toEndpoint),
            directionMode: getStoredDirectionMode(metadata),
        });
    }

    return edges;
};

export const buildNetworkComponents = (featuresById: Record<string, FeatureState>): NetworkComponentDescriptor[] => {
    const nodes = collectNetworkNodes(featuresById);
    const nodeIds = new Set(nodes.keys());
    const edges = collectNetworkEdges(featuresById, nodeIds);
    const adjacency = new Map<string, Set<string>>();
    const edgeIdsByNode = new Map<string, Set<string>>();

    for (const nodeId of nodeIds) {
        adjacency.set(nodeId, new Set());
        edgeIdsByNode.set(nodeId, new Set());
    }

    for (const edge of edges) {
        adjacency.get(edge.from)?.add(edge.to);
        adjacency.get(edge.to)?.add(edge.from);
        edgeIdsByNode.get(edge.from)?.add(edge.id);
        edgeIdsByNode.get(edge.to)?.add(edge.id);
    }

    const visited = new Set<string>();
    const components: NetworkComponentDescriptor[] = [];

    for (const nodeId of nodeIds) {
        if (visited.has(nodeId)) continue;

        const queue = [nodeId];
        const componentNodeIds: string[] = [];
        const componentEdgeIds = new Set<string>();
        visited.add(nodeId);

        while (queue.length > 0) {
            const current = queue.shift();
            if (!current) continue;
            componentNodeIds.push(current);

            for (const edgeId of edgeIdsByNode.get(current) || []) {
                componentEdgeIds.add(edgeId);
            }

            for (const neighbor of adjacency.get(current) || []) {
                if (visited.has(neighbor)) continue;
                visited.add(neighbor);
                queue.push(neighbor);
            }
        }

        const originIds = componentNodeIds.filter(id => nodes.get(id)?.isOrigin);
        components.push({
            nodeIds: componentNodeIds,
            edgeIds: [...componentEdgeIds],
            originIds,
        });
    }

    return components;
};

export const getComponentForNode = (featuresById: Record<string, FeatureState>, nodeId: string): NetworkComponentDescriptor | null =>
    buildNetworkComponents(featuresById).find(component => component.nodeIds.includes(nodeId)) || null;

const reverseLineCoordinates = (feature: FeatureState): LineStringCoordinates | undefined => {
    const coords = getLineCoordinates(feature);
    if (!coords || coords.length < 2) return undefined;
    return [...coords].reverse();
};

const buildFeatureUpdateEvent = (
    feature: FeatureState,
    metadata: FeatureMetadata,
    coordinates?: LineStringCoordinates
): DesignEventType => ({
    type: 'FeatureUpdated',
    payload: {
        id: feature.id,
        ...(coordinates ? { coordinates } : {}),
        metadata: JSON.stringify(metadata),
    },
});

const buildAdjacency = (component: NetworkComponentDescriptor, edges: Map<string, NetworkEdgeDescriptor>) => {
    const adjacency = new Map<string, Set<string>>();

    for (const nodeId of component.nodeIds) {
        adjacency.set(nodeId, new Set());
    }

    for (const edgeId of component.edgeIds) {
        const edge = edges.get(edgeId);
        if (!edge) continue;
        adjacency.get(edge.from)?.add(edge.to);
        adjacency.get(edge.to)?.add(edge.from);
    }

    return adjacency;
};

const computeTopologyDistance = (component: NetworkComponentDescriptor, edges: Map<string, NetworkEdgeDescriptor>, originId: string) => {
    const adjacency = buildAdjacency(component, edges);
    const distances = new Map<string, number>([[originId, 0]]);
    const queue = [originId];

    while (queue.length > 0) {
        const current = queue.shift();
        if (!current) continue;
        const currentDistance = distances.get(current) ?? 0;

        for (const neighbor of adjacency.get(current) || []) {
            if (distances.has(neighbor)) continue;
            distances.set(neighbor, currentDistance + 1);
            queue.push(neighbor);
        }
    }

    return distances;
};

export const buildSetOriginEvents = (featuresById: Record<string, FeatureState>, originId: string): DesignEventType[] => {
    return buildToggleOriginEvents(featuresById, originId);
};

export const buildToggleOriginEvents = (featuresById: Record<string, FeatureState>, nodeId: string): DesignEventType[] => {
    const nodes = collectNetworkNodes(featuresById);
    const originNode = nodes.get(nodeId);
    if (!originNode) return [];

    const component = getComponentForNode(featuresById, nodeId);
    if (!component) return [];

    const events: DesignEventType[] = [];
    const shouldClear = originNode.isOrigin;
    const nextOriginId = shouldClear ? null : nodeId;
    const edges = new Map(collectNetworkEdges(featuresById, new Set(nodes.keys())).map(edge => [edge.id, edge]));

    for (const nodeId of component.nodeIds) {
        const node = nodes.get(nodeId);
        if (!node) continue;
        const nextMetadata: FeatureMetadata = {
            ...node.metadata,
            network: {
                ...(node.metadata.network || {}),
                ...(shouldClear ? {} : { is_origin: nodeId === nextOriginId }),
            },
        };

        if ((shouldClear && node.metadata.network?.is_origin) || (!shouldClear && node.metadata.network?.is_origin !== (nodeId === nextOriginId))) {
            events.push(buildFeatureUpdateEvent(node.feature, nextMetadata));
        }
    }

    if (shouldClear) return events;
    const distances = computeTopologyDistance(component, edges, nodeId);

    for (const edgeId of component.edgeIds) {
        const edge = edges.get(edgeId);
        if (!edge || edge.directionMode !== 'auto') continue;

        const fromDistance = distances.get(edge.from);
        const toDistance = distances.get(edge.to);
        if (fromDistance === undefined || toDistance === undefined || fromDistance === toDistance) continue;

        const shouldReverse = fromDistance > toDistance;
        const nextFrom = shouldReverse ? edge.to : edge.from;
        const nextTo = shouldReverse ? edge.from : edge.to;
        const nextMetadata: FeatureMetadata = {
            ...edge.metadata,
            network: {
                ...(edge.metadata.network || {}),
                from_feature_id: nextFrom,
                to_feature_id: nextTo,
                direction_mode: 'auto',
            },
        };

        const coordinates = shouldReverse ? reverseLineCoordinates(edge.feature) : undefined;
        const metadataChanged = edge.metadata.network?.from_feature_id !== nextFrom ||
            edge.metadata.network?.to_feature_id !== nextTo ||
            edge.metadata.network?.direction_mode !== 'auto';

        if (metadataChanged || coordinates) {
            events.push(buildFeatureUpdateEvent(edge.feature, nextMetadata, coordinates));
        }
    }

    return events;
};

export const buildManualEdgeDirectionEvent = (feature: FeatureState, reverse = false): DesignEventType | null => {
    const metadata = getParsedMetadata(feature) as FeatureMetadata;
    if (!isNetworkEdgeFeature(feature, metadata)) return null;

    const from = metadata.network?.from_feature_id;
    const to = metadata.network?.to_feature_id;
    if (!from || !to) return null;

    const nextFrom = reverse ? to : from;
    const nextTo = reverse ? from : to;
    const nextMetadata: FeatureMetadata = {
        ...metadata,
        network: {
            ...(metadata.network || {}),
            from_feature_id: nextFrom,
            to_feature_id: nextTo,
            direction_mode: 'manual',
        },
    };

    const coordinates = reverse ? reverseLineCoordinates(feature) : undefined;
    return buildFeatureUpdateEvent(feature, nextMetadata, coordinates);
};

export const buildSnapLinks = (snapIds: Array<string | null | undefined>): Record<string, string> | undefined => {
    const entries = snapIds
        .map((snapId, index) => snapId ? [`v${index}`, snapId] as [string, string] : null)
        .filter((entry): entry is [string, string] => entry !== null);

    if (entries.length === 0) return undefined;
    return Object.fromEntries(entries);
};

export const getPolylineSnapCoordinate = (feature: FeatureState, lng: number, lat: number): [number, number] | null => {
    const coords = getLineCoordinates(feature);
    if (!coords || coords.length < 2) return null;

    let bestPoint: [number, number] | null = null;
    let bestDistance = Number.POSITIVE_INFINITY;

    for (let index = 0; index < coords.length - 1; index += 1) {
        const start = coords[index];
        const end = coords[index + 1];
        const dx = end[0] - start[0];
        const dy = end[1] - start[1];
        const lengthSquared = dx * dx + dy * dy;
        if (lengthSquared === 0) continue;

        const t = Math.max(0, Math.min(1, ((lng - start[0]) * dx + (lat - start[1]) * dy) / lengthSquared));
        const projectedLng = start[0] + t * dx;
        const projectedLat = start[1] + t * dy;
        const distance = Math.hypot(projectedLng - lng, projectedLat - lat);

        if (distance < bestDistance) {
            bestDistance = distance;
            bestPoint = [projectedLng, projectedLat];
        }
    }

    return bestPoint;
};

const distanceToPoint = (source: [number, number], target: [number, number]): number =>
    Math.hypot(source[0] - target[0], source[1] - target[1]);

export const resolveNetworkNodeIdFromSnap = (
    featuresById: Record<string, FeatureState>,
    snapFeatureId: string | null | undefined,
    snappedCoordinate?: [number, number] | null
): string | null => {
    if (!snapFeatureId) return null;
    const snapFeature = featuresById[snapFeatureId];
    if (!snapFeature) return null;

    const snapMetadata = getParsedMetadata(snapFeature) as FeatureMetadata;
    if (!isNetworkEdgeFeature(snapFeature, snapMetadata)) {
        return isPointFeature(snapFeature) ? snapFeature.id : null;
    }

    const { fromEndpoint, toEndpoint } = getNetworkEndpointsFromMetadata(snapMetadata);
    const fromId = fromEndpoint ? getRepresentativeFeatureIdForEndpoint(fromEndpoint, featuresById) : null;
    const toId = toEndpoint ? getRepresentativeFeatureIdForEndpoint(toEndpoint, featuresById) : null;
    if (!fromId || !toId) return null;

    const fromFeature = featuresById[fromId];
    const toFeature = featuresById[toId];
    const fromCoords = getPointCoordinates(fromFeature);
    const toCoords = getPointCoordinates(toFeature);
    if (!fromCoords || !toCoords) return null;

    if (!snappedCoordinate) {
        return fromId;
    }

    return distanceToPoint(snappedCoordinate, fromCoords) <= distanceToPoint(snappedCoordinate, toCoords)
        ? fromId
        : toId;
};

export const isPolylineEndpointIndex = (feature: FeatureState, index: number): boolean => {
    const coords = getParsedCoordinates(feature);
    if (!Array.isArray(coords)) return false;
    const geomType = (feature.geom_type || '').toLowerCase();

    if (geomType === 'polygon') {
        if (!Array.isArray(coords[0])) return false;
        const ring = coords[0] as unknown[];
        return index === 0 || index === ring.length - 1;
    }

    return index === 0 || index === coords.length - 1;
};

import { create } from 'zustand';
import type { NetworkStatusSnapshot, NetworkEntityStatus } from './NetworkGraphService';

export interface TelemetryEvent {
    entityId: string;
    entityType: 'node' | 'edge';
    status: NetworkEntityStatus;
    observedAt: number;
}

export interface EntityData {
    status: NetworkEntityStatus;
    observedAt: number;
}

interface NetworkStatusState {
    mode: 'realtime' | 'simulation';
    isStale: boolean;
    realtimeData: {
        nodes: Record<string, EntityData>;
        edges: Record<string, EntityData>;
    };
    simulationData: NetworkStatusSnapshot;
    setMode: (mode: 'realtime' | 'simulation') => void;
    receiveEvent: (event: TelemetryEvent) => void;
    markRealtimeDisconnected: () => void;
    simulateEvent: (entityId: string, entityType: 'node' | 'edge', status: NetworkEntityStatus) => void;
    resetSimulation: () => void;
    getSnapshot: () => NetworkStatusSnapshot;
}

export const useNetworkStatusStore = create<NetworkStatusState>((set, get) => ({
    mode: 'realtime',
    isStale: true,
    realtimeData: { nodes: {}, edges: {} },
    simulationData: { nodes: {}, edges: {} },

    setMode: (mode) => {
        set({ mode });
        if (mode === 'simulation') {
            get().resetSimulation();
        }
    },

    receiveEvent: (event) => {
        set((state) => {
            const data = state.realtimeData;
            const collection = event.entityType === 'node' ? 'nodes' : 'edges';
            const currentData = data[collection][event.entityId];

            if (currentData && currentData.observedAt > event.observedAt) {
                return state;
            }

            return {
                isStale: false,
                realtimeData: {
                    ...data,
                    [collection]: {
                        ...data[collection],
                        [event.entityId]: {
                            status: event.status,
                            observedAt: event.observedAt
                        }
                    }
                }
            };
        });
    },

    markRealtimeDisconnected: () => {
        set({ isStale: true });
    },

    simulateEvent: (entityId, entityType, status) => {
        set((state) => {
            const data = state.simulationData;
            const collection = entityType === 'node' ? 'nodes' : 'edges';
            return {
                simulationData: {
                    ...data,
                    [collection]: {
                        ...data[collection],
                        [entityId]: status
                    }
                }
            };
        });
    },

    resetSimulation: () => {
        set((state) => {
            const snap: NetworkStatusSnapshot = { nodes: {}, edges: {} };
            for (const [id, data] of Object.entries(state.realtimeData.nodes)) {
                snap.nodes![id] = data.status;
            }
            for (const [id, data] of Object.entries(state.realtimeData.edges)) {
                snap.edges![id] = data.status;
            }
            return { simulationData: snap };
        });
    },

    getSnapshot: () => {
        const state = get();
        if (state.mode === 'realtime') {
            const snap: NetworkStatusSnapshot = { nodes: {}, edges: {} };
            for (const [id, data] of Object.entries(state.realtimeData.nodes)) {
                snap.nodes![id] = data.status;
            }
            for (const [id, data] of Object.entries(state.realtimeData.edges)) {
                snap.edges![id] = data.status;
            }
            return snap;
        }
        return state.simulationData;
    }
}));

import { StateCreator } from 'zustand';
import { DesignActionSlice, DesignSyncStore } from './types';
import { invoke } from '@tauri-apps/api/core';
import { logger } from '../../../../tool/utils/logger';
import { invoke_design_event_batch } from '../../../../tool/utils/designIpc';
import { enrichEventBeforeDispatch } from '../../../../tool/utils/designEvents';
import { DesignEventType } from '@CONTRACT/designTypes';

let lastRecoveryInitializeAt = 0;
const RECOVERY_INITIALIZE_COOLDOWN_MS = 5000;
let consecutiveSyncFailures = 0;
let firstFailureAt = 0;
const SYNC_FAILURE_WINDOW_MS = 30000;
const MAX_SYNC_FAILURES_BEFORE_BREAKER = 3;
const IS_DEV = import.meta.env.DEV;

const shouldRecoverByInitialize = (): boolean => {
    const now = Date.now();
    if (!firstFailureAt || now - firstFailureAt > SYNC_FAILURE_WINDOW_MS) {
        firstFailureAt = now;
        consecutiveSyncFailures = 1;
    } else {
        consecutiveSyncFailures += 1;
    }
    return consecutiveSyncFailures < MAX_SYNC_FAILURES_BEFORE_BREAKER;
};

const markSyncRecovered = () => {
    consecutiveSyncFailures = 0;
    firstFailureAt = 0;
};

const tryRecoveryInitialize = (get: () => DesignSyncStore, projectId: string) => {
    const now = Date.now();
    const st = get();
    if (st.isLoading || st.isHydrating || st.error) {
        return;
    }
    if (now - lastRecoveryInitializeAt <= RECOVERY_INITIALIZE_COOLDOWN_MS) {
        return;
    }
    lastRecoveryInitializeAt = now;
    st.initialize(projectId, st.projectPath ?? undefined);
};

export const createDesignActionSlice: StateCreator<DesignSyncStore, [], [], DesignActionSlice> = (set, get) => ({
    dispatchEvent: async (incomingEvent) => {
        const { projectId, state, lastDispatchTime, isHydrating } = get();
        if (!projectId || !state || isHydrating) return;
        const event = enrichEventBeforeDispatch(incomingEvent);

        if (event.type === 'FeatureUpdated') {
            const payload = event.payload as any;
            if (payload.id && payload.coordinates) {
                const now = Date.now();
                const last = lastDispatchTime[payload.id] || 0;
                if (now - last < 50) return;
                set(prev => ({ lastDispatchTime: { ...prev.lastDispatchTime, [payload.id]: now } }));
            }
        }

        const previousState = state;
        try {
            get().applyEventsOptimistically([incomingEvent]);
            set({ pendingSync: true, error: null });

            if (IS_DEV) {
                console.log(`[Sync] Dispatching ${event.type} to Rust (Incremental)...`, event.payload);
            }

            return invoke_design_event_batch(projectId, [event])
                .then((response) => {
                    markSyncRecovered();
                    if (response) {
                        get().applyPatchToState(response);
                    }
                    if (event.type === 'FeatureCreated' || (event.type === 'FeatureUpdated' && (event.payload as any).metadata)) {
                        get().syncDisplayOrderWithSTT();
                    }
                })
                .catch((e: any) => {
                    console.error("[Sync] Dispatch error, rolling back or re-hydrating:", e);
                    const now = Date.now();
                    if (shouldRecoverByInitialize() && now - lastRecoveryInitializeAt > RECOVERY_INITIALIZE_COOLDOWN_MS) {
                        tryRecoveryInitialize(get, projectId);
                    } else {
                        set({ error: "Sync đang lỗi liên tục. Đã tạm ngắt tự đồng bộ để tránh lặp. Vui lòng mở lại dự án." });
                    }
                    throw e;
                })
                .finally(() => {
                    set({ pendingSync: false });
                });
        } catch (e: any) {
            console.error("[Sync] internal dispatch error:", e);
            set({ state: previousState, pendingSync: false });
            throw e;
        }
    },

    dispatchEvents: async (events) => {
        const { projectId, state, isHydrating } = get();
        if (!projectId || !state || isHydrating || events.length === 0) return;

        const enrichedEvents = events.map(enrichEventBeforeDispatch);
        const previousState = state;

        try {
            get().applyEventsOptimistically(events);
            set({ pendingSync: true, error: null });

            return invoke_design_event_batch(projectId, enrichedEvents)
                .then((response) => {
                    markSyncRecovered();
                    if (response) {
                        get().applyPatchToState(response);
                    }
                })
                .catch((e: any) => {
                    console.error("[Sync] Batch dispatch error:", e);
                    const now = Date.now();
                    if (shouldRecoverByInitialize() && now - lastRecoveryInitializeAt > RECOVERY_INITIALIZE_COOLDOWN_MS) {
                        tryRecoveryInitialize(get, projectId);
                    } else {
                        set({ error: "Sync đang lỗi liên tục. Đã tạm ngắt tự đồng bộ để tránh lặp. Vui lòng mở lại dự án." });
                    }
                    throw e;
                })
                .finally(() => {
                    set({ pendingSync: false });
                });
        } catch (e: any) {
            set({ state: previousState, pendingSync: false });
            throw e;
        }
    },

    queueEvent: async (event) => get().queueEvents([event]),

    queueEvents: async (events) => {
        const { projectId: queuedProjectId, projectKey: queuedProjectKey } = get();
        if (!queuedProjectId || events.length === 0) return;

        const preparedEvents = events.map(enrichEventBeforeDispatch);
        get().applyEventsOptimistically(events);
        set({ pendingSync: true });

        try {
            const response = await get()._internalBufferedSyncEvents(preparedEvents);
            const currentStore = get();

            if (
                response &&
                currentStore.projectId === queuedProjectId &&
                (currentStore.projectKey ?? `id:${queuedProjectId}`) === queuedProjectKey
            ) {
                currentStore.applyQueuedAckToState(response);
            }
        } catch (error) {
            console.error('[Sync] Direct sync failed for palette/settings:', error);
            throw error;
        } finally {
            set({ pendingSync: false });
        }
    },

    undo: async () => {
        const { projectId } = get();
        if (!projectId) return;
        try {
            const responseStr = await invoke<string>('undo_design_event', { projectId });
            const response = JSON.parse(responseStr);
            if (response.success) {
                tryRecoveryInitialize(get, projectId);
            }
        } catch (e) {
            logger.error(`[Sync] Undo failed: ${e instanceof Error ? e.message : String(e)}`);
        }
    },

    redo: async () => {
        const { projectId } = get();
        if (!projectId) return;
        try {
            const responseStr = await invoke<string>('redo_design_event', { projectId });
            const response = JSON.parse(responseStr);
            if (response.success) {
                tryRecoveryInitialize(get, projectId);
            }
        } catch (e) {
            logger.error(`[Sync] Redo failed: ${e instanceof Error ? e.message : String(e)}`);
        }
    },

    deduplicate: async () => {
        const { projectId } = get();
        if (!projectId) return;
        try {
            await invoke('deduplicate_features', { projectId });
            tryRecoveryInitialize(get, projectId);
        } catch (e) {
            logger.error(`[Sync] Deduplicate failed: ${e instanceof Error ? e.message : String(e)}`);
        }
    },

    deleteFeature: async (id) => {
        const { dispatchEvent, boxSelection, setBoxSelection } = get();
        await dispatchEvent({
            type: 'FeatureDeleted',
            payload: { id }
        });

        if (boxSelection) {
            const updatedItems = boxSelection.items.filter(item => item.id !== id);
            if (updatedItems.length === 0) {
                setBoxSelection(null);
            } else {
                setBoxSelection({
                    ...boxSelection,
                    count: updatedItems.length,
                    items: updatedItems,
                });
            }
        }
    },

    deleteSelectedFeatures: async () => {
        const { selectionSet, dispatchEvents, boxSelection, setBoxSelection } = get();
        if (selectionSet.size === 0) return;

        const idsToDelete = Array.from(selectionSet);
        const events: DesignEventType[] = idsToDelete.map(id => ({
            type: 'FeatureDeleted',
            payload: { id }
        }));

        await dispatchEvents(events);
        set({ selectionSet: new Set() });

        if (boxSelection) {
            const updatedItems = boxSelection.items.filter(item => !selectionSet.has(item.id));
            if (updatedItems.length === 0) {
                setBoxSelection(null);
            } else if (updatedItems.length !== boxSelection.items.length) {
                setBoxSelection({
                    ...boxSelection,
                    count: updatedItems.length,
                    items: updatedItems,
                });
            }
        }
    },

    syncDisplayOrderWithSTT: async () => {
        const { state, dispatchEvents } = get();
        if (!state || !state.features) return;

        // FeatureUtils calculateFeatureNumbers and getParsedMetadata are needed
        // I already moved them to @TOOL/utils/featureUtils
        const { calculateFeatureNumbers, getParsedMetadata, syncDisplayOrderAliases } = await import('../../../../tool/utils/featureUtils');

        const features = Object.values(state.features);
        const featureNumbers = calculateFeatureNumbers(features, state.features);
        const updateEvents: DesignEventType[] = [];

        features.forEach(f => {
            const calculatedSTT = featureNumbers[f.id];
            if (!calculatedSTT) return;
            const rawMetaStr = typeof f.metadata === 'string' ? f.metadata : '';
            const meta = getParsedMetadata(f);
            const nextMeta = syncDisplayOrderAliases(
                meta as Record<string, unknown>,
                String(calculatedSTT),
                f.properties as Record<string, unknown>
            );
            const currentOrder = typeof meta.display_order === 'string' || typeof meta.display_order === 'number'
                ? String(meta.display_order)
                : '';
            const currentAliasState = JSON.stringify(syncDisplayOrderAliases(
                meta as Record<string, unknown>,
                currentOrder,
                f.properties as Record<string, unknown>
            ));

            if (currentOrder !== String(calculatedSTT) || currentAliasState !== JSON.stringify(nextMeta)) {
                if (Object.keys(meta).length === 0 && rawMetaStr.length > 4 && rawMetaStr !== 'null' && rawMetaStr !== 'undefined') {
                    return;
                }
                updateEvents.push({
                    type: 'FeatureUpdated',
                    payload: {
                        id: f.id,
                        metadata: JSON.stringify(nextMeta)
                    }
                });
            }
        });

        if (updateEvents.length > 0) {
            await dispatchEvents(updateEvents);
        }
    }
});

import { StateCreator } from 'zustand';
import { DrawingSlice, DesignSyncStore } from './types';
import { emit } from '@tauri-apps/api/event';
import { getParsedCoordinates, getParsedMetadata, getPointCoordinates } from '../../../../tool/utils/featureUtils';
import type { LineStringCoordinates, PolygonCoordinates, FeatureState } from '@CONTRACT/types';
import { buildSnapLinks, isPolylineEndpointIndex } from '../network/networkTopology';

const isPolygonCoordinates = (coords: unknown): coords is PolygonCoordinates =>
    Array.isArray(coords) &&
    Array.isArray(coords[0]) &&
    Array.isArray((coords[0] as unknown[])[0]);

const isLineCoordinates = (coords: unknown): coords is LineStringCoordinates =>
    Array.isArray(coords) &&
    Array.isArray(coords[0]) &&
    !Array.isArray((coords[0] as unknown[])[0]);

export const isPointInPolygon = (point: [number, number], polygon: PolygonCoordinates): boolean => {
    const ring = polygon[0];
    if (!ring || ring.length < 3) return false;

    const x = point[0]; // lng
    const y = point[1]; // lat
    let inside = false;

    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const xi = ring[i][0];
        const yi = ring[i][1];
        const xj = ring[j][0];
        const yj = ring[j][1];

        const intersect = ((yi > y) !== (yj > y))
            && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
        if (intersect) inside = !inside;
    }

    return inside;
};

export const getIntersectionScope = (
    parentId: string | null,
    features: Record<string, FeatureState>
): PolygonCoordinates | null => {
    if (!parentId || !features) return null;

    const parentFeature = features[parentId];
    if (parentFeature && (parentFeature.geom_type || '').toLowerCase() === 'polygon') {
        const coords = getParsedCoordinates(parentFeature);
        if (isPolygonCoordinates(coords)) {
            return coords;
        }
    }

    for (const f of Object.values(features)) {
        const fMeta = getParsedMetadata(f);
        if (fMeta.parent_feature_id === parentId && (f.geom_type || '').toLowerCase() === 'polygon') {
            const coords = getParsedCoordinates(f);
            if (isPolygonCoordinates(coords)) {
                return coords;
            }
        }
    }

    return null;
};

export const isSignalLineFeature = (feature: FeatureState): boolean => {
    if (!feature) return false;
    const geomType = (feature.geom_type || '').toLowerCase();
    return geomType.includes('line');
};

export const createDrawingSlice: StateCreator<DesignSyncStore, [], [], DrawingSlice> = (set, get) => ({
    drawingMode: 'none',
    editingFeatureId: null,
    currentDrawingPoints: [],
    currentDrawingSnapIds: [],
    snappedPoint: null,
    activeParentFeatureId: null,
    networkConnectionDraft: null,

    setDrawingMode: (mode) => {
        const currentMode = get().drawingMode;
        if (currentMode !== mode) {
            set({ drawingMode: mode, currentDrawingPoints: [], currentDrawingSnapIds: [], networkConnectionDraft: null });
            emit('sync-drawing-mode', { mode });
        }
    },

    setEditingFeatureId: (id) => set({ editingFeatureId: id }),
    setActiveParentFeature: (id) => set({ activeParentFeatureId: id }),
    addDrawingPoint: (lat, lng, snapId = null) => {
        const newPoints: [number, number][] = [...get().currentDrawingPoints, [lng, lat]];
        const newSnapIds: (string | null)[] = [...get().currentDrawingSnapIds, snapId || null];
        set({ currentDrawingPoints: newPoints, currentDrawingSnapIds: newSnapIds });
    },
    clearDrawingPoints: () => set({ currentDrawingPoints: [], currentDrawingSnapIds: [] }),
    setSnappedPoint: (point) => set({ snappedPoint: point }),
    setNetworkConnectionDraft: (draft) => set({ networkConnectionDraft: draft }),
    clearNetworkConnectionDraft: () => set({ networkConnectionDraft: null }),

    setDrawingPoint: async (index, lat, lng, snapId = null) => {
        const { state, editingFeatureId, dispatchEvent, activeParentFeatureId } = get();
        if (!editingFeatureId || !state?.features[editingFeatureId]) return;

        const feature = state.features[editingFeatureId];

        // ponytail: validate intersection scope boundary check for SignalLine edits
        if (isSignalLineFeature(feature)) {
            const parentId = activeParentFeatureId || (getParsedMetadata(feature).parent_feature_id as string | undefined);
            if (parentId) {
                const scope = getIntersectionScope(parentId, state.features);
                if (scope) {
                    let actualLng = lng;
                    let latVal = lat;
                    if (snapId && state.features[snapId]) {
                        const targetFeature = state.features[snapId];
                        const targetCoords = getPointCoordinates(targetFeature);
                        if (targetCoords) {
                            actualLng = targetCoords[0];
                            latVal = targetCoords[1];
                        }
                    }
                    if (!isPointInPolygon([actualLng, latVal], scope)) {
                        throw new Error("Point is outside intersection scope");
                    }
                }
            }
        }

        const coords = getParsedCoordinates(feature);
        if (!coords || !Array.isArray(coords)) return;

        const isPolygon = (feature.geom_type || '').toLowerCase() === 'polygon';
        let newCoords: LineStringCoordinates | PolygonCoordinates = isPolygonCoordinates(coords)
            ? [...coords]
            : isLineCoordinates(coords)
                ? [...coords]
                : [];

        // V2 Fix: If snapped to a target, use the TARGET's actual coordinates
        // instead of the raw click position. This ensures geometric integrity.
        let actualLng = lng;
        let actualLat = lat;

        if (snapId && state.features[snapId]) {
            const targetFeature = state.features[snapId];
            const targetCoords = getPointCoordinates(targetFeature);
            if (targetCoords) {
                // For Point targets, use [lng, lat] directly
                actualLng = targetCoords[0];
                actualLat = targetCoords[1];
            }
        }

        if (isPolygon) {
            const ring = isPolygonCoordinates(newCoords) ? [...newCoords[0]] : [];
            ring[index] = [actualLng, actualLat];
            if (index === 0) ring[ring.length - 1] = [actualLng, actualLat];
            newCoords = [ring];
        } else {
            (newCoords as LineStringCoordinates)[index] = [actualLng, actualLat];
        }

        const currentMeta = { ...getParsedMetadata(feature) };
        let metaChanged = false;
        const isPolyline = (feature.geom_type || '').toUpperCase() === 'LINESTRING' || (feature.geom_type || '').toUpperCase() === 'POLYLINE';

        if (isPolyline) {
            if (currentMeta.manual_override !== true) {
                currentMeta.manual_override = true;
                metaChanged = true;
            }
        }

        if (isPolyline) {
            const isEndpoint = isPolylineEndpointIndex(feature, index);
            if (isEndpoint && !snapId) {
                const endpointLabel = index === 0 ? 'đầu bắt đầu' : 'đầu kết thúc';
                alert(`Không thể tách ${endpointLabel} khỏi đối tượng kết nối. Hãy snap sang một đối tượng hợp lệ khác.`);
                throw new Error(`Polyline endpoint ${index} requires a snap target.`);
            }

            if (index === 0 && currentMeta.start_node_id !== snapId) {
                currentMeta.start_node_id = snapId || null;
                metaChanged = true;
            }
            const lastIdx = isPolygon ? (Array.isArray(newCoords[0]) ? newCoords[0].length - 1 : newCoords.length - 1) : newCoords.length - 1;
            if (index === lastIdx && currentMeta.end_node_id !== snapId) {
                currentMeta.end_node_id = snapId || null;
                metaChanged = true;
            }

            if (!currentMeta.snap_links) currentMeta.snap_links = {};
            const key = `v${index}`;
            const snapLinks = currentMeta.snap_links as Record<string, string | null>;
            if (snapId) {
                if (snapLinks[key] !== snapId) {
                    snapLinks[key] = snapId;
                    metaChanged = true;
                }
            } else if (snapLinks[key]) {
                delete snapLinks[key];
                metaChanged = true;
            }

            const maxVertexIndex = isPolygon && Array.isArray(newCoords[0])
                ? (newCoords[0] as LineStringCoordinates).length - 1
                : newCoords.length - 1;
            const mergedSnapIds = Array.from({ length: maxVertexIndex + 1 }, (_, vertexIndex) => {
                if (vertexIndex === index) return snapId || null;
                return snapLinks[`v${vertexIndex}`] || null;
            });
            const nextSnapLinks = buildSnapLinks(mergedSnapIds);
            const currentSnapLinks = currentMeta.snap_links as Record<string, string> | undefined;
            if (JSON.stringify(currentSnapLinks || {}) !== JSON.stringify(nextSnapLinks || {})) {
                if (nextSnapLinks) currentMeta.snap_links = nextSnapLinks;
                else delete currentMeta.snap_links;
                metaChanged = true;
            }
        } else if ((feature.geom_type || '').toUpperCase() === 'POINT') {
            if (snapId) {
                if (currentMeta.snap_to_id !== snapId) {
                    currentMeta.snap_to_id = snapId;
                    metaChanged = true;
                }
            } else if (currentMeta.snap_to_id) {
                delete currentMeta.snap_to_id;
                metaChanged = true;
            }
        }

        const payload: any = {
            id: editingFeatureId,
            geom_type: feature.geom_type,
            coordinates: newCoords
        };

        if (metaChanged) {
            payload.metadata = JSON.stringify(currentMeta);
        }

        await dispatchEvent({
            type: 'FeatureUpdated',
            payload
        });
    },

    insertDrawingPoint: async (index, lat, lng) => {
        const { editingFeatureId, state, dispatchEvent, activeParentFeatureId } = get();
        if (!editingFeatureId || !state?.features[editingFeatureId]) return;

        const feature = state.features[editingFeatureId];

        // ponytail: validate intersection scope boundary check for SignalLine inserts
        if (isSignalLineFeature(feature)) {
            const parentId = activeParentFeatureId || (getParsedMetadata(feature).parent_feature_id as string | undefined);
            if (parentId) {
                const scope = getIntersectionScope(parentId, state.features);
                if (scope && !isPointInPolygon([lng, lat], scope)) {
                    throw new Error("Point is outside intersection scope");
                }
            }
        }

        let coords = getParsedCoordinates(feature);
        if (!coords) return;

        const isPolygon = (feature.geom_type || '').toLowerCase() === 'polygon';
        let newCoords: LineStringCoordinates | PolygonCoordinates = isPolygonCoordinates(coords)
            ? [...coords]
            : isLineCoordinates(coords)
                ? [...coords]
                : [];

        if (isPolygon) {
            const ring = isPolygonCoordinates(newCoords) ? [...newCoords[0]] : [];
            ring.splice(index, 0, [lng, lat]);
            newCoords = [ring];
        } else {
            (newCoords as LineStringCoordinates).splice(index, 0, [lng, lat]);
        }

        const isPolyline = (feature.geom_type || '').toUpperCase() === 'LINESTRING' || (feature.geom_type || '').toUpperCase() === 'POLYLINE';
        const payload: any = {
            id: editingFeatureId,
            geom_type: feature.geom_type,
            coordinates: newCoords
        };
        if (isPolyline) {
            payload.metadata = JSON.stringify({
                ...getParsedMetadata(feature),
                manual_override: true
            });
        }

        await dispatchEvent({
            type: 'FeatureUpdated',
            payload
        });
    },

    deleteDrawingPoint: async (index) => {
        const { editingFeatureId, state, dispatchEvent } = get();
        if (!editingFeatureId || !state?.features[editingFeatureId]) return;

        const feature = state.features[editingFeatureId];
        let coords = getParsedCoordinates(feature);
        if (!coords) return;

        const isPolygon = (feature.geom_type || '').toLowerCase() === 'polygon';
        let newCoords: LineStringCoordinates | PolygonCoordinates = isPolygonCoordinates(coords)
            ? [...coords]
            : isLineCoordinates(coords)
                ? [...coords]
                : [];

        if (isPolygon) {
            const ring = isPolygonCoordinates(newCoords) ? [...newCoords[0]] : [];
            if (ring.length <= 4) return;
            ring.splice(index, 1);
            if (index === 0) ring[ring.length - 1] = ring[0];
            newCoords = [ring];
        } else {
            if ((newCoords as LineStringCoordinates).length <= 2) return;
            (newCoords as LineStringCoordinates).splice(index, 1);
        }

        const isPolyline = (feature.geom_type || '').toUpperCase() === 'LINESTRING' || (feature.geom_type || '').toUpperCase() === 'POLYLINE';
        const payload: any = {
            id: editingFeatureId,
            geom_type: feature.geom_type,
            coordinates: newCoords
        };
        if (isPolyline) {
            payload.metadata = JSON.stringify({
                ...getParsedMetadata(feature),
                manual_override: true
            });
        }

        await dispatchEvent({
            type: 'FeatureUpdated',
            payload
        });
    }
});

import { StateCreator } from 'zustand';
import { InitializationSlice, DesignSyncStore } from './types';
import { safeInvoke as invoke } from '../../../../implement/lib/tauri';
import { listen } from '@tauri-apps/api/event';
import { logger } from '../../../../tool/utils/logger';
import {
    incrementInitializeRequestId,
    getLatestInitializeRequestId,
    loadDesignState
} from '../../../../tool/utils/designIpc';
import { normalizeMapStateForDisplay } from '../../../../tool/utils/normalizeDisplay';


let initWatchdogTimer: ReturnType<typeof setTimeout> | null = null;
let loadingSinceTs: number | null = null;
let lastInitializedKey: string | null = null;
let lastInitializedAt = 0;
let initBurstWindowStart = 0;
let initBurstCount = 0;
let initBurstKey: string | null = null;
const INIT_BURST_WINDOW_MS = 30000;
const INIT_BURST_MAX_COUNT = 6;

export const createInitializationSlice: StateCreator<DesignSyncStore, [], [], InitializationSlice> = (set, get) => ({
    unsubscribeFirestore: null,
    pegmanState: {
        active: false,
        location: null,
        heading: 0,
        fov: 90,
        windowOpen: false,
        source: 'map',
        lastSyncAt: 0,
        featureId: null
    },

    setPegmanState: (updates) => set((s) => ({
        pegmanState: { ...s.pegmanState, ...updates }
    })),

    initialize: async (projectId: string, projectPath?: string) => {
        const withTimeout = async <T>(promise: Promise<T>, timeoutMs: number, label: string): Promise<T> => {
            return await Promise.race([
                promise,
                new Promise<T>((_, reject) =>
                    setTimeout(() => reject(new Error(`${label} timeout after ${timeoutMs}ms`)), timeoutMs)
                )
            ]);
        };
        const normalizedProjectKey = projectPath ?? `id:${projectId}`;
        const currentInitKey = `${projectId}@${normalizedProjectKey}`;
        const {
            projectId: currentProjectId,
            state: currentState,
            isLoading: currentlyLoading
        } = get();

        // Prevent rapid re-initialize storms for the same project.
        const now = Date.now();
        if (
            initBurstKey !== currentInitKey ||
            !initBurstWindowStart ||
            now - initBurstWindowStart > INIT_BURST_WINDOW_MS
        ) {
            initBurstKey = currentInitKey;
            initBurstWindowStart = now;
            initBurstCount = 1;
        } else {
            initBurstCount += 1;
        }
        if (initBurstCount > INIT_BURST_MAX_COUNT) {
            logger.error(
                `[Sync] Initialization burst detected for ${currentInitKey} (${initBurstCount}/${INIT_BURST_WINDOW_MS}ms). Blocking to prevent loop.`
            );
            set({
                isLoading: false,
                isHydrating: false,
                error: 'Đã phát hiện vòng lặp đồng bộ. Vui lòng đóng/mở lại dự án để tiếp tục.'
            });
            return;
        }

        if (
            lastInitializedKey === currentInitKey &&
            now - lastInitializedAt < 3000 &&
            currentState &&
            !currentlyLoading
        ) {
            return;
        }

        // 1. Nếu đang nạp chính project này, bỏ qua để tránh loop
        if (currentlyLoading && currentProjectId === projectId) {
            const now = Date.now();
            const isStaleLoading = !!loadingSinceTs && now - loadingSinceTs > 20000;
            if (!isStaleLoading) {
                logger.sync(`[Sync] Already initializing project ${projectId}. Ignoring duplicate call.`);
                return;
            }
            logger.warn(`[Sync] Detected stale loading state for project ${projectId}. Recovering...`);
            set({ isLoading: false, isHydrating: false });
        }

        // 2. Nếu đã nạp xong và không có lỗi, không cần nạp lại
        if (
            currentProjectId === projectId &&
            currentState &&
            !get().error &&
            !currentlyLoading
        ) {
            return;
        }

        const initializeRequestId = incrementInitializeRequestId();
        loadingSinceTs = Date.now();
        if (initWatchdogTimer) {
            clearTimeout(initWatchdogTimer);
            initWatchdogTimer = null;
        }
        initWatchdogTimer = setTimeout(() => {
            if (initializeRequestId === getLatestInitializeRequestId()) {
                set({
                    isLoading: false,
                    isHydrating: false,
                    error: 'Hydration timeout: vui lòng thử mở lại dự án.'
                });
                loadingSinceTs = null;
            }
        }, 20000);

        const currentUnsubscribe = get().unsubscribeFirestore;
        if (currentUnsubscribe) currentUnsubscribe();

        set({
            isLoading: true,
            isHydrating: true,
            error: null,
            state: (currentProjectId === projectId || get().isSaving) ? currentState : null,
            projectId,
            projectPath,
            projectKey: normalizedProjectKey,
            unsubscribeFirestore: null,
            pendingSync: false,
            previewMetadata: null,
            boxSelection: null,
            printArea: null,
            currentDrawingPoints: [],
            currentDrawingSnapIds: [],
            snappedPoint: null,
            editingFeatureId: null,
            hoverId: null,
            groupThemePreview: null,
            selectedFeatureId: null,
            selectedGroupId: null,
            activeParentFeatureId: null,
            selectionSet: new Set(),
            mapHiddenIds: new Set(),
            searchResultMarker: null,
            zoomToTrigger: null
        });

        try {
            let activeProject = await invoke<any>('get_active_project').catch(() => null);
            const activeProjectId = activeProject?.id ? String(activeProject.id) : null;
            const needsLoad = !activeProject || activeProjectId !== projectId;

            if (needsLoad) {
                if (projectPath) {
                    logger.sync(`[Sync] Loading project from: ${projectPath}`);
                    await withTimeout(invoke('load_pmp_file', { path: projectPath }), 15000, 'load_pmp_file');
                } else if (activeProject) {
                    throw new Error(`Phiên làm việc cho dự án ${projectId} đã kết thúc. Vui lòng mở lại tệp.`);
                }
            }

            if (initializeRequestId !== getLatestInitializeRequestId()) return;

            console.log(`[useDesignSync] Initializing project: ${projectId} (Task: ${initializeRequestId})`);

            const tStart = performance.now();
            let state;
            try {
                // ✅ Sử dụng utility loadDesignState (V2 Bridge) thay vì invokeBincode
                state = await withTimeout(loadDesignState(projectId), 15000, 'loadDesignState');

                if (initializeRequestId !== getLatestInitializeRequestId()) {
                    logger.sync(`[Sync] Request ${initializeRequestId} stale after hydration. Abandoning state update.`);
                    return;
                }
            } catch (e: any) {
                if (e?.toString().includes("CANCELLED")) {
                    logger.sync(`[Sync] Backend cancelled hydration for req ${initializeRequestId}.`);
                    return;
                }

                if (e?.toString().includes("Timeout")) {
                    throw new Error(`Không thể nạp dữ liệu: Phản hồi từ Backend quá chậm hoặc Database bị khóa (Locked). Vui lòng thử lại.`);
                }

                if (e?.toString().includes("Database Lock")) {
                    console.warn("[useDesignSync] Retrying hydration after lock discovery...");
                    await new Promise(r => setTimeout(r, 2000));
                    state = await withTimeout(loadDesignState(projectId), 15000, 'loadDesignState');
                } else {
                    throw e;
                }
            }

            if (initializeRequestId !== getLatestInitializeRequestId()) return;

            if (!state) {
                throw new Error("Không thể nạp dữ liệu bản vẽ từ backend.");
            }

            const tDone = performance.now();
            logger.info(`[Store] ✅ Hydration completed in ${(tDone - tStart).toFixed(1)}ms for project ${projectId}`);

            // Standardize state using the canonical helper
            const normalizedState = normalizeMapStateForDisplay(state);

            set({
                state: normalizedState,
                projectId,
                projectKey: normalizedProjectKey,
                projectPath,
                lastSync: Date.now()
            });
            lastInitializedKey = currentInitKey;
            lastInitializedAt = Date.now();

            // V2 Fix: DO NOT hide any data from database
            // All data is visible by default. Only hide when user clicks the eye icon.
            // mapHiddenIds starts empty - only populated by user actions

            await get().syncDisplayOrderWithSTT();
            console.log(`[Store] Hydration and Display Sync complete for project: ${projectId}`);

            const handleOnline = () => set({ isOnline: true });
            const handleOffline = () => set({ isOnline: false });
            window.addEventListener('online', handleOnline);
            window.addEventListener('offline', handleOffline);

            const unlistenSync = await listen<number>('sync-status', (event) => {
                console.log(`[Sync] Status updated from backend: ${event.payload}`);
                set({ syncStatus: event.payload });
            });

            set({
                unsubscribeFirestore: () => {
                    window.removeEventListener('online', handleOnline);
                    window.removeEventListener('offline', handleOffline);
                    unlistenSync();
                }
            });

        } catch (err: any) {
            if (initializeRequestId !== getLatestInitializeRequestId()) {
                logger.warn(
                    `[Store] Ignoring stale hydration failure for project ${projectId} (${normalizedProjectKey})`
                );
                return;
            }

            logger.error(`[Store] Hydration error for project ${projectId} (${normalizedProjectKey}): ${err}`);
            localStorage.removeItem('lastProjectId');
            localStorage.removeItem('bando:v2_state'); // Clear stale layout/state cache
            set({ error: String(err) });
        } finally {
            if (initWatchdogTimer) {
                clearTimeout(initWatchdogTimer);
                initWatchdogTimer = null;
            }
            loadingSinceTs = null;
            if (initializeRequestId === getLatestInitializeRequestId()) {
                set({ isLoading: false, isHydrating: false });
            }
        }
    },

    reset: () => set({
        state: null,
        projectId: null,
        projectPath: null,
        projectKey: null,
        error: null,
        isLoading: false,
        isHydrating: false,
        pendingSync: false,
        selectedFeatureId: null,
        editingFeatureId: null,
        selectionSet: new Set(),
        currentDrawingPoints: [],
        currentDrawingSnapIds: [],
        snappedPoint: null,
        hoverId: null
    }),

    setMockState: (state, projectId, projectKey) => set({
        state,
        projectId,
        projectKey: projectKey ?? `id:${projectId}`,
        lastSync: Date.now()
    })
});

import { StateCreator } from 'zustand';
import { MapStateSlice, DesignSyncStore } from './types';
import { MapState } from '@CONTRACT/types';
import { DesignEventType } from '@CONTRACT/designTypes';
import { normalizeMapStateForDisplay } from '../../../../tool/utils/normalizeDisplay';



const UPDATE_THROTTLE_MS = 100;
const IS_DEV = import.meta.env.DEV;
let inboundUpdateTimer: any = null;
let inboundStateBuffer: MapState | null = null;
let lastUpdateTimestamp = 0;

export const createMapStateSlice: StateCreator<DesignSyncStore, [], [], MapStateSlice> = (set, get) => ({
    state: null,
    projectId: null,
    projectPath: null,
    projectKey: null,
    isLoading: false,
    isHydrating: false,
    error: null,
    lastSync: null,
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    pendingSync: false,
    isMigrating: false,
    isSaving: false,
    lastDispatchTime: {},
    syncStatus: 0,

    // Giai đoạn 5: Optimistic UI state
    pendingSyncEvents: [],

    updateEntityMetadataOptimistic: async (entityType: string, entityId: string, metadata: any) => {
        const { state, projectKey, pendingSyncEvents } = get();
        if (!state || !projectKey) return;

        const tempId = crypto.randomUUID();
        let originalMetadata: any = {};

        // 1. Cập nhật UI ngay lập tức
        const optimisticState = { ...state };
        if (entityType === 'feature' && optimisticState.features[entityId]) {
            originalMetadata = { ...optimisticState.features[entityId].properties };
            optimisticState.features[entityId].properties = metadata;
        }

        // 2. Đẩy sự kiện vào pendingSyncEvents
        set({
            state: optimisticState,
            pendingSyncEvents: [...pendingSyncEvents, { id: tempId, payload: { entityType, entityId, metadata, original: originalMetadata } }]
        });

        // 3. Gọi IPC invoke
        try {
            const { invoke } = await import('@tauri-apps/api/core');
            await invoke('update_entity_metadata_v2', {
                request: {
                    project_id: projectKey, // projectKey is the string UUID
                    entity_id: entityId,
                    entity_type: entityType,
                    metadata: metadata,
                    device_id: 'frontend-optimistic-ui'
                }
            });

            // 4. Thành công: Xóa khỏi hàng đợi
            set((s) => ({
                pendingSyncEvents: s.pendingSyncEvents.filter(e => e.id !== tempId)
            }));
        } catch (error) {
            console.error("[Optimistic UI] Update failed, rolling back:", error);

            // 5. Thất bại: Rollback và xóa khỏi hàng đợi
            const currentStore = get();
            const failedEvent = currentStore.pendingSyncEvents.find(e => e.id === tempId);

            if (failedEvent) {
                const rollbackState = { ...currentStore.state! };
                if (entityType === 'feature' && rollbackState.features[entityId]) {
                    rollbackState.features[entityId].properties = failedEvent.payload.original;
                }

                set({
                    state: rollbackState,
                    pendingSyncEvents: currentStore.pendingSyncEvents.filter(e => e.id !== tempId)
                });
            }
        }
    },

    throttledSetState: (newState: MapState) => {
        if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
            inboundStateBuffer = newState;
            return;
        }

        inboundStateBuffer = newState;
        const now = Date.now();
        const timeSinceLast = now - lastUpdateTimestamp;

        if (inboundUpdateTimer) return;

        if (timeSinceLast >= UPDATE_THROTTLE_MS) {
            lastUpdateTimestamp = now;
            set({ state: newState });
        } else {
            inboundUpdateTimer = setTimeout(() => {
                if (inboundStateBuffer) {
                    lastUpdateTimestamp = Date.now();
                    set({ state: inboundStateBuffer });
                    inboundStateBuffer = null;
                }
                inboundUpdateTimer = null;
            }, UPDATE_THROTTLE_MS - timeSinceLast);
        }
    },

    applyPatchToState: (response) => {
        const currentState = get().state;
        if (!currentState) return;

        const newState = { ...currentState };

        const applySingle = (event: DesignEventType) => {
            const { type, payload } = event as any;
            switch (type) {
                case 'FeatureCreated':
                case 'FeatureUpdated': {
                    const currentFeature = newState.features[payload.id];
                    if (IS_DEV && type === 'FeatureUpdated') {
                        console.groupCollapsed(`[Sync] applyPatchToState FeatureUpdated ${payload.id}`);
                        console.log('incoming payload:', payload);
                        console.log('before metadata:', currentFeature?.metadata);
                        console.log('before properties:', currentFeature?.properties);
                        console.groupEnd();
                    }
                    newState.features = {
                        ...newState.features,
                        [payload.id]: currentFeature ? {
                            ...currentFeature,
                            ...Object.fromEntries(Object.entries(payload).filter(([_, v]) => v !== null && v !== undefined))
                        } : { ...payload }
                    };
                    break;
                }
                case 'FeatureDeleted': {
                    const { [payload.id]: _, ...remainingFeatures } = newState.features;
                    newState.features = remainingFeatures;
                    break;
                }
                case 'RegionCreated':
                case 'RegionUpdated':
                    if (!newState.regions) newState.regions = {};
                    newState.regions = {
                        ...newState.regions,
                        [payload.id]: {
                            ...(newState.regions[payload.id] || {}),
                            ...payload
                        }
                    };
                    break;
                case 'RegionDeleted': {
                    const { [payload.id]: __, ...remainingRegions } = newState.regions;
                    newState.regions = remainingRegions;
                    break;
                }
                case 'LayerCreated':
                case 'LayerUpdated':
                    if (!newState.layers) newState.layers = {};
                    newState.layers = {
                        ...newState.layers,
                        [payload.id]: {
                            ...(newState.layers[payload.id] || {}),
                            ...payload
                        }
                    };
                    break;
                case 'LayerDeleted': {
                    const { [payload.id]: ___, ...remainingLayers } = newState.layers;
                    newState.layers = remainingLayers;
                    break;
                }
                case 'FeatureGroupCreated':
                case 'FeatureGroupUpdated':
                    if (!newState.feature_groups) newState.feature_groups = {};
                    newState.feature_groups = {
                        ...newState.feature_groups,
                        [payload.id]: {
                            ...(newState.feature_groups[payload.id] || {}),
                            ...payload
                        }
                    };
                    break;
                case 'FeatureGroupDeleted': {
                    const { [payload.id]: ____, ...remainingGroups } = newState.feature_groups;
                    newState.feature_groups = remainingGroups;
                    break;
                }
                case 'update_metadata':
                case 'preview_update':
                    newState.features = {
                        ...newState.features,
                        [payload.featureId]: {
                            ...newState.features[payload.featureId],
                            metadata: typeof payload.metadata === 'string'
                                ? payload.metadata
                                : JSON.stringify(payload.metadata)
                        }
                    };
                    break;
                case 'SettingsUpdated':
                    newState.settings = payload.settings;
                    break;
            }
        };

        if ('applied_event' in response) {
            newState.lastEventId = response.event_id;
            applySingle(response.applied_event);
            response.side_effects?.forEach(applySingle);
        } else {
            newState.lastEventId = response.last_event_id;
            response.applied_events?.forEach(applySingle);
            response.side_effects?.forEach(applySingle);
        }

        const normalizedState = normalizeMapStateForDisplay(newState);
        set({ state: normalizedState });
        if (IS_DEV) {
            console.log(`[Sync] Patch applied for ${normalizedState.lastEventId}`);
        }
    },

    applyQueuedAckToState: (response) => {
        const currentState = get().state;
        if (!currentState) return;

        const newState = { ...currentState };

        const applySingle = (event: DesignEventType) => {
            const { type, payload } = event as any;
            switch (type) {
                case 'FeatureCreated':
                case 'FeatureUpdated': {
                    if (IS_DEV && type === 'FeatureUpdated') {
                        console.groupCollapsed(`[Sync] applyQueuedAckToState FeatureUpdated ${payload.id}`);
                        console.log('incoming payload:', payload);
                        console.log('before metadata:', newState.features[payload.id]?.metadata);
                        console.log('before properties:', newState.features[payload.id]?.properties);
                        console.groupEnd();
                    }
                    newState.features = {
                        ...newState.features,
                        [payload.id]: {
                            ...newState.features[payload.id],
                            ...payload
                        }
                    };
                    break;
                }
                case 'FeatureDeleted': {
                    const { [payload.id]: _, ...remainingFeatures } = newState.features;
                    newState.features = remainingFeatures;
                    break;
                }
                case 'RegionCreated':
                case 'RegionUpdated':
                    if (!newState.regions) newState.regions = {};
                    newState.regions = {
                        ...newState.regions,
                        [payload.id]: {
                            ...(newState.regions[payload.id] || {}),
                            ...payload
                        }
                    };
                    break;
                case 'RegionDeleted': {
                    const { [payload.id]: __, ...remainingRegions } = newState.regions;
                    newState.regions = remainingRegions;
                    break;
                }
                case 'LayerCreated':
                case 'LayerUpdated':
                    if (!newState.layers) newState.layers = {};
                    newState.layers = {
                        ...newState.layers,
                        [payload.id]: {
                            ...(newState.layers[payload.id] || {}),
                            ...payload
                        }
                    };
                    break;
                case 'LayerDeleted': {
                    const { [payload.id]: ___, ...remainingLayers } = newState.layers;
                    newState.layers = remainingLayers;
                    break;
                }
                case 'FeatureGroupCreated':
                case 'FeatureGroupUpdated':
                    if (!newState.feature_groups) newState.feature_groups = {};
                    newState.feature_groups = {
                        ...newState.feature_groups,
                        [payload.id]: {
                            ...(newState.feature_groups[payload.id] || {}),
                            ...payload
                        }
                    };
                    break;
                case 'FeatureGroupDeleted': {
                    const { [payload.id]: ____, ...remainingGroups } = newState.feature_groups;
                    newState.feature_groups = remainingGroups;
                    break;
                }
                case 'SettingsUpdated':
                    newState.settings = payload.settings;
                    break;
            }
        };

        if ('applied_event' in response) {
            newState.lastEventId = response.event_id;
            applySingle(response.applied_event);
            response.side_effects?.forEach(applySingle);
        } else {
            newState.lastEventId = response.last_event_id;
            response.applied_events?.forEach(applySingle);
            response.side_effects?.forEach(applySingle);
        }

        const normalizedState = normalizeMapStateForDisplay(newState);
        set({ state: normalizedState });
        if (IS_DEV) {
            console.log(`[Sync] Queued ack applied for ${normalizedState.lastEventId}`);
        }
    },

    applyEventsOptimistically: (events) => {
        const currentState = get().state;
        if (!currentState) return;

        const newState = { ...currentState };

        const apply = (ev: DesignEventType) => {
            const { type, payload } = ev as any;
            if (!payload) return;

            switch (type) {
                case 'FeatureCreated':
                case 'FeatureUpdated': {
                    if (!newState.features) newState.features = {};
                    const fPayload = { ...payload };
                    if (fPayload.group_id === '') fPayload.group_id = null;
                    const currentFeature = newState.features[payload.id];
                    if (IS_DEV && type === 'FeatureUpdated') {
                        console.groupCollapsed(`[Sync] applyEventsOptimistically FeatureUpdated ${payload.id}`);
                        console.log('incoming payload:', fPayload);
                        console.log('before metadata:', currentFeature?.metadata);
                        console.log('before properties:', currentFeature?.properties);
                        console.groupEnd();
                    }
                    newState.features = {
                        ...newState.features,
                        [payload.id]: currentFeature ? {
                            ...currentFeature,
                            ...Object.fromEntries(Object.entries(fPayload).filter(([_, v]) => v !== null && v !== undefined))
                        } : { ...fPayload }
                    };
                    break;
                }
                case 'FeatureDeleted': {
                    if (!newState.features) break;
                    const { [payload.id]: _, ...remainingFeatures } = newState.features;
                    newState.features = remainingFeatures;
                    break;
                }
                case 'RegionCreated':
                case 'RegionUpdated':
                    if (!newState.regions) newState.regions = {};
                    newState.regions = { 
                        ...newState.regions, 
                        [payload.id]: { ...(newState.regions[payload.id] || {}), ...payload } 
                    };
                    break;
                case 'RegionDeleted': {
                    if (!newState.regions) break;
                    const { [payload.id]: __, ...remainingRegions } = newState.regions;
                    newState.regions = remainingRegions;
                    break;
                }
                case 'LayerCreated':
                case 'LayerUpdated':
                    if (!newState.layers) newState.layers = {};
                    newState.layers = { 
                        ...newState.layers, 
                        [payload.id]: { ...(newState.layers[payload.id] || {}), ...payload } 
                    };
                    break;
                case 'LayerDeleted': {
                    if (!newState.layers) break;
                    const { [payload.id]: ___, ...remainingLayers } = newState.layers;
                    newState.layers = remainingLayers;
                    break;
                }
                case 'FeatureGroupCreated':
                case 'FeatureGroupUpdated': {
                    if (!newState.feature_groups) newState.feature_groups = {};
                    const gPayload = { ...payload };
                    if (gPayload.parent_id === '') gPayload.parent_id = null;
                    newState.feature_groups = { 
                        ...newState.feature_groups, 
                        [payload.id]: { ...(newState.feature_groups[payload.id] || {}), ...gPayload } 
                    };
                    break;
                }
                case 'FeatureGroupDeleted': {
                    if (!newState.feature_groups) break;
                    const { [payload.id]: ____, ...remainingGroups } = newState.feature_groups;
                    newState.feature_groups = remainingGroups;
                    break;
                }
                case 'update_metadata':
                case 'preview_update':
                    if (!newState.features) break;
                    if (!newState.features[payload.featureId]) break;
                    newState.features = {
                        ...newState.features,
                        [payload.featureId]: {
                            ...newState.features[payload.featureId],
                            metadata: typeof payload.metadata === 'string'
                                ? payload.metadata
                                : JSON.stringify(payload.metadata)
                        }
                    };
                    break;
                case 'SettingsUpdated':
                    newState.settings = payload.settings;
                    break;
            }
        };

        events?.forEach(apply);
        const normalizedState = normalizeMapStateForDisplay(newState);
        set({ state: normalizedState });
        if (IS_DEV) {
            console.log(`[Sync] Optimistic update applied for ${events?.length || 0} events`);
        }
    },

    updateSettings: async (settings) => {
        const event: DesignEventType = {
            type: 'SettingsUpdated',
            payload: { settings },
        };
        try {
            await get().queueEvent(event);
        } catch (error) {
            console.error('Failed to update settings:', error);
            throw error;
        }
    },

    setIsSaving: (isSaving) => set({ isSaving })
});

import { StateCreator } from 'zustand';
import { SelectionSlice, DesignSyncStore } from './types';

export const createSelectionSlice: StateCreator<DesignSyncStore, [], [], SelectionSlice> = (set, get) => ({
    selectedFeatureId: null,
    selectedGroupId: null,
    selectedPopupLocation: null,
    hoverId: null,
    selectionSet: new Set(),
    boxSelection: null,

    selectFeature: (id: string | null, keepSelection = false, location?: [number, number]) => {
        const currentState = get();

        if (currentState.drawingMode === 'move' && id === null) return;

        if (id === currentState.selectedFeatureId && id !== null && !keepSelection) {
            set({
                selectedFeatureId: null,
                selectedPopupLocation: null,
                editingFeatureId: null,
                previewMetadata: null,
                selectionSet: new Set()
            });
            return;
        }

        if (id && currentState.state?.features?.[id]) {
            const feature = currentState.state.features[id];
            const groupId = feature.group_id;
            const geomType = (feature.geom_type || '').toUpperCase();
            const isVector = geomType === 'LINESTRING' || geomType === 'POLYLINE' || geomType === 'POLYGON';

            const newSelectionSet = keepSelection
                ? new Set(currentState.selectionSet).add(id)
                : new Set([id]);

            set({
                selectedFeatureId: id,
                selectedGroupId: groupId,
                selectedPopupLocation: location || null,
                editingFeatureId: isVector ? id : null,
                previewMetadata: null,
                selectionSet: newSelectionSet
            });
        } else {
            set({
                selectedFeatureId: id,
                selectedPopupLocation: location || null,
                editingFeatureId: null,
                previewMetadata: null,
                selectionSet: keepSelection ? get().selectionSet : new Set()
            });
        }
    },

    setHoverId: (id) => set({ hoverId: id }),
    setBoxSelection: (summary) => set({
        boxSelection: summary,
        selectedFeatureId: summary ? null : get().selectedFeatureId
    }),
    toggleSelection: (id) => {
        const selectionSet = new Set(get().selectionSet);
        if (selectionSet.has(id)) {
            selectionSet.delete(id);
        } else {
            selectionSet.add(id);
        }
        set({ selectionSet });
    },
    selectAll: (ids) => {
        const selectionSet = new Set(get().selectionSet);
        ids.forEach(id => selectionSet.add(id));
        set({ selectionSet });
    },
    clearSelection: () => set({ selectionSet: new Set() }),
    setSelectedGroup: (id) => set({ selectedGroupId: id })
});

import { StateCreator } from 'zustand';
import { UIControlSlice, DesignSyncStore } from './types';
import { emit } from '@tauri-apps/api/event';

export const createUIControlSlice: StateCreator<DesignSyncStore, [], [], UIControlSlice> = (set, get) => ({
    isCoordinatePanelOpen: false,
    showDORILayers: false,
    showDORIHeatmap: false,
    showFeatureGroups: true,
    showNotes: true,
    showQr: true,
    showCode: true,
    isAnyDialogOpen: false,
    zoomExtendTrigger: 0,
    zoomToTrigger: null,
    previewMetadata: null,
    groupThemePreview: null,
    searchResultMarker: null,
    printArea: null,
    mapHiddenIds: new Set<string>(),

    toggleCoordinatePanel: () => set((state) => ({ isCoordinatePanelOpen: !state.isCoordinatePanelOpen })),

    setShowDORILayers: (show) => {
        set({ showDORILayers: show });
        emit('sync-dori-layers', { show });
    },

    setShowDORIHeatmap: (show) => {
        set({ showDORIHeatmap: show });
        emit('sync-dori-heatmap', { show });
    },

    setShowFeatureGroups: (show) => {
        set({ showFeatureGroups: show });
        emit('sync-feature-groups', { show });
    },

    setShowNotes: (show) => {
        set({ showNotes: show });
        emit('sync-explorer-notes', { show });
    },

    setShowQr: (show) => {
        set({ showQr: show });
        emit('sync-explorer-qr', { show });
    },

    setShowCode: (show) => {
        set({ showCode: show });
        emit('sync-explorer-code', { show });
    },

    setAnyDialogOpen: (open) => set({ isAnyDialogOpen: open }),

    triggerZoomExtend: () => set((state) => ({ zoomExtendTrigger: state.zoomExtendTrigger + 1 })),

    zoomTo: (id, type, location) => {
        const trigger = { id, type, location, timestamp: Date.now() };
        set({ zoomToTrigger: trigger });
        emit('sync-zoom-to', trigger);
    },

    setPreview: (id, metadata, name) => {
        set((state) => {
            const previousName = state.previewMetadata?.id === id ? state.previewMetadata.name : undefined;
            const nextPreview = id && metadata ? { id, metadata, name: name ?? previousName } : null;
            emit('sync-preview-metadata', nextPreview || { id, metadata });
            return { previewMetadata: nextPreview };
        });
    },

    setGroupThemePreview: (groupId, config) => {
        set({ groupThemePreview: groupId && config ? { groupId, config } : null });
        emit('sync-group-theme-preview', { groupId, config });
    },

    setSearchResultMarker: (marker) => set({ searchResultMarker: marker }),

    setPrintArea: (bounds) => {
        const currentBounds = get().printArea;
        if (JSON.stringify(currentBounds) !== JSON.stringify(bounds)) {
            set({ printArea: bounds });
            emit('sync-print-area', { bounds });
        }
    },

    toggleMapHidden: (id: string) => {
        set((state) => {
            const newSet = new Set(state.mapHiddenIds);
            if (newSet.has(id)) {
                newSet.delete(id);
            } else {
                newSet.add(id);
            }
            return { mapHiddenIds: newSet };
        });
    }
});

import { StateCreator } from 'zustand';
import { UISyncSlice, DesignSyncStore } from './types';
import {
    DesignActionResponse,
    DesignBulkActionResponse,
    DesignEventType
} from '@CONTRACT/designTypes';
import { invoke } from '@tauri-apps/api/core';
import { listen } from '@tauri-apps/api/event';
import {
    invoke_design_event_batch,
    isCollaborationCoordinatorEnabled,
    pull_collaboration_events
} from '@TOOL/utils/designIpc';

const DESIGN_PERSIST_BATCH_DELAY_MS = 150;
const IS_DEV = import.meta.env.DEV;

let eventBuffer: DesignEventType[] = [];
let flushTimeout: NodeJS.Timeout | null = null;
let bufferedProjectId: string | null = null;
let bufferedResolvers: Array<{
    resolve: (value: DesignBulkActionResponse | DesignActionResponse | undefined) => void;
    reject: (reason?: unknown) => void;
}> = [];
let lastUiRecoveryInitializeAt = 0;
const UI_RECOVERY_INITIALIZE_COOLDOWN_MS = 5000;
let consecutiveUiSyncFailures = 0;
let firstUiFailureAt = 0;
const UI_SYNC_FAILURE_WINDOW_MS = 30000;
const UI_MAX_SYNC_FAILURES_BEFORE_BREAKER = 3;
const COLLAB_PULL_INTERVAL_MS = 5000;
let collabPullInterval: ReturnType<typeof setInterval> | null = null;
let collabPullInFlight = false;

const onUiSyncSuccess = () => {
    consecutiveUiSyncFailures = 0;
    firstUiFailureAt = 0;
};

const onUiSyncFailure = (): boolean => {
    const now = Date.now();
    if (!firstUiFailureAt || now - firstUiFailureAt > UI_SYNC_FAILURE_WINDOW_MS) {
        firstUiFailureAt = now;
        consecutiveUiSyncFailures = 1;
    } else {
        consecutiveUiSyncFailures += 1;
    }
    return consecutiveUiSyncFailures < UI_MAX_SYNC_FAILURES_BEFORE_BREAKER;
};

export const createUISyncSlice: StateCreator<DesignSyncStore, [], [], UISyncSlice> = (set, get) => ({
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    pendingSync: false,
    isMigrating: false,
    isSaving: false,
    lastSync: null,
    syncStatus: 0,
    error: null,
    unsubscribeFirestore: null,

    setIsSaving: (isSaving: boolean) => set({ isSaving }),
    setPendingSync: (pending: boolean) => set({ pendingSync: pending }),
    setError: (error: string | null) => set({ error }),

    setupSyncListeners: async () => {
        const unlistenSync = await listen<number>('sync-status', (event) => {
            console.log(`[Sync] Status updated from backend: ${event.payload}`);
            set({ syncStatus: event.payload });
        });

        const unlistenBridge = await listen<unknown>('design-event-processed', (event) => {
            console.log(`[Bridge] Event processed by backend:`, event.payload);
            set({ lastSync: Date.now() });
        });

        const handleOnline = () => set({ isOnline: true });
        const handleOffline = () => set({ isOnline: false });
        window.addEventListener('online', handleOnline);
        window.addEventListener('offline', handleOffline);

        if (isCollaborationCoordinatorEnabled() && !collabPullInterval) {
            collabPullInterval = setInterval(async () => {
                const st = get();
                if (
                    collabPullInFlight ||
                    !st.projectId ||
                    !st.isOnline ||
                    st.isSaving ||
                    st.pendingSync ||
                    st.isHydrating
                ) {
                    return;
                }

                collabPullInFlight = true;
                try {
                    const response = await pull_collaboration_events(st.projectId);
                    if (response.applied_events?.length) {
                        get().applyPatchToState(response);
                        set({ lastSync: Date.now(), error: null });
                    }
                } catch (error: any) {
                    const message = typeof error === 'string' ? error : error?.message || String(error);
                    console.warn('[Sync] Collaboration pull failed:', message);
                    set({ error: `Collaboration pull failed: ${message}` });
                } finally {
                    collabPullInFlight = false;
                }
            }, COLLAB_PULL_INTERVAL_MS);
        }

        set({
            unsubscribeFirestore: () => {
                window.removeEventListener('online', handleOnline);
                window.removeEventListener('offline', handleOffline);
                if (collabPullInterval) {
                    clearInterval(collabPullInterval);
                    collabPullInterval = null;
                }
                unlistenSync();
                unlistenBridge();
            }
        });
    },

    syncWithBackend: async (projectId: string, events: DesignEventType[]) => {
        if (!events || events.length === 0) return { success: true } as any;

        const batchId = crypto.randomUUID().substring(0, 8);
        if (IS_DEV) {
            console.group(`%c[PMP_FLOW] Batch Edit Start: ${batchId}`, 'color: #2196F3; font-weight: bold; font-size: 11px;');
            console.log(`[PMP_FLOW] Project ID: ${projectId} | Events: ${events.length}`);
        }

        try {
            set({ isSaving: true });

            const response = await invoke_design_event_batch(String(projectId), events as DesignEventType[]);

            if (IS_DEV) {
                console.log(`%c[PMP_SYNC] Success. .pmp updated. Last event: ${response.last_event_id}`, 'color: #4CAF50; font-weight: bold;');
            }
            onUiSyncSuccess();

            set({ lastSync: Date.now(), error: null, isSaving: false });
            if (IS_DEV) {
                console.groupEnd();
            }

            return response as any;
        } catch (error: any) {
            console.error(`%c[PMP_SYNC] Critical Sync Failure:`, 'color: #F44336; font-weight: bold;', error);

            const errorMsg = typeof error === 'string' ? error : (error.message || JSON.stringify(error));
            console.error('[PMP_SYNC] Error details:', errorMsg);
            const shouldRetryRecover = onUiSyncFailure();
            set({
                error: shouldRetryRecover
                    ? `Backend Sync Error: ${errorMsg}`
                    : 'Sync đang lỗi liên tục. Đã tạm ngắt tự đồng bộ để tránh lặp. Vui lòng mở lại dự án.',
                isSaving: false
            });
            if (IS_DEV) {
                console.groupEnd();
            }
            throw error;
        }
    },

    _internalBufferedSyncEvent: async (event: DesignEventType) => {
        return get()._internalBufferedSyncEvents([event]);
    },

    _internalBufferedSyncEvents: async (events: DesignEventType[]) => {
        const { syncWithBackend, projectId } = get();
        if (!projectId || events.length === 0) return;

        const flushNow = async () => {
            if (!bufferedProjectId || eventBuffer.length === 0) return;

            const batch = eventBuffer;
            const resolvers = bufferedResolvers;
            const targetProjectId = bufferedProjectId;
            eventBuffer = [];
            bufferedResolvers = [];
            bufferedProjectId = null;
            if (flushTimeout) {
                clearTimeout(flushTimeout);
                flushTimeout = null;
            }

            try {
                const result = await syncWithBackend(targetProjectId, batch);
                set({ pendingSync: false });
                resolvers.forEach(({ resolve }) => resolve(result));
            } catch (err) {
                set({ pendingSync: false });
                resolvers.forEach(({ reject }) => reject(err));
            }
        };

        if (bufferedProjectId && bufferedProjectId !== projectId && eventBuffer.length > 0) {
            await flushNow();
        }

        bufferedProjectId = projectId;
        eventBuffer.push(...events);
        set({ pendingSync: true });

        if (flushTimeout) {
            clearTimeout(flushTimeout);
        }

        return new Promise((resolve, reject) => {
            bufferedResolvers.push({ resolve, reject });
            flushTimeout = setTimeout(() => {
                void flushNow();
            }, DESIGN_PERSIST_BATCH_DELAY_MS);
        });
    },

    flushPendingPersists: async () => {
        const { syncWithBackend, projectId } = get();
        const targetProjectId = bufferedProjectId ?? projectId;
        if (!targetProjectId || eventBuffer.length === 0) return;

        if (flushTimeout) {
            clearTimeout(flushTimeout);
            flushTimeout = null;
        }

        const batch = eventBuffer;
        const resolvers = bufferedResolvers;
        eventBuffer = [];
        bufferedResolvers = [];
        bufferedProjectId = null;

        try {
            const result = await syncWithBackend(targetProjectId, batch);
            set({ pendingSync: false });
            resolvers.forEach(({ resolve }) => resolve(result));
        } catch (err) {
            set({ pendingSync: false });
            resolvers.forEach(({ reject }) => reject(err));
            throw err;
        }
    },

    _undo: async (projectId: string) => {
        const responseStr = await invoke<string>('undo_design_event', { projectId: String(projectId) });
        const response = JSON.parse(responseStr);
        if (response.success) {
            const now = Date.now();
            if (now - lastUiRecoveryInitializeAt > UI_RECOVERY_INITIALIZE_COOLDOWN_MS) {
                lastUiRecoveryInitializeAt = now;
                get().initialize(String(projectId), get().projectPath ?? undefined);
            }
        }
    },

    _redo: async (projectId: string) => {
        const responseStr = await invoke<string>('redo_design_event', { projectId: String(projectId) });
        const response = JSON.parse(responseStr);
        if (response.success) {
            const now = Date.now();
            if (now - lastUiRecoveryInitializeAt > UI_RECOVERY_INITIALIZE_COOLDOWN_MS) {
                lastUiRecoveryInitializeAt = now;
                get().initialize(String(projectId), get().projectPath ?? undefined);
            }
        }
    },

    _deduplicate: async (projectId: string) => {
        await invoke('deduplicate_project_data', { projectId: String(projectId) });
        const now = Date.now();
        if (now - lastUiRecoveryInitializeAt > UI_RECOVERY_INITIALIZE_COOLDOWN_MS) {
            lastUiRecoveryInitializeAt = now;
            get().initialize(String(projectId), get().projectPath ?? undefined);
        }
    },

    syncWithFirestore: (projectId: string, data: unknown) => {
        console.warn('Firestore sync not yet implemented in V2 architecture.', { projectId, data });
        return Promise.resolve();
    }
});

