import { useEffect, useMemo, useState } from "react";
import { emit, listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { save } from "@tauri-apps/plugin-dialog";
import { Check, ChevronDown, ChevronRight, Download, Eye, FileText, Loader2, X } from "lucide-react";
import { useDesignSync } from "@IMPLEMENT/stores/useDesignSync";
import { resolveMediaAsset } from "@IMPLEMENT/services/mediaAssetService";
import { cn } from "@TOOL/utils/cn";
import {
  buildReportModel,
  getDefaultReportSelections,
  getSelectableReportItems,
  type ReportBounds,
  type ReportModel,
  type ReportPhoto,
  type ReportSelection,
} from "./reportModel";
import { buildReportDocx, type ReportImageMap } from "./reportDocx";

interface ReportExportDialogProps {
  projectName: string;
  onClose: () => void;
}

type CaptureResult = { captureId?: string; dataUrl: string };
type CaptureError = { captureId?: string; error: string };

const keyOf = (selection: ReportSelection): string => `${selection.type}:${selection.id}`;
type SelectableReportItem = ReturnType<typeof getSelectableReportItems>[number];
const REPORT_MAP_CAPTURE_MAX_ZOOM = 36;

const parseKey = (key: string): ReportSelection | null => {
  const [type, id] = key.split(":");
  if (!id) return null;
  if (type === "region" || type === "group" || type === "feature") return { type, id };
  return null;
};

const sanitizeFileName = (value: string): string =>
  value.replace(/[\\/:*?"<>|]/g, "-").trim() || "Báo-cáo-thiết-kế";

const getDescendantKeys = (items: SelectableReportItem[], key: string): string[] => {
  const index = items.findIndex((item) => item.key === key);
  if (index < 0) return [];
  const parentLevel = items[index].level;
  const keys: string[] = [];
  for (let i = index + 1; i < items.length; i += 1) {
    if (items[i].level <= parentLevel) break;
    keys.push(items[i].key);
  }
  return keys;
};

const getVisibleSelectableItems = (
  items: SelectableReportItem[],
  expandedKeys: Set<string>,
): SelectableReportItem[] => {
  const visible: SelectableReportItem[] = [];
  const collapsedLevels: number[] = [];
  items.forEach((item) => {
    while (collapsedLevels.length > 0 && item.level <= collapsedLevels[collapsedLevels.length - 1]) {
      collapsedLevels.pop();
    }
    if (collapsedLevels.length === 0) visible.push(item);
    if (!expandedKeys.has(item.key) && getDescendantKeys(items, item.key).length > 0) {
      collapsedLevels.push(item.level);
    }
  });
  return visible;
};

const requestMapCapture = async (
  bounds: ReportBounds | null,
  captureId: string,
  scale = 2,
  fitToBounds = true,
  zoom = REPORT_MAP_CAPTURE_MAX_ZOOM,
): Promise<string | undefined> => {
  if (!bounds) return undefined;

  return new Promise<string | undefined>((resolve) => {
    let done = false;
    let unlistenResult: (() => void) | undefined;
    let unlistenError: (() => void) | undefined;
    const timeout = window.setTimeout(() => {
      cleanup();
      resolve(undefined);
    }, 45000);

    const cleanup = () => {
      if (done) return;
      done = true;
      window.clearTimeout(timeout);
      unlistenResult?.();
      unlistenError?.();
    };

    const setupAndEmit = async () => {
      unlistenResult = await listen<CaptureResult>("map-capture-result", (event) => {
        if (event.payload.captureId && event.payload.captureId !== captureId) return;
        cleanup();
        resolve(event.payload.dataUrl);
      });

      unlistenError = await listen<CaptureError>("map-capture-error", (event) => {
        if (event.payload.captureId && event.payload.captureId !== captureId) return;
        cleanup();
        resolve(undefined);
      });

      if (!done) {
        await emit("request-map-capture", { captureId, printArea: bounds, scale, fitToBounds, zoom });
      }
    };

    void setupAndEmit().catch(() => {
      cleanup();
      resolve(undefined);
    });
  });
};

const captureMissingReportImages = async (
  model: ReportModel,
  existing: ReportImageMap,
  onProgress?: (current: number, total: number) => void,
): Promise<ReportImageMap> => {
  const imageMap: ReportImageMap = { ...existing };
  const missingSections = model.sections.filter((section) => !imageMap[section.id]);
  for (let index = 0; index < missingSections.length; index += 1) {
    const section = missingSections[index];
    onProgress?.(index + 1, missingSections.length);
    if (imageMap[section.id]) continue;
    for (let attempt = 1; attempt <= 3; attempt += 1) {
      const dataUrl = await requestMapCapture(section.bounds, `report-${section.id}-${Date.now()}-${attempt}`, 1.5, true);
      if (dataUrl) {
        imageMap[section.id] = dataUrl;
        break;
      }
    }
  }
  return imageMap;
};

const capturePreviewImage = async (model: ReportModel, sectionId: string): Promise<string | undefined> => {
  const section = model.sections.find((item) => item.id === sectionId) || model.sections[0];
  if (!section) return undefined;
  return requestMapCapture(section.bounds, `report-preview-${section.id}-${Date.now()}`, 1.25, true);
};

const hydrateReportPhotoAssets = async (model: ReportModel, projectId?: string | null): Promise<ReportModel> => {
  if (!projectId) return model;
  const cache = new Map<string, string>();
  const resolvePhotos = async (photos: ReportPhoto[]): Promise<ReportPhoto[]> => {
    const resolved = await Promise.all(photos.map(async (photo) => {
      if (photo.dataUrl) return photo;
      if (!photo.assetId) return null;
      try {
        if (!cache.has(photo.assetId)) {
          const asset = await resolveMediaAsset(projectId, photo.assetId);
          cache.set(photo.assetId, asset.src);
        }
        const dataUrl = cache.get(photo.assetId) || "";
        return dataUrl ? { ...photo, dataUrl } : null;
      } catch (error) {
        console.warn("[ReportExportDialog] Failed to resolve report photo asset:", photo.assetId, error);
        return null;
      }
    }));
    return resolved.filter((photo): photo is ReportPhoto => !!photo && !!photo.dataUrl);
  };

  const sections = await Promise.all(model.sections.map(async (section) => ({
    ...section,
    photos: await resolvePhotos(section.photos),
    details: await Promise.all(section.details.map(async (detail) => ({
      ...detail,
      photos: await resolvePhotos(detail.photos),
    }))),
  })));
  return { ...model, sections };
};

export function ReportExportDialog({ projectName, onClose }: ReportExportDialogProps) {
  const state = useDesignSync((store) => store.state);
  const projectId = useDesignSync((store) => store.projectId);
  const selectedFeatureId = useDesignSync((store) => store.selectedFeatureId);
  const selectedGroupId = useDesignSync((store) => store.selectedGroupId);
  const selectionSet = useDesignSync((store) => store.selectionSet);

  const selectableItems = useMemo(() => state ? getSelectableReportItems(state) : [], [state]);
  const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set());
  const [expandedSelectionKeys, setExpandedSelectionKeys] = useState<Set<string>>(new Set());
  const [imageMap, setImageMap] = useState<ReportImageMap>({});
  const [activeView, setActiveView] = useState<"select" | "preview">("preview");
  const [activeSectionId, setActiveSectionId] = useState<string | null>(null);
  const [includeMapImages, setIncludeMapImages] = useState(true);
  const [isCapturing, setIsCapturing] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exportStatus, setExportStatus] = useState<string | null>(null);

  useEffect(() => {
    if (!state) return;
    const defaults = getDefaultReportSelections(state, { selectionSet, selectedFeatureId, selectedGroupId });
    const keys = defaults.map(keyOf);
    keys.forEach((key) => getDescendantKeys(selectableItems, key).forEach((childKey) => keys.push(childKey)));
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSelectedKeys(new Set(keys));
  }, [selectableItems, state, selectedFeatureId, selectedGroupId, selectionSet]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setExpandedSelectionKeys((prev) => {
      const expandableKeys = new Set(selectableItems
        .filter((item) => getDescendantKeys(selectableItems, item.key).length > 0)
        .map((item) => item.key));
      if (prev.size === 0) return expandableKeys;
      return new Set(Array.from(prev).filter((key) => expandableKeys.has(key)));
    });
  }, [selectableItems]);

  const selections = useMemo(() => Array.from(selectedKeys)
    .map(parseKey)
    .filter((selection): selection is ReportSelection => selection !== null), [selectedKeys]);
  const visibleSelectableItems = useMemo(
    () => getVisibleSelectableItems(selectableItems, expandedSelectionKeys),
    [expandedSelectionKeys, selectableItems],
  );

  const baseReportModel = useMemo(() => {
    if (!state) return null;
    return buildReportModel(state, selections, `Báo cáo thiết kế - ${projectName}`);
  }, [projectName, selections, state]);
  const [reportModel, setReportModel] = useState<ReportModel | null>(null);

  useEffect(() => {
    let cancelled = false;
    if (!baseReportModel) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setReportModel(null);
      return;
    }
    hydrateReportPhotoAssets(baseReportModel, projectId)
      .then((hydrated) => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        if (!cancelled) setReportModel(hydrated);
      });
    return () => {
      cancelled = true;
    };
  }, [baseReportModel, projectId]);

  const currentSectionId = activeSectionId || reportModel?.sections[0]?.id || null;

  useEffect(() => {
    if (!reportModel || reportModel.sections.length === 0) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setActiveSectionId(null);
      return;
    }
    if (!currentSectionId || !reportModel.sections.some((section) => section.id === currentSectionId)) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setActiveSectionId(reportModel.sections[0].id);
    }
  }, [currentSectionId, reportModel]);

  const toggleSelection = (key: string) => {
    setSelectedKeys((prev) => {
      const next = new Set(prev);
      const cascadeKeys = [key, ...getDescendantKeys(selectableItems, key)];
      const shouldRemove = cascadeKeys.every((itemKey) => next.has(itemKey));
      cascadeKeys.forEach((itemKey) => {
        if (shouldRemove) next.delete(itemKey);
        else next.add(itemKey);
      });
      return next;
    });
    setImageMap({});
  };

  const toggleSelectionExpanded = (key: string) => {
    setExpandedSelectionKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const handlePreview = async () => {
    if (!reportModel || !currentSectionId) return;
    setError(null);
    setExportStatus(null);
    setIsCapturing(true);
    try {
      const dataUrl = await capturePreviewImage(reportModel, currentSectionId);
      if (dataUrl) {
        setImageMap((prev) => ({ ...prev, [currentSectionId]: dataUrl }));
      }
      setActiveView("preview");
    } finally {
      setIsCapturing(false);
    }
  };

  const handleSelectPreviewSection = async (sectionId: string) => {
    setActiveSectionId(sectionId);
    setActiveView("preview");
    if (imageMap[sectionId] || !reportModel) return;
    setIsCapturing(true);
    try {
      const dataUrl = await capturePreviewImage(reportModel, sectionId);
      if (dataUrl) {
        setImageMap((prev) => ({ ...prev, [sectionId]: dataUrl }));
      }
    } finally {
      setIsCapturing(false);
    }
  };

  const handleExport = async () => {
    if (!reportModel || reportModel.sections.length === 0) return;
    setError(null);
    setExportStatus("Đang chuẩn bị file Word...");
    setIsExporting(true);
    try {
      if (includeMapImages) {
        setExportStatus("Đang chụp ảnh bản đồ...");
      }
      const nextImageMap = includeMapImages
        ? await captureMissingReportImages(reportModel, imageMap, (current, total) => {
          setExportStatus(`Đang chụp ảnh bản đồ ${current}/${total}...`);
        })
        : imageMap;
      if (includeMapImages) {
        const missingMapImages = reportModel.sections.filter((section) => !nextImageMap[section.id]);
        if (missingMapImages.length > 0) {
          throw new Error(`Không chụp được ảnh bản đồ cho ${missingMapImages.length} mục. Vui lòng mở bản đồ và thử xuất lại.`);
        }
      }
      setImageMap(nextImageMap);
      const filePath = await save({
        filters: [{ name: "Word Document", extensions: ["docx"] }],
        defaultPath: `${sanitizeFileName(projectName)}-báo-cáo-thiết-kế.docx`,
      });
      if (!filePath) {
        setExportStatus(null);
        return;
      }

      setExportStatus("Đang tạo nội dung Word...");
      const buffer = await buildReportDocx(reportModel, nextImageMap);
      setExportStatus("Đang lưu file...");
      await invoke("save_binary_file", {
        path: filePath,
        data: Array.from(new Uint8Array(buffer)),
      });
      setExportStatus("Đã xuất file Word.");
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setIsExporting(false);
    }
  };

  if (!state || !reportModel) {
    return null;
  }

  return (
    <div className="fixed inset-0 z-[9999] bg-black/65 backdrop-blur-sm flex items-center justify-center p-6">
      <div className="w-[min(1180px,96vw)] h-[min(760px,92vh)] bg-cad-surface border border-cad-border shadow-2xl flex flex-col overflow-hidden rounded">
        <div className="h-14 px-5 border-b border-cad-border flex items-center justify-between shrink-0">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-cad-accent/10 text-cad-accent rounded">
              <FileText size={18} />
            </div>
            <div>
              <h2 className="text-sm font-black text-cad-text-primary uppercase tracking-wide">Báo cáo thiết kế</h2>
              <p className="text-[10px] text-cad-text-muted">{reportModel.sections.length} mục chi tiết</p>
            </div>
          </div>
          <button onClick={onClose} className="p-2 text-cad-text-muted hover:text-white hover:bg-white/10 rounded">
            <X size={18} />
          </button>
        </div>

        <div className="h-12 border-b border-cad-border flex items-center justify-between px-5 shrink-0">
          <div className="flex items-center gap-2">
            <button
              onClick={() => setActiveView("select")}
              className={cn("px-3 py-1.5 text-[10px] font-bold uppercase rounded border", activeView === "select" ? "border-cad-accent text-cad-accent bg-cad-accent/10" : "border-cad-border text-cad-text-muted")}
            >
              Chọn dữ liệu
            </button>
            <button
              onClick={handlePreview}
              disabled={isCapturing}
              className="px-3 py-1.5 text-[10px] font-bold uppercase rounded border border-cad-border text-cad-text-secondary hover:text-white flex items-center gap-2 disabled:opacity-50"
            >
              {isCapturing ? <Loader2 size={13} className="animate-spin" /> : <Eye size={13} />}
              Preview
            </button>
          </div>
          <button
            onClick={handleExport}
            disabled={isExporting || reportModel.sections.length === 0}
            className="px-4 py-2 text-[10px] font-black uppercase rounded bg-cad-accent text-black hover:bg-cad-accent/90 flex items-center gap-2 disabled:opacity-50"
          >
            {isExporting ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />}
            Xuất Word
          </button>
        </div>

        {error && (
          <div className="px-5 py-2 bg-red-500/10 text-red-300 text-xs border-b border-red-500/20">
            {error}
          </div>
        )}

        {exportStatus && (
          <div className="px-5 py-2 bg-cad-accent/10 text-cad-accent text-xs border-b border-cad-accent/20">
            {exportStatus}
          </div>
        )}

        <div className="flex-1 min-h-0 grid grid-cols-[320px_1fr]">
          <aside className="border-r border-cad-border overflow-y-auto p-3">
            <label className="mb-3 flex items-start gap-2 rounded border border-cad-border bg-white/5 p-2 text-[10px] text-cad-text-secondary">
              <input
                type="checkbox"
                className="mt-0.5"
                checked={includeMapImages}
                onChange={(event) => setIncludeMapImages(event.target.checked)}
              />
              <span>
                <span className="block font-black uppercase text-cad-text-primary">Kèm ảnh bản đồ khi xuất</span>
                <span className="block text-cad-text-muted">Bật mặc định. Có thể tắt nếu báo cáo quá nhiều đối tượng.</span>
              </span>
            </label>
            <div className="text-[10px] font-black uppercase tracking-widest text-cad-text-muted mb-2">Thư mục / đối tượng</div>
            <div className="space-y-1">
              {visibleSelectableItems.map((item) => {
                const checked = selectedKeys.has(item.key);
                const hasChildren = getDescendantKeys(selectableItems, item.key).length > 0;
                const isExpanded = expandedSelectionKeys.has(item.key);
                return (
                  <div
                    key={item.key}
                    className="flex items-center gap-1 rounded px-1 py-1 hover:bg-white/5 text-xs"
                    style={{ paddingLeft: 8 + item.level * 16 }}
                  >
                    <button
                      type="button"
                      onClick={() => hasChildren && toggleSelectionExpanded(item.key)}
                      className={cn("flex h-5 w-5 shrink-0 items-center justify-center rounded text-cad-text-muted", hasChildren && "hover:bg-white/10 hover:text-cad-text-primary")}
                      aria-label={hasChildren ? (isExpanded ? "Thu gọn mục" : "Mở rộng mục") : undefined}
                      disabled={!hasChildren}
                    >
                      {hasChildren && (isExpanded ? <ChevronDown size={13} /> : <ChevronRight size={13} />)}
                    </button>
                    <label className="flex min-w-0 flex-1 cursor-pointer items-center gap-2">
                      <span className={cn("w-4 h-4 border rounded flex items-center justify-center shrink-0", checked ? "bg-cad-accent border-cad-accent text-black" : "border-cad-border")}>
                        {checked && <Check size={12} />}
                      </span>
                      <input
                        type="checkbox"
                        className="sr-only"
                        checked={checked}
                        onChange={() => toggleSelection(item.key)}
                      />
                      <span className="truncate text-cad-text-secondary">{item.name}</span>
                    </label>
                  </div>
                );
              })}
            </div>
          </aside>

          <main className="overflow-hidden bg-white text-slate-900">
            {activeView === "select" ? (
              <div className="p-8 text-sm text-slate-600">
                Đã chọn {selectedKeys.size} mục. Bấm Preview để xem trước nội dung báo cáo.
              </div>
            ) : (
              <ReportPreview
                model={reportModel}
                imageMap={imageMap}
                activeSectionId={currentSectionId}
                onSelectSection={handleSelectPreviewSection}
              />
            )}
          </main>
        </div>
      </div>
    </div>
  );
}

function ReportPreview({
  model,
  imageMap,
  activeSectionId,
  onSelectSection,
}: {
  model: ReportModel;
  imageMap: ReportImageMap;
  activeSectionId: string | null;
  onSelectSection: (sectionId: string) => void;
}) {
  const activeSection = model.sections.find((section) => section.id === activeSectionId) || model.sections[0];
  const [isTocOpen, setIsTocOpen] = useState(true);
  const [expandedSections, setExpandedSections] = useState<Set<string>>(
    () => new Set(activeSection ? [activeSection.id] : []),
  );

  useEffect(() => {
    if (!activeSection) return;
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setExpandedSections((prev) => {
      if (prev.has(activeSection.id)) return prev;
      const next = new Set(prev);
      next.add(activeSection.id);
      return next;
    });
  }, [activeSection]);

  const toggleSection = (sectionId: string) => {
    setExpandedSections((prev) => {
      const next = new Set(prev);
      if (next.has(sectionId)) next.delete(sectionId);
      else next.add(sectionId);
      return next;
    });
  };

  return (
    <div className="grid h-full min-h-0 grid-cols-[300px_1fr] bg-slate-50 text-sm">
      <aside className="min-h-0 overflow-y-auto border-r border-slate-200 bg-slate-100/90">
        <div className="sticky top-0 z-10 border-b border-slate-200 bg-slate-100/95 p-3">
          <h1 className="truncate text-sm font-black uppercase text-slate-900">{model.title}</h1>
          <p className="text-[11px] text-slate-500">{model.sections.length} mục chi tiết</p>
        </div>
        <div className="p-2">
          <button
            type="button"
            onClick={() => setIsTocOpen((value) => !value)}
            className="mb-1 flex w-full items-center gap-1 rounded px-2 py-2 text-left text-[11px] font-black uppercase tracking-wide text-slate-700 hover:bg-white"
          >
            {isTocOpen ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
            Mục lục
          </button>
          {isTocOpen && (
            <div className="space-y-1">
              {model.sections.map((section, index) => {
                const isActive = activeSection?.id === section.id;
                const isExpanded = expandedSections.has(section.id);
                return (
                  <div key={section.id}>
                    <div className={cn("flex items-center rounded", isActive ? "bg-white shadow-sm" : "hover:bg-white/70")}>
                      <button
                        type="button"
                        onClick={() => toggleSection(section.id)}
                        className="flex h-8 w-7 shrink-0 items-center justify-center text-slate-500"
                        aria-label={isExpanded ? "Thu gọn mục" : "Mở rộng mục"}
                      >
                        {isExpanded ? <ChevronDown size={14} /> : <ChevronRight size={14} />}
                      </button>
                      <button
                        type="button"
                        onClick={() => onSelectSection(section.id)}
                        className={cn("min-w-0 flex-1 truncate py-2 pr-2 text-left text-xs", isActive ? "font-bold text-blue-800" : "text-slate-700")}
                        title={section.title}
                      >
                        {index + 1}. {section.title}
                      </button>
                    </div>
                    {isExpanded && (
                      <div className="ml-7 mt-1 space-y-1 border-l border-slate-200 pl-2">
                        <button
                          type="button"
                          onClick={() => onSelectSection(section.id)}
                          className="block w-full truncate rounded px-2 py-1 text-left text-[11px] text-slate-500 hover:bg-white"
                        >
                          Ảnh bản đồ và tổng hợp
                        </button>
                        {section.details.map((detail) => (
                          <button
                            key={detail.feature.id}
                            type="button"
                            onClick={() => onSelectSection(section.id)}
                            className="block w-full truncate rounded px-2 py-1 text-left text-[11px] text-slate-500 hover:bg-white"
                            title={`${detail.label}: ${detail.feature.name}`}
                          >
                            {detail.label}: {detail.feature.name}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </aside>

      <article className="min-h-0 overflow-y-auto bg-white p-8 leading-relaxed text-slate-900">
        <div className="mx-auto max-w-[820px]">
          <h1 className="mb-2 text-center text-2xl font-bold">{model.title}</h1>
          <p className="mb-8 text-center text-slate-500">Ngày tạo: {new Date(model.generatedAt).toLocaleString("vi-VN")}</p>

      {activeSection ? (
        <section key={activeSection.id} id={activeSection.anchor} className="mb-10 break-inside-avoid">
          <h2 className="text-xl font-bold mb-3">{activeSection.title} <span className="text-slate-500">({activeSection.displayType})</span></h2>
          {imageMap[activeSection.id] ? (
            <img src={imageMap[activeSection.id]} alt={activeSection.title} loading="lazy" className="w-full max-h-[360px] object-contain border mb-3" />
          ) : (
            <div className="h-40 border bg-slate-100 text-slate-500 flex items-center justify-center mb-3">Chưa capture ảnh bản đồ</div>
          )}
          {activeSection.summary.length > 0 && (
            <div className="mb-3">
              <h3 className="font-bold">Tổng hợp</h3>
              <ul className="list-disc pl-5">
                {activeSection.summary.map((item) => <li key={item}>{item}</li>)}
              </ul>
            </div>
          )}
          {activeSection.description && <p className="mb-3"><strong>Mô tả:</strong> {activeSection.description}</p>}
          {activeSection.details.map((detail) => (
            <div key={detail.feature.id} className="mt-5 border-t pt-4">
              <h3 className="font-bold">{detail.label}: {detail.feature.name}</h3>
              <p><strong>Loại:</strong> {detail.displayType}</p>
              <p><strong>Mô tả:</strong> {detail.description || "-"}</p>
              {detail.startPoint && <p><strong>Điểm đầu:</strong> {detail.startPoint[1].toFixed(6)}, {detail.startPoint[0].toFixed(6)}</p>}
              {detail.endPoint && <p><strong>Điểm cuối:</strong> {detail.endPoint[1].toFixed(6)}, {detail.endPoint[0].toFixed(6)}</p>}
              {detail.connectedNames.length > 0 && <p><strong>Kết nối/tuyến đi qua:</strong> {detail.connectedNames.join(", ")}</p>}
              <div className="grid grid-cols-2 gap-3 mt-3">
                {detail.photos.filter((photo) => !!photo.dataUrl).map((photo) => (
                  <figure key={photo.id} className="border p-2">
                    <img src={photo.dataUrl} alt={photo.label} loading="lazy" className="w-full h-40 object-contain" />
                    <figcaption className="text-xs text-slate-500 mt-1">{photo.label}</figcaption>
                  </figure>
                ))}
              </div>
            </div>
          ))}
        </section>
      ) : (
        <div className="h-40 border bg-slate-100 text-slate-500 flex items-center justify-center">Không có nội dung preview</div>
      )}
        </div>
      </article>
    </div>
  );
}

import type { FeatureState, FeatureGroupState, MapState, RegionState } from "@CONTRACT/types";
import { getFeatureDisplayInfo, getParsedMetadata, getFeatureMetadataValue, safeString, isNetworkLinkFeature } from "@TOOL/utils/featureUtils";

export type ReportSelection =
  | { type: "region"; id: string }
  | { type: "group"; id: string }
  | { type: "feature"; id: string };

export type ReportBounds = [number, number, number, number];

export interface ReportPhoto {
  id: string;
  label: string;
  dataUrl: string;
  assetId?: string;
}

export interface ReportFeatureDetail {
  feature: FeatureState;
  label: string;
  displayType: string;
  description: string;
  metadata: Record<string, unknown>;
  properties: Record<string, unknown>;
  photos: ReportPhoto[];
  bounds: ReportBounds | null;
  startPoint?: [number, number];
  endPoint?: [number, number];
  connectedNames: string[];
}

export interface ReportSection {
  id: string;
  anchor: string;
  title: string;
  displayType: string;
  feature: FeatureState;
  description: string;
  summary: string[];
  details: ReportFeatureDetail[];
  photos: ReportPhoto[];
  bounds: ReportBounds | null;
}

export interface ReportModel {
  title: string;
  generatedAt: string;
  selectedItems: ReportSelection[];
  sections: ReportSection[];
}

const POINT_PADDING_DEGREES = 0.0009;
const CLUSTER_PADDING_DEGREES = 0.00006;
const LINE_PADDING_RATIO = 0.08;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const asStringArray = (value: unknown): string[] => {
  if (!Array.isArray(value)) return [];
  return value.filter((item): item is string => typeof item === "string" && item.length > 0);
};

const getGroupKind = (group?: FeatureGroupState | null): string | undefined =>
  group?.type || group?.group_type;

export const normalizeAnchor = (id: string): string =>
  `report_${id.replace(/[^A-Za-z0-9_]/g, "_")}`;

export const getFeatureChildrenMap = (state: MapState): Map<string, FeatureState[]> => {
  const childrenMap = new Map<string, FeatureState[]>();
  Object.values(state.features || {}).forEach((feature) => {
    const metadata = getParsedMetadata(feature);
    const parentId = typeof metadata.parent_feature_id === "string" ? metadata.parent_feature_id : null;
    if (!parentId) return;
    const list = childrenMap.get(parentId) || [];
    list.push(feature);
    childrenMap.set(parentId, list);
  });
  childrenMap.forEach((items) => {
    items.sort(compareFeatures);
  });
  return childrenMap;
};

const compareFeatures = (left: FeatureState, right: FeatureState): number => {
  const leftMeta = getParsedMetadata(left);
  const rightMeta = getParsedMetadata(right);
  const leftOrder = safeString(leftMeta.display_order || left.properties?.display_order);
  const rightOrder = safeString(rightMeta.display_order || right.properties?.display_order);
  if (leftOrder || rightOrder) return leftOrder.localeCompare(rightOrder, undefined, { numeric: true });
  return (left.name || left.id).localeCompare(right.name || right.id, undefined, { numeric: true });
};

const getRegionLayerIds = (state: MapState, regionId: string): Set<string> => {
  const layerIds = new Set<string>();
  Object.values(state.layers || {}).forEach((layer) => {
    if (layer.region_id === regionId) layerIds.add(layer.id);
  });
  return layerIds;
};

const getGroupAndSubgroupIds = (state: MapState, groupId: string): Set<string> => {
  const ids = new Set<string>([groupId]);
  let changed = true;
  while (changed) {
    changed = false;
    Object.values(state.feature_groups || {}).forEach((group) => {
      if (group.parent_id && ids.has(group.parent_id) && !ids.has(group.id)) {
        ids.add(group.id);
        changed = true;
      }
    });
  }
  return ids;
};

const collectFeatureAndChildren = (
  featureId: string,
  state: MapState,
  childrenMap: Map<string, FeatureState[]>,
  out: Map<string, FeatureState>,
): void => {
  const feature = state.features?.[featureId];
  if (!feature || out.has(feature.id)) return;
  out.set(feature.id, feature);
  (childrenMap.get(feature.id) || []).forEach((child) => collectFeatureAndChildren(child.id, state, childrenMap, out));
};

export const expandReportSelections = (state: MapState, selections: ReportSelection[]): FeatureState[] => {
  const childrenMap = getFeatureChildrenMap(state);
  const selectedFeatures = new Map<string, FeatureState>();

  selections.forEach((selection) => {
    if (selection.type === "feature") {
      collectFeatureAndChildren(selection.id, state, childrenMap, selectedFeatures);
      return;
    }

    if (selection.type === "group") {
      const groupIds = getGroupAndSubgroupIds(state, selection.id);
      Object.values(state.features || {}).forEach((feature) => {
        if (feature.group_id && groupIds.has(feature.group_id)) {
          collectFeatureAndChildren(feature.id, state, childrenMap, selectedFeatures);
        }
      });
      return;
    }

    const layerIds = getRegionLayerIds(state, selection.id);
    Object.values(state.features || {}).forEach((feature) => {
      if (layerIds.has(feature.layer_id)) {
        collectFeatureAndChildren(feature.id, state, childrenMap, selectedFeatures);
      }
    });
  });

  return Array.from(selectedFeatures.values())
    .filter((feature) => !isNetworkLinkFeature(feature))
    .sort(compareFeatures);
};

export const getDefaultReportSelections = (state: MapState, options: {
  selectionSet?: Set<string>;
  selectedFeatureId?: string | null;
  selectedGroupId?: string | null;
}): ReportSelection[] => {
  const explicitSelections = Array.from(options.selectionSet || [])
    .filter((id) => state.features?.[id] && !isNetworkLinkFeature(state.features[id]))
    .map((id) => ({ type: "feature", id } as ReportSelection));
  if (explicitSelections.length > 0) return explicitSelections;
  if (options.selectedFeatureId && state.features?.[options.selectedFeatureId] && !isNetworkLinkFeature(state.features[options.selectedFeatureId])) {
    return [{ type: "feature", id: options.selectedFeatureId }];
  }
  if (options.selectedGroupId && state.feature_groups?.[options.selectedGroupId]) {
    return [{ type: "group", id: options.selectedGroupId }];
  }
  return Object.keys(state.regions || {}).map((id) => ({ type: "region", id }));
};

const parseCoordinates = (feature: FeatureState): unknown => {
  if (typeof feature.coordinates === "string") {
    try {
      return JSON.parse(feature.coordinates);
    } catch {
      return null;
    }
  }
  return feature.coordinates;
};

const collectPointsFromCoordinates = (coords: unknown, points: Array<[number, number]>): void => {
  if (!Array.isArray(coords)) return;
  if (coords.length >= 2 && typeof coords[0] === "number" && typeof coords[1] === "number") {
    points.push([coords[0], coords[1]]);
    return;
  }
  coords.forEach((child) => collectPointsFromCoordinates(child, points));
};

const getRepresentativePoint = (feature: FeatureState): [number, number] | null => {
  const points = getFeaturePoints(feature);
  if (points.length === 0) return null;
  const lng = points.reduce((sum, point) => sum + point[0], 0) / points.length;
  const lat = points.reduce((sum, point) => sum + point[1], 0) / points.length;
  return [lng, lat];
};

export const getFeaturePoints = (feature: FeatureState): Array<[number, number]> => {
  const points: Array<[number, number]> = [];
  collectPointsFromCoordinates(parseCoordinates(feature), points);
  return points;
};

export const getFeatureClusterBounds = (feature: FeatureState, related: FeatureState[] = []): ReportBounds | null => {
  const allPoints = [feature, ...related]
    .map(getRepresentativePoint)
    .filter((point): point is [number, number] => point !== null);
  if (allPoints.length === 0) return getFeatureBounds(feature, related);

  let minLng = Math.min(...allPoints.map((point) => point[0]));
  let maxLng = Math.max(...allPoints.map((point) => point[0]));
  let minLat = Math.min(...allPoints.map((point) => point[1]));
  let maxLat = Math.max(...allPoints.map((point) => point[1]));

  const width = Math.max(maxLng - minLng, CLUSTER_PADDING_DEGREES);
  const height = Math.max(maxLat - minLat, CLUSTER_PADDING_DEGREES);
  const padLng = width * LINE_PADDING_RATIO + CLUSTER_PADDING_DEGREES;
  const padLat = height * LINE_PADDING_RATIO + CLUSTER_PADDING_DEGREES;

  minLng -= padLng;
  maxLng += padLng;
  minLat -= padLat;
  maxLat += padLat;

  return [minLat, minLng, maxLat, maxLng];
};

export const getFeatureBounds = (feature: FeatureState, related: FeatureState[] = []): ReportBounds | null => {
  const allPoints = [feature, ...related].flatMap(getFeaturePoints);
  if (allPoints.length === 0) return null;

  let minLng = Math.min(...allPoints.map((point) => point[0]));
  let maxLng = Math.max(...allPoints.map((point) => point[0]));
  let minLat = Math.min(...allPoints.map((point) => point[1]));
  let maxLat = Math.max(...allPoints.map((point) => point[1]));

  const metadata = getParsedMetadata(feature);
  const fovRadiusMeters = Number(getFeatureMetadataValue(feature, "gis.fov_radius", "fov_radius", metadata) || 0);
  const radiusPadding = Number.isFinite(fovRadiusMeters) && fovRadiusMeters > 0
    ? Math.min(fovRadiusMeters / 111_000, 0.02)
    : 0;

  const width = Math.max(maxLng - minLng, POINT_PADDING_DEGREES, radiusPadding);
  const height = Math.max(maxLat - minLat, POINT_PADDING_DEGREES, radiusPadding);
  const padLng = width * LINE_PADDING_RATIO + POINT_PADDING_DEGREES;
  const padLat = height * LINE_PADDING_RATIO + POINT_PADDING_DEGREES;

  minLng -= padLng;
  maxLng += padLng;
  minLat -= padLat;
  maxLat += padLat;

  return [minLat, minLng, maxLat, maxLng];
};

const getFeatureDescription = (feature: FeatureState, metadata: Record<string, unknown>): string => {
  const propertyDescription = feature.properties?.description;
  return safeString(metadata.description || metadata.notes || metadata.note || propertyDescription || feature.note || "");
};

const getFeaturePhotos = (feature: FeatureState, metadata: Record<string, unknown>): ReportPhoto[] => {
  const media = isRecord(metadata.media) ? metadata.media : {};
  const urls = [
    ...asStringArray(media.imageUrls),
    ...asStringArray(metadata.imageUrls),
  ];
  const singleUrl = safeString(media.imageUrl || metadata.imageUrl);
  if (singleUrl) urls.unshift(singleUrl);
  const assetIds = asStringArray(media.imageAssetIds);

  const legacyPhotos = Array.from(new Set(urls))
    .filter((url) => url.startsWith("data:image") || /^https?:\/\//i.test(url))
    .map((dataUrl, index) => ({
      id: `${feature.id}-photo-${index + 1}`,
      label: `Ảnh ${index + 1}`,
      dataUrl,
    }));

  const assetPhotos = assetIds.map((assetId, index) => ({
    id: `${feature.id}-asset-photo-${index + 1}`,
    label: `Ảnh ${legacyPhotos.length + index + 1}`,
    dataUrl: "",
    assetId,
  }));

  return [...legacyPhotos, ...assetPhotos];
};

const toPlainRecord = (value: unknown): Record<string, unknown> =>
  isRecord(value) ? value : {};

const makeFeatureDetail = (
  feature: FeatureState,
  state: MapState,
  childrenMap: Map<string, FeatureState[]>,
  label: string,
): ReportFeatureDetail => {
  const metadata = getParsedMetadata(feature);
  const group = feature.group_id ? state.feature_groups?.[feature.group_id] : null;
  const info = getFeatureDisplayInfo(feature, getGroupKind(group), group?.name, metadata);
  const points = getFeaturePoints(feature);
  const startPoint = points[0];
  const endPoint = points.length > 1 ? points[points.length - 1] : undefined;

  return {
    feature,
    label,
    displayType: info.label,
    description: getFeatureDescription(feature, metadata),
    metadata,
    properties: toPlainRecord(feature.properties),
    photos: getFeaturePhotos(feature, metadata),
    bounds: getFeatureBounds(feature, childrenMap.get(feature.id) || []),
    startPoint,
    endPoint,
    connectedNames: getConnectedNames(feature, state),
  };
};

const getConnectedNames = (feature: FeatureState, state: MapState): string[] => {
  const info = getFeatureDisplayInfo(feature);
  if (!info.isLine) return [];
  const lineBounds = getFeatureBounds(feature);
  if (!lineBounds) return [];
  const [minLat, minLng, maxLat, maxLng] = lineBounds;
  return Object.values(state.features || {})
    .filter((candidate) => candidate.id !== feature.id)
    .filter((candidate) => getFeaturePoints(candidate).some(([lng, lat]) => (
      lng >= minLng && lng <= maxLng && lat >= minLat && lat <= maxLat
    )))
    .map((candidate) => candidate.name || candidate.id);
};

const makeSectionSummary = (
  feature: FeatureState,
  state: MapState,
  children: FeatureState[],
  metadata: Record<string, unknown>,
  childrenMap: Map<string, FeatureState[]>,
): string[] => {
  const group = feature.group_id ? state.feature_groups?.[feature.group_id] : null;
  const info = getFeatureDisplayInfo(feature, getGroupKind(group), group?.name, metadata);
  if (info.isIntersection) {
    const childDetails = children.map((child, index) => makeFeatureDetail(child, state, childrenMap, `Đối tượng 1_${index + 1}`));
    const cameraCounts = childDetails.reduce<Record<string, number>>((acc, detail) => {
      if (["CCTV", "PTZ", "SPEED", "LPR"].includes(detail.displayType)) {
        acc[detail.displayType] = (acc[detail.displayType] || 0) + 1;
      }
      return acc;
    }, {});
    const cameraText = Object.entries(cameraCounts).map(([type, count]) => `${type}: ${count}`).join(", ") || "Không có camera";
    return [`Số vị trí thuộc nút giao: ${children.length}`, `Loại camera: ${cameraText}`];
  }

  if (info.isLine) {
    const detail = makeFeatureDetail(feature, state, childrenMap, feature.name);
    const lineType = safeString(getFeatureMetadataValue(feature, "infrastructure.type", undefined, metadata));
    const summary = [`Điểm đầu: ${formatPoint(detail.startPoint)}`, `Điểm cuối: ${formatPoint(detail.endPoint)}`];
    if (lineType === "SignalLine") {
      summary.push(`Nút/đối tượng kết nối trên tuyến: ${detail.connectedNames.join(", ") || "Chưa xác định"}`);
    }
    return summary;
  }

  return [getFeatureDescription(feature, metadata)].filter(Boolean);
};

export const formatPoint = (point?: [number, number]): string =>
  point ? `${point[1].toFixed(6)}, ${point[0].toFixed(6)}` : "Chưa có tọa độ";

export const buildReportModel = (state: MapState, selections: ReportSelection[], title = "Báo cáo thiết kế"): ReportModel => {
  const childrenMap = getFeatureChildrenMap(state);
  const expandedFeatures = expandReportSelections(state, selections);
  const featureIds = new Set(expandedFeatures.map((feature) => feature.id));
  const roots = expandedFeatures.filter((feature) => {
    const metadata = getParsedMetadata(feature);
    const parentId = typeof metadata.parent_feature_id === "string" ? metadata.parent_feature_id : null;
    return !parentId || !featureIds.has(parentId);
  });

  const sections = roots.map((feature, sectionIndex) => {
    const metadata = getParsedMetadata(feature);
    const group = feature.group_id ? state.feature_groups?.[feature.group_id] : null;
    const info = getFeatureDisplayInfo(feature, getGroupKind(group), group?.name, metadata);
    const children = (childrenMap.get(feature.id) || []).filter((child) => featureIds.has(child.id));
    const details = info.isIntersection
      ? children.map((child, index) => makeFeatureDetail(child, state, childrenMap, `Đối tượng ${sectionIndex + 1}_${index + 1}`))
      : [makeFeatureDetail(feature, state, childrenMap, feature.name || `Đối tượng ${sectionIndex + 1}`)];

    return {
      id: feature.id,
      anchor: normalizeAnchor(feature.id),
      title: `${sectionIndex + 1}. ${feature.name || feature.id}`,
      displayType: info.label,
      feature,
      description: getFeatureDescription(feature, metadata),
      summary: makeSectionSummary(feature, state, children, metadata, childrenMap),
      details,
      photos: getFeaturePhotos(feature, metadata),
      bounds: info.isIntersection ? getFeatureClusterBounds(feature, children) : getFeatureBounds(feature, children),
    } satisfies ReportSection;
  });

  return {
    title,
    generatedAt: new Date().toISOString(),
    selectedItems: selections,
    sections,
  };
};

export const getSelectableReportItems = (state: MapState): Array<{
  key: string;
  selection: ReportSelection;
  name: string;
  level: number;
}> => {
  const items: Array<{ key: string; selection: ReportSelection; name: string; level: number }> = [];
  const regions = Object.values(state.regions || {}).sort((a: RegionState, b: RegionState) => a.name.localeCompare(b.name));
  const childrenMap = getFeatureChildrenMap(state);

  const addFeature = (feature: FeatureState, level: number) => {
    if (isNetworkLinkFeature(feature)) return;
    items.push({
      key: `feature:${feature.id}`,
      selection: { type: "feature", id: feature.id },
      name: feature.name || feature.id,
      level,
    });
    (childrenMap.get(feature.id) || []).forEach((child) => addFeature(child, level + 1));
  };

  const isChildFeature = (feature: FeatureState): boolean => {
    const metadata = getParsedMetadata(feature);
    return typeof metadata.parent_feature_id === "string" && metadata.parent_feature_id.length > 0;
  };

  regions.forEach((region) => {
    items.push({ key: `region:${region.id}`, selection: { type: "region", id: region.id }, name: region.name, level: 0 });
    const layerIds = getRegionLayerIds(state, region.id);
    const topGroups = Object.values(state.feature_groups || {})
      .filter((group) => layerIds.has(group.layer_id) && !group.parent_id)
      .sort((a, b) => a.name.localeCompare(b.name));

    const addGroup = (group: FeatureGroupState, level: number) => {
      items.push({ key: `group:${group.id}`, selection: { type: "group", id: group.id }, name: group.name, level });
      Object.values(state.feature_groups || {})
        .filter((child) => child.parent_id === group.id)
        .sort((a, b) => a.name.localeCompare(b.name))
        .forEach((child) => addGroup(child, level + 1));
      Object.values(state.features || {})
        .filter((feature) => feature.group_id === group.id)
        .filter((feature) => !isChildFeature(feature))
        .sort(compareFeatures)
        .forEach((feature) => addFeature(feature, level + 1));
    };

    topGroups.forEach((group) => addGroup(group, 1));
    Object.values(state.features || {})
      .filter((feature) => layerIds.has(feature.layer_id) && !feature.group_id)
      .filter((feature) => !isChildFeature(feature))
      .sort(compareFeatures)
      .forEach((feature) => addFeature(feature, 1));
  });

  return items;
};

import { useCallback, useEffect } from "react";
import { useDesignSync } from "@IMPLEMENT/stores/useDesignSync";
import { getNextFeatureDisplayOrder, syncDisplayOrderAliases } from "@TOOL/utils/featureMapping";
import { getParsedMetadata } from "@TOOL/utils/featureMetadata";
import { buildFeatureCreatedPayload } from "@TOOL/utils/featurePersistence";
import { getNetworkEndpointCoordinate, getRepresentativeFeatureIdForEndpoint } from "@DESIGN/features/map/network/NetworkEndpoint";
import { buildSnapLinks, inferNetworkRole, isSourceRole, resolveNetworkNodeIdFromSnap } from "@DESIGN/features/map/network/networkTopology";

type OneClickDrawingMode = 'point' | 'image' | 'intersection';

const ONE_CLICK_DRAWING_MODES = new Set<string>(['point', 'image', 'intersection']);

const getOneClickDefaults = (mode: OneClickDrawingMode) => {
    switch (mode) {
        case 'image':
            return {
                name: "Ảnh Hiện Trường Mới",
                icon: 'cctv',
                type: 'cctv',
                color: '#3B82F6'
            };
        case 'intersection':
            return {
                name: "Nút Giao Mới",
                icon: 'intersection',
                type: 'intersection',
                color: '#6366F1'
            };
        case 'point':
        default:
            return {
                name: "Điểm Khảo Sát Mới",
                icon: 'default',
                type: 'point',
                color: '#3B82F6'
            };
    }
};

export function useDrawingInteraction() {
    const {
        state,
        drawingMode,
        selectedGroupId,
        activeParentFeatureId,
        dispatchEvent,
        setDrawingMode,
        addDrawingPoint,
        currentDrawingPoints,
        currentDrawingSnapIds,
        networkConnectionDraft,
        clearNetworkConnectionDraft,
        dispatchEvents,
        queueEvent,
        queueEvents,
    } = useDesignSync();

    const finalizePolyline = useCallback(async () => {
        const featuresById = state?.features || {};
        const workingPoints = [...currentDrawingPoints];
        const workingSnapIds = [...currentDrawingSnapIds];

        if (networkConnectionDraft) {
            const startCoordinate = getNetworkEndpointCoordinate(networkConnectionDraft.fromEndpoint, featuresById);
            const endCoordinate = getNetworkEndpointCoordinate(networkConnectionDraft.toEndpoint, featuresById);
            const startSnapId = getRepresentativeFeatureIdForEndpoint(networkConnectionDraft.fromEndpoint, featuresById);
            const endSnapId = getRepresentativeFeatureIdForEndpoint(networkConnectionDraft.toEndpoint, featuresById);

            if (startCoordinate && startSnapId && (workingSnapIds[0] || null) !== startSnapId) {
                workingPoints.unshift(startCoordinate);
                workingSnapIds.unshift(startSnapId);
            }

            if (endCoordinate && endSnapId && (workingSnapIds[workingSnapIds.length - 1] || null) !== endSnapId) {
                workingPoints.push(endCoordinate);
                workingSnapIds.push(endSnapId);
            }
        }

        if (workingPoints.length < 2) {
            alert("Cần ít nhất 2 điểm để tạo đường.");
            return;
        }

        if (!selectedGroupId) {
            alert("Vui lòng chọn một nhóm trước khi lưu.");
            return;
        }

        const startSnapId = workingSnapIds[0] || null;
        const endSnapId = workingSnapIds[workingSnapIds.length - 1] || null;

        if (!startSnapId || !featuresById[startSnapId]) {
            alert("Không thể lưu polyline vì đầu bắt đầu chưa kết nối vào đối tượng hợp lệ.");
            return;
        }

        if (!endSnapId || !featuresById[endSnapId]) {
            alert("Không thể lưu polyline vì đầu kết thúc chưa kết nối vào đối tượng hợp lệ.");
            return;
        }

        const id = crypto.randomUUID();
        const metadata: any = syncDisplayOrderAliases({
            color: '#EF4444',
        }, getNextFeatureDisplayOrder(
            featuresById,
            selectedGroupId,
            activeParentFeatureId
        ));

        if (activeParentFeatureId) {
            metadata.parent_feature_id = activeParentFeatureId;
        }

        const group = selectedGroupId ? state?.feature_groups?.[selectedGroupId] : null;
        if (!group) return;

        const resolvedStartNetworkNodeId = resolveNetworkNodeIdFromSnap(featuresById, startSnapId, workingPoints[0] || null);
        const resolvedEndNetworkNodeId = resolveNetworkNodeIdFromSnap(featuresById, endSnapId, workingPoints[workingPoints.length - 1] || null);
        const shouldCreateNetworkEdge = !!resolvedStartNetworkNodeId &&
            !!resolvedEndNetworkNodeId &&
            resolvedStartNetworkNodeId !== resolvedEndNetworkNodeId;

        const finalMetadata: any = {
            ...metadata,
            start_node_id: startSnapId,
            end_node_id: endSnapId,
            manual_override: true,
        };

        const snapLinks = buildSnapLinks(workingSnapIds);
        if (snapLinks) {
            finalMetadata.snap_links = snapLinks;
        }

        if (shouldCreateNetworkEdge) {
            const fromEndpoint = networkConnectionDraft?.fromEndpoint || null;
            const toEndpoint = networkConnectionDraft?.toEndpoint || null;
            const fromRepresentativeId = fromEndpoint
                ? getRepresentativeFeatureIdForEndpoint(fromEndpoint, featuresById)
                : null;
            const toRepresentativeId = toEndpoint
                ? getRepresentativeFeatureIdForEndpoint(toEndpoint, featuresById)
                : null;
            finalMetadata.infrastructure = {
                ...(finalMetadata.infrastructure || {}),
                type: 'SignalLine'
            };
            finalMetadata.network = {
                ...(finalMetadata.network || {}),
                from_feature_id: fromEndpoint?.type === 'feature'
                    ? fromEndpoint.id
                    : (resolvedStartNetworkNodeId || fromRepresentativeId),
                to_feature_id: toEndpoint?.type === 'feature'
                    ? toEndpoint.id
                    : (resolvedEndNetworkNodeId || toRepresentativeId),
                ...(fromEndpoint ? { from_endpoint: fromEndpoint } : {}),
                ...(toEndpoint ? { to_endpoint: toEndpoint } : {}),
                direction_mode: 'auto',
            };
        }

        const events: any[] = [];

        if (shouldCreateNetworkEdge) {
            const resolvedStartFeature = featuresById[resolvedStartNetworkNodeId!];
            const resolvedEndFeature = featuresById[resolvedEndNetworkNodeId!];
            const startMeta = getParsedMetadata(resolvedStartFeature) as Record<string, any>;
            const endMeta = getParsedMetadata(resolvedEndFeature) as Record<string, any>;
            const startRole = inferNetworkRole(resolvedStartFeature, startMeta as any);
            const endRole = inferNetworkRole(resolvedEndFeature, endMeta as any);
            const sourceFeature = isSourceRole(startRole) && !isSourceRole(endRole)
                ? resolvedStartFeature
                : isSourceRole(endRole) && !isSourceRole(startRole)
                    ? resolvedEndFeature
                    : null;
            const deviceFeature = sourceFeature?.id === resolvedStartFeature.id ? resolvedEndFeature : sourceFeature?.id === resolvedEndFeature.id ? resolvedStartFeature : null;

            if (sourceFeature && deviceFeature) {
                const deviceMeta = { ...(getParsedMetadata(deviceFeature) as Record<string, any>) };
                if (deviceMeta.parent_feature_id !== sourceFeature.id) {
                    deviceMeta.parent_feature_id = sourceFeature.id;
                    events.push({
                        type: 'FeatureUpdated',
                        payload: {
                            id: deviceFeature.id,
                            metadata: JSON.stringify(deviceMeta),
                        },
                    });
                }
            }
        }

        events.push({
            type: 'FeatureCreated',
            payload: buildFeatureCreatedPayload({
                id,
                layer_id: group.layer_id,
                group_id: selectedGroupId,
                name: shouldCreateNetworkEdge ? "Tuyến SignalLine Mới" : "Đường Khảo Sát Mới",
                geom_type: 'LineString',
                coordinates: workingPoints,
                metadata: finalMetadata,
            })
        } as any);

        if (shouldCreateNetworkEdge) {
            if (events.length > 1) {
                await queueEvents(events);
            } else {
                await queueEvent(events[0]);
            }
        } else if (events.length > 1) {
            await dispatchEvents(events);
        } else {
            await dispatchEvent(events[0]);
        }

        setDrawingMode('none');
        clearNetworkConnectionDraft();
    }, [currentDrawingPoints, selectedGroupId, state, activeParentFeatureId, currentDrawingSnapIds, dispatchEvent, dispatchEvents, queueEvent, queueEvents, setDrawingMode, networkConnectionDraft, clearNetworkConnectionDraft]);

    const finishDrawingSession = useCallback(() => {
        if (drawingMode === 'polyline' && (networkConnectionDraft || currentDrawingPoints.length >= 2)) {
            void finalizePolyline();
            return;
        }
        setDrawingMode('none');
        clearNetworkConnectionDraft();
    }, [clearNetworkConnectionDraft, currentDrawingPoints.length, drawingMode, finalizePolyline, networkConnectionDraft, setDrawingMode]);

    const handleLocationChange = useCallback(async (lat: number, lng: number, _unused: number, snapId?: string | null) => {
        if (drawingMode === 'none') return;

        if (ONE_CLICK_DRAWING_MODES.has(drawingMode)) {
            if (!selectedGroupId) {
                alert("Vui lòng chọn một nhóm trước khi thêm đối tượng.");
                setDrawingMode('none');
                return;
            }

            const mode = drawingMode as OneClickDrawingMode;
            const defaults = getOneClickDefaults(mode);

            const metadata: any = syncDisplayOrderAliases({
                icon: defaults.icon,
                type: defaults.type,
                color: defaults.color,
                snap_to_id: snapId || undefined,
            }, getNextFeatureDisplayOrder(
                state?.features || {},
                selectedGroupId,
                activeParentFeatureId
            ));

            if (activeParentFeatureId) {
                metadata.parent_feature_id = activeParentFeatureId;
            }

            const group = selectedGroupId ? state?.feature_groups?.[selectedGroupId] : null;
            if (!group) return;

            await dispatchEvent({
                type: 'FeatureCreated',
                payload: buildFeatureCreatedPayload({
                    id: crypto.randomUUID(),
                    layer_id: group.layer_id,
                    group_id: selectedGroupId,
                    name: defaults.name,
                    geom_type: 'Point',
                    coordinates: [lng, lat],
                    metadata,
                })
            } as any);
        } else if (drawingMode === 'polyline') {
            addDrawingPoint(lat, lng, snapId);
        }
    }, [drawingMode, selectedGroupId, state, activeParentFeatureId, dispatchEvent, setDrawingMode, addDrawingPoint]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (e.key === 'Enter' && drawingMode === 'polyline') {
                finalizePolyline();
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [drawingMode, finalizePolyline]);

    return {
        handleLocationChange,
        finalizePolyline,
        finishDrawingSession
    };
}

