import React, { useState, useEffect } from 'react';
import { Shield, History, Plus, Trash2, AlertTriangle } from 'lucide-react';
import { safeInvoke } from '@IMPLEMENT/lib/tauri';
import { cn } from '@TOOL/utils/cn';

interface AppConfig {
    admins: Record<string, string>;
    last_opened_project_path?: string;
    is_ai_enabled: boolean;
}

export const AdminPanel: React.FC = () => {
    const [config, setConfig] = useState<AppConfig | null>(null);
    const [newEmail, setNewEmail] = useState('');
    const [newRole, setNewRole] = useState<'Admin' | 'Editor' | 'Viewer'>('Editor');
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'ROLES' | 'LOGS'>('ROLES');
    const [logs, setLogs] = useState<any[]>([]);

    const fetchConfig = async () => {
        try {
            const cfg = await safeInvoke<AppConfig>('get_app_config');
            setConfig(cfg);
        } catch (err) {
            console.error("Failed to fetch config:", err);
        } finally {
            setLoading(false);
        }
    };

    const fetchLogs = async () => {
        try {
            const auditLogs = await safeInvoke<any[]>('get_audit_logs', { limit: 50 });
            setLogs(auditLogs);
        } catch (err) {
            console.error("Failed to fetch logs:", err);
        }
    };

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        fetchConfig();
        fetchLogs();
    }, []);

    const handleUpdateRole = async (email: string, role: string) => {
        if (!config) return;
        const newAdmins = { ...config.admins, [email]: role };
        try {
            await safeInvoke('update_app_config', {
                config: { ...config, admins: newAdmins }
            });
            await fetchConfig();
        } catch (err) {
            alert("Failed to update: " + (err instanceof Error ? err.message : String(err)));
        }
    };

    const handleRemoveAdmin = async (email: string) => {
        if (!config) return;
        const { [email]: _, ...newAdmins } = config.admins;
        try {
            await safeInvoke('update_app_config', {
                config: { ...config, admins: newAdmins }
            });
            await fetchConfig();
        } catch (err) {
            alert("Failed to remove: " + (err instanceof Error ? err.message : String(err)));
        }
    };

    if (loading) return <div className="p-8 text-cad-text-muted font-mono animate-pulse">Initializing Administrative Terminal...</div>;

    return (
        <div className="flex h-full flex-col overflow-hidden border-l border-cad-border bg-cad-surface animate-in slide-in-from-right duration-500">
            <div className="border-b border-cad-border bg-cad-elevated/30 p-6">
                <div className="mb-6 flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                        <div className="rounded-md border border-cad-border bg-cad-bg p-2 text-cad-accent">
                            <Shield size={20} />
                        </div>
                        <div>
                            <h2 className="text-sm font-black uppercase tracking-widest text-cad-text-primary">System Administration</h2>
                            <p className="text-[10px] font-bold uppercase tracking-tight text-cad-text-muted">Access Control & Audit Logs</p>
                        </div>
                    </div>

                    <div className="flex rounded-md border border-cad-border bg-cad-bg p-1">
                        <button
                            onClick={() => setActiveTab('ROLES')}
                            className={cn(
                                "rounded-md px-4 py-1.5 text-[10px] font-black uppercase tracking-wider transition-all",
                                activeTab === 'ROLES' ? "bg-cad-accent text-black shadow-lg" : "text-cad-text-muted hover:text-cad-text-primary"
                            )}
                        >
                            Identities
                        </button>
                        <button
                            onClick={() => setActiveTab('LOGS')}
                            className={cn(
                                "rounded-md px-4 py-1.5 text-[10px] font-black uppercase tracking-wider transition-all",
                                activeTab === 'LOGS' ? "bg-cad-accent text-black shadow-lg" : "text-cad-text-muted hover:text-cad-text-primary"
                            )}
                        >
                            Chronicle
                        </button>
                    </div>
                </div>

                {activeTab === 'ROLES' && (
                    <div className="flex gap-2">
                        <input
                            value={newEmail}
                            onChange={(e) => setNewEmail(e.target.value)}
                            placeholder="operator@system.com"
                            className="cad-input flex-1"
                        />
                        <select
                            value={newRole}
                            onChange={(e) => setNewRole(e.target.value as any)}
                            className="cad-select w-32 text-[10px] font-bold uppercase"
                        >
                            <option value="Admin">Admin</option>
                            <option value="Editor">Editor</option>
                            <option value="Viewer">Viewer</option>
                        </select>
                        <button
                            onClick={() => {
                                if (newEmail) handleUpdateRole(newEmail, newRole);
                                setNewEmail('');
                            }}
                            className="cad-button cad-button-primary px-3"
                        >
                            <Plus size={18} />
                        </button>
                    </div>
                )}
            </div>

            <div className="cad-scrollbar flex-1 overflow-y-auto p-6">
                {activeTab === 'ROLES' ? (
                    <div className="space-y-3">
                        {Object.entries(config?.admins || {}).map(([email, role]) => (
                            <div key={email} className="group flex items-center justify-between rounded-md border border-cad-border bg-cad-elevated/50 p-4 transition-all hover:border-cad-accent/30">
                                <div className="flex items-center gap-4">
                                    <div className={cn(
                                        "flex h-10 w-10 items-center justify-center rounded-full border border-cad-border text-xs font-black",
                                        role === 'Admin' ? "bg-cad-accent/20 text-cad-accent" : "bg-blue-500/10 text-blue-400"
                                    )}>
                                        {email.charAt(0).toUpperCase()}
                                    </div>
                                    <div>
                                        <div className="text-[13px] font-bold text-cad-text-primary">{email}</div>
                                        <div className="mt-0.5 flex items-center gap-2">
                                            <span className={cn(
                                                "rounded-full border px-2 py-0.5 text-[9px] font-black uppercase",
                                                role === 'Admin' ? "border-cad-accent bg-cad-accent text-black" : "border-blue-500/20 bg-blue-500/10 text-blue-400"
                                            )}>
                                                {role}
                                            </span>
                                        </div>
                                    </div>
                                </div>
                                <button
                                    onClick={() => handleRemoveAdmin(email)}
                                    className="cad-icon-button opacity-0 group-hover:opacity-100"
                                >
                                    <Trash2 size={16} className="text-red-400" />
                                </button>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="space-y-4">
                        {logs.map((log) => (
                            <div key={log.id} className="flex gap-4 rounded-md border border-cad-border bg-cad-elevated/20 p-4 transition-colors hover:bg-cad-elevated/40">
                                <div className="shrink-0 rounded-md bg-white/5 p-2">
                                    <History size={14} className="text-cad-text-muted" />
                                </div>
                                <div
                                    className="flex-1 cursor-pointer overflow-hidden"
                                    onClick={() => {
                                        const details = document.getElementById(`log-details-${log.id}`);
                                        if (details) details.classList.toggle('hidden');
                                    }}
                                >
                                    <div className="mb-1 flex items-baseline justify-between gap-4">
                                        <div className="flex items-center gap-2">
                                            <span className="truncate text-[10px] font-black uppercase tracking-wider text-cad-accent">{log.action_type || log.event_type}</span>
                                            <span className="truncate text-[9px] font-bold text-cad-text-muted">@{log.table_name}</span>
                                        </div>
                                        <span className="shrink-0 font-mono text-[9px] text-cad-text-muted">{new Date(log.timestamp || log.created_at).toLocaleString()}</span>
                                    </div>
                                    <div className="mb-1 truncate text-[11px] font-medium text-cad-text-primary">Record ID: {log.record_id || log.entity_id}</div>
                                    <div className="flex items-center justify-between gap-2">
                                        <div className="flex items-center gap-2">
                                            <div className="h-1.5 w-1.5 rounded-full bg-cad-accent" />
                                            <span className="truncate text-[10px] font-bold text-cad-text-muted">User: {log.user_email || 'System'}</span>
                                        </div>
                                        {(log.old_values_json || log.new_values_json) && (
                                            <span className="text-[8px] font-black uppercase text-cad-accent/50 animate-pulse">Click to see Delta</span>
                                        )}
                                    </div>

                                    <div id={`log-details-${log.id}`} className="hidden mt-4 space-y-3 rounded-md border border-cad-border bg-black/40 p-3 animate-in fade-in zoom-in duration-200">
                                        {log.old_values_json && (
                                            <div>
                                                <div className="mb-1 text-[9px] font-black uppercase leading-none text-red-400/50">[-] Old Values</div>
                                                <pre className="whitespace-pre-wrap break-all rounded-md border border-red-500/10 bg-red-500/5 p-2 font-mono text-[10px] text-red-200/40">
                                                    {JSON.stringify(JSON.parse(log.old_values_json), null, 2)}
                                                </pre>
                                            </div>
                                        )}
                                        {log.new_values_json && (
                                            <div>
                                                <div className="mb-1 text-[9px] font-black uppercase leading-none text-green-400/50">[+] New Values</div>
                                                <pre className="whitespace-pre-wrap break-all rounded-md border border-green-500/10 bg-green-500/5 p-2 font-mono text-[10px] text-green-200/40">
                                                    {JSON.stringify(JSON.parse(log.new_values_json), null, 2)}
                                                </pre>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            <div className="border-t border-cad-border bg-black/20 p-6">
                <div className="flex items-center gap-2 rounded-md border border-yellow-500/10 bg-yellow-500/5 p-3">
                    <AlertTriangle size={14} className="shrink-0 text-yellow-500" />
                    <p className="text-[9px] font-bold leading-relaxed text-yellow-200/60 uppercase">
                        Caution: Permissions grant recursive access to linked assets.
                    </p>
                </div>
            </div>
        </div>
    );
};

import { useState, useEffect, useRef, memo } from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

export const GEOM_TYPES_OPTIONS = [
    'Điểm', 'Nút giao', 'CCTV', 'PTZ', 'SPEED', 'LPR',
    'Tủ thiết bị', 'Cột/Trụ', 'Cầu/Hầm'
];

export const EditableCell = memo(({
    value: initialValue,
    row,
    column,
    onUpdate,
    className
}: {
    value: any,
    row: any,
    column: any,
    onUpdate: (id: string, key: string, value: any) => void,
    className?: string
}) => {
    const [value, setValue] = useState(initialValue);
    const [isEditing, setIsEditing] = useState(false);
    const cancelEditRef = useRef(false);

    useEffect(() => {
        setValue(initialValue);
    }, [initialValue]);

    const onBlur = () => {
        setIsEditing(false);
        if (cancelEditRef.current) {
            cancelEditRef.current = false;
            setValue(initialValue);
            return;
        }
        if (value !== initialValue) {
            onUpdate(row.original.id, column.id, value);
        }
    };

    if (isEditing) {
        return (
            <input
                value={value as string || ''}
                onChange={e => setValue(e.target.value)}
                onBlur={onBlur}
                onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                        e.preventDefault();
                        e.currentTarget.blur();
                    }
                    if (e.key === 'Escape') {
                        e.preventDefault();
                        cancelEditRef.current = true;
                        setValue(initialValue);
                        e.currentTarget.blur();
                    }
                }}
                // eslint-disable-next-line jsx-a11y/no-autofocus
                autoFocus
                className="w-full bg-cad-elevated border-cad-accent border rounded px-1 py-0.5 outline-none font-medium text-cad-text-primary"
            />
        );
    }

    return (
        <div
            data-editable-cell
            className={cn(
                'cursor-text hover:bg-cad-accent/10 rounded px-1 -mx-1 min-h-[1.5rem] flex items-center transition-colors',
                className
            )}
            onClick={() => setIsEditing(true)}
            onDoubleClick={() => setIsEditing(true)}
            title="Click để sửa"
        >
            <span className="truncate">{value || <span className="text-cad-text-muted italic opacity-30">N/A</span>}</span>
        </div>
    );
});

export const DropdownCell = memo(({
    value: initialValue,
    options,
    row,
    column,
    onUpdate
}: {
    value: string,
    options: string[],
    row: any,
    column: any,
    onUpdate: (id: string, key: string, value: string) => void
}) => {
    const [value, setValue] = useState(initialValue);

    useEffect(() => {
        setValue(initialValue);
    }, [initialValue]);

    return (
        <select
            value={value}
            onChange={e => {
                const newValue = e.target.value;
                setValue(newValue);
                onUpdate(row.original.id, column.id, newValue);
            }}
            className="w-full bg-transparent border-none outline-none cursor-pointer text-cad-text-primary font-medium focus:ring-1 focus:ring-cad-accent rounded"
        >
            {options.map(opt => (
                <option key={opt} value={opt} className="bg-cad-bg text-cad-text-primary">
                    {opt}
                </option>
            ))}
        </select>
    );
});

export const checklistFilter = (row: any, columnId: string, filterValue: any) => {
    if (filterValue === undefined || filterValue === null) return true;
    if (Array.isArray(filterValue) && filterValue.length === 0) return false;

    const value = row.getValue(columnId);
    const stringValue = String(value || '(Blanks)');

    if (Array.isArray(filterValue)) {
        return filterValue.includes(stringValue);
    }
    return stringValue.toLowerCase().includes(String(filterValue).toLowerCase());
};

/**
 * Enhanced Analysis Dialog
 * Combines data grid, BOM summary, filtering, and technical specs
 */

import { useCallback, useMemo, useState, type ChangeEvent } from 'react';
import { Trash2, Eraser, Filter, Package, ListFilter } from 'lucide-react';
import { type ColumnDef, type SortingFn } from '@tanstack/react-table';
import { AnalysisTable } from '@DESIGN/components/ui/AnalysisTable';
import { BOMSummaryPanel } from '@DESIGN/components/ui/BOMSummaryPanel';
import { DeleteConfirmationModal } from '@DESIGN/components/ui/DeleteConfirmationModal';
import { useDesignSync, type DesignEventType } from '@IMPLEMENT/stores/useDesignSync';
import { EditableCell, DropdownCell, GEOM_TYPES_OPTIONS } from '@IMPLEMENT/features/analysis/AnalysisCells';
import {
  ANALYSIS_CORE_COLUMN_ORDER,
  ANALYSIS_EXPORT_COLUMN_ORDER,
  buildAnalysisExportRows,
  getAnalysisUserColumnKeys,
  getAnalysisSchemaColumnKeys,
  isAllowedAnalysisDynamicColumnKey,
  isAnalysisScalarValue,
  normalizeAnalysisColumnKey,
} from '@IMPLEMENT/features/analysis/analysisColumns';
import {
  buildAnalysisHierarchyRows,
} from '@IMPLEMENT/features/analysis/analysisHierarchy';
import { getAnalysisTemplateGroups, normalizeProjectSettings } from '@TOOL/utils/objectDataTemplates';
import { compareAnalysisHierarchyRows } from '@IMPLEMENT/features/analysis/analysisHierarchy';
import { cn } from '@TOOL/utils/cn';
import { getLineCoordinates, getPointCoordinates, getPolygonCoordinates } from '@TOOL/utils/featureUtils';

interface AnalysisDialogProps {
  onClose: () => void;
}

interface FlatFeature {
  id: string;
  stt: string;
  name: string;
  junction_scope: string;
  group: string;
  layer: string;
  region: string;
  geom_type: string;
  coordinates: string;
  display_order?: string;
  description?: string;
  __analysis_depth: number;
  __analysis_is_intersection: boolean;
  __analysis_parent_id: string | null;
  __analysis_root_id: string;
  __analysis_root_values: Record<string, unknown>;
  __analysis_sort_key: string;
  [key: string]: any;
}

type ViewMode = 'grid' | 'bom';

const CORE_COLUMN_TITLES: Record<string, string> = {
  id: 'ID',
  index_stt: 'STT',
  display_order: 'MÃ HIỆU',
  name: 'TÊN ĐỐI TƯỢNG',
  type: 'LOẠI',
  group: 'NHÓM',
  region: 'VÙNG',
  layer: 'LỚP CHÍNH',
  sub_layer: 'LỚP PHỤ',
  owner: 'ĐƠN VỊ QUẢN LÝ',
  geom_type: 'GEO TYPE',
  technical_geom: 'KỸ THUẬT',
  latitude: 'VĨ ĐỘ',
  longitude: 'KINH ĐỘ',
  status: 'TRẠNG THÁI',
  note: 'GHI CHÚ',
  description: 'MÔ TẢ',
  is_visible: 'HIỂN THỊ',
  length: 'CHIỀU DÀI',
  area: 'DIỆN TÍCH',
  coordinates_summary: 'TỌA ĐỘ',
};

const ANALYSIS_COLUMN_TITLES: Record<string, string> = {
  ...CORE_COLUMN_TITLES,
  junction_scope: 'NÚT GIAO',
};

const NON_EDITABLE_FIELDS = new Set([
  'id',
  'index_stt',
  'group',
  'region',
  'layer',
  'technical_geom',
  'coordinates_summary',
  'length',
  'area',
]);

const ANALYSIS_NON_EDITABLE_FIELDS = new Set([
  ...NON_EDITABLE_FIELDS,
  'junction_scope',
]);

const BATCH_NOTE_OPTIONS = ['Đã kiểm tra', 'Cần sửa', 'OK'];
const BOOLEAN_OPTIONS = ['Có', 'Không'];

const toColumnLabel = (key: string) => {
  if (
    key.startsWith('source_')
    || key === 'parent_intersection_name'
    || key === 'parent_intersection_display_order'
  ) {
    return key;
  }
  if (ANALYSIS_COLUMN_TITLES[key]) return ANALYSIS_COLUMN_TITLES[key];
  return key.replace(/_/g, ' ').replace(/\s+/g, ' ').trim().toUpperCase();
};

const getColumnWidth = (key: string) => {
  if (['name', 'description', 'coordinates_summary'].includes(key)) return 220;
  if (['note', 'status', 'type', 'group', 'region', 'layer', 'geom_type', 'technical_geom'].includes(key)) return 140;
  if (['latitude', 'longitude', 'length', 'area'].includes(key)) return 120;
  if (['is_visible', 'id'].includes(key)) return 110;
  return 160;
};

const buildDisplayValue = (value: unknown) => {
  if (typeof value === 'boolean') {
    return value ? 'Có' : 'Không';
  }
  return value;
};

const hasKeyInRows = (rows: FlatFeature[], key: string) => rows.some((row) => key in row);

const hierarchySortingFn: SortingFn<FlatFeature> = (rowA, rowB, columnId) => (
  compareAnalysisHierarchyRows(rowA.original, rowB.original, columnId)
);

const buildAnalysisFieldColumn = (
  key: string,
  handleUpdate: (id: string, field: string, value: any) => Promise<void>,
  options?: string[],
): ColumnDef<FlatFeature> => {
  if (key === 'name') {
    return {
      header: toColumnLabel(key),
      accessorKey: key,
      size: 220,
      sortingFn: hierarchySortingFn,
      cell: (info) => (
        <div
          className="flex items-center gap-2"
          style={{ paddingLeft: `${(info.row.original.__analysis_depth || 0) * 16}px` }}
        >
          {info.row.original.__analysis_is_intersection && (
            <span className="shrink-0 rounded border border-cad-accent/40 bg-cad-accent/10 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-cad-accent">
              Nút giao
            </span>
          )}
          {!!info.row.original.__analysis_parent_id && (
            <span className="shrink-0 rounded border border-cad-border bg-cad-surface/80 px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-cad-text-muted">
              Thuộc nút giao
            </span>
          )}
          <EditableCell
            value={info.getValue()}
            row={info.row}
            column={info.column}
            onUpdate={handleUpdate}
            className="font-bold text-cad-accent"
          />
        </div>
      ),
    };
  }

  if (key === 'geom_type') {
    return {
      header: toColumnLabel(key),
      accessorKey: key,
      size: getColumnWidth(key),
      sortingFn: hierarchySortingFn,
      meta: { options: GEOM_TYPES_OPTIONS },
      cell: (info) => (
        <DropdownCell
          value={String((info.getValue() as any) ?? '')}
          options={GEOM_TYPES_OPTIONS}
          row={info.row}
          column={info.column}
          onUpdate={handleUpdate}
        />
      ),
    };
  }

  if (options && options.length > 0) {
    return {
      header: toColumnLabel(key),
      accessorKey: key,
      size: getColumnWidth(key),
      sortingFn: hierarchySortingFn,
      meta: { options },
      cell: (info) => (
        <DropdownCell
          value={String((info.getValue() as any) ?? '')}
          options={options}
          row={info.row}
          column={info.column}
          onUpdate={handleUpdate}
        />
      ),
    };
  }

  if (ANALYSIS_NON_EDITABLE_FIELDS.has(key)) {
    return {
      header: toColumnLabel(key),
      accessorKey: key,
      size: getColumnWidth(key),
      sortingFn: hierarchySortingFn,
    };
  }

  return {
    header: toColumnLabel(key),
    accessorKey: key,
    size: getColumnWidth(key),
    sortingFn: hierarchySortingFn,
    cell: (info) => (
      <EditableCell
        value={buildDisplayValue(info.getValue())}
        row={info.row}
        column={info.column}
        onUpdate={handleUpdate}
      />
    ),
  };
};

const getGeomIconValue = (value: unknown) => {
  const lowerVal = String((value as any) ?? '').toLowerCase();
  if (['cctv', 'ptz', 'speed', 'lpr'].includes(lowerVal)) return lowerVal;
  if (lowerVal.includes('nut giao')) return 'intersection';
  return null;
};

export const AnalysisDialog = ({ onClose }: AnalysisDialogProps) => {
  const { state, selectFeature, zoomTo, dispatchEvent, deleteFeature, deduplicate } = useDesignSync();
  const projectId = useDesignSync.getState().projectId;
  const [deleteModalConfig, setDeleteModalConfig] = useState<{
    isOpen: boolean;
    type: 'feature' | 'column' | 'import' | null;
    id: string | null;
    itemName: string;
    message: string;
  }>({ isOpen: false, type: null, id: null, itemName: '', message: '' });
  const [viewMode, setViewMode] = useState<ViewMode>('grid');
  const [filterGroup, setFilterGroup] = useState<string>('ALL');
  const [filterLayer, setFilterLayer] = useState<string>('ALL');
  const [filterRegion, setFilterRegion] = useState<string>('ALL');
  const [filterGeomType, setFilterGeomType] = useState<string>('ALL');
  const [manualColumnKeys, setManualColumnKeys] = useState<string[]>([]);

  const allData = useMemo(() => {
    if (!state) return [];
    return buildAnalysisHierarchyRows(state) as FlatFeature[];
  }, [state]);

  const filterOptions = useMemo(() => {
    const groups = new Set<string>();
    const layers = new Set<string>();
    const regions = new Set<string>();
    const geomTypes = new Set<string>();

    allData.forEach((feature) => {
      if (feature.group) groups.add(feature.group);
      if (feature.layer) layers.add(feature.layer);
      if (feature.region) regions.add(feature.region);
      if (feature.geom_type) geomTypes.add(feature.geom_type);
    });

    return {
      groups: Array.from(groups).sort(),
      layers: Array.from(layers).sort(),
      regions: Array.from(regions).sort(),
      geomTypes: Array.from(geomTypes).sort(),
    };
  }, [allData]);

  const data = useMemo(() => {
    return allData.filter((feature) => {
      if (filterGroup !== 'ALL' && feature.group !== filterGroup) return false;
      if (filterLayer !== 'ALL' && feature.layer !== filterLayer) return false;
      if (filterRegion !== 'ALL' && feature.region !== filterRegion) return false;
      if (filterGeomType !== 'ALL' && feature.geom_type !== filterGeomType) return false;
      return true;
    });
  }, [allData, filterGroup, filterLayer, filterRegion, filterGeomType]);

  const projectSettings = useMemo(() => normalizeProjectSettings(state?.settings), [state?.settings]);
  const schemaColumnKeys = useMemo(() => getAnalysisSchemaColumnKeys(projectSettings), [projectSettings]);
  const userColumnKeys = useMemo(() => (
    getAnalysisUserColumnKeys(Object.values(state?.features || {}), manualColumnKeys)
  ), [manualColumnKeys, state]);

  const analysisColumnKeys = useMemo(() => {
    const coreKeys = ANALYSIS_CORE_COLUMN_ORDER.filter((key) => hasKeyInRows(allData, key));
    const schemaKeys = schemaColumnKeys.filter((key) => hasKeyInRows(allData, key));
    const dynamicKeys = userColumnKeys.filter((key) => !coreKeys.includes(key as (typeof coreKeys)[number]));
    return [...coreKeys, ...schemaKeys, ...dynamicKeys];
  }, [allData, schemaColumnKeys, userColumnKeys]);

  const exportColumnKeys = useMemo(() => (
    [
      ...analysisColumnKeys,
      ...ANALYSIS_EXPORT_COLUMN_ORDER.filter((key) => !analysisColumnKeys.includes(key)),
    ].filter((key) => hasKeyInRows(data, key))
  ), [analysisColumnKeys, data]);

  const exportRows = useMemo(() => (
    buildAnalysisExportRows(data, exportColumnKeys, toColumnLabel)
  ), [data, exportColumnKeys]);

  const handleGoToFeatureLocation = useCallback((row: FlatFeature) => {
    const feature = state?.features[row.id];
    if (!feature) return;

    selectFeature(feature.id);

    try {
      const point = getPointCoordinates(feature);
      const line = getLineCoordinates(feature);
      const polygon = getPolygonCoordinates(feature)?.[0];
      const center = point || polygon?.[0] || line?.[0];

      if (center) {
        zoomTo(feature.id, 'location', [center[1], center[0]]);
        return;
      }
    } catch (error) {
      console.error('Go to feature location error:', error);
    }

    zoomTo(feature.id, 'feature');
  }, [selectFeature, state, zoomTo]);

  const handleUpdate = useCallback(async (id: string, key: string, value: any) => {
    const feature = state?.features[id];
    if (!feature) return;

    const meta = typeof feature.metadata === 'string' ? JSON.parse(feature.metadata || '{}') : { ...(feature.metadata as any) };
    const props = typeof feature.properties === 'object' ? { ...(feature.properties as any) } : {};

    if (key === 'name') {
      await dispatchEvent({ type: 'FeatureUpdated', payload: { id, name: value } });
      return;
    }

    if (key === 'is_visible') {
      meta.is_visible = Boolean(value);
      await dispatchEvent({ type: 'FeatureUpdated', payload: { id, metadata: JSON.stringify(meta) } });
      return;
    }

    if (['display_order', 'description', 'geom_type', 'status', 'note'].includes(key) || key.toLowerCase().includes('stt')) {
      const targetKey = key.toLowerCase().includes('stt') || key === 'display_order'
        ? 'display_order'
        : (key === 'geom_type' ? 'type' : key);
      meta[targetKey] = value;
      if (key === 'note') meta.notes = value;
      if (key === 'geom_type') {
        const nextIcon = getGeomIconValue(value);
        if (nextIcon) meta.icon = nextIcon;
      }
      await dispatchEvent({ type: 'FeatureUpdated', payload: { id, metadata: JSON.stringify(meta) } });
      return;
    }

    if (key === 'latitude' || key === 'longitude') {
      try {
        const nextCoord = parseFloat(value);
        if (!Number.isNaN(nextCoord)) {
          const point = getPointCoordinates(feature);
          const line = getLineCoordinates(feature);
          const polygon = getPolygonCoordinates(feature)?.[0];

          if (point) {
            const coords = [...point] as [number, number];
            if (key === 'latitude') coords[1] = nextCoord;
            else coords[0] = nextCoord;
            await dispatchEvent({ type: 'FeatureUpdated', payload: { id, coordinates: coords } });
          } else if (polygon?.[0]) {
            const coords = polygon.map((coord) => [...coord] as [number, number]);
            if (key === 'latitude') coords[0][1] = nextCoord;
            else coords[0][0] = nextCoord;
            await dispatchEvent({ type: 'FeatureUpdated', payload: { id, coordinates: [coords] } });
          } else if (line?.[0]) {
            const coords = line.map((coord) => [...coord] as [number, number]);
            if (key === 'latitude') coords[0][1] = nextCoord;
            else coords[0][0] = nextCoord;
            await dispatchEvent({ type: 'FeatureUpdated', payload: { id, coordinates: coords } });
          }
        }
      } catch (error) {
        console.error('Coord update error:', error);
      }
      return;
    }

    props[key] = value;
    await dispatchEvent({ type: 'FeatureUpdated', payload: { id, properties: props } });
  }, [state, dispatchEvent]);

  const onBatchUpdate = useCallback(async (selectedIds: string[], field: string, value: any) => {
    if (!state) return;

    const events: DesignEventType[] = [];
    selectedIds.forEach((id) => {
      const feature = state.features[id];
      if (!feature) return;

      const meta = typeof feature.metadata === 'string' ? JSON.parse(feature.metadata || '{}') : { ...(feature.metadata as any) };
      const props = typeof feature.properties === 'object' ? { ...(feature.properties as any) } : {};

      if (field === 'is_visible') {
        meta.is_visible = value === true || value === 'Co';
        events.push({ type: 'FeatureUpdated', payload: { id, metadata: JSON.stringify(meta) } });
        return;
      }

      if (['geom_type', 'type', 'category', 'technical', 'display_order', 'description', 'status', 'note'].includes(field)) {
        const targetKey = field === 'geom_type' ? 'type' : field;
        meta[targetKey] = value;
        if (field === 'note') meta.notes = value;
        if (field === 'geom_type') {
          const nextIcon = getGeomIconValue(value);
          if (nextIcon) meta.icon = nextIcon;
        }
        events.push({ type: 'FeatureUpdated', payload: { id, metadata: JSON.stringify(meta) } });
        return;
      }

      if (field === 'layer' || field === 'group') {
        events.push({ type: 'FeatureUpdated', payload: { id, [field]: value } });
        return;
      }

      props[field] = value;
      events.push({ type: 'FeatureUpdated', payload: { id, properties: props } });
    });

    if (events.length > 0) {
      const { dispatchEvents } = useDesignSync.getState();
      await dispatchEvents(events);
    }
  }, [state]);

  const handleAddColumn = useCallback(async () => {
    if (!state || data.length === 0) {
      alert('Không có đối tượng để thêm cột.');
      return;
    }

    const label = window.prompt('Nhập tên cột mới');
    if (!label) return;

    const columnKey = normalizeAnalysisColumnKey(label);
    if (!columnKey || !isAllowedAnalysisDynamicColumnKey(columnKey)) {
      alert('Tên cột không hợp lệ hoặc trùng với cột hệ thống.');
      return;
    }

    if (analysisColumnKeys.includes(columnKey)) {
      alert('Cột này đã tồn tại.');
      return;
    }

    const { dispatchEvents } = useDesignSync.getState();
    const events: DesignEventType[] = data
      .map((row) => state.features[row.id])
      .filter((feature): feature is NonNullable<typeof feature> => Boolean(feature))
      .map((feature) => ({
        type: 'FeatureUpdated',
        payload: {
          id: feature.id,
          properties: {
            ...(typeof feature.properties === 'object' ? feature.properties : {}),
            [columnKey]: '',
          },
        },
      }));

    if (events.length > 0) {
      await dispatchEvents(events);
    }

    setManualColumnKeys((prev) => (
      prev.includes(columnKey) ? prev : [...prev, columnKey]
    ));
  }, [analysisColumnKeys, data, state]);

  const handleExport = async () => {
    try {
      const { analysisService } = await import('@IMPLEMENT/services/analysisService');
      await analysisService.exportToExcel(exportRows, projectId?.toString() || 'default');
    } catch (error: any) {
      alert(`Export error: ${error.message}`);
    }
  };

  const handleImport = async (event: ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !state) return;

    try {
      const { analysisService } = await import('@IMPLEMENT/services/analysisService');
      const events = await analysisService.importFromExcel(state);
      if (events.length > 0) {
        setDeleteModalConfig({
          isOpen: true,
          type: 'import',
          id: JSON.stringify(events),
          itemName: `${events.length} thay đổi`,
          message: `Tìm thấy ${events.length} thay đổi. Bạn có muốn cập nhật?`,
        });
      } else {
        alert('Không tìm thấy thay đổi.');
      }
    } catch (error: any) {
      alert(`Import error: ${error.message}`);
    }
  };

  const columns = useMemo<ColumnDef<FlatFeature>[]>(() => {
    const coreColumns: ColumnDef<FlatFeature>[] = ANALYSIS_CORE_COLUMN_ORDER
      .filter((key) => hasKeyInRows(allData, key))
      .map((key) => buildAnalysisFieldColumn(
        key,
        handleUpdate,
        key === 'geom_type' ? GEOM_TYPES_OPTIONS : key === 'note' ? BATCH_NOTE_OPTIONS : undefined
      ));

    const schemaColumns: ColumnDef<FlatFeature>[] = getAnalysisTemplateGroups(projectSettings)
      .flatMap((typeGroup) => {
        const groupColumns = typeGroup.groups
          .map((group) => {
            const fields = typeGroup.fields
              .filter((field) => field.groupId === group.id && hasKeyInRows(allData, field.key))
              .sort((left, right) => left.order - right.order);

            if (fields.length === 0) return null;

            return {
              header: group.label,
              columns: fields.map((field) => buildAnalysisFieldColumn(
                field.key,
                handleUpdate,
                field.type === 'select' ? field.options : undefined
              )),
            } as { header: string; columns: ColumnDef<FlatFeature>[] };
          })
          .filter(Boolean) as Array<{ header: string; columns: ColumnDef<FlatFeature>[] }>;

        if (groupColumns.length === 0) return [];

        return [{
          header: typeGroup.label,
          columns: groupColumns,
        } as ColumnDef<FlatFeature>];
      });

    const extraColumns: ColumnDef<FlatFeature>[] = userColumnKeys.map((key) => ({
      header: toColumnLabel(key),
      accessorKey: key,
      size: getColumnWidth(key),
      sortingFn: hierarchySortingFn,
      cell: (info) => {
        const value = info.getValue();
        if (!isAnalysisScalarValue(value)) {
          return <span className="text-cad-text-muted">N/A</span>;
        }

        if (ANALYSIS_NON_EDITABLE_FIELDS.has(key)) {
          return <span>{String((buildDisplayValue(value) as any) ?? '')}</span>;
        }

        return (
          <EditableCell
            value={buildDisplayValue(value)}
            row={info.row}
            column={info.column}
            onUpdate={handleUpdate}
          />
        );
      },
    }));

    return [
      {
        id: 'select',
        size: 40,
        header: ({ table }) => (
          <div className="relative flex items-center justify-center">
            <input
              type="checkbox"
              checked={table.getIsAllPageRowsSelected()}
              onChange={table.getToggleAllPageRowsSelectedHandler()}
              className="peer appearance-none w-4 h-4 rounded border border-cad-border hover:border-cad-accent checked:bg-cad-accent checked:border-cad-accent outline-none cursor-pointer transition-all"
            />
            <svg
              className="absolute w-2.5 h-2.5 pointer-events-none stroke-black stroke-[3.5] fill-none opacity-0 peer-checked:opacity-100 transition-opacity"
              viewBox="0 0 24 24"
            >
              <polyline points="20 6 9 17 4 12" />
            </svg>
          </div>
        ),
        cell: ({ row }) => (
          <div className="relative flex items-center justify-center">
            <input
              type="checkbox"
              checked={row.getIsSelected()}
              onChange={row.getToggleSelectedHandler()}
              className="peer appearance-none w-4 h-4 rounded border border-cad-border hover:border-cad-accent checked:bg-cad-accent checked:border-cad-accent outline-none cursor-pointer transition-all"
            />
            <svg
              className="absolute w-2.5 h-2.5 pointer-events-none stroke-black stroke-[3.5] fill-none opacity-0 peer-checked:opacity-100 transition-opacity"
              viewBox="0 0 24 24"
            >
              <polyline points="20 6 9 17 4 12" />
            </svg>
          </div>
        ),
      },
      {
        header: 'Core',
        columns: coreColumns,
      },
      ...schemaColumns,
      {
        header: 'Custom',
        columns: extraColumns,
      },
      {
        id: 'Action',
        size: 80,
        header: 'XOA',
        cell: ({ row }) => (
          <button onClick={() => deleteFeature(row.original.id)} className="p-1 hover:text-rose-500 transition-colors">
            <Trash2 size={14} />
          </button>
        ),
      },
    ];
  }, [allData, deleteFeature, handleUpdate, projectSettings, userColumnKeys]);

  const activeFiltersCount = [filterGroup, filterLayer, filterRegion, filterGeomType].filter((value) => value !== 'ALL').length;

  return (
    <>
      <div
        className="absolute inset-0 flex flex-col min-h-0 min-w-0 overflow-hidden bg-cad-bg"
      >
        <div className="flex items-center justify-between px-6 py-2.5 border-b border-cad-border/50 bg-cad-elevated/70 backdrop-blur-md select-none gap-4">
          <div className="flex p-0.5 bg-cad-bg/60 border border-cad-border/60 rounded-lg h-9 items-center">
            <button
              onClick={() => setViewMode('grid')}
              className={cn(
                'flex items-center gap-2 px-4 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all cursor-pointer',
                viewMode === 'grid'
                  ? 'bg-cad-surface text-cad-accent border border-cad-border/40 shadow-sm font-black'
                  : 'text-cad-text-secondary hover:text-cad-text-primary hover:bg-cad-surface/30 border border-transparent'
              )}
            >
              <ListFilter size={13} />
              Bảng dữ liệu
            </button>
            <button
              onClick={() => setViewMode('bom')}
              className={cn(
                'flex items-center gap-2 px-4 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all cursor-pointer',
                viewMode === 'bom'
                  ? 'bg-cad-surface text-cad-accent border border-cad-border/40 shadow-sm font-black'
                  : 'text-cad-text-secondary hover:text-cad-text-primary hover:bg-cad-surface/30 border border-transparent'
              )}
            >
              <Package size={13} />
              BOM Summary
            </button>
          </div>

          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 px-3 py-1.5 bg-cad-surface/80 border border-cad-border/40 rounded-lg shadow-inner">
              <Filter size={12} className="text-cad-text-muted" />
              <span className="text-[10px] font-bold text-cad-text-secondary uppercase mr-1">Lọc:</span>

              <select
                value={filterGroup}
                onChange={(e) => setFilterGroup(e.target.value)}
                className="bg-cad-bg/90 border border-cad-border/60 hover:border-cad-accent/50 focus:border-cad-accent text-[10px] font-semibold text-cad-text-primary rounded px-2.5 py-1 outline-none transition-all cursor-pointer max-w-[125px] truncate appearance-none pr-6 bg-[image:url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M7%209l3%203%203-3%22%20stroke%3D%22%239CA3AF%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E')] bg-[position:right_4px_center] bg-[size:16px_16px] bg-no-repeat"
              >
                <option value="ALL">Tất cả nhóm</option>
                {filterOptions.groups.map((group) => (
                  <option key={group} value={group}>{group}</option>
                ))}
              </select>

              <select
                value={filterLayer}
                onChange={(e) => setFilterLayer(e.target.value)}
                className="bg-cad-bg/90 border border-cad-border/60 hover:border-cad-accent/50 focus:border-cad-accent text-[10px] font-semibold text-cad-text-primary rounded px-2.5 py-1 outline-none transition-all cursor-pointer max-w-[125px] truncate appearance-none pr-6 bg-[image:url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M7%209l3%203%203-3%22%20stroke%3D%22%239CA3AF%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E')] bg-[position:right_4px_center] bg-[size:16px_16px] bg-no-repeat"
              >
                <option value="ALL">Tất cả lớp</option>
                {filterOptions.layers.map((layer) => (
                  <option key={layer} value={layer}>{layer}</option>
                ))}
              </select>

              <select
                value={filterRegion}
                onChange={(e) => setFilterRegion(e.target.value)}
                className="bg-cad-bg/90 border border-cad-border/60 hover:border-cad-accent/50 focus:border-cad-accent text-[10px] font-semibold text-cad-text-primary rounded px-2.5 py-1 outline-none transition-all cursor-pointer max-w-[125px] truncate appearance-none pr-6 bg-[image:url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M7%209l3%203%203-3%22%20stroke%3D%22%239CA3AF%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E')] bg-[position:right_4px_center] bg-[size:16px_16px] bg-no-repeat"
              >
                <option value="ALL">Tất cả vùng</option>
                {filterOptions.regions.map((region) => (
                  <option key={region} value={region}>{region}</option>
                ))}
              </select>

              <select
                value={filterGeomType}
                onChange={(e) => setFilterGeomType(e.target.value)}
                className="bg-cad-bg/90 border border-cad-border/60 hover:border-cad-accent/50 focus:border-cad-accent text-[10px] font-semibold text-cad-text-primary rounded px-2.5 py-1 outline-none transition-all cursor-pointer max-w-[125px] truncate appearance-none pr-6 bg-[image:url('data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2020%2020%22%20fill%3D%22none%22%3E%3Cpath%20d%3D%22M7%209l3%203%203-3%22%20stroke%3D%22%239CA3AF%22%20stroke-width%3D%221.5%22%20stroke-linecap%3D%22round%22%20stroke-linejoin%3D%22round%22%2F%3E%3C%2Fsvg%3E')] bg-[position:right_4px_center] bg-[size:16px_16px] bg-no-repeat"
              >
                <option value="ALL">Tất cả geo</option>
                {filterOptions.geomTypes.map((geomType) => (
                  <option key={geomType} value={geomType}>{geomType}</option>
                ))}
              </select>

              {activeFiltersCount > 0 && (
                <button
                  onClick={() => {
                    setFilterGroup('ALL');
                    setFilterLayer('ALL');
                    setFilterRegion('ALL');
                    setFilterGeomType('ALL');
                  }}
                  className="text-[10px] font-bold text-rose-400 hover:text-rose-300 transition-colors cursor-pointer px-1.5 py-0.5 hover:bg-rose-500/10 rounded"
                >
                  Xóa lọc ({activeFiltersCount})
                </button>
              )}
            </div>
          </div>
        </div>

        <div className="flex-1 min-h-0 min-w-0 overflow-hidden">
          {viewMode === 'grid' ? (
            <AnalysisTable
              data={data}
              columns={columns}
              projectId={projectId ?? undefined}
              title={`BẢNG TỔNG HỢP GIS (${data.length} ĐỐI TƯỢNG)`}
              isStandalone={true}
              showWindowControls={false}
              onClose={onClose}
              onUpdate={handleUpdate}
              onGoToRowLocation={handleGoToFeatureLocation}
              batchFields={[
                { label: 'Layer', value: 'layer' },
                { label: 'Group', value: 'group' },
                { label: 'Status', value: 'status', options: ['N/A', 'Đã kiểm tra', 'Cần sửa', 'OK'] },
                { label: 'Note', value: 'note', options: BATCH_NOTE_OPTIONS },
                { label: 'Geom Type', value: 'geom_type', options: GEOM_TYPES_OPTIONS },
                { label: 'Hiển thị', value: 'is_visible', options: BOOLEAN_OPTIONS },
              ]}
              onBatchUpdate={onBatchUpdate}
              onExport={handleExport}
              onAddColumn={handleAddColumn}
              onImport={() => {
                const input = document.createElement('input');
                input.type = 'file';
                input.accept = '.xlsx,.xls';
                (input as any).onchange = handleImport;
                input.click();
                return Promise.resolve();
              }}
              renderExtraActions={() => (
                <button
                  onClick={() => deduplicate()}
                  className="flex items-center gap-2 px-4 py-2 bg-amber-500/10 border border-amber-500/30 hover:border-amber-500/60 text-amber-500 hover:bg-amber-500 hover:text-black rounded-lg text-xs font-semibold uppercase tracking-wider transition-all duration-200 shadow-sm cursor-pointer"
                >
                  <Eraser size={14} /> Dọn trùng
                </button>
              )}
            />
          ) : (
            <BOMSummaryPanel />
          )}
        </div>
      </div>

      <DeleteConfirmationModal
        isOpen={deleteModalConfig.isOpen}
        onClose={() => setDeleteModalConfig((prev) => ({ ...prev, isOpen: false }))}
        onConfirm={async () => {
          if (deleteModalConfig.type === 'import' && deleteModalConfig.id) {
            const events = JSON.parse(deleteModalConfig.id);
            for (const event of events) await dispatchEvent(event);
          }
          setDeleteModalConfig((prev) => ({ ...prev, isOpen: false }));
        }}
        title="Xác nhận"
        itemName={deleteModalConfig.itemName}
        message={deleteModalConfig.message}
      />
    </>
  );
};

import React, { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { BarChart3, Minus, Square, X } from 'lucide-react';
import { AnalysisDialog } from '@IMPLEMENT/features/analysis/AnalysisDialog';
import { useDesignSync } from '@IMPLEMENT/stores/useDesignSync';
import { useSettingsStore } from '@IMPLEMENT/stores/useSettingsStore';
import { useAuthStore } from '@IMPLEMENT/stores/useAuthStore';
import { cn } from '@TOOL/utils/cn';

const AnalysisWindow: React.FC = () => {
    const { initialize, state, error: projectError } = useDesignSync();
    const { loadSettings } = useSettingsStore();
    const { user, initialized: authInitialized, isStandalone } = useAuthStore();
    const [isMaximized, setIsMaximized] = useState(false);
    const windowRootRef = useRef<HTMLDivElement | null>(null);

    const resetViewportScroll = () => {
        window.scrollTo(0, 0);
        document.documentElement.scrollTop = 0;
        document.documentElement.scrollLeft = 0;
        document.body.scrollTop = 0;
        document.body.scrollLeft = 0;
        document.scrollingElement?.scrollTo?.(0, 0);
        windowRootRef.current?.scrollTo?.(0, 0);
    };

    useLayoutEffect(() => {
        resetViewportScroll();
    }, []);

    useEffect(() => {
        let disposed = false;
        let cleanup: (() => void) | null = null;

        const initWindowControls = async () => {
            try {
                const { getCurrentWebviewWindow } = await import('@tauri-apps/api/webviewWindow');
                const appWindow = getCurrentWebviewWindow();
                const syncMaximized = async () => {
                    if (!disposed) {
                        setIsMaximized(await appWindow.isMaximized());
                    }
                };

                await syncMaximized();
                const unlisten = await appWindow.onResized(() => {
                    void syncMaximized();
                });
                cleanup = () => {
                    unlisten();
                };
            } catch (error) {
                console.warn('[AnalysisWindow] Failed to initialize window controls:', error);
            }
        };

        void initWindowControls();

        return () => {
            disposed = true;
            cleanup?.();
        };
    }, []);

    useEffect(() => {
        const params = new URLSearchParams(window.location.search);
        const urlProjectId = params.get('projectId');
        resetViewportScroll();
        console.log(`[AnalysisWindow] Detected urlProjectId from URL: ${urlProjectId}`);
        const currentProjectId = useDesignSync.getState().projectId;

        if (urlProjectId && currentProjectId !== urlProjectId) {
            console.log(`[AnalysisWindow] Calling initialize for project ${urlProjectId}...`);
            initialize(urlProjectId).catch(err => {
                console.error("[AnalysisWindow] Initialization error:", err);
            });
        } else if (urlProjectId) {
            console.log(`[AnalysisWindow] Project already initialized: ${urlProjectId}`);
        } else {
            console.warn("[AnalysisWindow] No projectId found in URL params.");
        }
        loadSettings();

        document.title = "Bảng phân tích dữ liệu - Analysis";
    }, []);

    useEffect(() => {
        if (!state) return;
        const frame = window.requestAnimationFrame(() => {
            resetViewportScroll();
        });
        return () => {
            window.cancelAnimationFrame(frame);
        };
    }, [state]);

    // 1. Wait for Auth
    if (!authInitialized && !isStandalone) {
        return (
            <div className="h-full w-full min-h-0 min-w-0 flex items-center justify-center bg-cad-bg text-cad-text-primary flex-col gap-4">
                <div className="w-10 h-10 border-2 border-cad-accent border-t-transparent rounded-full animate-spin"></div>
                <div className="text-[11px] font-mono text-cad-text-muted uppercase tracking-widest">
                    Đang xác thực hệ thống...
                </div>
            </div>
        );
    }

    // 2. Check User session
    // Since we added a protection buffer in useAuthStore, we can trust 'user' being null here 
    // means a definitive failure after the grace period.
    if (!user && !isStandalone) {
        console.error("[AnalysisWindow] Auth failed: No user soul found after window warmup.");
        return (
            <div className="h-full w-full min-h-0 min-w-0 flex items-center justify-center bg-cad-bg text-red-400 flex-col gap-4 p-8 text-center">
                <div className="text-xl font-bold italic">Phiên đăng nhập hết hạn</div>
                <div className="text-[10px] text-cad-text-muted uppercase">Vui lòng đăng nhập lại ở cửa sổ chính hoặc làm mới trang.</div>
                <button
                    onClick={() => window.location.reload()}
                    className="px-4 py-1 border border-red-500/30 hover:bg-red-500/10 text-[9px] uppercase tracking-tighter transition-colors"
                >
                    Thử lại (Reload)
                </button>
            </div>
        );
    }

    if (projectError) {
        return (
            <div className="h-full w-full min-h-0 min-w-0 flex items-center justify-center bg-cad-bg text-red-500 flex-col gap-4 p-8 text-center">
                <div className="text-xl font-bold">Lỗi khởi tạo</div>
                <div className="text-sm border border-red-500/30 bg-red-500/10 p-4 rounded max-w-lg overflow-auto">
                    {projectError}
                </div>
                <button
                    onClick={() => window.location.reload()}
                    className="mt-4 px-4 py-2 bg-cad-accent text-white rounded hover:opacity-90 transition-opacity"
                >
                    Thử lại
                </button>
            </div>
        );
    }

    if (!state) {
        return (
            <div className="h-full w-full min-h-0 min-w-0 flex items-center justify-center bg-cad-bg text-cad-text-primary flex-col gap-4">
                <div className="w-10 h-10 border-2 border-cad-accent border-t-transparent rounded-full animate-spin"></div>
                <div className="text-[11px] font-mono text-cad-text-muted uppercase tracking-widest">
                    Đang khởi tạo dữ liệu dự án...
                </div>
            </div>
        );
    }

    return (
        <div ref={windowRootRef} className="fixed inset-0 min-h-0 min-w-0 bg-cad-bg overflow-hidden flex flex-col">
            <div
                data-tauri-drag-region
                onMouseDown={(event) => {
                    if (event.currentTarget === event.target || (event.target as HTMLElement).hasAttribute('data-tauri-drag-region')) {
                        import('@tauri-apps/api/webviewWindow').then((m) => {
                            m.getCurrentWebviewWindow().startDragging();
                        });
                    }
                }}
                onDoubleClick={() => import('@tauri-apps/api/webviewWindow').then((m) => m.getCurrentWebviewWindow().toggleMaximize())}
                className="h-11 shrink-0 border-b border-cad-border bg-cad-elevated/95 backdrop-blur-md flex items-center justify-between pl-3 pr-0 select-none"
            >
                <div data-tauri-drag-region className="flex items-center gap-3 min-w-0">
                    <div data-tauri-drag-region className="w-7 h-7 rounded-md bg-cad-accent/10 text-cad-accent flex items-center justify-center">
                        <BarChart3 data-tauri-drag-region className="w-4 h-4" />
                    </div>
                    <div data-tauri-drag-region className="min-w-0">
                        <div data-tauri-drag-region className="text-[11px] font-black text-cad-text-primary uppercase tracking-wider truncate">
                            Analysis
                        </div>
                        <div data-tauri-drag-region className="text-[9px] font-mono text-cad-text-muted uppercase tracking-widest truncate">
                            Drag window here
                        </div>
                    </div>
                </div>

                <div className="flex items-center h-full">
                    <button
                        onClick={() => import('@tauri-apps/api/webviewWindow').then((m) => m.getCurrentWebviewWindow().minimize())}
                        className="w-12 h-full flex items-center justify-center text-cad-text-secondary hover:bg-cad-surface transition-colors"
                        aria-label="Minimize analysis window"
                    >
                        <Minus className="w-4 h-4" />
                    </button>
                    <button
                        onClick={() => import('@tauri-apps/api/webviewWindow').then((m) => m.getCurrentWebviewWindow().toggleMaximize())}
                        className="w-12 h-full flex items-center justify-center text-cad-text-secondary hover:bg-cad-surface transition-colors"
                        aria-label="Maximize analysis window"
                    >
                        <Square className={cn('w-3.5 h-3.5', isMaximized && 'rotate-180')} />
                    </button>
                    <button
                        onClick={() => import('@tauri-apps/api/webviewWindow').then((m) => m.getCurrentWebviewWindow().close())}
                        className="w-12 h-full flex items-center justify-center text-cad-text-secondary hover:bg-rose-500 hover:text-white transition-colors"
                        aria-label="Close analysis window"
                    >
                        <X className="w-4 h-4" />
                    </button>
                </div>
            </div>
            <div className="flex-1 min-h-0 min-w-0 overflow-hidden relative">
                <AnalysisDialog onClose={() => {
                    import('@tauri-apps/api/webviewWindow').then(m => {
                        m.getCurrentWebviewWindow().close();
                    });
                }} />
            </div>
        </div>
    );
};

export default AnalysisWindow;

import type { ProjectSettingsSchema } from '@TOOL/utils/objectDataTemplates';
import { getAnalysisTemplateColumnKeys } from '@TOOL/utils/objectDataTemplates';

export type AnalysisScalarValue = string | number | boolean;

type AnalysisFeatureLike = {
  properties?: Record<string, unknown> | null;
  metadata?: unknown;
};

export const ANALYSIS_CORE_COLUMN_ORDER = [
  'index_stt',
  'display_order',
  'name',
  'junction_scope',
  'geom_type',
  'group',
  'layer',
  'region',
  'status',
  'note',
] as const;

export const ANALYSIS_EXPORT_COLUMN_ORDER = [
  ...ANALYSIS_CORE_COLUMN_ORDER,
  'source_feature_id',
  'source_group_id',
  'source_group_type',
  'source_layer_id',
  'source_region_id',
  'source_parent_feature_id',
  'source_coordinates',
  'source_technical_geom',
  'source_icon',
  'source_type',
  'parent_intersection_name',
  'parent_intersection_display_order',
] as const;

const CORE_COLUMN_SET = new Set<string>(ANALYSIS_CORE_COLUMN_ORDER);

const BLOCKED_DYNAMIC_FIELDS = new Set([
  'id',
  'index_stt',
  'display_order',
  'name',
  'type',
  'group',
  'region',
  'layer',
  'geom_type',
  'technical_geom',
  'latitude',
  'longitude',
  'coordinates',
  'coordinates_summary',
  'is_visible',
  'length',
  'area',
  'icon',
  'color',
  'size',
  'media',
  'business',
  'ai',
  'vertexmetadata',
  'technical_specs',
  'properties',
  'specs',
  'gis',
  'source_properties',
  'sourceproperties',
  'imported_from',
  'imported_tile_id',
  'metadata',
  'description',
  'stt',
  'notes',
]);

const BLOCKED_DYNAMIC_PREFIXES = [
  'gis_',
  'source_',
  'imported_',
  '__',
];

export const isAnalysisScalarValue = (value: unknown): value is AnalysisScalarValue => (
  ['string', 'number', 'boolean'].includes(typeof value)
);

const parseMetadata = (metadata: unknown): Record<string, unknown> => {
  if (!metadata) return {};
  if (typeof metadata === 'object') return metadata as Record<string, unknown>;
  if (typeof metadata !== 'string') return {};

  try {
    const parsed = JSON.parse(metadata);
    return parsed && typeof parsed === 'object' ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
};

export const normalizeAnalysisColumnKey = (label: string) => (
  label
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase()
);

export const isAllowedAnalysisDynamicColumnKey = (key: string) => {
  const normalized = key.trim().toLowerCase();
  if (!normalized) return false;
  if (CORE_COLUMN_SET.has(normalized)) return false;
  if (BLOCKED_DYNAMIC_FIELDS.has(normalized)) return false;
  return !BLOCKED_DYNAMIC_PREFIXES.some((prefix) => normalized.startsWith(prefix));
};

export const getAnalysisUserColumnKeys = (
  features: AnalysisFeatureLike[],
  manualKeys: string[] = [],
) => {
  const keys = new Set<string>();

  const addKey = (key: string, value: unknown) => {
    if (!isAllowedAnalysisDynamicColumnKey(key)) return;
    if (value == null) return;
    if (isAnalysisScalarValue(value)) keys.add(key);
  };

  features.forEach((feature) => {
    Object.entries(feature.properties || {}).forEach(([key, value]) => {
      addKey(key, value);
    });

    const metadata = parseMetadata(feature.metadata);
    Object.entries(metadata).forEach(([key, value]) => {
      addKey(key, value);
    });
  });

  manualKeys.forEach((key) => {
    if (isAllowedAnalysisDynamicColumnKey(key)) keys.add(key);
  });

  return Array.from(keys).sort((a, b) => a.localeCompare(b));
};

export const getAnalysisSchemaColumnKeys = (settings?: ProjectSettingsSchema | null) => (
  settings ? getAnalysisTemplateColumnKeys(settings) : []
);

export const buildAnalysisExportRows = (
  rows: Record<string, unknown>[],
  columnKeys: string[],
  getColumnLabel: (key: string) => string,
) => rows.map((row) => (
  columnKeys.reduce<Record<string, unknown>>((acc, key) => {
    acc[getColumnLabel(key)] = row[key] ?? '';
    return acc;
  }, {})
));

import type { FeatureState, MapState } from '@CONTRACT/types';
import { flattenFeature } from '@TOOL/utils/dataFlattening';
import { getFeatureDisplayInfo, isNetworkLinkFeature } from '@TOOL/utils/featureDisplay';
import { calculateFeatureNumbers } from '@TOOL/utils/featureMapping';

type ComparableValue = string | number | boolean | null | undefined;

type ProcessedFeature = {
  feature: FeatureState;
  metadata: Record<string, unknown>;
  flatRow: Record<string, unknown>;
  parentId: string | null;
  rootId: string;
  isIntersection: boolean;
};

export type AnalysisHierarchyRow = Record<string, unknown> & {
  id: string;
  name: string;
  junction_scope: string;
  __analysis_depth: number;
  __analysis_is_intersection: boolean;
  __analysis_parent_id: string | null;
  __analysis_root_id: string;
  __analysis_root_values: Record<string, unknown>;
  __analysis_sort_key: string;
};

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });

const parseMetadata = (feature: FeatureState) => {
  try {
    return typeof feature.metadata === 'string'
      ? JSON.parse(feature.metadata || '{}') as Record<string, unknown>
      : ((feature.metadata || {}) as Record<string, unknown>);
  } catch {
    return {};
  }
};

const compareValues = (left: ComparableValue, right: ComparableValue) => {
  if (left == null && right == null) return 0;
  if (left == null) return 1;
  if (right == null) return -1;

  if (typeof left === 'number' && typeof right === 'number') {
    return left - right;
  }

  if (typeof left === 'boolean' || typeof right === 'boolean') {
    return Number(Boolean(left)) - Number(Boolean(right));
  }

  return collator.compare(String(left), String(right));
};

const compareFeatures = (left: ProcessedFeature, right: ProcessedFeature) => {
  const leftDisplayOrder = String((left.flatRow.display_order as any) || '');
  const rightDisplayOrder = String((right.flatRow.display_order as any) || '');

  if (leftDisplayOrder && rightDisplayOrder) {
    const displayOrderComparison = collator.compare(leftDisplayOrder, rightDisplayOrder);
    if (displayOrderComparison !== 0) return displayOrderComparison;
  } else if (leftDisplayOrder || rightDisplayOrder) {
    return leftDisplayOrder ? -1 : 1;
  }

  const nameComparison = collator.compare(String(left.feature.name || ''), String(right.feature.name || ''));
  if (nameComparison !== 0) return nameComparison;

  return collator.compare(left.feature.id, right.feature.id);
};

const compareSortKeys = (leftKey: string, rightKey: string) => {
  const leftParts = leftKey.split('.').map((segment) => Number.parseInt(segment, 10));
  const rightParts = rightKey.split('.').map((segment) => Number.parseInt(segment, 10));
  const maxLength = Math.max(leftParts.length, rightParts.length);

  for (let index = 0; index < maxLength; index += 1) {
    const leftPart = leftParts[index] ?? -1;
    const rightPart = rightParts[index] ?? -1;
    if (leftPart !== rightPart) return leftPart - rightPart;
  }

  return 0;
};

const resolveRootId = (
  featureId: string,
  processedMap: Map<string, ProcessedFeature>,
  cache: Map<string, string>,
): string => {
  const cached = cache.get(featureId);
  if (cached) return cached;

  const current = processedMap.get(featureId);
  if (!current?.parentId) {
    cache.set(featureId, featureId);
    return featureId;
  }

  const parent = processedMap.get(current.parentId);
  if (!parent) {
    cache.set(featureId, featureId);
    return featureId;
  }

  const rootId = resolveRootId(parent.feature.id, processedMap, cache);
  cache.set(featureId, rootId);
  return rootId;
};

export const buildAnalysisHierarchyRows = (state: MapState): AnalysisHierarchyRow[] => {
  const featureNumbers = calculateFeatureNumbers(
    Object.values(state.features || {}),
    state.features || {},
  );

  const processedFeatures = Object.values(state.features || {})
    .filter((feature) => !isNetworkLinkFeature(feature))
    .map((feature) => {
    const metadata = parseMetadata(feature);
    const group = feature.group_id ? state.feature_groups?.[feature.group_id] : null;
    const displayInfo = getFeatureDisplayInfo(feature, group?.type || group?.group_type, group?.name, metadata);
    return {
      feature,
      metadata,
      flatRow: flattenFeature(feature, state, metadata, { featureNumbers }),
      parentId: typeof metadata.parent_feature_id === 'string' ? metadata.parent_feature_id : null,
      rootId: feature.id,
      isIntersection: displayInfo.isIntersection,
    } satisfies ProcessedFeature;
  });

  const processedMap = new Map(processedFeatures.map((item) => [item.feature.id, item]));
  const rootCache = new Map<string, string>();
  processedFeatures.forEach((item) => {
    item.rootId = resolveRootId(item.feature.id, processedMap, rootCache);
  });

  const childrenMap = new Map<string, ProcessedFeature[]>();
  processedFeatures.forEach((item) => {
    if (!item.parentId || !processedMap.has(item.parentId)) return;
    const currentChildren = childrenMap.get(item.parentId) || [];
    currentChildren.push(item);
    childrenMap.set(item.parentId, currentChildren);
  });
  childrenMap.forEach((items) => items.sort(compareFeatures));

  const roots = processedFeatures
    .filter((item) => !item.parentId || !processedMap.has(item.parentId))
    .sort(compareFeatures);

  const rows: AnalysisHierarchyRow[] = [];

  const walk = (
    current: ProcessedFeature,
    depth: number,
    sortKey: string,
    root: ProcessedFeature,
  ) => {
    const row = {
      ...(current.flatRow as Record<string, unknown>),
      junction_scope: current.parentId
        ? (root.feature.name || String((root.flatRow.name as any) || ''))
        : (current.isIntersection ? String((current.feature.name as any) || (current.flatRow.name as any) || '') : ''),
      __analysis_depth: depth,
      __analysis_is_intersection: current.isIntersection,
      __analysis_parent_id: current.parentId,
      __analysis_root_id: root.feature.id,
      __analysis_root_values: root.flatRow,
      __analysis_sort_key: sortKey,
    } as AnalysisHierarchyRow;

    rows.push(row);

    const children = childrenMap.get(current.feature.id) || [];
    children.forEach((child, index) => {
      walk(child, depth + 1, `${sortKey}.${String(index + 1).padStart(4, '0')}`, root);
    });
  };

  roots.forEach((root, index) => {
    walk(root, 0, String(index + 1).padStart(4, '0'), root);
  });

  return rows.map((row, index) => ({
    ...row,
    index_stt: String(index + 1),
  }));
};

export const compareAnalysisHierarchyRows = (
  left: AnalysisHierarchyRow,
  right: AnalysisHierarchyRow,
  columnId: string,
) => {
  const leftRootValue = left.__analysis_root_values?.[columnId] as ComparableValue;
  const rightRootValue = right.__analysis_root_values?.[columnId] as ComparableValue;
  const rootComparison = compareValues(
    leftRootValue ?? (left[columnId] as ComparableValue),
    rightRootValue ?? (right[columnId] as ComparableValue),
  );

  if (left.__analysis_root_id !== right.__analysis_root_id) {
    if (rootComparison !== 0) return rootComparison;

    const leftRootDisplayOrder = left.__analysis_root_values?.display_order as ComparableValue;
    const rightRootDisplayOrder = right.__analysis_root_values?.display_order as ComparableValue;
    const displayOrderComparison = compareValues(leftRootDisplayOrder, rightRootDisplayOrder);
    if (displayOrderComparison !== 0) return displayOrderComparison;

    const rootNameComparison = compareValues(
      left.__analysis_root_values?.name as ComparableValue,
      right.__analysis_root_values?.name as ComparableValue,
    );
    if (rootNameComparison !== 0) return rootNameComparison;

    return compareValues(left.__analysis_root_id, right.__analysis_root_id);
  }

  return compareSortKeys(left.__analysis_sort_key, right.__analysis_sort_key);
};

