import { useState, useEffect, useMemo, useCallback } from 'react';
import {
  Plus,
  Package,
  Building2,
  FolderOpen,
  FileText,
  Clock,
  Zap,
  PlayCircle,
  ExternalLink,
  Cpu,
  CheckCircle2,
  User,
} from 'lucide-react';
import { invoke } from '@tauri-apps/api/core';
import { addDays, parse, format, isValid } from 'date-fns';
import { AnalysisTable } from '@DESIGN/components/ui/AnalysisTable';
import { ColumnDef } from '@tanstack/react-table';
import { BOMItem, ContractMetadata } from '@CONTRACT/types';

export interface ContractExecutionGroup {
  id?: string;
  project_id: string;
  name: string;
  description: string;
  status: string;
  due_date: string;
  assignee: string;
  color: string;
  bom_item_uids: string[];
}

interface Props {
  projectId: string;
  data: ContractMetadata;
  onViewRaw: () => void;
  onSaveCorrections?: (correctedData: ContractMetadata) => void;
  onBulkSync?: () => Promise<void>;
  viewType?: 'dashboard' | 'groups' | 'analysis';
  projectName?: string;
  isAnalyzing?: boolean;
}
const calculateEndDate = (signedDate: string, durationStr: string) => {
  try {
    const date = parse(signedDate, 'dd/MM/yyyy', new Date());
    if (!isValid(date)) return '---';
    const days = parseInt(durationStr.replace(/\D/g, '')) || 0;
    if (days <= 0) return signedDate;
    return format(addDays(date, days), 'dd/MM/yyyy');
  } catch (e) {
    return '---';
  }
};

export function ContractAnalysisView({
  projectId,
  data: initialData,
  onViewRaw,
  // onSaveCorrections, // Unused in this view
  onBulkSync,
  viewType = 'analysis',
  projectName,
  isAnalyzing = false,
}: Props) {
  const [isEditing, setIsEditing] = useState(false);
  const [data, setData] = useState<ContractMetadata>(initialData);
  const [executionGroups, setExecutionGroups] = useState<ContractExecutionGroup[]>([]);
  const [isAddingGroup, setIsAddingGroup] = useState(false);

  const fetchGroups = useCallback(async () => {
    try {
      const groups = await invoke<ContractExecutionGroup[]>('get_execution_groups', { projectId });
      setExecutionGroups(groups);
    } catch (error) {
      console.error('Fetch groups error:', error);
    }
  }, [projectId]);

  useEffect(() => {
    const calculatedEndDate = calculateEndDate(initialData.signed_date, initialData.duration);
    const processedBOM = initialData.bom_table.map((item) => ({
      ...item,
      uid: item.uid && item.uid !== '' ? item.uid : crypto.randomUUID(),
    }));
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setData({
      ...initialData,
      bom_table: processedBOM,
      end_date:
        initialData.end_date && initialData.end_date !== '---'
          ? initialData.end_date
          : calculatedEndDate,
    });
  }, [initialData]);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    if (projectId) void fetchGroups();
  }, [projectId, fetchGroups]);

  const handleUpsertGroup = async (group: Partial<ContractExecutionGroup>) => {
    try {
      const newGroup = {
        project_id: projectId,
        name: group.name || 'Nhóm mới',
        description: group.description || '',
        status: group.status || 'todo',
        due_date: group.due_date || '',
        assignee: group.assignee || '',
        color: group.color || 'emerald',
        bom_item_uids: group.bom_item_uids || [],
        id: group.id,
      };
      await invoke('upsert_execution_group', { group: newGroup });
      fetchGroups();
      setIsAddingGroup(false);
    } catch (error) {
      console.error('Upsert group error:', error);
    }
  };



  const handleBOMUpdate = useCallback((id: string, field: string, value: string | number | boolean) => {
    setData((prev) => {
      const newBOM = prev.bom_table.map((item) => {
        if (item.uid === id) {
          const newItem = { ...item, [field]: value };
          if (field === 'quantity' || field === 'price') {
            newItem.total = (newItem.quantity || 0) * (newItem.price || 0);
          }
          return newItem;
        }
        return item;
      });
      return { ...prev, bom_table: newBOM };
    });
    return Promise.resolve();
  }, []);

  const onBatchUpdate = useCallback((selectedIds: string[], field: string, value: string | number | boolean) => {
    setData((prev) => {
      const newBOM = prev.bom_table.map((item) => {
        if (selectedIds.includes(item.uid)) {
          const newItem = { ...item, [field]: value };
          if (field === 'quantity' || field === 'price') {
            newItem.total = (newItem.quantity || 0) * (newItem.price || 0);
          }
          return newItem;
        }
        return item;
      });
      return { ...prev, bom_table: newBOM };
    });
    return Promise.resolve();
  }, []);

  const tableData = useMemo(() => {
    return data.bom_table.map((item) => ({
      ...item,
      id: item.uid,
    }));
  }, [data.bom_table]);

  const columns = useMemo<ColumnDef<BOMItem>[]>(
    () => [
      {
        id: 'select',
        size: 40,
        header: ({ table }) => (
          <input
            type="checkbox"
            checked={table.getIsAllPageRowsSelected()}
            onChange={table.getToggleAllPageRowsSelectedHandler()}
            className="accent-cad-accent w-4 h-4"
          />
        ),
        cell: ({ row }) => (
          <input
            type="checkbox"
            checked={row.getIsSelected()}
            onChange={row.getToggleSelectedHandler()}
            className="accent-cad-accent w-4 h-4"
          />
        ),
      },
      { header: 'STT', accessorKey: 'stt', size: 60 },
      {
        header: 'TÊN HẠNG MỤC',
        accessorKey: 'name',
        size: 250,
        cell: (info) => (
          <div className="font-bold text-white tracking-tight">{info.getValue() as string}</div>
        ),
      },
      { header: 'QUY CÁCH', accessorKey: 'description', size: 300 },
      { header: 'ĐVT', accessorKey: 'unit', size: 70 },
      {
        header: 'SỐ LƯỢNG',
        accessorKey: 'quantity',
        size: 100,
        cell: (info) => (info.getValue() as number).toLocaleString(),
      },
      {
        header: 'ĐƠN GIÁ',
        accessorKey: 'price',
        size: 120,
        cell: (info) => `${(info.getValue() as number).toLocaleString()} đ`,
      },
      {
        header: 'THÀNH TIỀN',
        accessorKey: 'total',
        size: 140,
        cell: (info) => (
          <span className="font-bold text-cad-accent">
            {(info.getValue() as number).toLocaleString()} đ
          </span>
        ),
      },
    ],
    []
  );

  const totalAmount = data.bom_table.reduce((sum, item) => sum + item.total, 0);

  const renderActions = () => (
    <div className="flex gap-2 font-sans">
      {onBulkSync && (
        <button
          onClick={onBulkSync}
          className="px-4 py-1.5 bg-cad-accent text-black text-[10px] font-black rounded uppercase tracking-wider hover:brightness-110 transition-all flex items-center gap-2"
        >
          <PlayCircle size={14} /> ĐỒNG BỘ DỮ LIỆU
        </button>
      )}
      <button
        onClick={() => setIsEditing(!isEditing)}
        className={`px-4 py-1.5 border text-[10px] font-black rounded uppercase tracking-wider transition-all ${isEditing ? 'bg-cad-accent/30 text-cad-accent border-cad-accent/50' : 'bg-cad-accent/10 text-cad-accent border-cad-accent/20'}`}
      >
        {isEditing ? 'LƯU BOM' : 'CHỈNH SỬA BOM'}
      </button>
      <button
        onClick={onViewRaw}
        className="px-4 py-1.5 bg-cad-elevated text-cad-text-muted hover:text-white text-[10px] font-black rounded border border-cad-border uppercase transition-all flex items-center gap-2"
      >
        <ExternalLink size={12} /> XEM GỐC
      </button>
    </div>
  );

  if (viewType === 'dashboard') {
    return (
      <div className="flex-1 bg-cad-bg p-8 overflow-y-auto custom-scrollbar animate-in fade-in duration-500 font-sans">
        <div className="max-w-7xl mx-auto space-y-8">
          <ProjectInfoBar projectName={projectName} data={data} isAnalyzing={isAnalyzing} />
          <header className="flex justify-between items-end mb-4">
            <div>
              <h1 className="text-4xl font-black text-white tracking-tighter uppercase leading-none mb-2">
                PROJECT <span className="text-cad-accent">OVERSIGHT</span>
              </h1>
              <p className="text-cad-text-secondary text-xs font-medium uppercase tracking-widest opacity-60">
                Dữ liệu tổng hợp và tiến độ.
              </p>
            </div>
            {onBulkSync && (
              <button
                onClick={onBulkSync}
                className="px-6 py-2 bg-cad-accent text-black text-xs font-black rounded-sm hover:brightness-110 transition-all flex items-center gap-2 uppercase"
              >
                <PlayCircle size={16} /> Đồng bộ toàn bộ dữ liệu
              </button>
            )}
          </header>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <StatCard
              icon={<Building2 className="text-cad-accent" />}
              label="Tổng giá trị"
              value={`${totalAmount.toLocaleString()} đ`}
              subValue="Hợp đồng hiện tại"
            />
            <StatCard
              icon={<Package className="text-cad-accent" />}
              label="Vật tư"
              value={data.bom_table.length.toString()}
              subValue="Số hạng mục"
            />
            <StatCard
              icon={<Cpu className="text-cad-accent" />}
              label="Nhóm việc"
              value={executionGroups.length.toString()}
              subValue="Đã phân công"
            />
            <StatCard
              icon={<CheckCircle2 className="text-cad-accent" />}
              label="Tồn kho"
              value="92%"
              subValue="Sẵn sàng"
              color="text-cad-accent"
            />
          </div>
        </div>
      </div>
    );
  }

  const tableContent = (
    <AnalysisTable
      data={tableData}
      columns={columns as any}
      projectId={projectId}
      title="DANH SÁCH THIẾT BỊ HÀNG HÓA"
      onUpdate={handleBOMUpdate}
      onBatchUpdate={onBatchUpdate}
      isStandalone={false}
      renderExtraActions={renderActions}
      batchFields={[
        { label: 'Số lượng', value: 'quantity' },
        { label: 'Đơn giá', value: 'price' },
        { label: 'Xuất xứ', value: 'origin' },
        { label: 'Hãng sản xuất', value: 'manufacturer' },
      ]}
    />
  );

  if (viewType === 'groups') {
    return (
      <div className="flex-1 bg-cad-bg overflow-hidden flex flex-col animate-in fade-in duration-500 font-sans">
        <div className="px-8 py-4 border-b border-cad-border bg-cad-bg/80 backdrop-blur-md z-10 flex flex-col gap-2">
          <h1 className="text-2xl font-black text-white tracking-tighter uppercase leading-none">
            DETAILED <span className="text-cad-accent">SUMMARY</span>
          </h1>
          <ProjectInfoBar projectName={projectName} data={data} compact isAnalyzing={isAnalyzing} />
        </div>
        <div className="flex-1 overflow-hidden flex">
          <div className="w-80 border-r border-cad-border bg-cad-bg p-6 overflow-y-auto space-y-4">
            <div className="flex justify-between items-center">
              <h2 className="text-xs font-black text-white uppercase tracking-widest">
                NHÓM CÔNG VIỆC
              </h2>
              <button
                onClick={() => setIsAddingGroup(true)}
                className="p-1.5 bg-cad-accent/10 text-cad-accent rounded-full hover:bg-cad-accent/20 transition-colors"
              >
                <Plus size={14} />
              </button>
            </div>
            {isAddingGroup && (
              <div className="p-4 bg-cad-surface border border-cad-accent/30 rounded-lg space-y-2">
                <input
                  // eslint-disable-next-line jsx-a11y/no-autofocus
                  autoFocus
                  placeholder="Tên nhóm..."
                  className="w-full bg-cad-bg border border-cad-border px-3 py-1.5 text-xs text-white rounded outline-none"
                  onKeyDown={(e) =>
                    e.key === 'Enter' &&
                    handleUpsertGroup({ name: (e.target as HTMLInputElement).value })
                  }
                />
                <p className="text-[9px] text-cad-text-muted font-bold">ENTER để lưu, ESC hủy</p>
              </div>
            )}
            {executionGroups.map((group) => (
              <TaskCard
                key={group.id}
                {...group}
                status={group.status.toUpperCase()}
                title={group.name}
                desc={group.description || `Hạng mục: ${group.bom_item_uids.length}`}
                color={group.color as any}
                due={group.due_date || 'N/A'}
              />
            ))}
          </div>
          <div className="flex-1 bg-cad-surface/30 flex flex-col">{tableContent}</div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 bg-cad-bg overflow-hidden flex flex-col animate-in fade-in duration-500 font-sans">
      <div className="px-8 py-6 border-b border-cad-border bg-cad-bg/80 backdrop-blur-sm z-10 space-y-4">
        <div className="flex justify-between items-end">
          <div>
            <h1 className="text-4xl font-black text-white tracking-tighter uppercase leading-none mb-1">
              CONTRACT <span className="text-cad-accent">ANALYSIS</span>
            </h1>
            <p className="text-cad-text-secondary text-[10px] font-bold uppercase tracking-widest opacity-60">
              Theo dõi mua sắm và hiệu suất.
            </p>
          </div>
          <div className="flex flex-col items-end gap-2 text-cad-accent">
            <div className="flex items-center gap-4">
              <span className="text-[10px] font-black text-cad-text-muted uppercase tracking-widest">
                TỒN KHO
              </span>
              <span className="text-3xl font-black">{totalAmount === 0 ? 0 : 92}%</span>
            </div>
            <div className="w-64 h-1.5 bg-cad-elevated rounded-full overflow-hidden">
              <div
                className="h-full bg-cad-accent rounded-full shadow-[0_0_10px_rgba(34,197,94,0.3)] transition-all duration-1000"
                style={{ width: '92%' }}
              ></div>
            </div>
          </div>
        </div>
        <ProjectInfoBar projectName={projectName} data={data} compact isAnalyzing={isAnalyzing} />
      </div>
      <div className="flex-1 overflow-hidden flex flex-col">{tableContent}</div>
    </div>
  );
}

function ProjectInfoBar({ projectName, data, compact }: any) {
  return (
    <div
      className={`grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-x-8 gap-y-2 ${compact ? '' : 'bg-cad-surface/50 border border-cad-border p-4 rounded-xl'}`}
    >
      <InfoItem icon={<FolderOpen size={12} />} label="DỰ ÁN" value={projectName || '---'} />
      <InfoItem icon={<FileText size={12} />} label="SỐ HĐ" value={data.contract_number || '---'} />
      <InfoItem icon={<Building2 size={12} />} label="CHỦ ĐẦU TƯ" value={data.investor || '---'} />
      <InfoItem icon={<User size={12} />} label="NHÀ THẦU" value={data.contractor || '---'} />
      <InfoItem icon={<Clock size={12} />} label="DỰ KIẾN" value={data.end_date || '---'} />
      <InfoItem
        icon={<Zap size={12} />}
        label="GIÁ TRỊ"
        value={`${Math.round(data.bom_table.reduce((s: any, i: any) => s + i.total, 0) / 1000000)}M`}
      />
    </div>
  );
}

function InfoItem({ icon, label, value }: any) {
  return (
    <div className="flex items-center gap-2">
      <div className="text-cad-accent opacity-70">{icon}</div>
      <div className="flex flex-col">
        <span className="text-[8px] font-black text-cad-text-muted uppercase tracking-widest">
          {label}
        </span>
        <span className="text-[10px] font-bold text-white truncate max-w-[120px]">{value}</span>
      </div>
    </div>
  );
}

function StatCard({ icon, label, value, subValue, color = 'text-white' }: any) {
  return (
    <div className="bg-cad-surface border border-cad-border p-5 rounded-xl hover:border-cad-accent/30 transition-all group">
      <div className="mb-3">{icon}</div>
      <span className="text-[9px] font-black text-cad-text-muted uppercase tracking-widest mb-1 block">
        {label}
      </span>
      <div className={`text-xl font-black ${color} tracking-tight mb-0.5`}>{value}</div>
      <div className="text-[8px] font-bold text-cad-text-secondary uppercase opacity-50">
        {subValue}
      </div>
    </div>
  );
}

function TaskCard({ status, title, due, color }: any) {
  const colors: any = {
    emerald: 'bg-cad-accent/10 text-cad-accent border-cad-accent/20',
    slate: 'bg-cad-elevated text-cad-text-muted border-cad-border',
  };
  return (
    <div
      className={`p-4 bg-cad-surface border rounded-xl hover:border-cad-accent/30 cursor-pointer transition-all ${colors[color] || colors.slate}`}
    >
      <div className="flex justify-between items-center mb-2">
        <span className="text-[8px] font-black px-1.5 py-0.5 rounded bg-black/20 uppercase tracking-widest">
          {status}
        </span>
        <span className="text-[8px] opacity-60 font-bold">{due}</span>
      </div>
      <h3 className="text-white font-black text-xs uppercase mb-1">{title}</h3>
    </div>
  );
}

import React, { useState } from "react";
import { Plus, X } from "lucide-react";
import { Contract } from "@CONTRACT/types";
import { CADInput } from "@IMPLEMENT/features/project-management/ProjectDetailPanels";
import { DeleteConfirmationModal } from "@DESIGN/components/ui/DeleteConfirmationModal";

interface Props {
  contracts: Contract[];
  onAdd: (form: Partial<Contract>) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
  featureCounts?: Record<string, number>;
  onViewAnalysis?: (contract: Contract) => void;
}

export function ContractManager({ contracts, onAdd, onDelete, featureCounts = {}, onViewAnalysis }: Props) {
  const [addingContract, setAddingContract] = useState(false);
  const [newContractForm, setNewContractForm] = useState<Partial<Contract>>({});
  const [deleteModalConfig, setDeleteModalConfig] = useState<{ isOpen: boolean; id: string | null; itemName: string }>({
    isOpen: false,
    id: null,
    itemName: ""
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newContractForm.name?.trim()) return;
    await onAdd(newContractForm);
    setNewContractForm({});
    setAddingContract(false);
  };

  return (
    <div className="flex-1 overflow-y-auto p-6 bg-cad-bg custom-scrollbar">
      <div className="max-w-4xl mx-auto">
        <div className="flex justify-between items-center mb-8">
          <h2 className="text-xl font-display font-black text-white tracking-tight uppercase">CONTRACT MANAGEMENT</h2>
          <button
            onClick={() => setAddingContract(true)}
            className="px-4 py-1.5 bg-cad-accent text-black text-xs font-black rounded-sm hover:bg-cad-accent/80 transition-colors flex items-center gap-2"
          >
            <Plus size={14} /> NEW CONTRACT
          </button>
        </div>

        {addingContract && (
          <form onSubmit={handleSubmit} className="mb-8 bg-cad-surface border border-cad-accent p-6 rounded-sm shadow-2xl">
            <div className="grid grid-cols-2 gap-6 mb-6">
              <CADInput label="Contract Name" value={newContractForm.name || ""} onChange={(v: any) => setNewContractForm(p => ({ ...p, name: v }))} />
              <CADInput label="Contract Number" value={newContractForm.contract_number || ""} onChange={(v: any) => setNewContractForm(p => ({ ...p, contract_number: v }))} />
              <CADInput label="Vendor" value={newContractForm.vendor || ""} onChange={(v: any) => setNewContractForm(p => ({ ...p, vendor: v }))} />
              <CADInput label="Value" type="number" value={newContractForm.value || ""} onChange={(v: any) => setNewContractForm(p => ({ ...p, value: parseFloat(v) }))} />
              <CADInput label="Signed Date" type="date" value={newContractForm.signed_date || ""} onChange={(v: any) => setNewContractForm(p => ({ ...p, signed_date: v }))} />
            </div>
            <div className="flex justify-end gap-3">
              <button type="button" onClick={() => setAddingContract(false)} className="px-4 py-1.5 text-xs font-bold text-cad-text-muted hover:text-white uppercase">Cancel</button>
              <button type="submit" className="px-4 py-1.5 bg-cad-accent text-black text-xs font-black rounded-sm uppercase">Create Record</button>
            </div>
          </form>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {contracts?.map(c => (
            <div key={c.id} className="bg-cad-surface border border-cad-border p-5 hover:border-cad-accent transition-all group/card relative">
              <button
                onClick={() => {
                  setDeleteModalConfig({
                    isOpen: true,
                    id: c.id,
                    itemName: c.name || "Hợp đồng không tên"
                  });
                }}
                className="absolute top-4 right-4 text-cad-text-muted hover:text-red-500 opacity-0 group-hover/card:opacity-100 transition-opacity"
              >
                <X size={14} />
              </button>
              <div className="text-[9px] font-mono text-cad-accent mb-1 font-bold">{c.contract_number || 'PENDING'}</div>
              <h3 className="font-display font-black text-sm text-white mb-4 uppercase">{c.name}</h3>
              <div className="flex justify-between items-center text-[10px] font-mono">
                <span className="text-cad-text-muted uppercase">Vendor: <span className="text-white">{c.vendor || '---'}</span></span>
                <span className="text-cad-accent font-bold">${c.value?.toLocaleString() || '0'}</span>
              </div>
              <div className="mt-3 pt-3 border-t border-cad-border/50 flex justify-between items-center text-[8px] font-bold uppercase tracking-widest text-cad-text-muted">
                <div className="flex flex-col gap-1">
                  <span>Linked Objects: <span className="text-cad-accent">{featureCounts[c.id] || 0}</span></span>
                  {c.has_analysis && (
                    <span className="flex items-center gap-1 text-green-500">
                      <div className="w-1 h-1 bg-green-500 rounded-full animate-pulse" />
                      BOM ANALYZED
                    </span>
                  )}
                </div>
                <div className="flex flex-col items-end gap-1">
                  {c.signed_date && <span>Signed: {new Date(c.signed_date).toLocaleDateString()}</span>}
                  {c.file_path && onViewAnalysis && (
                    <button
                      onClick={() => onViewAnalysis(c)}
                      className="mt-1 text-cad-accent hover:underline hover:text-white transition-colors"
                    >
                      VIEW ANALYSIS
                    </button>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
      <DeleteConfirmationModal
        isOpen={deleteModalConfig.isOpen}
        onClose={() => setDeleteModalConfig({ ...deleteModalConfig, isOpen: false })}
        onConfirm={async () => {
          if (deleteModalConfig.id) {
            await onDelete(deleteModalConfig.id);
            setDeleteModalConfig({ isOpen: false, id: null, itemName: "" });
          }
        }}
        title="Xác nhận xóa hợp đồng"
        itemName={deleteModalConfig.itemName}
        message="Bạn có chắc chắn muốn xóa bản ghi hợp đồng này? Tất cả dữ liệu liên quan sẽ bị loại bỏ khỏi quản lý dự án."
      />
    </div>
  );
}

import { useState, useEffect } from "react";
import { FolderTree } from "@IMPLEMENT/features/project-management/ProjectDetailPanels/FolderTree";
import { FileItem } from "@IMPLEMENT/features/project-management/ProjectDetailPanels/FileItem";
import { TrendingUp, FileSearch, ExternalLink, FolderOpen } from "lucide-react";
import { open as openDialog } from "@tauri-apps/plugin-dialog";
import { invoke } from "@tauri-apps/api/core";
import { Contract } from "@CONTRACT/types";

interface ContractSidebarProps {
    projectId: string | number;
    contractType: 'INVESTOR' | 'SUBCONTRACTOR' | 'FINANCE';
    onFileSelect?: (name: string, path?: string) => void;
}

export function ContractSidebar({ projectId, contractType, onFileSelect }: ContractSidebarProps) {
    const [contextMenu, setContextMenu] = useState<{ x: number, y: number, type: 'folder' | 'file', path?: string } | null>(null);
    const [linkedContract, setLinkedContract] = useState<{ name: string, path: string } | null>(null);

    const loadContracts = async () => {
        try {
            const contracts: Contract[] = await invoke("get_contracts", { projectId });
            if (contracts && contracts.length > 0) {
                // Find the first contract that has a file_path
                const mainContract = contracts.find(c => c.file_path);
                if (mainContract && mainContract.file_path) {
                    setLinkedContract({ name: mainContract.name, path: mainContract.file_path });
                }
            }
        } catch (err) {
            console.error("Failed to load contracts:", err);
        }
    };

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        loadContracts();

        // Listen for metadata updates to refresh sidebar
        let unlisten: any;
        const setupListener = async () => {
            try {
                const { listen } = await import("@tauri-apps/api/event");
                unlisten = await listen<any>("metadata-updated", (event) => {
                    const payload = event.payload;
                    // id safety
                    if (String(payload.project_id) === String(projectId)) {
                        console.log("[Sidebar] Refreshing contracts due to metadata update for project:", projectId);
                        loadContracts();
                    }
                });
            } catch (err) {
                console.error("Failed to setup metadata listener:", err);
            }
        };
        setupListener();

        return () => {
            if (unlisten && typeof unlisten === 'function') unlisten();
        };
    }, [projectId]);

    const handleOpenLinkContract = async () => {
        setContextMenu(null);
        try {
            const selected = await openDialog({
                multiple: false,
                filters: [{ name: 'Documents', extensions: ['pdf', 'docx', 'doc', 'xlsx', 'xls'] }]
            });
            if (selected && typeof selected === 'string') {
                const fileName = selected.split(/[/\\]/).pop() || 'Contract';

                // Save to database
                await invoke("create_contract", {
                    projectId,
                    name: fileName,
                    filePath: selected
                });

                setLinkedContract({ name: fileName, path: selected });
                onFileSelect?.(fileName, selected);
            }
        } catch (err) {
            console.error("Failed to open contract file:", err);
        }
    };

    const handleOpenFile = async (path: string) => {
        setContextMenu(null);
        try {
            await invoke("open_file_external", { path });
        } catch (err) {
            console.error("Failed to open file:", err);
        }
    };

    const handleOpenFolder = async (path: string) => {
        setContextMenu(null);
        try {
            await invoke("open_containing_folder", { path });
        } catch (err) {
            console.error("Failed to open containing folder:", err);
        }
    };

    const renderInvestorTree = () => (
        <FolderTree name="INVESTOR MANAGEMENT" expanded>
            <FolderTree
                name="Hợp đồng"
                expanded={!!linkedContract}
                onContextMenu={(e: React.MouseEvent) => setContextMenu({ x: e.pageX, y: e.pageY, type: 'folder' })}
            >
                {linkedContract && (
                    <FileItem
                        name={linkedContract.name}
                        path={linkedContract.path}
                        onSelect={() => onFileSelect?.(linkedContract.name, linkedContract.path)}
                        onContextMenu={(e: React.MouseEvent) => setContextMenu({ x: e.pageX, y: e.pageY, type: 'file', path: linkedContract.path })}
                        isActive={true}
                    />
                )}
            </FolderTree>
            <FileItem
                name="Bảng dữ liệu hợp đồng"
                onSelect={() => onFileSelect?.("Bảng dữ liệu hợp đồng")}
            />
            <FileItem
                name="Tổng hợp chi tiết (Local)"
                onSelect={() => onFileSelect?.("Tổng hợp chi tiết (Local)")}
            />
        </FolderTree>
    );

    const renderSubcontractorTree = () => (
        <FolderTree name="SUBCONTRACTOR MANAGEMENT" expanded>
            <FileItem
                name="Danh sách Hợp đồng"
                onSelect={() => onFileSelect?.("Danh sách Hợp đồng")}
            />
            <FileItem
                name="Financial report"
                onSelect={() => onFileSelect?.("Financial report")}
            />
            <FileItem
                name="Subcontractor tracking"
                onSelect={() => onFileSelect?.("Subcontractor tracking")}
            />
        </FolderTree>
    );

    const renderFinanceTree = () => (
        <FolderTree name="FINANCIAL OVERSIGHT" expanded>
            <FileItem
                name="Bảng giá trị chi tiết hợp đồng"
                onSelect={() => onFileSelect?.("Bảng giá trị chi tiết hợp đồng")}
            />
            <FileItem
                name="Đối ứng giá trị nhà thầu"
                onSelect={() => onFileSelect?.("Đối ứng giá trị nhà thầu")}
            />
        </FolderTree>
    );

    return (
        <div className="flex flex-col py-1 px-1 relative h-full" onClick={() => setContextMenu(null)}>
            {contractType === 'INVESTOR' && renderInvestorTree()}
            {contractType === 'SUBCONTRACTOR' && renderSubcontractorTree()}
            {contractType === 'FINANCE' && renderFinanceTree()}

            {contextMenu && (
                <div
                    className="fixed z-[250] bg-cad-surface border border-cad-border rounded-lg shadow-2xl flex flex-col min-w-[200px] overflow-hidden backdrop-blur-md bg-opacity-95"
                    style={{ top: contextMenu.y, left: contextMenu.x }}
                    onClick={(e) => e.stopPropagation()}
                >
                    {contextMenu.type === 'folder' ? (
                        <button
                            className="px-4 py-2.5 text-left text-[10px] font-black text-cad-text-primary hover:bg-cad-accent hover:text-black transition-all flex items-center gap-3 uppercase tracking-wider"
                            onClick={handleOpenLinkContract}
                        >
                            <FileSearch size={14} className="text-cad-accent group-hover:text-black" /> Open link contract
                        </button>
                    ) : (
                        <>
                            <button
                                className="px-4 py-2.5 text-left text-[10px] font-black text-cad-text-primary hover:bg-cad-accent hover:text-black transition-all flex items-center gap-3 uppercase tracking-wider group"
                                onClick={() => contextMenu.path && handleOpenFile(contextMenu.path)}
                            >
                                <ExternalLink size={14} className="text-cad-accent group-hover:text-black" /> Open file
                            </button>
                            <button
                                className="px-4 py-2.5 text-left text-[10px] font-black text-cad-text-primary hover:bg-cad-accent hover:text-black transition-all flex items-center gap-3 uppercase tracking-wider group border-t border-cad-border/30"
                                onClick={() => contextMenu.path && handleOpenFolder(contextMenu.path)}
                            >
                                <FolderOpen size={14} className="text-cad-accent group-hover:text-black" /> Open contain folder
                            </button>
                        </>
                    )}
                </div>
            )}

            <div className="mt-8 px-4 py-2 border-t border-cad-border/30">
                <div className="flex items-center gap-2 mb-2">
                    <TrendingUp size={12} className="text-cad-accent" />
                    <span className="text-[9px] font-black text-cad-text-muted uppercase tracking-widest">Quick Insight</span>
                </div>
                <div className="bg-cad-elevated/30 rounded p-2 border border-cad-border/50">
                    <p className="text-[10px] text-cad-text-secondary leading-tight">
                        Module {contractType} đang hoạt động độc lập và link trực tiếp với kho dữ liệu CAD.
                    </p>
                </div>
            </div>
        </div>
    );
}

