import React, { useState, useEffect } from "react";
import { Plus, X, Trash2, Edit2, Save } from "lucide-react";
import { invoke } from "@tauri-apps/api/core";
import { ContentType, ContentField, ContentItem } from "@CONTRACT/types";
import { CADInput } from "@IMPLEMENT/features/project-management/ProjectDetailPanels/CADInput";
import { logger } from "@TOOL/utils/logger";

interface Props {
    projectId: string;
    contentType: ContentType;
}

export function DynamicContentManager({ projectId, contentType }: Props) {
    const [fields, setFields] = useState<ContentField[]>([]);
    const [items, setItems] = useState<ContentItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [isAdding, setIsAdding] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [formValues, setFormValues] = useState<Record<string, any>>({});
    const [itemName, setItemName] = useState("");

    const fetchData = async () => {
        setLoading(true);
        try {
            const [fetchedFields, fetchedItems] = await Promise.all([
                invoke<ContentField[]>("get_content_fields", { typeId: contentType.id }),
                invoke<ContentItem[]>("get_content_items", { projectId, typeId: contentType.id })
            ]);
            setFields(fetchedFields);
            setItems(fetchedItems);
        } catch (err) {
            logger.error("Failed to fetch dynamic content data:", err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        fetchData();
    }, [projectId, contentType.id]);

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        try {
            await invoke("save_content_item", {
                contentTypeId: contentType.id,
                projectId,
                name: itemName,
                dataJson: JSON.stringify(formValues),
                id: editingId
            });
            setIsAdding(false);
            setEditingId(null);
            setFormValues({});
            setItemName("");
            fetchData();
        } catch (err) {
            logger.error("Failed to save content item:", err);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Xác nhận xóa bản ghi này?")) return;
        try {
            await invoke("delete_content_item", { itemId: id });
            fetchData();
        } catch (err) {
            logger.error("Failed to delete content item:", err);
        }
    };

    const startEdit = (item: ContentItem) => {
        setEditingId(item.id);
        setItemName(item.name);
        setFormValues(JSON.parse(item.data_json));
        setIsAdding(true);
    };

    if (loading) {
        return <div className="p-8 text-cad-text-muted animate-pulse">Loading {contentType.name}...</div>;
    }

    return (
        <div className="flex-1 overflow-y-auto bg-cad-bg p-6 cad-scrollbar">
            <div className="mx-auto max-w-6xl">
                <div className="mb-8 flex items-center justify-between gap-4">
                    <div>
                        <h2 className="text-xl font-display font-black uppercase tracking-tight text-cad-text-primary">
                            {contentType.name}
                        </h2>
                        {contentType.description && (
                            <p className="mt-1 text-xs text-cad-text-muted">{contentType.description}</p>
                        )}
                    </div>
                    <button
                        onClick={() => {
                            setIsAdding(true);
                            setEditingId(null);
                            setFormValues({});
                            setItemName("");
                        }}
                        className="cad-button cad-button-primary"
                    >
                        <Plus size={14} /> NEW RECORD
                    </button>
                </div>

                {isAdding && (
                    <form onSubmit={handleSave} className="cad-card mb-8 p-6">
                        <div className="mb-6 flex items-center justify-between">
                            <h3 className="text-sm font-black uppercase text-cad-accent">
                                {editingId ? "Edit Record" : "Create New Record"}
                            </h3>
                            <button type="button" onClick={() => setIsAdding(false)} className="cad-icon-button">
                                <X size={16} />
                            </button>
                        </div>

                        <div className="mb-6 grid grid-cols-1 gap-6 md:grid-cols-2">
                            <CADInput
                                label="Bản ghi / Đối tượng"
                                value={itemName}
                                onChange={setItemName}
                                required
                            />
                            {fields.map(field => (
                                <CADInput
                                    key={field.id}
                                    label={field.label}
                                    type={field.field_type as any}
                                    value={formValues[field.name] || ""}
                                    onChange={(val: any) => setFormValues(prev => ({ ...prev, [field.name]: val }))}
                                    required={field.required}
                                />
                            ))}
                        </div>

                        <div className="flex justify-end gap-3">
                            <button
                                type="button"
                                onClick={() => setIsAdding(false)}
                                className="cad-button cad-button-secondary"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                className="cad-button cad-button-primary"
                            >
                                <Save size={14} /> {editingId ? "Update Record" : "Save Record"}
                            </button>
                        </div>
                    </form>
                )}

                <div className="cad-card overflow-hidden">
                    <table className="w-full border-collapse text-left">
                        <thead>
                            <tr className="border-b border-cad-border bg-cad-header/50">
                                <th className="p-4 text-[10px] font-black uppercase tracking-wider text-cad-text-muted">Item Name</th>
                                {fields.map(f => (
                                    <th key={f.id} className="p-4 text-[10px] font-black uppercase tracking-wider text-cad-text-muted">
                                        {f.label}
                                    </th>
                                ))}
                                <th className="w-24 p-4 text-[10px] font-black uppercase tracking-wider text-cad-text-muted">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-cad-border/30">
                            {items.length === 0 ? (
                                <tr>
                                    <td colSpan={fields.length + 2} className="p-8 text-center text-xs italic text-cad-text-muted">
                                        No records found for this module.
                                    </td>
                                </tr>
                            ) : (
                                items.map(item => {
                                    const data = JSON.parse(item.data_json);
                                    return (
                                        <tr key={item.id} className="group transition-colors hover:bg-white/5">
                                            <td className="p-4 text-xs font-bold text-cad-text-primary">{item.name}</td>
                                            {fields.map(f => (
                                                <td key={f.id} className="p-4 font-mono text-xs text-cad-text-muted">
                                                    {data[f.name] || "---"}
                                                </td>
                                            ))}
                                            <td className="p-4">
                                                <div className="flex items-center gap-2 opacity-0 transition-opacity group-hover:opacity-100">
                                                    <button
                                                        onClick={() => startEdit(item)}
                                                        className="cad-icon-button h-7 w-7"
                                                    >
                                                        <Edit2 size={14} />
                                                    </button>
                                                    <button
                                                        onClick={() => handleDelete(item.id)}
                                                        className="cad-icon-button h-7 w-7"
                                                    >
                                                        <Trash2 size={14} className="text-red-400" />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}

import { X, FileIcon, Maximize2, FileText } from "lucide-react";
import { convertFileSrc } from "@tauri-apps/api/core";
import Editor from "@monaco-editor/react";

interface Props {
  selectedFile: {
    name: string;
    type: 'doc' | 'excel' | 'code' | 'image' | 'pdf';
    path?: string;
  };
  fileContent: string;
  onClose: () => void;
  onOpenExternally: () => void;
  onEditorMount: (editor: any) => void;
}

export function FilePreview({ selectedFile, fileContent, onClose, onOpenExternally, onEditorMount }: Props) {
  return (
    <div className="fixed inset-10 z-[100] overflow-hidden rounded-md border border-cad-border bg-cad-surface shadow-[0_0_50px_rgba(0,0,0,0.35)] flex flex-col">
      <div className="cad-toolbar">
        <div className="flex items-center gap-2">
          <FileIcon size={14} className="text-cad-accent" />
          <span className="max-w-[55vw] truncate text-xs font-black uppercase tracking-wider text-cad-text-primary">
            {selectedFile.name}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={onOpenExternally} className="cad-icon-button" title="Open externally">
            <Maximize2 size={14} />
          </button>
          <button onClick={onClose} className="cad-icon-button" title="Close preview">
            <X size={16} />
          </button>
        </div>
      </div>
      <div className="relative flex-1 overflow-hidden bg-cad-bg">
        {selectedFile.type === 'image' ? (
          <div className="flex h-full w-full items-center justify-center bg-cad-bg p-4">
            <img
              src={convertFileSrc(selectedFile.path || '')}
              alt={selectedFile.name}
              className="max-h-[80%] max-w-full rounded-md border border-cad-border object-contain shadow-md"
            />
          </div>
        ) : selectedFile.type === 'pdf' ? (
          <iframe
            src={convertFileSrc(selectedFile.path || '')}
            className="h-full w-full border-none"
            title={selectedFile.name}
          />
        ) : ['code', 'doc', 'excel'].includes(selectedFile.type) ? (
          <div className="h-full w-full p-2">
            <Editor
              height="100%"
              theme="vs-dark"
              path={selectedFile.name}
              value={fileContent || "Loading content..."}
              options={{
                readOnly: true,
                minimap: { enabled: false },
                scrollBeyondLastLine: false,
                fontSize: 12,
                wordWrap: "on"
              }}
              onMount={onEditorMount}
            />
          </div>
        ) : (
          <div className="flex h-full items-center justify-center p-6">
            <div className="cad-empty-state max-w-sm w-full">
              <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-md border border-cad-border bg-cad-bg">
                <FileText size={24} className="text-cad-text-muted" />
              </div>
              <h3 className="mb-1 truncate px-4 text-sm font-bold text-cad-text-primary">{selectedFile.name}</h3>
              <p className="mb-6 text-[11px] text-cad-text-muted">Preview rendering is restricted.</p>
              <button onClick={onOpenExternally} className="cad-button cad-button-primary w-full">
                Open Externally
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import {
  AlertCircle,
  ArrowRight,
  CheckCircle2,
  FileArchive,
  FileCode,
  FileSpreadsheet,
  Loader2,
  Settings2,
  Upload,
  X,
} from "lucide-react";
import { open } from "@tauri-apps/plugin-dialog";
import type { Project } from "@CONTRACT/types";
import { useDesignSync } from "@IMPLEMENT/stores/useDesignSync";
import {
  applyImportedRecords,
  importService,
  type DatasetMeta,
  type FeatureRecord,
  type ImportMapping,
  type PmpImportPreview,
} from "@IMPLEMENT/services/importService";
import { requestStorageHealthRefresh } from "@IMPLEMENT/services/projectStorageService";
import { ImportReviewDialog } from "@IMPLEMENT/components/import/ImportReviewDialog";

interface Props {
  onClose: () => void;
  onSuccess: (datasetId: string) => void;
  project?: Project | null;
}

type Step = "select" | "preview" | "mapping" | "importing" | "complete" | "pmpPreview";
type ImportMode = "gis" | "pmp" | null;

const COMMON_FIELDS = {
  name: ["ten", "name", "label", "doi tuong", "title"],
  lat: ["vi do", "latitude", "lat", "y", "vi_do"],
  lon: ["kinh do", "longitude", "lon", "lng", "x", "kinh_do"],
  order: ["stt", "thu tu", "order", "no", "id", "so thu tu"],
};

export function ImportDialog({ onClose, onSuccess, project }: Props) {
  const [step, setStep] = useState<Step>("select");
  const [mode, setMode] = useState<ImportMode>(null);
  const [filePath, setFilePath] = useState("");
  const [meta, setMeta] = useState<DatasetMeta | null>(null);
  const [pmpPreview, setPmpPreview] = useState<PmpImportPreview | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [review, setReview] = useState<{
    fileName: string;
    sourceLabel: string;
    records: FeatureRecord[];
  } | null>(null);
  const [mapping, setMapping] = useState<ImportMapping>({
    name_column: "",
    lat_column: "",
    lng_column: "",
  });

  const isKml =
    filePath.toLowerCase().endsWith(".kml") || filePath.toLowerCase().endsWith(".kmz");

  const resetSelection = () => {
    setFilePath("");
    setMeta(null);
    setPmpPreview(null);
    setReview(null);
    setError(null);
    setMode(null);
    setMapping({
      name_column: "",
      lat_column: "",
      lng_column: "",
    });
    setStep("select");
  };

  const handleSelectGisFile = async () => {
    try {
      const selected = await open({
        multiple: false,
        filters: [
          {
            name: "GIS Data",
            extensions: ["xlsx", "xls", "xlsb", "xlsm", "kml", "kmz"],
          },
        ],
      });

      if (!selected || typeof selected !== "string") {
        return;
      }

      setMode("gis");
      setFilePath(selected);
      setLoading(true);
      setError(null);
      setPmpPreview(null);

      const inferredMeta = await importService.analyzeFile(selected);
      setMeta(inferredMeta);

      const newMapping: Partial<ImportMapping> = {};
      inferredMeta.fields.forEach((field) => {
        const lowerName = field.name.toLowerCase();
        const lowerDisplay = field.display_name.toLowerCase();
        const matches = (keys: string[]) =>
          keys.some((key) => lowerName.includes(key) || lowerDisplay.includes(key));

        if (matches(COMMON_FIELDS.name)) newMapping.name_column = field.display_name;
        if (matches(COMMON_FIELDS.lat)) newMapping.lat_column = field.display_name;
        if (matches(COMMON_FIELDS.lon)) newMapping.lng_column = field.display_name;
        if (matches(COMMON_FIELDS.order)) newMapping.order_column = field.display_name;
      });

      setMapping({
        name_column: newMapping.name_column || "",
        lat_column: newMapping.lat_column || "",
        lng_column: newMapping.lng_column || "",
        description_column: newMapping.description_column,
        order_column: newMapping.order_column,
      });
      setStep("preview");
    } catch (err: any) {
      setError(err?.message || err?.toString() || "Failed to analyze import file.");
    } finally {
      setLoading(false);
    }
  };

  const handleSelectPmpFile = async () => {
    try {
      if (!project?.id || !project.path) {
        throw new Error("Open a target project before importing a .pmp file.");
      }

      const selected = await open({
        multiple: false,
        filters: [{ name: "PMP Database", extensions: ["pmp"] }],
      });

      if (!selected || typeof selected !== "string") {
        return;
      }

      setMode("pmp");
      setFilePath(selected);
      setLoading(true);
      setError(null);
      setMeta(null);
      setReview(null);

      const preview = await importService.analyzePmpImport(selected);
      setPmpPreview(preview);
      setStep("pmpPreview");
    } catch (err: any) {
      setError(err?.message || err?.toString() || "Failed to inspect .pmp file.");
    } finally {
      setLoading(false);
    }
  };

  const handleStartImport = async () => {
    if (!filePath) return;

    setLoading(true);
    setStep("importing");
    setError(null);

    try {
      const records = await importService.startImport(filePath, mapping);
      setReview({
        fileName: filePath.split("\\").pop() || filePath,
        sourceLabel: isKml ? "KML/KMZ" : "Excel",
        records,
      });
      setStep("preview");
    } catch (err: any) {
      setError(err?.message || err?.toString() || "Import failed.");
      setStep("preview");
    } finally {
      setLoading(false);
    }
  };

  const confirmImportRecords = async (records: FeatureRecord[]) => {
    try {
      const importedCount = await applyImportedRecords(records);
      setStep("complete");
      onSuccess(`imported_${importedCount}`);
      onClose();
    } finally {
      setReview(null);
    }
  };

  const confirmPmpImport = async () => {
    if (!project?.id || !project.path || !filePath) {
      setError("Target project is missing for .pmp import.");
      return;
    }

    setLoading(true);
    setStep("importing");
    setError(null);

    try {
      const result = await importService.importPmpIntoProject(filePath, String(project.id));
      await useDesignSync.getState().initialize(String(project.id), project.path);
      requestStorageHealthRefresh();
      setStep("complete");
      onSuccess(`pmp_import_${result.importedFeatures}`);
      onClose();
    } catch (err: any) {
      setError(err?.message || err?.toString() || "PMP import failed.");
      setStep("pmpPreview");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div className="fixed inset-0 z-50 flex-center bg-surface-900/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
        <div className="bg-surface-100 rounded-2xl shadow-2xl border border-surface-200 w-full max-w-xl overflow-hidden animate-in zoom-in-95 duration-200 relative pb-2">
          <div className="absolute top-0 right-0 w-64 h-64 bg-brand-500/10 rounded-full blur-3xl pointer-events-none -mt-32 -mr-32" />

          <div className="flex items-center justify-between p-6 border-b border-surface-200/50 bg-surface-50/50 backdrop-blur">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-brand-500/10 rounded-xl text-brand-600">
                <Upload size={20} />
              </div>
              <h2 className="text-xl font-bold text-surface-900">Import Data</h2>
            </div>
            <button
              onClick={onClose}
              className="p-1.5 rounded-lg text-surface-400 hover:bg-surface-200 hover:text-surface-900 transition-colors"
            >
              <X size={18} />
            </button>
          </div>

          <div className="p-8">
            {step === "select" && (
              <div className="space-y-4">
                <button
                  type="button"
                  className="w-full flex flex-col items-center justify-center border-2 border-dashed border-surface-300 rounded-2xl p-10 bg-surface-50/50 hover:bg-surface-50 transition-colors text-left"
                  onClick={() => void handleSelectGisFile()}
                >
                  <div className="w-16 h-16 bg-brand-50 rounded-2xl flex-center text-brand-500 mb-4">
                    <FileSpreadsheet size={32} />
                  </div>
                  <p className="text-surface-900 font-semibold mb-1 text-lg">Import GIS dataset</p>
                  <p className="text-surface-500 text-sm">
                    Supports Excel (.xlsx) and KML/KMZ files.
                  </p>
                </button>

                <button
                  type="button"
                  className="w-full flex flex-col items-center justify-center border-2 border-dashed border-surface-300 rounded-2xl p-10 bg-surface-50/50 hover:bg-surface-50 transition-colors text-left"
                  onClick={() => void handleSelectPmpFile()}
                >
                  <div className="w-16 h-16 bg-brand-50 rounded-2xl flex-center text-brand-500 mb-4">
                    <FileArchive size={32} />
                  </div>
                  <p className="text-surface-900 font-semibold mb-1 text-lg">
                    Import from .pmp
                  </p>
                  <p className="text-surface-500 text-sm">
                    Merge design data and linked media into the current project.
                  </p>
                </button>

                {loading && (
                  <div className="flex items-center justify-center gap-2 text-brand-500 font-medium pt-2">
                    <Loader2 className="animate-spin" size={18} />
                    <span>Analyzing file...</span>
                  </div>
                )}

                {error && (
                  <div className="p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-start gap-3 text-rose-600">
                    <div className="p-1 bg-rose-100 rounded-lg text-rose-600">
                      <AlertCircle size={14} />
                    </div>
                    <p className="text-xs leading-relaxed">{error}</p>
                  </div>
                )}
              </div>
            )}

            {step === "preview" && meta && mode === "gis" && (
              <div className="space-y-6">
                <div className="p-4 bg-brand-50 rounded-xl border border-brand-100 flex items-center gap-4">
                  <div className="p-2 bg-white rounded-lg shadow-sm text-brand-500">
                    {isKml ? <FileCode size={20} /> : <FileSpreadsheet size={20} />}
                  </div>
                  <div>
                    <p className="text-xs text-brand-600 font-bold uppercase tracking-wider">
                      Target File
                    </p>
                    <p className="text-surface-900 font-medium truncate max-w-sm">
                      {filePath.split("\\").pop()}
                    </p>
                  </div>
                </div>

                <div>
                  <h3 className="text-sm font-bold text-surface-800 mb-3 flex items-center gap-2">
                    <CheckCircle2 size={16} className="text-emerald-500" />
                    Detected Schema
                  </h3>
                  <div className="grid grid-cols-2 gap-3 max-h-48 overflow-y-auto pr-2 custom-scrollbar">
                    {meta.fields.map((field) => (
                      <div
                        key={field.name}
                        className="flex items-center justify-between p-3 bg-surface-50 border border-surface-200 rounded-xl"
                      >
                        <span className="text-sm text-surface-900 font-medium">
                          {field.name}
                        </span>
                        <span className="text-[10px] font-bold px-2 py-0.5 bg-surface-200 text-surface-600 rounded-md uppercase">
                          {field.field_type}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>

                {error && (
                  <div className="p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-start gap-3 text-rose-600">
                    <div className="p-1 bg-rose-100 rounded-lg text-rose-600">
                      <AlertCircle size={14} />
                    </div>
                    <p className="text-xs leading-relaxed">{error}</p>
                  </div>
                )}

                <div className="flex justify-end gap-3 pt-4 border-t border-surface-200/50">
                  <button
                    onClick={resetSelection}
                    className="px-5 py-2.5 text-sm font-semibold text-surface-600 hover:bg-surface-200 rounded-xl transition-colors"
                  >
                    Change File
                  </button>
                  <button
                    onClick={() => setStep("mapping")}
                    className="flex items-center gap-2 px-8 py-2.5 text-sm font-bold bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-md transition-all active:scale-95"
                  >
                    Continue to Mapping
                    <ArrowRight size={16} />
                  </button>
                </div>
              </div>
            )}

            {step === "pmpPreview" && pmpPreview && mode === "pmp" && (
              <div className="space-y-6">
                <div className="p-4 bg-brand-50 rounded-xl border border-brand-100 flex items-center gap-4">
                  <div className="p-2 bg-white rounded-lg shadow-sm text-brand-500">
                    <FileArchive size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-xs text-brand-600 font-bold uppercase tracking-wider">
                      Source PMP
                    </p>
                    <p className="text-surface-900 font-medium truncate max-w-sm">
                      {filePath.split("\\").pop()}
                    </p>
                    <p className="text-xs text-surface-500 mt-1 truncate">
                      {pmpPreview.sourceProjectName}
                    </p>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <Metric label="Regions" value={pmpPreview.regions} />
                  <Metric label="Layers" value={pmpPreview.layers} />
                  <Metric label="Groups" value={pmpPreview.groups} />
                  <Metric label="Features" value={pmpPreview.features} />
                  <Metric label="Media" value={pmpPreview.mediaAssets} />
                  <Metric label="Target" value={project?.name || "Missing"} />
                </div>

                <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs leading-relaxed text-amber-900">
                  Imported data will be copied into the current project with new IDs. Existing
                  data stays unchanged.
                </div>

                {pmpPreview.warnings.length > 0 && (
                  <div className="space-y-2">
                    {pmpPreview.warnings.map((warning) => (
                      <div
                        key={warning}
                        className="p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-start gap-3 text-rose-600"
                      >
                        <div className="p-1 bg-rose-100 rounded-lg text-rose-600">
                          <AlertCircle size={14} />
                        </div>
                        <p className="text-xs leading-relaxed">{warning}</p>
                      </div>
                    ))}
                  </div>
                )}

                {error && (
                  <div className="p-3 bg-rose-50 border border-rose-100 rounded-xl flex items-start gap-3 text-rose-600">
                    <div className="p-1 bg-rose-100 rounded-lg text-rose-600">
                      <AlertCircle size={14} />
                    </div>
                    <p className="text-xs leading-relaxed">{error}</p>
                  </div>
                )}

                <div className="flex justify-end gap-3 pt-4 border-t border-surface-200/50">
                  <button
                    onClick={resetSelection}
                    className="px-5 py-2.5 text-sm font-semibold text-surface-600 hover:bg-surface-200 rounded-xl transition-colors"
                  >
                    Change File
                  </button>
                  <button
                    onClick={() => void confirmPmpImport()}
                    className="flex items-center gap-2 px-8 py-2.5 text-sm font-bold bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-md transition-all active:scale-95"
                  >
                    Import PMP
                    <ArrowRight size={16} />
                  </button>
                </div>
              </div>
            )}

            {step === "mapping" && meta && mode === "gis" && (
              <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
                <div className="flex items-center gap-2 mb-2">
                  <Settings2 size={18} className="text-brand-500" />
                  <h3 className="font-bold text-surface-900">Map your data columns</h3>
                </div>

                <div className="grid gap-4">
                  {[
                    { label: "STT (Order)", key: "order_column" as const },
                    { label: "Name", key: "name_column" as const },
                    { label: "Latitude", key: "lat_column" as const },
                    { label: "Longitude", key: "lng_column" as const },
                  ].map((field) => (
                    <div
                      key={field.key}
                      className="flex items-center gap-4 p-3 bg-surface-50 border border-surface-200 rounded-xl"
                    >
                      <span className="text-sm font-medium text-surface-700 w-32 shrink-0">
                        {field.label}
                      </span>
                      <select
                        value={mapping[field.key] || ""}
                        onChange={(event) =>
                          setMapping((prev) => ({
                            ...prev,
                            [field.key]: event.target.value,
                          }))
                        }
                        className="flex-1 bg-white border border-surface-200 rounded-lg px-3 py-1.5 text-sm outline-none focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500 transition-all"
                      >
                        <option value="">-- Do not map --</option>
                        {meta.fields.map((fieldMeta) => (
                          <option key={fieldMeta.name} value={fieldMeta.display_name}>
                            {fieldMeta.display_name}
                          </option>
                        ))}
                      </select>
                    </div>
                  ))}
                </div>

                <p className="text-[10px] text-surface-500 bg-surface-50 p-3 rounded-lg border border-surface-200">
                  Unmapped columns will be kept as extra properties on imported features.
                </p>

                <div className="flex justify-end gap-3 pt-4 border-t border-surface-200/50">
                  <button
                    onClick={() => setStep("preview")}
                    className="px-5 py-2.5 text-sm font-semibold text-surface-600 hover:bg-surface-200 rounded-xl transition-colors"
                  >
                    Back
                  </button>
                  <button
                    onClick={() => void handleStartImport()}
                    className="px-8 py-2.5 text-sm font-bold bg-brand-600 hover:bg-brand-500 text-white rounded-xl shadow-md transition-all active:scale-95"
                  >
                    Start Import
                  </button>
                </div>
              </div>
            )}

            {step === "importing" && (
              <div className="flex flex-col items-center justify-center p-12 text-center">
                <div className="relative mb-8">
                  <div className="absolute inset-0 bg-brand-500/20 rounded-full blur-2xl animate-pulse" />
                  <Loader2 className="animate-spin text-brand-600 relative" size={64} />
                </div>
                <h3 className="text-xl font-bold text-surface-900 mb-2">Processing Data</h3>
                <p className="text-surface-500 max-w-xs">
                  {mode === "pmp"
                    ? "Copying design data, remapping IDs, and rebuilding the project snapshot."
                    : "Applying field mapping and preparing imported records."}
                </p>
              </div>
            )}

            {step === "complete" && (
              <div className="flex flex-col items-center justify-center p-12 text-center">
                <div className="w-20 h-20 bg-emerald-50 text-emerald-500 rounded-full flex-center mb-6 animate-in zoom-in duration-500">
                  <CheckCircle2 size={48} />
                </div>
                <h3 className="text-2xl font-bold text-surface-900 mb-2">Import Successful</h3>
                <p className="text-surface-500">
                  {mode === "pmp"
                    ? "The .pmp data has been merged into the current project."
                    : "Your dataset has been imported successfully."}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {review && (
        <ImportReviewDialog
          open={true}
          fileName={review.fileName}
          sourceLabel={review.sourceLabel}
          records={review.records}
          onClose={() => setReview(null)}
          onConfirm={confirmImportRecords}
        />
      )}
    </>
  );
}

function Metric({ label, value }: { label: string; value: string | number }) {
  return (
    <div className="flex items-center justify-between p-3 bg-surface-50 border border-surface-200 rounded-xl">
      <span className="text-sm text-surface-600 font-medium">{label}</span>
      <span className="text-sm font-bold text-surface-900">{value}</span>
    </div>
  );
}

