import { useState, useEffect } from "react";
import { safeInvoke as invoke, safeSaveDialog as save } from "@IMPLEMENT/lib/tauri";
import type { Project } from "@CONTRACT/types";
import { X, FolderPlus, Info } from "lucide-react";

interface Props {
  onClose: () => void;
  onSuccess: (project?: Project) => void;
}

export function CreateProjectModal({ onClose, onSuccess }: Props) {
  const [name, setName] = useState("");
  const [path, setPath] = useState("");
  const [desc, setDesc] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (path) {
      const filenameWithExt = path.split(/[/\\]/).pop() || "";
      const derivedName = filenameWithExt.replace(/\.pmp$/i, "");
      if (derivedName && derivedName !== name) {
        console.log("[CreateProjectModal] Auto-deriving name:", derivedName);
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setName(derivedName);
      }
    }
  }, [path, name]);

  const handleSelectPath = async () => {
    try {
      console.info("[CreateProjectModal] Opening save dialog...");
      const selected = await save({
        filters: [{ name: 'PMP Database', extensions: ['pmp'] }],
        defaultPath: 'Project.pmp',
        title: 'Save New Project'
      });

      if (selected && typeof selected === 'string') {
        console.info("[CreateProjectModal] Path selected:", selected);
        setPath(selected);

        // Extract filename without extension as project name
        // Supports both \ and / for cross-platform robustness
        const filenameWithExt = selected.split(/[\\/]/).pop() || "";
        const filename = filenameWithExt.replace(/\.pmp$/i, "");

        if (filename) {
          console.info("[CreateProjectModal] Derived name:", filename);
          setName(filename);
        }
      }
    } catch (e) {
      console.error("[CreateProjectModal] Select path error:", e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!path.trim() || !name.trim()) {
      console.warn("[CreateProjectModal] Validation failed: path or name is empty.");
      return;
    }

    try {
      setLoading(true);
      setError(null);
      console.log("[CreateProjectModal] Submitting New Project", { path, name });

      const project = await invoke<Project>("create_pmp_v2", {
        path,
        name,
        description: desc || null
      });

      console.log("[CreateProjectModal] Success! Project:", project?.id || "unknown");
      onSuccess(project || undefined);
      onClose();
    } catch (err: any) {
      console.error("[CreateProjectModal] Submission Error:", err);
      setError(err.message || "Failed to create project");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
      <div className="cad-overlay" onClick={onClose} />

      <div
        className="cad-dialog relative w-full max-w-md animate-in zoom-in-95 duration-200"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="h-1 bg-gradient-to-r from-transparent via-cad-accent to-transparent" />
        <div className="flex items-center justify-between border-b border-cad-border px-5 py-4">
          <div>
            <h2 className="text-sm font-black text-cad-text-primary uppercase tracking-[0.16em]">New Project</h2>
            <p className="text-[9px] text-cad-text-muted uppercase tracking-[0.14em] mt-1">Create a new workspace file</p>
          </div>
          <button
            onClick={onClose}
            className="cad-icon-button"
          >
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 flex flex-col gap-5 relative z-10">

          <div>
            <label className="block text-[10px] font-bold uppercase tracking-widest text-cad-text-secondary mb-1.5">
              Database File (.pmp) <span className="text-red-500">*</span>
            </label>
            <div className="flex gap-2">
              <input
                required
                readOnly
                type="text"
                value={path}
                placeholder="Select where to save the .pmp file"
                className="cad-input flex-1 font-mono overflow-ellipsis"
              />
              <button
                type="button"
                onClick={handleSelectPath}
                className="cad-button cad-button-primary px-4"
                title="Browse..."
              >
                <FolderPlus size={18} />
              </button>
            </div>
            {error && (
              <div className="mt-2 flex items-center gap-2 rounded-md border border-red-500/20 bg-red-500/10 p-2.5 text-[10px] font-mono uppercase text-red-300">
                <Info size={14} className="rotate-180" />
                <span>{error}</span>
              </div>
            )}
            {name && (
              <div className="mt-2 flex items-center gap-2 rounded-md border border-cad-accent/20 bg-cad-accent/10 p-2.5 text-[10px] font-mono uppercase text-cad-accent">
                <Info size={14} />
                <span>Project Name: <strong>{name}</strong> (derived from file)</span>
              </div>
            )}
          </div>

          <div>
            <label className="block text-[10px] font-bold uppercase tracking-widest text-cad-text-secondary mb-1.5">
              Description (Optional)
            </label>
            <textarea
              value={desc}
              onChange={e => setDesc(e.target.value)}
              placeholder="Short description..."
              rows={3}
              className="cad-textarea"
            />
          </div>

          <div className="mt-4 flex justify-end gap-3 border-t border-cad-border pt-4">
            <button
              type="button"
              onClick={onClose}
              className="cad-button cad-button-secondary flex-1 py-3"
            >
              Cancel
            </button>
            <button
              disabled={loading}
              type="submit"
              className="cad-button cad-button-primary flex-1 py-3"
            >
              {loading ? "Creating..." : "Create Project"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useMemo } from 'react';
import { Project } from "@CONTRACT/types";
import { ProjectSidebar } from "./ProjectSidebar";
import { ProjectMainView } from "./ProjectMainView";
import { ProjectOverlayLayer } from "./ProjectOverlayLayer";
import { useProjectDetailLogic } from "@IMPLEMENT/hooks/useProjectDetailLogic";
import { useResizablePanels } from "@IMPLEMENT/hooks/useResizablePanels";
import { useSettingsStore } from "@IMPLEMENT/stores/useSettingsStore";
import { useLayoutStore } from "@IMPLEMENT/stores/useLayoutStore";
import { ResizeHandle } from "@DESIGN/components/ui/ResizeHandle";
import { cn } from "@TOOL/utils/cn";
import { invoke } from "@tauri-apps/api/core";
import { logger } from "@TOOL/utils/logger";

interface ProjectDetailProps {
  project: Project;
  activeTab: string;
  contractType?: 'INVESTOR' | 'SUBCONTRACTOR' | 'FINANCE';
  onProjectUpdate?: () => void;
}

export type ProjectDetailViewMode =
  | 'tasks'
  | 'contracts'
  | 'kanban'
  | 'search'
  | 'calendar'
  | 'analysis'
  | 'global-bom'
  | 'global-summary'
  | 'manager';

export function ProjectDetail({
  project,
  activeTab,
  contractType = 'INVESTOR',
  onProjectUpdate
}: ProjectDetailProps) {
  const {
    fileNodes,
    viewMode,
    setViewMode,
    selectedFile,
    setSelectedFile,
    fileContent,
    localMetadata,
    analysisData,
    analyzing,
    showRawFile,
    setShowRawFile,
    globalBOMData,
    contentTypes,
    handleFileSelect,
    contracts,
    handleCreateContract,
    handleDeleteContract,
    handleBulkSync,
    handleSaveCorrections,
    handleProjectMetadataUpdate
  } = useProjectDetailLogic(project, onProjectUpdate);

  const { leftWidth, handleLeftResize } = useResizablePanels();
  const { lowPowerMode } = useSettingsStore();

  const layoutColumns = useLayoutStore(s => s.layoutColumns);
  const paletteConfigs = useLayoutStore(s => s.paletteConfigs);

  const bottomHeight = useMemo(() => {
    const bottomPalettes = layoutColumns
      .flat()
      .filter(id => paletteConfigs[id]?.dockPosition === 'bottom' && paletteConfigs[id]?.isVisible && !paletteConfigs[id]?.isFloating);
    return bottomPalettes.reduce((sum, id) => sum + (paletteConfigs[id]?.height || 320), 0);
  }, [layoutColumns, paletteConfigs]);

  const handleOpenExternally = async () => {
    if (selectedFile?.path) {
      try {
        await invoke("open_file_external", { path: selectedFile.path });
      } catch (err) {
        logger.error("Failed to open file externally:", err);
      }
    }
  };

  return (
    <div className={cn(
      "flex-1 min-h-0 min-w-0 flex overflow-hidden bg-cad-bg relative",
      lowPowerMode && "low-power-active"
    )}>
      <div 
        className="border-r border-cad-border flex flex-col shrink-0 bg-cad-surface group/sidebar relative min-h-0" 
        style={{ 
          width: leftWidth,
          height: bottomHeight > 0 ? `calc(100% - ${bottomHeight}px)` : '100%'
        }}
      >
        <ResizeHandle direction="left" onResize={handleLeftResize} />
        <ProjectSidebar
          activeTab={activeTab}
          contractType={contractType}
          fileNodes={fileNodes}
          selectedFile={selectedFile}
          onFileSelect={(path, name, ext) => handleFileSelect(path, name, ext, activeTab)}
          contentTypes={contentTypes}
          project={project}
        />
      </div>

      <div 
        className="flex-1 min-h-0 min-w-0 flex flex-col overflow-hidden relative"
        style={{ 
          height: bottomHeight > 0 ? `calc(100% - ${bottomHeight}px)` : '100%'
        }}
      >
        <ProjectMainView
          project={project}
          activeTab={activeTab}
          viewMode={viewMode}
          setViewMode={setViewMode}
          analysisData={analysisData}
          showRawFile={showRawFile}
          setShowRawFile={setShowRawFile}
          analyzing={analyzing}
          localMetadata={localMetadata}
          globalBOMData={globalBOMData}
          handleBulkSync={handleBulkSync}
          handleSaveCorrections={handleSaveCorrections}
          handleProjectMetadataUpdate={handleProjectMetadataUpdate}
          contracts={contracts}
          handleCreateContract={(form: any) => handleCreateContract(form || {})}
          handleDeleteContract={handleDeleteContract}
          handleFileSelect={(path, name, ext) => handleFileSelect(path, name, ext, activeTab)}
          contentTypes={contentTypes}
        />
      </div>

      <ProjectOverlayLayer
        activeTab={activeTab}
        selectedFile={selectedFile}
        setSelectedFile={setSelectedFile}
        fileContent={fileContent}
        showRawFile={showRawFile}
        setShowRawFile={setShowRawFile}
        handleOpenExternally={handleOpenExternally}
      />
    </div>
  );
}

import { format, isSameMonth, subMonths, addMonths, isSameDay } from "date-fns";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@TOOL/utils/cn";
import { Task } from "@CONTRACT/types";

interface CalendarViewProps {
   days: Date[];
   tasks: Task[];
   month: Date;
   onMonthChange: (d: Date) => void;
   onClick: (path: string) => void;
}

export function CalendarView({ days, tasks, month, onMonthChange, onClick }: CalendarViewProps) {
   return (
      <div className="flex-1 flex flex-col bg-cad-bg p-4 h-full">
         <div className="flex items-center justify-between mb-4">
            <div className="flex items-center gap-4">
               <button onClick={() => onMonthChange(subMonths(month, 1))} className="p-1 hover:bg-cad-elevated text-white"><ChevronLeft size={16} /></button>
               <h3 className="text-sm font-black text-white uppercase tracking-tighter w-40 text-center">{format(month, "MMMM yyyy")}</h3>
               <button onClick={() => onMonthChange(addMonths(month, 1))} className="p-1 hover:bg-cad-elevated text-white"><ChevronRight size={16} /></button>
            </div>
         </div>
         <div className="flex-1 border border-cad-border bg-cad-surface grid grid-cols-7 overflow-hidden rounded-sm">
            {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(day => (
               <div key={day} className="py-2 text-center text-[9px] font-black text-cad-text-muted uppercase border-b border-cad-border bg-cad-bg/50">{day}</div>
            ))}
            {days.map((day, idx) => {
               const currentMonth = isSameMonth(day, month);
               const today = isSameDay(day, new Date());
               const dayTasks = tasks.filter(t => t.start_date && t.end_date && t.status !== 'folder' && new Date(t.start_date) <= day && new Date(t.end_date) >= day);
               return (
                  <div key={idx} className={cn("border-b border-r border-cad-border p-1 min-h-[80px] flex flex-col gap-1 transition-all", !currentMonth && "opacity-20 bg-cad-bg/50", today && "bg-cad-accent/5")}>
                     <div className={cn("text-[9px] font-mono text-right p-1", today ? "text-cad-accent font-bold" : "text-cad-text-muted")}>{format(day, "d")}</div>
                     <div className="flex-1 overflow-y-auto flex flex-col gap-1 no-scrollbar">
                        {dayTasks.map(t => (
                           <div key={t.id} onClick={() => t.target_file_path && onClick(t.target_file_path)} className={cn("text-[8px] px-1.5 py-0.5 rounded-sm truncate font-bold cursor-pointer uppercase tracking-tighter border", t.is_completed ? "bg-cad-elevated text-cad-text-muted line-through" : "bg-cad-accent/10 text-cad-accent border-cad-accent/20 hover:bg-cad-accent/20")}>
                              {t.name}
                           </div>
                        ))}
                     </div>
                  </div>
               );
            })}
         </div>
      </div>
   );
}

import { FileText } from "lucide-react";
import { cn } from "@TOOL/utils/cn";

export function FileItem({ name, onSelect, onContextMenu, isActive, path }: { name: string, type?: 'doc' | 'excel' | 'code' | 'image' | 'pdf', onSelect?: () => void, onContextMenu?: (e: React.MouseEvent) => void, isActive?: boolean, path?: string }) {
  const Icon = FileText;

  return (
    <div
      draggable={!!path}
      onDragStart={(e) => {
        if (path) {
          e.dataTransfer.setData("application/file-path", path);
        }
      }}
      onClick={(e) => { e.stopPropagation(); onSelect && onSelect(); }}
      onContextMenu={(e) => {
        if (onContextMenu) {
          e.preventDefault();
          e.stopPropagation();
          onContextMenu(e);
        }
      }}
      className={cn(
        "flex items-center gap-2 py-1 pl-4 pr-2 hover:bg-cad-elevated rounded-sm cursor-pointer group transition-all",
        isActive && "bg-cad-elevated border-l-2 border-cad-accent"
      )}
    >
      <Icon size={12} className={cn("shrink-0", isActive ? "text-cad-accent" : "text-cad-text-muted")} />
      <span className={cn("text-[11px] cursor-pointer truncate transition-colors w-full uppercase font-medium", isActive ? "text-white" : "text-cad-text-primary")}>{name}</span>
    </div>
  );
}

import React, { useState } from "react";
import { ChevronDown, ChevronRight, Folder } from "lucide-react";

export function FolderTree({ name, expanded = false, children, onContextMenu }: { name: string, expanded?: boolean, children?: React.ReactNode, onContextMenu?: (e: React.MouseEvent) => void }) {
  const [isOpen, setIsOpen] = useState(expanded);

  const handleContextMenu = (e: React.MouseEvent) => {
    if (onContextMenu) {
      e.preventDefault();
      e.stopPropagation();
      onContextMenu(e);
    }
  };

  return (
    <div className="select-none mb-0">
      <div
        className="flex items-center gap-1.5 py-1 px-1.5 hover:bg-cad-elevated rounded-sm cursor-pointer group transition-colors"
        onClick={() => setIsOpen(!isOpen)}
        onContextMenu={handleContextMenu}
      >
        <div className="text-cad-text-muted shrink-0 w-4 transition-colors flex justify-center mt-0.5">
          {isOpen ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
        </div>
        <Folder size={12} className="text-cad-accent shrink-0 opacity-70" />
        <span className="text-[11px] text-cad-text-primary uppercase font-bold truncate transition-colors">{name}</span>
      </div>
      {isOpen && children && (
        <div className="ml-4 pl-1.5 border-l border-cad-border">
          {children}
        </div>
      )}
    </div>
  );
}

import { FileIcon } from "lucide-react";
import { Task } from "@CONTRACT/types";

interface KanbanViewProps {
  tasks: Task[];
  onUpdateStatus: (id: string, s: string) => void;
  onClick: (path: string) => void;
}

export function KanbanView({ tasks, onUpdateStatus, onClick }: KanbanViewProps) {
  const statuses = ['todo', 'in_progress', 'done'];
  return (
    <div className="flex-1 overflow-x-auto bg-cad-bg p-4 flex gap-4 custom-scrollbar">
      {statuses.map(status => {
        const columnTasks = tasks.filter(t => t.status === status);
        return (
          <div
            key={status}
            className="w-72 shrink-0 flex flex-col bg-cad-surface border border-cad-border rounded-sm"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => {
              const id = e.dataTransfer.getData("taskId");
              if (id) onUpdateStatus(id, status);
            }}
          >
            <div className="p-3 border-b border-cad-border flex items-center justify-between bg-cad-bg/30">
              <h4 className="text-[10px] font-black uppercase tracking-widest text-cad-accent">
                {status.replace('_', ' ')}
              </h4>
              <span className="text-[9px] font-mono bg-cad-elevated px-1.5 py-0.5 rounded text-cad-text-muted">{columnTasks.length}</span>
            </div>
            <div className="flex-1 overflow-y-auto p-2 flex flex-col gap-2 custom-scrollbar">
              {columnTasks.map(t => (
                <div
                  key={t.id}
                  draggable
                  onDragStart={(e) => e.dataTransfer.setData("taskId", t.id)}
                  className="bg-cad-bg border border-cad-border p-3 hover:border-cad-accent transition-all cursor-grab active:cursor-grabbing group"
                  onClick={() => t.target_file_path && onClick(t.target_file_path)}
                >
                  <div className="text-[11px] font-bold text-white mb-2 uppercase tracking-tight">{t.name}</div>
                  {t.target_file_path && (
                    <div className="flex items-center gap-1.5 text-[9px] text-cad-accent font-mono">
                      <FileIcon size={10} /> <span className="truncate">{t.target_file_path.split(/[/\\]/).pop()}</span>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </div>
        );
      })}
    </div>
  );
}

import { Folder, FileIcon, Trash2 } from "lucide-react";
import { cn } from "@TOOL/utils/cn";
import { useState } from "react";
import { DeleteConfirmationModal } from "@DESIGN/components/ui/DeleteConfirmationModal";

interface TaskItem {
   id: string;
   name: string;
   status: string;
   parent_id?: string | null;
   target_file_path?: string;
   is_completed?: boolean;
}

interface ProjectTasksSidebarProps {
   tasks: TaskItem[];
   onAdd: (showInput: boolean) => void;
   onAddGroup: () => void;
   onDrop: (e: React.DragEvent, groupId: string | null) => void;
   onSelect: (path: string) => void;
   onDeleteTask: (id: string) => Promise<void>;
   adding: boolean;
   newName: string;
   setNewName: (name: string) => void;
   onSubmit: (e: React.FormEvent) => void;
}

export function ProjectTasksSidebar({
   tasks, onAdd, onAddGroup, onDrop, onSelect, onDeleteTask,
   adding, newName, setNewName, onSubmit
}: ProjectTasksSidebarProps) {
   const [deleteModalConfig, setDeleteModalConfig] = useState<{ isOpen: boolean; id: string | null; itemName: string; message: string }>({
      isOpen: false,
      id: null,
      itemName: "",
      message: ""
   });
   const groups = tasks.filter((t: TaskItem) => t.status === 'folder');
   const unassigned = tasks.filter((t: TaskItem) => t.status !== 'folder' && !t.parent_id);

   return (
      <div className="flex flex-col gap-4">
         <div className="flex justify-between items-center bg-cad-bg/30 p-2 rounded-sm border border-cad-border">
            <span className="text-[10px] font-black text-cad-text-muted uppercase">Structure</span>
            <button onClick={onAddGroup} className="text-[9px] font-black text-cad-accent uppercase hover:underline">+ New Group</button>
         </div>

         <div className="flex flex-col gap-3">
            {[...groups, { id: "unassigned", name: "Unassigned", status: "folder" } as TaskItem].map((g: TaskItem) => {
               const isUnassigned = g.id === "unassigned";
               const groupTasks = isUnassigned ? unassigned : tasks.filter((t: TaskItem) => t.parent_id === g.id);
               return (
                  <div
                     key={g.id}
                     className="bg-cad-bg/50 border border-cad-border p-2 rounded-sm min-h-[50px]"
                     onDragOver={(e) => e.preventDefault()}
                     onDrop={(e) => onDrop(e, isUnassigned ? null : g.id)}
                  >
                     <div className="flex items-center justify-between gap-2 mb-2 group">
                        <div className="flex items-center gap-2">
                           <Folder size={12} className={isUnassigned ? "text-cad-text-muted" : "text-cad-accent"} />
                           <span className="text-[10px] font-black text-white uppercase">{g.name}</span>
                        </div>
                        {!isUnassigned && (
                           <button
                              onClick={() => {
                                 setDeleteModalConfig({
                                    isOpen: true,
                                    id: g.id,
                                    itemName: g.name,
                                    message: "Bạn có chắc chắn muốn xóa nhóm này và tất cả các mục bên trong? Hành động này không thể hoàn tác."
                                 });
                              }}
                              className="text-cad-text-muted hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                           >
                              <Trash2 size={10} />
                           </button>
                        )}
                     </div>
                     <div className="flex flex-col gap-1">
                        {groupTasks.map((t: TaskItem) => (
                           <div
                              key={t.id}
                              draggable
                              onDragStart={(e) => e.dataTransfer.setData("taskId", t.id)}
                              onClick={() => t.target_file_path && onSelect(t.target_file_path)}
                              className="bg-cad-surface px-2 py-1.5 border border-cad-border hover:border-cad-accent cursor-pointer flex items-center justify-between"
                           >
                              <div className="flex items-center gap-2 overflow-hidden">
                                 <span className={cn("text-[9px] font-bold uppercase truncate", t.is_completed ? "text-cad-text-muted line-through" : "text-white")}>{t.name}</span>
                                 {t.target_file_path && <FileIcon size={10} className="text-cad-accent opacity-50" />}
                              </div>
                              <button
                                 onClick={(e) => {
                                    e.stopPropagation();
                                    setDeleteModalConfig({
                                       isOpen: true,
                                       id: t.id,
                                       itemName: t.name,
                                       message: "Bạn có chắc chắn muốn xóa mục này?"
                                    });
                                 }}
                                 className="text-cad-text-muted hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                              >
                                 <Trash2 size={10} />
                              </button>
                           </div>
                        ))}
                     </div>
                  </div>
               );
            })}
         </div>

         {adding ? (
            <form onSubmit={onSubmit} className="bg-cad-bg p-3 border border-cad-accent">
               {/* eslint-disable-next-line jsx-a11y/no-autofocus */}
               <input autoFocus value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-cad-surface border border-cad-border p-2 text-[10px] text-white outline-none" placeholder="TASK NAME..." />
               <div className="flex justify-end gap-2 mt-2">
                  <button type="button" onClick={() => onAdd(false)} className="text-[9px] font-black text-cad-text-muted hover:text-white uppercase transition-all">Cancel</button>
                  <button type="submit" className="text-[9px] font-black bg-cad-accent text-black px-2 py-1 rounded-sm uppercase transition-all hover:bg-cad-accent/80">Save</button>
               </div>
            </form>
         ) : (
            <button onClick={() => onAdd(true)} className="w-full py-2 border border-cad-border border-dashed text-[10px] font-bold text-cad-text-muted hover:text-cad-accent hover:border-cad-accent transition-all uppercase">
               + NEW TASK
            </button>
         )}
         <DeleteConfirmationModal
            isOpen={deleteModalConfig.isOpen}
            onClose={() => setDeleteModalConfig({ ...deleteModalConfig, isOpen: false })}
            onConfirm={async () => {
               if (deleteModalConfig.id !== null) {
                  await onDeleteTask(deleteModalConfig.id);
                  setDeleteModalConfig({ ...deleteModalConfig, isOpen: false });
               }
            }}
            title="Xác nhận xóa"
            itemName={deleteModalConfig.itemName}
            message={deleteModalConfig.message}
         />
      </div>
   );
}

