/**
 * Accessibility utilities for WCAG 2.1 AA compliance.
 * Provides ARIA helpers, keyboard event handlers, focus management,
 * color contrast checking, and screen reader announcement.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type ARIAAttribute =
  | 'aria-label'
  | 'aria-labelledby'
  | 'aria-describedby'
  | 'aria-hidden'
  | 'aria-expanded'
  | 'aria-haspopup'
  | 'aria-live'
  | 'aria-atomic'
  | 'aria-relevant'
  | 'aria-busy'
  | 'aria-controls'
  | 'aria-current'
  | 'aria-disabled'
  | 'aria-invalid'
  | 'aria-required'
  | 'aria-roledescription'
  | 'aria-sort'
  | 'aria-valuemin'
  | 'aria-valuemax'
  | 'aria-valuenow'
  | 'aria-valuetext'
  | 'aria-checked'
  | 'aria-selected'
  | 'aria-orientation'
  | 'aria-multiselectable'
  | 'aria-level'
  | 'aria-posinset'
  | 'aria-setsize'
  | 'aria-colcount'
  | 'aria-colindex'
  | 'aria-rowcount'
  | 'aria-rowindex';

export interface ARIAProps {
  label?: string;
  labelledBy?: string;
  describedBy?: string;
  hidden?: boolean;
  expanded?: boolean;
  disabled?: boolean;
  required?: boolean;
  invalid?: boolean;
  live?: 'polite' | 'assertive' | 'off';
  atomic?: boolean;
  busy?: boolean;
  role?: string;
}

export type FocusDirection = 'next' | 'previous' | 'first' | 'last';

export interface FocusTrapOptions {
  /** CSS selector for the trap container (default: '[data-focus-trap]') */
  containerSelector?: string;
  /** CSS selector for focusable elements (default: standard focusable set) */
  focusableSelector?: string;
  /** Callback when Escape is pressed */
  onEscape?: () => void;
  /** Auto-focus the first element on activation */
  autoFocus?: boolean;
  /** Restore focus to the previously focused element on deactivation */
  restoreFocus?: boolean;
}

export interface KeyboardHandlerOptions {
  /** Called when Enter is pressed */
  onEnter?: (e: KeyboardEvent) => void;
  /** Called when Space is pressed */
  onSpace?: (e: KeyboardEvent) => void;
  /** Called when Escape is pressed */
  onEscape?: (e: KeyboardEvent) => void;
  /** Called when ArrowUp is pressed */
  onArrowUp?: (e: KeyboardEvent) => void;
  /** Called when ArrowDown is pressed */
  onArrowDown?: (e: KeyboardEvent) => void;
  /** Called when ArrowLeft is pressed */
  onArrowLeft?: (e: KeyboardEvent) => void;
  /** Called when ArrowRight is pressed */
  onArrowRight?: (e: KeyboardEvent) => void;
  /** Called when Tab is pressed */
  onTab?: (e: KeyboardEvent) => void;
  /** Called for any other key */
  onOther?: (e: KeyboardEvent) => void;
}

// ---------------------------------------------------------------------------
// Color Contrast
// ---------------------------------------------------------------------------

/** Parse a hex color string (#RGB, #RGBA, #RRGGBB, #RRGGBBAA) to RGBA components. */
export function parseColor(hex: string): { r: number; g: number; b: number; a: number } {
  const cleaned = hex.replace('#', '');
  let r: number, g: number, b: number, a: number;

  if (cleaned.length === 3) {
    r = parseInt(cleaned[0] + cleaned[0], 16);
    g = parseInt(cleaned[1] + cleaned[1], 16);
    b = parseInt(cleaned[2] + cleaned[2], 16);
    a = 1;
  } else if (cleaned.length === 4) {
    r = parseInt(cleaned[0] + cleaned[0], 16);
    g = parseInt(cleaned[1] + cleaned[1], 16);
    b = parseInt(cleaned[2] + cleaned[2], 16);
    a = parseInt(cleaned[3] + cleaned[3], 16) / 255;
  } else if (cleaned.length === 6) {
    r = parseInt(cleaned.slice(0, 2), 16);
    g = parseInt(cleaned.slice(2, 4), 16);
    b = parseInt(cleaned.slice(4, 6), 16);
    a = 1;
  } else if (cleaned.length === 8) {
    r = parseInt(cleaned.slice(0, 2), 16);
    g = parseInt(cleaned.slice(2, 4), 16);
    b = parseInt(cleaned.slice(4, 6), 16);
    a = parseInt(cleaned.slice(6, 8), 16) / 255;
  } else {
    throw new Error(`Invalid hex color: ${hex}`);
  }

  return { r, g, b, a };
}

/**
 * Calculate relative luminance per WCAG 2.1 spec.
 * https://www.w3.org/WAI/GL/wiki/Relative_luminance
 */
export function relativeLuminance(r: number, g: number, b: number): number {
  const [rs, gs, bs] = [r, g, b].map((c) => {
    const sRGB = c / 255;
    return sRGB <= 0.03928 ? sRGB / 12.92 : Math.pow((sRGB + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;
}

/**
 * Calculate contrast ratio between two colors per WCAG 2.1.
 * Returns a value between 1 and 21.
 * https://www.w3.org/TR/WCAG21/#dfn-contrast-ratio
 */
export function contrastRatio(color1: string, color2: string): number {
  const c1 = parseColor(color1);
  const c2 = parseColor(color2);

  // Blend with white background based on alpha
  const blendWithWhite = (c: { r: number; g: number; b: number; a: number }) => ({
    r: Math.round(c.r * c.a + 255 * (1 - c.a)),
    g: Math.round(c.g * c.a + 255 * (1 - c.a)),
    b: Math.round(c.b * c.a + 255 * (1 - c.a)),
  });

  const b1 = blendWithWhite(c1);
  const b2 = blendWithWhite(c2);

  const l1 = relativeLuminance(b1.r, b1.g, b1.b);
  const l2 = relativeLuminance(b2.r, b2.g, b2.b);

  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);

  return (lighter + 0.05) / (darker + 0.05);
}

/** WCAG 2.1 AA minimum contrast ratios. */
export const WCAG_AA_THRESHOLD = {
  /** Normal text (< 18px or < 14px bold) */
  normal: 4.5,
  /** Large text (>= 18px or >= 14px bold) */
  large: 3.0,
  /** UI components and graphical objects */
  uiComponent: 3.0,
};

/** WCAG 2.1 AAA minimum contrast ratios. */
export const WCAG_AAA_THRESHOLD = {
  normal: 7.0,
  large: 4.5,
};

/** Check if a color pair meets WCAG 2.1 AA requirements. */
export function meetsWCAGAA(
  foreground: string,
  background: string,
  textType: 'normal' | 'large' = 'normal'
): boolean {
  const ratio = contrastRatio(foreground, background);
  return ratio >= WCAG_AA_THRESHOLD[textType];
}

/** Check if a color pair meets WCAG 2.1 AAA requirements. */
export function meetsWCAGAAA(
  foreground: string,
  background: string,
  textType: 'normal' | 'large' = 'normal'
): boolean {
  const ratio = contrastRatio(foreground, background);
  return ratio >= WCAG_AAA_THRESHOLD[textType];
}

/**
 * Suggest a contrasting text color (black or white) based on background luminance.
 * Returns '#000000' or '#FFFFFF'.
 */
export function suggestTextColor(backgroundColor: string): string {
  const { r, g, b, a } = parseColor(backgroundColor);
  // Blend with white
  const blended = {
    r: Math.round(r * a + 255 * (1 - a)),
    g: Math.round(g * a + 255 * (1 - a)),
    b: Math.round(b * a + 255 * (1 - a)),
  };
  const luminance = relativeLuminance(blended.r, blended.g, blended.b);
  return luminance > 0.179 ? '#000000' : '#FFFFFF';
}

// ---------------------------------------------------------------------------
// ARIA Helpers
// ---------------------------------------------------------------------------

/** Build an ARIA attributes object from a typed config. */
export function buildAriaProps(props: ARIAProps): Record<string, string | boolean | undefined> {
  const result: Record<string, string | boolean | undefined> = {};
  if (props.label !== undefined) result['aria-label'] = props.label;
  if (props.labelledBy !== undefined) result['aria-labelledby'] = props.labelledBy;
  if (props.describedBy !== undefined) result['aria-describedby'] = props.describedBy;
  if (props.hidden !== undefined) result['aria-hidden'] = props.hidden;
  if (props.expanded !== undefined) result['aria-expanded'] = props.expanded;
  if (props.disabled !== undefined) result['aria-disabled'] = props.disabled;
  if (props.required !== undefined) result['aria-required'] = props.required;
  if (props.invalid !== undefined) result['aria-invalid'] = props.invalid;
  if (props.live !== undefined) result['aria-live'] = props.live;
  if (props.atomic !== undefined) result['aria-atomic'] = props.atomic;
  if (props.busy !== undefined) result['aria-busy'] = props.busy;
  if (props.role !== undefined) result['role'] = props.role;
  return result;
}

/** Set an ARIA attribute on an element. */
export function setAriaAttribute(
  element: HTMLElement,
  attribute: ARIAAttribute | 'role',
  value: string | boolean
): void {
  element.setAttribute(attribute, String(value));
}

/** Remove an ARIA attribute from an element. */
export function removeAriaAttribute(
  element: HTMLElement,
  attribute: ARIAAttribute | 'role'
): void {
  element.removeAttribute(attribute);
}

// ---------------------------------------------------------------------------
// Screen Reader Announcements
// ---------------------------------------------------------------------------

let announcementContainer: HTMLDivElement | null = null;

/**
 * Announce a message to screen readers via an ARIA live region.
 * Creates a persistent off-screen live region on first call.
 *
 * @param message - The text to announce
 * @param priority - 'polite' (default) or 'assertive'
 */
export function announce(
  message: string,
  priority: 'polite' | 'assertive' = 'polite'
): void {
  if (typeof document === 'undefined') return;

  if (!announcementContainer) {
    announcementContainer = document.createElement('div');
    announcementContainer.setAttribute('aria-live', priority);
    announcementContainer.setAttribute('aria-atomic', 'true');
    announcementContainer.setAttribute('role', 'status');
    announcementContainer.style.position = 'absolute';
    announcementContainer.style.width = '1px';
    announcementContainer.style.height = '1px';
    announcementContainer.style.padding = '0';
    announcementContainer.style.margin = '-1px';
    announcementContainer.style.overflow = 'hidden';
    announcementContainer.style.clip = 'rect(0, 0, 0, 0)';
    announcementContainer.style.whiteSpace = 'nowrap';
    announcementContainer.style.border = '0';
    document.body.appendChild(announcementContainer);
  }

  // Update the live region's aria-live in case priority changed
  announcementContainer.setAttribute('aria-live', priority);

  // Clear and set message with a small delay to ensure screen readers pick up the change
  announcementContainer.textContent = '';
  requestAnimationFrame(() => {
    if (announcementContainer) {
      announcementContainer.textContent = message;
    }
  });
}

/** Remove the announcement container from the DOM. */
export function cleanupAnnouncer(): void {
  if (announcementContainer && announcementContainer.parentNode) {
    announcementContainer.parentNode.removeChild(announcementContainer);
    announcementContainer = null;
  }
}

// ---------------------------------------------------------------------------
// Focus Management
// ---------------------------------------------------------------------------

const DEFAULT_FOCUSABLE_SELECTOR =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), details, summary, iframe, object, embed, [contenteditable]';

/**
 * Get all focusable elements within a container.
 */
export function getFocusableElements(container: HTMLElement = document.body): HTMLElement[] {
  const elements = Array.from(
    container.querySelectorAll<HTMLElement>(DEFAULT_FOCUSABLE_SELECTOR)
  );
  return elements.filter(
    (el) => !el.hasAttribute('disabled') && !el.getAttribute('aria-hidden')
  );
}

/**
 * Move focus to a specific element.
 */
export function focusElement(element: HTMLElement | null, options?: FocusOptions): void {
  if (element) {
    element.focus(options);
  }
}

/**
 * Move focus relative to the current element within a container.
 */
export function moveFocus(
  currentElement: HTMLElement,
  direction: FocusDirection,
  container: HTMLElement = document.body
): HTMLElement | null {
  const focusable = getFocusableElements(container);
  if (focusable.length === 0) return null;

  const currentIndex = focusable.indexOf(currentElement);

  let targetIndex: number;
  switch (direction) {
    case 'next':
      targetIndex = (currentIndex + 1) % focusable.length;
      break;
    case 'previous':
      targetIndex = currentIndex <= 0 ? focusable.length - 1 : currentIndex - 1;
      break;
    case 'first':
      targetIndex = 0;
      break;
    case 'last':
      targetIndex = focusable.length - 1;
      break;
    default:
      return null;
  }

  const target = focusable[targetIndex];
  if (target) {
    focusElement(target, { preventScroll: false });
  }
  return target;
}

/**
 * Create a focus trap within a container.
 * Returns a cleanup function to deactivate the trap.
 */
export function createFocusTrap(
  container: HTMLElement = document.body,
  options: FocusTrapOptions = {}
): () => void {
  const {
    focusableSelector = DEFAULT_FOCUSABLE_SELECTOR,
    onEscape,
    autoFocus = true,
    restoreFocus = true,
  } = options;

  const previouslyFocused = document.activeElement as HTMLElement | null;
  const focusable = Array.from(container.querySelectorAll<HTMLElement>(focusableSelector)).filter(
    (el) => !el.hasAttribute('disabled') && !el.getAttribute('aria-hidden')
  );

  if (autoFocus && focusable.length > 0) {
    focusable[0].focus();
  }

  const handleKeyDown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape') {
      if (onEscape) {
        onEscape();
      } else {
        cleanup();
      }
      return;
    }

    if (e.key !== 'Tab') return;

    const currentFocusable = Array.from(
      container.querySelectorAll<HTMLElement>(focusableSelector)
    ).filter((el) => !el.hasAttribute('disabled') && !el.getAttribute('aria-hidden'));

    if (currentFocusable.length === 0) return;

    const firstElement = currentFocusable[0];
    const lastElement = currentFocusable[currentFocusable.length - 1];

    if (e.shiftKey) {
      // Shift+Tab: if focus is on first element, wrap to last
      if (document.activeElement === firstElement) {
        e.preventDefault();
        lastElement.focus();
      }
    } else {
      // Tab: if focus is on last element, wrap to first
      if (document.activeElement === lastElement) {
        e.preventDefault();
        firstElement.focus();
      }
    }
  };

  document.addEventListener('keydown', handleKeyDown);

  const cleanup = (): void => {
    document.removeEventListener('keydown', handleKeyDown);
    if (restoreFocus && previouslyFocused) {
      previouslyFocused.focus({ preventScroll: true });
    }
  };

  return cleanup;
}

// ---------------------------------------------------------------------------
// Keyboard Event Handlers
// ---------------------------------------------------------------------------

/**
 * Create a keyboard event handler that maps keys to callbacks.
 * Returns the handler function.
 */
export function createKeyboardHandler(
  options: KeyboardHandlerOptions
): (e: React.KeyboardEvent | KeyboardEvent) => void {
  return (e: React.KeyboardEvent | KeyboardEvent): void => {
    const key = e.key;

    switch (key) {
      case 'Enter':
        if (options.onEnter) options.onEnter(e as KeyboardEvent);
        break;
      case ' ':
        e.preventDefault();
        if (options.onSpace) options.onSpace(e as KeyboardEvent);
        break;
      case 'Escape':
        if (options.onEscape) options.onEscape(e as KeyboardEvent);
        break;
      case 'ArrowUp':
        if (options.onArrowUp) options.onArrowUp(e as KeyboardEvent);
        break;
      case 'ArrowDown':
        if (options.onArrowDown) options.onArrowDown(e as KeyboardEvent);
        break;
      case 'ArrowLeft':
        if (options.onArrowLeft) options.onArrowLeft(e as KeyboardEvent);
        break;
      case 'ArrowRight':
        if (options.onArrowRight) options.onArrowRight(e as KeyboardEvent);
        break;
      case 'Tab':
        if (options.onTab) options.onTab(e as KeyboardEvent);
        break;
      default:
        if (options.onOther) options.onOther(e as KeyboardEvent);
        break;
    }
  };
}

/**
 * Handle keyboard navigation for a group of items (e.g., toolbar buttons, list items).
 * Supports ArrowLeft/ArrowRight or ArrowUp/ArrowDown navigation with optional wrapping.
 */
export function createRovingTabHandler(
  items: HTMLElement[],
  options?: {
    direction?: 'horizontal' | 'vertical' | 'both';
    wrap?: boolean;
    onActivate?: (item: HTMLElement, index: number) => void;
  }
): (e: React.KeyboardEvent | KeyboardEvent, currentIndex: number) => void {
  const { direction = 'horizontal', wrap = true, onActivate } = options || {};

  return (e: React.KeyboardEvent | KeyboardEvent, currentIndex: number): void => {
    const key = e.key;
    let newIndex = currentIndex;

    const isHorizontal = key === 'ArrowLeft' || key === 'ArrowRight';
    const isVertical = key === 'ArrowUp' || key === 'ArrowDown';

    if (direction === 'horizontal' && isHorizontal) {
      if (key === 'ArrowRight') newIndex = currentIndex + 1;
      else newIndex = currentIndex - 1;
    } else if (direction === 'vertical' && isVertical) {
      if (key === 'ArrowDown') newIndex = currentIndex + 1;
      else newIndex = currentIndex - 1;
    } else if (direction === 'both' && (isHorizontal || isVertical)) {
      if (key === 'ArrowRight' || key === 'ArrowDown') newIndex = currentIndex + 1;
      else newIndex = currentIndex - 1;
    } else if (key === 'Enter' || key === ' ') {
      e.preventDefault();
      onActivate?.(items[currentIndex], currentIndex);
      return;
    } else {
      return;
    }

    e.preventDefault();

    if (wrap) {
      newIndex = ((newIndex % items.length) + items.length) % items.length;
    } else {
      newIndex = Math.max(0, Math.min(items.length - 1, newIndex));
    }

    if (items[newIndex]) {
      items[newIndex].focus();
    }
  };
}

/**
 * Utility: make an element keyboard-activatable (responds to Enter and Space).
 * Call this in a useEffect or ref callback.
 */
export function makeKeyboardActivatable(
  element: HTMLElement | null,
  onClick: () => void
): void {
  if (!element) return;

  const handler = (e: KeyboardEvent): void => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onClick();
    }
  };

  element.addEventListener('keydown', handler);
}

// ---------------------------------------------------------------------------
// Utility: Visibly Focused Indicator
// ---------------------------------------------------------------------------

/**
 * Add a visible focus indicator class when an element receives focus via keyboard.
 * Removes the class on mouse/touch interactions.
 *
 * Usage: call this once at app root to enable global focus-visible behavior.
 */
export function initFocusVisibleBehavior(): void {
  if (typeof document === 'undefined') return;

  let hadKeyboardEvent = true;
  const KEYBOARD_MATCHING_KEYS = ['Tab', 'Enter', 'Escape', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' ', 'Shift', 'Control', 'Alt', 'Meta'];

  document.addEventListener('keydown', (e) => {
    if (KEYBOARD_MATCHING_KEYS.includes(e.key)) {
      hadKeyboardEvent = true;
    }
  }, true);

  document.addEventListener('mousedown', () => {
    hadKeyboardEvent = false;
  }, true);

  document.addEventListener('focusin', (e) => {
    const target = e.target as HTMLElement;
    if (target && hadKeyboardEvent) {
      target.setAttribute('data-focus-visible', 'true');
    }
  }, true);

  document.addEventListener('focusout', (e) => {
    const target = e.target as HTMLElement;
    if (target) {
      target.removeAttribute('data-focus-visible');
    }
  }, true);
}

// ---------------------------------------------------------------------------
// Utility: Skip Link
// ---------------------------------------------------------------------------

/**
 * Create a "Skip to main content" link for keyboard users.
 * Call once at app initialization.
 */
export function createSkipLink(
  targetId: string = 'main-content',
  linkText: string = 'Skip to main content'
): HTMLAnchorElement {
  const skipLink = document.createElement('a');
  skipLink.href = `#${targetId}`;
  skipLink.textContent = linkText;
  skipLink.className = 'skip-link';
  skipLink.style.position = 'absolute';
  skipLink.style.top = '-100px';
  skipLink.style.left = '0';
  skipLink.style.zIndex = '9999';
  skipLink.style.padding = '12px 24px';
  skipLink.style.backgroundColor = '#000';
  skipLink.style.color = '#fff';
  skipLink.style.textDecoration = 'none';
  skipLink.style.fontWeight = 'bold';
  skipLink.style.transition = 'top 0.2s';

  skipLink.addEventListener('focus', () => {
    skipLink.style.top = '0';
  });

  skipLink.addEventListener('blur', () => {
    skipLink.style.top = '-100px';
  });

  document.body.insertBefore(skipLink, document.body.firstChild);
  return skipLink;
}

const MAX_COLLECTION_LENGTH = 100000000;

export class BincodeDecoder {
    private view: DataView;
    private offset: number = 0;
    private decoder: TextDecoder;

    constructor(data: Uint8Array | ArrayBuffer | number[]) {
        const buffer = data instanceof Uint8Array ? data : new Uint8Array(data as any);
        this.view = new DataView(buffer.buffer, buffer.byteOffset, buffer.byteLength);
        this.decoder = new TextDecoder();
    }

    private checkBounds(bytesNeeded: number) {
        if (this.offset + bytesNeeded > this.view.byteLength) {
            throw new Error(`[BincodeDecoder] Out of bounds: offset ${this.offset}, needs ${bytesNeeded}, total ${this.view.byteLength}. Possible data corruption.`);
        }
    }

    decodeU64(): number {
        this.checkBounds(8);
        const val = this.view.getBigUint64(this.offset, true);
        this.offset += 8;
        return Number(val);
    }

    decodeLength(): number {
        const len = this.decodeU64();
        if (len > MAX_COLLECTION_LENGTH) {
            throw new Error(`[BincodeDecoder] Safe length exceeded: ${len}. Max is ${MAX_COLLECTION_LENGTH}. Data might be corrupted.`);
        }
        return len;
    }

    decodeU32(): number {
        this.checkBounds(4);
        const val = this.view.getUint32(this.offset, true);
        this.offset += 4;
        return val;
    }

    decodeF64(): number {
        this.checkBounds(8);
        const val = this.view.getFloat64(this.offset, true);
        this.offset += 8;
        return val;
    }

    decodeString(): string {
        const len = this.decodeLength();
        this.checkBounds(len);
        const bytes = new Uint8Array(this.view.buffer, this.view.byteOffset + this.offset, len);
        this.offset += len;
        return this.decoder.decode(bytes);
    }

    decodeOption<T>(decoderFunc: () => T): T | null {
        this.checkBounds(1);
        const isSome = this.view.getUint8(this.offset);
        this.offset += 1;
        if (isSome === 1) {
            return decoderFunc();
        }
        return null;
    }

    decodeVec<T>(decoderFunc: () => T): T[] {
        const len = this.decodeLength();
        const result: T[] = new Array(len);
        for (let i = 0; i < len; i++) {
            result[i] = decoderFunc();
        }
        return result;
    }

    decodeObject(): any {
        const jsonStr = this.decodeString();
        try {
            return JSON.parse(jsonStr);
        } catch {
            return {};
        }
    }

    decodeBBox(): any {
        return {
            min_y: this.decodeF64(),
            max_y: this.decodeF64(),
            min_x: this.decodeF64(),
            max_x: this.decodeF64(),
        };
    }

    // --- Domain Specific Decoders ---

    decodeRegion(id: string): any {
        this.decodeString(); // Consume 'id' field in the stream
        return {
            id,
            parent_id: this.decodeOption(() => this.decodeString()),
            name: this.decodeString(),
            description: this.decodeOption(() => this.decodeString()),
        };
    }

    decodeLayer(id: string): any {
        this.decodeString(); // Consume 'id' field in the stream
        return {
            id,
            region_id: this.decodeString(),
            name: this.decodeString(),
            is_visible: (() => {
                this.checkBounds(1);
                return this.view.getUint8(this.offset++) === 1;
            })(),
        };
    }

    decodeFeatureGroup(id: string): any {
        this.decodeString(); // Consume 'id' field in the stream
        return {
            id,
            layer_id: this.decodeString(),
            parent_id: this.decodeOption(() => this.decodeString()),
            name: this.decodeString(),
            type: this.decodeString(),
            group_type: this.decodeString(),
            is_visible: (() => {
                this.checkBounds(1);
                return this.view.getUint8(this.offset++) === 1;
            })(),
            metadata: this.decodeOption(() => this.decodeString()),
        };
    }

    decodeFeature(id: string): any {
        this.decodeString(); // Consume 'id' field in the stream
        return {
            id,
            layer_id: this.decodeString(),
            group_id: this.decodeOption(() => this.decodeString()),
            name: this.decodeString(),
            geom_type: this.decodeString(),
            is_visible: (() => {
                this.checkBounds(1);
                return this.view.getUint8(this.offset++) === 1;
            })(),
            note: this.decodeString(),
            metadata: this.decodeString(),
            bbox: this.decodeOption(() => this.decodeBBox()),
            area: this.decodeOption(() => this.decodeF64()),
            length: this.decodeOption(() => this.decodeF64()),
            coordinates: this.decodeObject(),
            properties: this.decodeObject(),
        };
    }

    async decodeMapStateAsync(): Promise<any> {
        const regionsLen = this.decodeLength();
        console.log(`[Bincode] Decoding ${regionsLen} regions...`);
        const regions: Record<string, any> = {};
        for (let i = 0; i < regionsLen; i++) {
            const id = this.decodeString();
            regions[id] = this.decodeRegion(id);
        }
        console.log(`[Bincode] Regions offset: ${this.offset}`);

        const layersLen = this.decodeLength();
        const layers: Record<string, any> = {};
        for (let i = 0; i < layersLen; i++) {
            const id = this.decodeString();
            layers[id] = this.decodeLayer(id);
        }
        console.log(`[Bincode] Layers offset: ${this.offset}`);

        const groupsLen = this.decodeLength();
        const feature_groups: Record<string, any> = {};
        for (let i = 0; i < groupsLen; i++) {
            const id = this.decodeString();
            feature_groups[id] = this.decodeFeatureGroup(id);
        }
        console.log(`[Bincode] Groups offset: ${this.offset}`);

        const featuresLen = this.decodeLength();
        console.log(`[Bincode] Decoding ${featuresLen} features (chunked)...`);
        const features: Record<string, any> = {};

        const CHUNK_SIZE = 100;
        for (let i = 0; i < featuresLen; i++) {
            const id = this.decodeString();
            features[id] = this.decodeFeature(id);

            if (i > 0 && i % CHUNK_SIZE === 0) {
                await new Promise(resolve => setTimeout(resolve, 0));
            }
        }

        const settings = this.decodeObject();
        const lastEventId = this.decodeOption(() => this.decodeString());

        return {
            regions,
            layers,
            feature_groups,
            features,
            settings,
            lastEventId
        };
    }

    decodeMapState(): any {
        const regionsLen = this.decodeLength();
        const regions: Record<string, any> = {};
        for (let i = 0; i < regionsLen; i++) {
            const id = this.decodeString();
            regions[id] = this.decodeRegion(id);
        }

        const layersLen = this.decodeLength();
        const layers: Record<string, any> = {};
        for (let i = 0; i < layersLen; i++) {
            const id = this.decodeString();
            layers[id] = this.decodeLayer(id);
        }

        const groupsLen = this.decodeLength();
        const feature_groups: Record<string, any> = {};
        for (let i = 0; i < groupsLen; i++) {
            const id = this.decodeString();
            feature_groups[id] = this.decodeFeatureGroup(id);
        }

        const featuresLen = this.decodeLength();
        const features: Record<string, any> = {};
        for (let i = 0; i < featuresLen; i++) {
            const id = this.decodeString();
            features[id] = this.decodeFeature(id);
        }

        const settings = this.decodeObject();
        const lastEventId = this.decodeOption(() => this.decodeString());

        return {
            regions,
            layers,
            feature_groups,
            features,
            settings,
            lastEventId
        };
    }
}

import { MapState, FeatureState } from '@CONTRACT/types';
import { getFeatureDisplayType } from '@TOOL/utils/featureUtils';
import { formatToIntegerString } from '@TOOL/utils/featureMapping';

type FlattenFeatureOptions = {
  featureNumbers?: Record<string, string>;
};

/**
 * Safely truncates strings to avoid Excel/UI overflow
 */
export const safeTruncate = (val: any, limit: number = 30000) => {
  if (val === undefined || val === null) return 'N/A';
  let str = typeof val === 'string' ? val : JSON.stringify(val);
  if (str.length > limit) {
    return str.substring(0, limit) + "... (Dữ liệu quá dài)";
  }
  return str;
};

/**
 * System fields to exclude from prefixing in SPEC_ or Biz_
 */
export const SYSTEM_FIELDS = [
  'gis', 'media', 'business', 'ai', 'vertexMetadata',
  'description', 'status', 'display_order', 'stt', 'STT', 'note', 'notes',
  'technical_specs', 'properties', 'specs', 'type', 'icon', 'color', 'size'
];

/**
 * Standardizes flattening a feature into a row object for consistent use in Analysis and Export
 */
export const flattenFeature = (
  f: FeatureState,
  state: MapState,
  preParsedMetadata?: any,
  options?: FlattenFeatureOptions,
) => {

  let metadata: any = preParsedMetadata;
  if (!metadata) {
    try {
      metadata = typeof f.metadata === 'string' ? JSON.parse(f.metadata) : (f.metadata || {});
    } catch (e) {
      metadata = {};
    }
  }

  const group = f.group_id && state.feature_groups ? state.feature_groups[f.group_id] : null;
  const layer = group ? state.layers[group.layer_id] : null;
  const region = layer ? state.regions[layer.region_id] : null;
  const runtimeParentFeatureId = typeof metadata?.parent_feature_id === 'string'
    ? metadata.parent_feature_id
    : '';
  const parentFeature = runtimeParentFeatureId ? state.features?.[runtimeParentFeatureId] : null;
  let parentMetadata: any = {};

  if (parentFeature) {
    try {
      parentMetadata = typeof parentFeature.metadata === 'string'
        ? JSON.parse(parentFeature.metadata || '{}')
        : (parentFeature.metadata || {});
    } catch {
      parentMetadata = {};
    }
  }

  const normalizeSourceCoordinates = () => {
    if (typeof f.coordinates === 'string') {
      try {
        return JSON.stringify(JSON.parse(f.coordinates));
      } catch {
        return f.coordinates;
      }
    }
    return JSON.stringify(f.coordinates ?? null);
  };

  // Optimized key finding with basic caching for current object
  const findValue = (obj: any, targetKeys: string[]) => {
    if (!obj || typeof obj !== 'object') return null;
    const normalizedTargets = targetKeys.map(k => k.trim().normalize('NFC').toLowerCase());

    // Simple iteration but without excessive re-normalization if possible
    const keys = Object.keys(obj);
    for (let i = 0; i < keys.length; i++) {
      const key = keys[i];
      const normalizedKey = key.trim().normalize('NFC').toLowerCase();
      if (normalizedTargets.includes(normalizedKey)) {
        return obj[key];
      }
    }
    return null;
  };

  // 1. Core technical fields
  const sttKeys = ['STT', 'stt', 'Mã hiệu', 'Số hiệu', 'Mã', 'Mã hiệu (STT)'];
  const sttFromProps = findValue(f.properties, sttKeys);
  const sttFromMeta = findValue(metadata, sttKeys);
  const calculatedDisplayOrder = options?.featureNumbers?.[f.id] || '';
  const parentDisplayOrder = runtimeParentFeatureId
    ? (options?.featureNumbers?.[runtimeParentFeatureId] || '')
    : '';

  const row: any = {
    'id': f.id,
    'name': f.name,
    'display_order': formatToIntegerString(calculatedDisplayOrder || metadata.display_order || sttFromProps || sttFromMeta || ''),
    'icon': metadata.icon || f.properties?.icon || '',
    'group': group?.name || 'Unknown',
    'layer': layer?.name || 'Unknown',
    'region': region?.name || 'Unknown',
    'description': metadata.description || '',
    'status': metadata.status || 'N/A',
    'geom_type': getFeatureDisplayType(f, group?.type, group?.name), // Unified display type
    'technical_geom': f.geom_type,
    'is_visible': metadata.is_visible ?? f.is_visible ?? true,
    'length': f.length ?? '',
    'area': f.area ?? '',
    'source_feature_id': String(metadata.source_feature_id || f.id),
    'source_group_id': f.group_id || '',
    'source_group_type': group?.type || group?.group_type || '',
    'source_layer_id': layer?.id || f.layer_id || '',
    'source_region_id': region?.id || '',
    'source_parent_feature_id': String(metadata.source_parent_feature_id || runtimeParentFeatureId || ''),
    'source_coordinates': normalizeSourceCoordinates(),
    'source_technical_geom': f.geom_type,
    'source_icon': metadata.icon || '',
    'source_type': metadata.type || '',
    'parent_intersection_name': parentFeature?.name || '',
    'parent_intersection_display_order': parentDisplayOrder || parentMetadata.display_order || '',
  };

  // 2. Extract Latitude and Longitude
  try {
    const coords = typeof f.coordinates === 'string' ? JSON.parse(f.coordinates) : f.coordinates;
    if (Array.isArray(coords)) {
      if (f.geom_type === 'Point' || f.geom_type === 'POINT') {
        const p = Array.isArray(coords[0]) ? coords[0] : coords;
        row['latitude'] = p[1];
        row['longitude'] = p[0];
      }
      row['coordinates_summary'] = safeTruncate(coords, 500);
    }
  } catch (e) {
    // Silently ignore coord errors for flattening
  }

  // 3. Process root feature properties
  if (f.properties && typeof f.properties === 'object') {
    Object.assign(row, f.properties);
  }

  // 4. Process root metadata (custom fields)
  Object.entries(metadata).forEach(([key, val]) => {
    if (!SYSTEM_FIELDS.includes(key) && (typeof val !== 'object' || val === null)) {
      row[key] = val;
    }
  });

  // 5. Specific sub-objects
  const specFields = ['technical_specs', 'properties', 'specs'];
  specFields.forEach(field => {
    if (metadata[field] && typeof metadata[field] === 'object') {
      Object.assign(row, metadata[field]);
    }
  });

  // 6. GIS metadata
  if (metadata.gis && typeof metadata.gis === 'object') {
    Object.entries(metadata.gis).forEach(([key, val]) => {
      if (typeof val !== 'object' || val === null) {
        row[`GIS_${key}`] = val;
      }
    });
  }

  row['note'] = metadata.note || metadata.notes || '';

  return row;
};

import { DesignEventType } from '@CONTRACT/designTypes';
import { designLogic } from './designLogic';

export const cloneDesignEvent = <T extends DesignEventType>(event: T): T =>
  JSON.parse(JSON.stringify(event)) as T;

export const normalizeIncomingEvent = (incomingEvent: DesignEventType): DesignEventType => {
  const event = cloneDesignEvent(incomingEvent);

  if (event.type === 'update_metadata') {
    const payload = event.payload;
    const featureId = 'feature_id' in payload ? payload.feature_id : payload.featureId;
    return {
      type: 'FeatureUpdated',
      payload: {
        id: featureId,
        metadata:
          typeof payload.metadata === 'string'
            ? payload.metadata
            : JSON.stringify(payload.metadata),
      },
    } as DesignEventType;
  }

  return event;
};

export const enrichEventBeforeDispatch = (incomingEvent: DesignEventType): any => {
  const event = normalizeIncomingEvent(incomingEvent);

  // Default mapping rules based on event type prefix
  let entityType = 'feature';
  if (event.type.startsWith('Region')) entityType = 'region';
  else if (event.type.startsWith('Layer')) entityType = 'layer';
  else if (event.type.startsWith('FeatureGroup')) entityType = 'group';
  else if (event.type.startsWith('Fiber')) entityType = 'fiber';

  const payload = { ...(event.payload as any) };

  // Extract entityId
  let entityId =
    payload.id ||
    (payload as any).feature_id ||
    (payload as any).featureId ||
    (payload as any).circuit_id ||
    (payload as any).circuitId ||
    (payload as any).layerId ||
    (payload as any).regionId ||
    '';

  // Specialized logic for metadata updates
  const metadata =
    typeof payload.metadata === 'string'
      ? JSON.parse(payload.metadata || '{}')
      : payload.metadata || {};
  const geomType = (payload.geom_type || '').toUpperCase();

  if (payload.coordinates && (geomType === 'LINESTRING' || geomType === 'POLYLINE')) {
    const coords =
      typeof payload.coordinates === 'string'
        ? JSON.parse(payload.coordinates)
        : payload.coordinates;
    if (Array.isArray(coords) && coords.length >= 2) {
      let totalLength = 0;
      for (let i = 0; i < coords.length - 1; i++) {
        totalLength += designLogic.calculateDistance(coords[i], coords[i + 1]);
      }
      payload.metadata = JSON.stringify({
        ...metadata,
        lengthKm: totalLength,
      });
    }
  }

  // Return the format Rust expects: DesignEventPayload / EventEnvelope
  return {
    id:
      typeof crypto !== 'undefined'
        ? crypto.randomUUID()
        : Math.random().toString(36).substring(2) + Date.now().toString(36),
    entityId: String(entityId),
    entityType,
    eventType: event.type,
    payload,
  };
};

import { safeInvoke as invoke } from '../../implement/lib/tauri';
import { BincodeDecoder } from './bincodeDecoder';
import { MapState } from '@CONTRACT/types';
import { DesignBulkActionResponse } from '@CONTRACT/designTypes';

let latestInitializeRequestId = 0;
export const getLatestInitializeRequestId = () => latestInitializeRequestId;
export const incrementInitializeRequestId = () => ++latestInitializeRequestId;

export const invokeBincode = async (
  cmd: string,
  args: any,
  timeoutMs = 30000,
  retryCount = 2
): Promise<MapState> => {
  const attempt = async (remaining: number): Promise<MapState> => {
    const tIPC = performance.now();
    let timeoutId: any;

    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(
        () => reject(new Error(`IPC Timeout (${cmd}) after ${timeoutMs}ms`)),
        timeoutMs
      );
    });

    try {
      const invokePromise = invoke<any>(cmd, args);
      const res = await Promise.race([invokePromise, timeoutPromise]);
      if (timeoutId) clearTimeout(timeoutId);

      const tData = performance.now();
      let uint8: Uint8Array;

      if (res instanceof Uint8Array) {
        uint8 = res;
      } else if (res instanceof ArrayBuffer) {
        uint8 = new Uint8Array(res);
      } else if (Array.isArray(res)) {
        uint8 = new Uint8Array(res);
      } else if (res && typeof res === 'object' && 'streaming_url' in res) {
        const fetchResp = await fetch((res as any).streaming_url);
        const buffer = await fetchResp.arrayBuffer();
        uint8 = new Uint8Array(buffer);
      } else {
        uint8 = new Uint8Array(res as any);
      }

      const tDecode = performance.now();
      const decoder = new BincodeDecoder(uint8);
      const result = await decoder.decodeMapStateAsync();
      const tDone = performance.now();

      console.log(
        `[Timeline] invokeBincode('${cmd}'): DataRecv=${(tData - tIPC).toFixed(1)}ms, Decode=${(tDone - tDecode).toFixed(1)}ms, Total=${(tDone - tIPC).toFixed(1)}ms`
      );
      return result;
    } catch (err) {
      if (timeoutId) clearTimeout(timeoutId);
      if (remaining > 0) {
        console.warn(`[Sync] invokeBincode('${cmd}') Retry (remaining: ${remaining})...`);
        await new Promise((resolve) => setTimeout(resolve, 1000));
        return attempt(remaining - 1);
      }
      throw err;
    }
  };

  return attempt(retryCount);
};

let designRequestId = 0;
const UUID_V4_LOOSE_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
export const isUuidLike = (value: unknown): boolean =>
  typeof value === 'string' && UUID_V4_LOOSE_RE.test(value.trim());

const hash32 = (input: string, seed: number): number => {
  let h = seed >>> 0;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
};

const stableUuidFromString = (raw: string): string => {
  const s = String(raw ?? '').trim() || 'empty';
  const p1 = hash32(s, 0x811c9dc5).toString(16).padStart(8, '0');
  const p2 = hash32(`b:${s}`, 0x9747b28c).toString(16).padStart(8, '0');
  const p3 = hash32(`c:${s}`, 0x85ebca6b).toString(16).padStart(8, '0');
  const p4 = hash32(`d:${s}`, 0xc2b2ae35).toString(16).padStart(8, '0');
  const hex = `${p1}${p2}${p3}${p4}`.slice(0, 32).split('');
  hex[12] = '5';
  const v = parseInt(hex[16], 16);
  hex[16] = ((v & 0x3) | 0x8).toString(16);
  const full = hex.join('');
  return `${full.slice(0, 8)}-${full.slice(8, 12)}-${full.slice(12, 16)}-${full.slice(16, 20)}-${full.slice(20, 32)}`;
};

const withCompatArgs = <T extends Record<string, unknown>>(
  snake: T,
  camel: Record<string, unknown>
) => ({
  ...snake,
  ...camel,
});

const COLLAB_COORDINATOR_URL = import.meta.env.VITE_COLLAB_COORDINATOR_URL?.trim() || '';
const COLLAB_SHARED_SECRET = import.meta.env.VITE_COLLAB_SHARED_SECRET?.trim() || '';

export const isCollaborationCoordinatorEnabled = () => COLLAB_COORDINATOR_URL.length > 0;

const syncCursorKey = (projectId: string) => `pmp.collaboration.cursor.${projectId}`;

const getStoredSyncCursor = (projectId: string): number => {
  if (typeof localStorage === 'undefined') return 0;
  const raw = localStorage.getItem(syncCursorKey(projectId));
  const parsed = Number(raw);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0;
};

const setStoredSyncCursor = (projectId: string, seq: unknown) => {
  const parsed = Number(seq);
  if (typeof localStorage === 'undefined' || !Number.isFinite(parsed) || parsed <= 0) return;
  localStorage.setItem(syncCursorKey(projectId), String(parsed));
};

const postCoordinator = async <T>(action: string, request: Record<string, unknown>): Promise<T> => {
  const body = {
    action,
    secret: COLLAB_SHARED_SECRET || undefined,
    request,
  };

  const response = await invoke<T>('post_collaboration_json', {
    url: COLLAB_COORDINATOR_URL,
    body,
  });
  if (response) return response;

  const fetchResponse = await fetch(COLLAB_COORDINATOR_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!fetchResponse.ok) {
    throw new Error(`Coordinator ${fetchResponse.status}: ${await fetchResponse.text()}`);
  }
  return (await fetchResponse.json()) as T;
};

const stableBatchId = (projectId: string, requestId: number, events: any[]) =>
  stableUuidFromString(
    `sync-batch:${projectId}:${requestId}:${events
      .map((event) => `${event?.id ?? ''}:${event?.entity_id ?? ''}:${event?.eventType ?? event?.type ?? ''}`)
      .join('|')}`
  );

const normalizeCollaborativeEvent = (
  projectId: string,
  event: any,
  requestId: number,
  index: number,
  batchId: string
) => {
  if (!event || typeof event !== 'object') return event;
  const obj: any = { ...event };
  const payload = obj.payload && typeof obj.payload === 'object' ? { ...obj.payload } : {};
  const payloadBasis =
    payload.id ||
    payload.feature_id ||
    payload.featureId ||
    payload.circuit_id ||
    payload.circuitId ||
    obj.entity_id ||
    obj.entityId ||
    `${obj.eventType || obj.type || 'event'}:${index}`;

  const stableEntityId = isUuidLike(payloadBasis)
    ? payloadBasis
    : isUuidLike(obj.entity_id ?? obj.entityId)
    ? (obj.entity_id ?? obj.entityId)
    : stableUuidFromString(`entity:${projectId}:${payloadBasis}`);
  const stableEventId = isUuidLike(obj.id)
    ? obj.id
    : stableUuidFromString(`event:${batchId}:${index}:${payloadBasis}`);

  obj.id = stableEventId;
  obj.entity_id = stableEntityId;
  obj.entityId = stableEntityId;
  obj.project_id = projectId;
  obj.projectId = projectId;
  obj.request_id = requestId;
  obj.requestId = requestId;
  obj.batch_id = batchId;
  obj.batchId = batchId;
  obj.base_entity_version = Number(obj.base_entity_version ?? obj.baseEntityVersion ?? 1);
  obj.baseEntityVersion = obj.base_entity_version;
  obj.entity_version = Number(obj.entity_version ?? obj.entityVersion ?? 1);
  obj.entityVersion = obj.entity_version;
  obj.payload = payload;
  return obj;
};

export const invoke_design_event_batch = async (
  projectId: string | number,
  events: any[],
  retryCount = 2
): Promise<DesignBulkActionResponse> => {
  const projectIdStr = String(projectId);
  const effectiveProjectId = isUuidLike(projectIdStr)
    ? projectIdStr
    : stableUuidFromString(`project:${projectIdStr}`);
  const requestId = ++designRequestId;
  const batchId = stableBatchId(effectiveProjectId, requestId, events || []);
  const normalizedEvents = (events || []).map((ev: any, idx: number) =>
    normalizeCollaborativeEvent(effectiveProjectId, ev, requestId, idx, batchId)
  );
  const timeoutMs = 60000;

  const attempt = async (remaining: number): Promise<DesignBulkActionResponse> => {
    let timeoutId: any;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutId = setTimeout(() => reject(new Error(`IPC Timeout (${requestId})`)), timeoutMs);
    });

    const payload = withCompatArgs(
      {
        project_id: effectiveProjectId,
        events: normalizedEvents,
        request_id: requestId,
        batch_id: batchId,
      },
      {
        projectId: effectiveProjectId,
        events: normalizedEvents,
        requestId,
        batchId,
      }
    );

    const invokePromise = (isCollaborationCoordinatorEnabled()
      ? postCoordinator<DesignBulkActionResponse>('commitBatch', payload)
      : invoke<DesignBulkActionResponse>('invoke_design_event_batch', payload)
    ).then((response) => {
      if (timeoutId) clearTimeout(timeoutId);
      if (!response) {
        return {
          success: false,
          last_event_id: '',
          applied_events: [],
          side_effects: [],
        } as DesignBulkActionResponse;
      }
      setStoredSyncCursor(effectiveProjectId, (response as any).seqEnd ?? (response as any).serverSeqEnd);
      return response;
    });

    try {
      return await Promise.race([invokePromise, timeoutPromise]);
    } catch (err) {
      if (timeoutId) clearTimeout(timeoutId);
      if (remaining > 0) {
        console.warn(`[Sync] IPC Retry ${requestId} (remaining: ${remaining})...`);
        await new Promise((resolve) => setTimeout(resolve, 1000));
        return attempt(remaining - 1);
      }
      throw err;
    }
  };

  return attempt(retryCount);
};

export const pull_collaboration_events = async (
  projectId: string | number,
  limit = 100
): Promise<DesignBulkActionResponse & { seqEnd?: number; hasMore?: boolean }> => {
  if (!isCollaborationCoordinatorEnabled()) {
    return {
      success: true,
      last_event_id: '',
      applied_events: [],
      side_effects: [],
    };
  }

  const projectIdStr = String(projectId);
  const effectiveProjectId = isUuidLike(projectIdStr)
    ? projectIdStr
    : stableUuidFromString(`project:${projectIdStr}`);
  const afterSeq = getStoredSyncCursor(effectiveProjectId);
  const response = await postCoordinator<DesignBulkActionResponse & { seqEnd?: number; hasMore?: boolean }>(
    'pullEvents',
    {
      project_id: effectiveProjectId,
      projectId: effectiveProjectId,
      after_seq: afterSeq,
      afterSeq,
      limit,
    }
  );
  setStoredSyncCursor(effectiveProjectId, (response as any).seqEnd ?? afterSeq);
  return response;
};

