import { MapPin } from "lucide-react";
import { Intersection, PolylineIcon, CameraCCTV, CameraPTZ, CameraSpeed, CameraLPR } from '../../design/components/icons/MapIcons';
import { getParsedMetadata, safeString } from "./featureMetadata";

/**
 * Camera icon types
 */
export const CAMERA_ICONS = ['camera', 'cctv', 'ptz', 'speed', 'lpr'];

/**
 * Intersection icon identifier
 */
export const INTERSECTION_ICON = 'intersection';

/**
 * Display names for various object types
 */
export const DISPLAY_TYPES = {
    INTERSECTION: 'Nút giao',
    CCTV: 'CCTV',
    PTZ: 'PTZ',
    SPEED: 'SPEED',
    LPR: 'LPR',
    CABINET: 'Tủ thiết bị',
    PILLAR: 'Cột/Trụ',
    BRIDGE: 'Cầu/Hầm',
    POINT: 'Điểm',
    LINE: 'Tuyến',
    POLYGON: 'Vùng',
} as const;

/**
 * Checks if an icon key represents a camera
 */
export const isCameraIcon = (icon?: string): boolean => {
    if (!icon) return false;
    return CAMERA_ICONS.includes(icon.toLowerCase());
};

/**
 * Determines the display label for a feature based on its geometry and metadata
 */
export const getFeatureDisplayType = (feature: any, groupType?: string, groupName?: string, providedMetadata?: any): string => {
    if (!feature) return "N/A";

    const meta = providedMetadata || getParsedMetadata(feature);
    const geomType = (feature.geom_type || '').toUpperCase();
    const icon = (meta.icon || '').toLowerCase();
    const metaType = safeString(meta.type || '').toUpperCase();
    const lowerGType = (groupType || '').toLowerCase();
    const lowerGName = (groupName || '').toLowerCase();
    const lowerName = safeString(feature.name || '').toLowerCase();

    const isPoint = geomType === 'POINT' || geomType === '' || geomType === 'DEFAULT';

    if (isPoint) {
        if (icon === INTERSECTION_ICON) return DISPLAY_TYPES.INTERSECTION;
        if (isCameraIcon(icon)) {
            if (icon === 'ptz') return DISPLAY_TYPES.PTZ;
            if (icon === 'speed') return DISPLAY_TYPES.SPEED;
            if (icon === 'lpr') return DISPLAY_TYPES.LPR;
            return DISPLAY_TYPES.CCTV;
        }
        if (metaType) {
            if (metaType === 'INTERSECTION' || metaType === 'NUT_GIAO' || metaType === 'NÚT GIAO') return DISPLAY_TYPES.INTERSECTION;
            if (metaType === 'CAMERA' || metaType === 'CCTV' || metaType === 'MẮT CAM') return DISPLAY_TYPES.CCTV;
            if (metaType === 'SPEED') return DISPLAY_TYPES.SPEED;
            if (metaType === 'LPR') return DISPLAY_TYPES.LPR;
            if (metaType === 'PTZ') return DISPLAY_TYPES.PTZ;
        }
        if (metaType && DISPLAY_TYPES[metaType as keyof typeof DISPLAY_TYPES]) {
            return DISPLAY_TYPES[metaType as keyof typeof DISPLAY_TYPES];
        }

        if (['cabinet', 'box', 'server'].includes(icon)) return DISPLAY_TYPES.CABINET;
        if (['pillar', 'pole', 'tower'].includes(icon)) return DISPLAY_TYPES.PILLAR;
        if (['bridge', 'tunnel', 'gate'].includes(icon)) return DISPLAY_TYPES.BRIDGE;

        const isCamera = [lowerGType, lowerGName, lowerName].some(s =>
            s.includes('camera') || s.includes('cam') || s.includes('cctv') || s.includes('lpr') ||
            s.includes('mắt cam') || s.includes('giám sát') || s.includes('quan sát')
        );
        if (isCamera) {
            if (icon === 'ptz') return DISPLAY_TYPES.PTZ;
            if (icon === 'speed') return DISPLAY_TYPES.SPEED;
            if (icon === 'lpr') return DISPLAY_TYPES.LPR;
            return DISPLAY_TYPES.CCTV;
        }

        if (lowerGType.includes('intersection') || lowerGType.includes('nut_giao')) return DISPLAY_TYPES.INTERSECTION;

        const isCabinet = lowerGType.includes('cabinet') || lowerGType.includes('tu_thiet_bi') ||
            lowerGName.includes('tủ thiết bị') || lowerName.includes('tủ thiết bị') || lowerName.includes('tủ cáp');
        if (isCabinet) return DISPLAY_TYPES.CABINET;

        return DISPLAY_TYPES.POINT;
    }

    if (geomType === 'LINESTRING' || geomType === 'POLYLINE') return DISPLAY_TYPES.LINE;
    if (geomType === 'POLYGON') return DISPLAY_TYPES.POLYGON;

    return geomType || DISPLAY_TYPES.POINT;
};

/**
 * Returns complete display configuration for a feature (Icon, Color, Label)
 */
export const getFeatureDisplayInfo = (feature: any, groupType?: string, groupName?: string, providedMetadata?: any) => {
    const meta = providedMetadata || getParsedMetadata(feature);
    const displayType = getFeatureDisplayType(feature, groupType, groupName, meta);
    const iconKey = (meta.icon || 'default').toLowerCase();

    let IconComponent: any = MapPin;
    let colorClass = "text-indigo-400";

    const isLine = displayType === DISPLAY_TYPES.LINE;
    const isPolygon = displayType === DISPLAY_TYPES.POLYGON;

    if (isLine) {
        IconComponent = PolylineIcon;
        colorClass = "text-emerald-400";
    } else if (displayType === DISPLAY_TYPES.INTERSECTION) {
        IconComponent = Intersection;
        colorClass = "text-indigo-400";
    } else if (displayType === DISPLAY_TYPES.CCTV || displayType === DISPLAY_TYPES.PTZ || displayType === DISPLAY_TYPES.SPEED || displayType === DISPLAY_TYPES.LPR) {
        colorClass = "text-blue-400";
        if (displayType === DISPLAY_TYPES.PTZ || iconKey === 'ptz') IconComponent = CameraPTZ;
        else if (displayType === DISPLAY_TYPES.SPEED || iconKey === 'speed') IconComponent = CameraSpeed;
        else if (displayType === DISPLAY_TYPES.LPR || iconKey === 'lpr') IconComponent = CameraLPR;
        else IconComponent = CameraCCTV;
    } else if (displayType === DISPLAY_TYPES.CABINET) {
        colorClass = "text-orange-400";
    }

    return {
        label: displayType,
        tailwindColor: colorClass,
        color: meta.color || (isLine ? '#10b981' : '#6366f1'),
        icon: IconComponent,
        iconKey: iconKey,
        isIntersection: displayType === DISPLAY_TYPES.INTERSECTION,
        isCamera: displayType === DISPLAY_TYPES.CCTV || displayType === DISPLAY_TYPES.PTZ || displayType === DISPLAY_TYPES.SPEED || displayType === DISPLAY_TYPES.LPR,
        isLine,
        isPolygon,
        gType: (feature.geom_type || 'POINT').toUpperCase()
    };
};

/**
 * Maps display label back to icon configuration (used for summary tables)
 */
export const getIconByDisplayType = (displayType: string) => {
    let IconComponent: any = MapPin;
    let colorClass = "text-indigo-400";

    switch (displayType) {
        case DISPLAY_TYPES.LINE:
            IconComponent = PolylineIcon;
            colorClass = "text-emerald-400";
            break;
        case DISPLAY_TYPES.INTERSECTION:
            IconComponent = Intersection;
            colorClass = "text-indigo-400";
            break;
        case DISPLAY_TYPES.CCTV:
            IconComponent = CameraCCTV;
            colorClass = "text-blue-400";
            break;
        case DISPLAY_TYPES.PTZ:
            IconComponent = CameraPTZ;
            colorClass = "text-blue-400";
            break;
        case DISPLAY_TYPES.POLYGON:
            IconComponent = PolylineIcon;
            colorClass = "text-fuchsia-400";
            break;
        case DISPLAY_TYPES.CABINET:
            colorClass = "text-orange-400";
            break;
    }

    return { icon: IconComponent, color: colorClass };
};

/**
 * Checks if a feature represents a network connection link that lacks coordinates (and thus should be hidden).
 * Features with valid coordinates should remain visible in both the map and list views.
 */
export const isNetworkLinkFeature = (feature: any): boolean => {
    if (!feature) return false;

    // We only hide network features if they DO NOT have valid coordinates.
    let coords = feature.coordinates;
    while (typeof coords === 'string') {
        try {
            const parsed = JSON.parse(coords);
            if (parsed === coords) break;
            coords = parsed;
        } catch {
            break;
        }
    }

    const hasCoordinates = coords && (
        (Array.isArray(coords) && coords.length > 0) ||
        (typeof coords === 'object' && !Array.isArray(coords) && Object.keys(coords).length > 0)
    );

    // If it has coordinates, we do NOT hide it from the frontend views.
    if (hasCoordinates) return false;

    if (feature.geom_type === 'NetworkLink') return true;
    if (typeof feature.name === 'string' && (feature.name.startsWith('Tuyen Network Moi') || feature.name.startsWith('Tuyến Network Mới'))) return true;

    let metadata = feature.metadata;
    if (typeof metadata === 'string') {
        try {
            metadata = JSON.parse(metadata);
        } catch {
            metadata = null;
        }
    }
    if (metadata && typeof metadata === 'object') {
        if (metadata.network && typeof metadata.network === 'object') return true;
        if (metadata.infrastructure && typeof metadata.infrastructure === 'object' && metadata.infrastructure.type === 'NetworkLink') return true;
    }
    return false;
};

import { getParsedMetadata, safeString, getFeatureNote } from "./featureMetadata";
import { FeatureCoordinates, FeatureState, PointCoordinates, LineStringCoordinates, PolygonCoordinates } from "../../contract/types";

// Cache for parsed coordinates to avoid repeated JSON.parse in render cycles
const _coordsCache = new WeakMap<object, FeatureCoordinates>();
const _coordsStringCache = new Map<string, FeatureCoordinates>();
const COORDS_STRING_CACHE_MAX = 50000;

/**
 * Safely parses the coordinates from a feature
 */
export const getParsedCoordinates = (feature: FeatureState | { coordinates: unknown }): FeatureCoordinates => {
    if (!feature) return null;
    const coords = feature.coordinates;
    if (!coords) return null;

    // Fast path: already an array
    if (Array.isArray(coords)) return coords as FeatureCoordinates;

    // Check WeakMap cache (keyed by feature object identity)
    const cached = _coordsCache.get(feature as object);
    if (cached) return cached;

    const parseAndCache = (data: unknown): FeatureCoordinates => {
        if (!data) return null;
        if (Array.isArray(data)) {
            _coordsCache.set(feature as object, data as FeatureCoordinates);
            return data as FeatureCoordinates;
        }

        // Handle Object format from Rust (e.g. { "points": [...] } or { "coordinates": [...] })
        if (typeof data === 'object') {
            const obj = data as Record<string, unknown>;
            const inner = obj.points || obj.coordinates || obj.coords;
            if (Array.isArray(inner)) {
                _coordsCache.set(feature as object, inner as FeatureCoordinates);
                return inner as FeatureCoordinates;
            }
        }

        if (typeof data === 'string') {
            const trimmed = data.trim();
            if (!trimmed) return null;

            if (_coordsStringCache.has(trimmed)) {
                const cached = _coordsStringCache.get(trimmed);
                if (cached !== undefined) {
                    _coordsCache.set(feature as object, cached);
                    return cached;
                }
            }

            try {
                let cleanStr = trimmed;
                if (cleanStr.startsWith('"') && cleanStr.endsWith('"')) {
                    try {
                        const inner = JSON.parse(cleanStr);
                        if (Array.isArray(inner)) {
                            _coordsCache.set(feature, inner);
                            return inner;
                        }
                        if (typeof inner === 'object' && inner !== null) {
                            const innerData = inner.points || inner.coordinates || inner.coords;
                            if (Array.isArray(innerData)) {
                                _coordsCache.set(feature, innerData);
                                return innerData;
                            }
                        }
                        if (typeof inner === 'string') cleanStr = inner.trim();
                    } catch {
                        cleanStr = cleanStr.slice(1, -1).trim();
                    }
                }

                const parsed = JSON.parse(cleanStr);
                const result = Array.isArray(parsed) ? parsed : (
                    (typeof parsed === 'object' && parsed !== null) ? (parsed.points || parsed.coordinates || parsed.coords) : null
                );

                if (Array.isArray(result)) {
                    _coordsCache.set(feature, result);
                    if (_coordsStringCache.size < COORDS_STRING_CACHE_MAX) _coordsStringCache.set(trimmed, result);
                    return result;
                }
            } catch (e) {
                console.error('[featureMapping] Coordinate parse error:', e, 'for raw:', data);
            }
        }
        return null;
    };

    return parseAndCache(coords);
};

const isNumber = (value: unknown): value is number =>
    typeof value === 'number' && Number.isFinite(value);

const isPointTuple = (value: unknown): value is PointCoordinates =>
    Array.isArray(value) && value.length >= 2 && isNumber(value[0]) && isNumber(value[1]);

const toPointTuple = (value: unknown): PointCoordinates | null => {
    if (isPointTuple(value)) return [value[0], value[1]];
    if (value && typeof value === 'object') {
        const point = value as Record<string, unknown>;
        if (isNumber(point.lng) && isNumber(point.lat)) return [point.lng, point.lat];
        if (isNumber(point.x) && isNumber(point.y)) return [point.x, point.y];
    }
    return null;
};

export const getPointCoordinates = (feature: FeatureState | { coordinates: unknown } | null | undefined): PointCoordinates | null => {
    if (!feature) return null;
    const coords = getParsedCoordinates(feature);
    return toPointTuple(coords);
};

export const getLineCoordinates = (feature: FeatureState | { coordinates: unknown } | null | undefined): LineStringCoordinates | null => {
    if (!feature) return null;
    const coords = getParsedCoordinates(feature);
    if (!Array.isArray(coords)) return null;
    if (coords.every((item) => isPointTuple(item))) {
        return coords as LineStringCoordinates;
    }
    return null;
};

export const getPolygonCoordinates = (feature: FeatureState | { coordinates: unknown } | null | undefined): PolygonCoordinates | null => {
    if (!feature) return null;
    const coords = getParsedCoordinates(feature);
    if (!Array.isArray(coords)) return null;
    if (coords.every((ring) => Array.isArray(ring) && ring.every((point) => isPointTuple(point)))) {
        return coords as PolygonCoordinates;
    }
    return null;
};

export const getRepresentativePoint = (feature: FeatureState | { coordinates: unknown } | null | undefined): PointCoordinates | null => {
    if (!feature) return null;
    return (
        getPointCoordinates(feature) ||
        getLineCoordinates(feature)?.[0] ||
        getPolygonCoordinates(feature)?.[0]?.[0] ||
        null
    );
};

/**
 * Safely converts any value to an integer string if it's a number,
 * otherwise returns trimmed string. Used for STT/Display Order.
 */
export const formatToIntegerString = (val: unknown): string => {
    if (val === undefined || val === null || val === '') return "";
    const s = String(val as any).trim();
    if (s === 'Data::Empty') return "";

    // Special Case: Junction Numbering (e.g. 15_1, 192_4)
    // We should preserve these as-is if they match the numeric hierarchy pattern
    if (/^\d+(_\d+)+$/.test(s)) {
        return s;
    }

    // If it looks like a number (including 193.0), parse and floor it
    const num = parseFloat(s);
    if (!isNaN(num) && isFinite(num)) {
        return Math.floor(num).toString();
    }
    return s;
};

/**
 * Removes STT prefix from feature names for cleaner display
 */
export const getCleanName = (feature: FeatureState | { name: unknown }, stt?: string): string => {
    const name = safeString(feature.name);
    if (!stt || stt === '0') return name;

    const s = stt.trim();
    const n = name.trim();

    const normalizeForMatch = (val: string) => val.replace(/^0+/, '').replace(/\.0+$/, '').replace(/[.:-]+$/, '');
    const sNorm = normalizeForMatch(s);
    const nNorm = normalizeForMatch(n);

    if (sNorm && (n.startsWith(s) || n.startsWith(sNorm) || nNorm.startsWith(sNorm))) {
        // Find how much of the original name to cut
        let prefixToCut = "";
        if (n.startsWith(s)) prefixToCut = s;
        else if (n.startsWith(sNorm)) prefixToCut = sNorm;
        else {
            // Check if name has something like "193.0 ..." but sNorm is "193"
            const match = n.match(/^(\d+\.0+)/);
            if (match && normalizeForMatch(match[1]) === sNorm) {
                prefixToCut = match[1];
            }
        }

        if (prefixToCut) {
            let rest = n.slice(prefixToCut.length).trim();
            while (rest.startsWith('.') || rest.startsWith('-') || rest.startsWith(':') || rest.startsWith(' ')) {
                rest = rest.slice(1).trim();
            }
            if (rest) return rest;
        }
    }

    return name;
};

/**
 * Removes Vietnamese tones for non-accented search
 */
export const removeVietnameseTones = (str: string): string => {
    if (!str) return "";
    str = str.replace(/à|á|ạ|ả|ã|â|ầ|ấ|ậ|ẩ|ẫ|ă|ằ|ắ|ặ|ẳ|ẵ/g, "a");
    str = str.replace(/è|é|ẹ|ẻ|ẽ|ê|ề|ế|ệ|ể|ễ/g, "e");
    str = str.replace(/ì|í|ị|ỉ|ĩ/g, "i");
    str = str.replace(/ò|ó|ọ|ỏ|õ|ô|ồ|ố|ộ|ổ|ỗ|ơ|ờ|ớ|ợ|ở|ỡ/g, "o");
    str = str.replace(/ù|ú|ụ|ủ|ũ|ư|ừ|ứ|ự|ử|ữ/g, "u");
    str = str.replace(/ỳ|ý|ỵ|ỷ|ỹ/g, "y");
    str = str.replace(/đ/g, "d");
    str = str.replace(/À|Á|Ạ|Ả|Ã|Â|Ầ|Ấ|Ậ|Ẩ|Ẫ|Ă|Ằ|Ắ|Ặ|Ẳ|Ẵ/g, "A");
    str = str.replace(/È|É|Ẹ|Ẻ|Ẽ|Ê|Ề|Ế|Ệ|Ể|Ễ/g, "E");
    str = str.replace(/Ì|Í|Ị|Ỉ|Ĩ/g, "I");
    str = str.replace(/Ò|Ó|Ọ|Ỏ|Õ|Ô|Ồ|Ố|Ộ|Ổ|Ỗ|Ơ|Ờ|Ớ|Ợ|Ở|Ỡ/g, "O");
    str = str.replace(/Ù|Ú|Ụ|Ủ|Ũ|Ư|Ừ|Ứ|Ự|Ử|Ữ/g, "U");
    str = str.replace(/Ỳ|Ý|Ỵ|Ỷ|Ỹ/g, "Y");
    str = str.replace(/Đ/g, "D");
    str = str.replace(/\u0300|\u0301|\u0303|\u0309|\u0323/g, "");
    str = str.replace(/\u02C6|\u0306|\u031B/g, "");
    return str.replace(/ + /g, " ").trim();
};

/**
 * Calculates display sequence numbers for features
 */
type FeaturesMapType = Record<string, FeatureState | { metadata: unknown; group_id?: string | null }>;
type OrderMetadata = Record<string, unknown>;

const normalizeOrderKey = (key: string): string =>
    key
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '');

const ORDER_FIELD_KEYS = new Set([
    'stt',
    'mahieu',
    'mahieustt',
    'sohieu',
    'ma',
    'matuyenduong',
    'mahieudoituong',
    'index',
    'order',
    'code',
]);

export const isOrderAliasKey = (key: string): boolean => {
    if (key === 'display_order') return false;
    return ORDER_FIELD_KEYS.has(normalizeOrderKey(key));
};

const asObject = (value: unknown): OrderMetadata | null =>
    value && typeof value === 'object' && !Array.isArray(value) ? value as OrderMetadata : null;

export const getDeclaredOrderFieldKey = (
    metadata?: OrderMetadata | null,
    properties?: OrderMetadata | null
): string | undefined => {
    const meta = asObject(metadata);
    const props = asObject(properties);
    const sourceProperties = asObject(meta?.source_properties);
    const candidates = [meta, sourceProperties, props];

    for (const candidate of candidates) {
        if (!candidate) continue;
        const key = Object.keys(candidate).find(isOrderAliasKey);
        if (key) return key;
    }

    return undefined;
};

export const syncDisplayOrderAliases = (
    metadata: OrderMetadata,
    displayOrder?: unknown,
    properties?: OrderMetadata | null
): OrderMetadata => {
    const next = { ...(metadata || {}) };
    const orderValue = formatToIntegerString(
        displayOrder ?? next.display_order ?? next.stt ?? next.STT ?? next.order ?? ''
    );

    if (!orderValue) return next;

    next.display_order = orderValue;
    const declaredKey = getDeclaredOrderFieldKey(next, properties);
    if (declaredKey && declaredKey !== 'display_order') {
        next[declaredKey] = orderValue;
    }

    return next;
};

export const calculateFeatureNumbers = (features: FeatureState[], featuresMap: FeaturesMapType): Record<string, string> => {
    const sortedFeatures = [...features].sort((a: FeatureState, b: FeatureState) => {
        return String(a.id || '').localeCompare(String(b.id || ''), undefined, { numeric: true, sensitivity: 'base' });
    });

    const featureNumberMap: Record<string, string> = {};
    const parentSequenceMap: Record<string, number> = {};
    const groupSequenceMap: Record<string, number> = {};

    // Helper to resolve STT for a feature, ensuring its parent is resolved first
    const getOrResolveSTT = (fId: string): string => {
        if (featureNumberMap[fId]) return featureNumberMap[fId];

        const f = featuresMap[fId];
        if (!f) return "";

        const meta = getParsedMetadata(f);
        let sttValue = meta.display_order || meta.stt || meta.STT || (meta as Record<string, unknown>).order;

        // If explicitly set, use it (but still format it)
        if (sttValue) {
            const formatted = formatToIntegerString(sttValue);
            if (formatted !== "") {
                featureNumberMap[fId] = formatted;
                return formatted;
            }
        }

        // Fallback: Check parent hierarchy
        const parentId = meta.parent_feature_id as string | undefined;
        if (parentId && featuresMap[parentId]) {
            const parentSTT = getOrResolveSTT(parentId);

            if (!parentSequenceMap[parentId]) parentSequenceMap[parentId] = 0;
            parentSequenceMap[parentId]++;

            const result = `${parentSTT}_${parentSequenceMap[parentId]}`;
            featureNumberMap[fId] = result;
            return result;
        } else {
            // Default: Root level sequencing by group
            const groupId = (f.group_id as string) || "default";
            if (!groupSequenceMap[groupId]) groupSequenceMap[groupId] = 0;
            groupSequenceMap[groupId]++;

            const result = `${groupSequenceMap[groupId]}`;
            featureNumberMap[fId] = result;
            return result;
        }
    };

    // Process all features in sorted order to maintain stable sequence numbers
    sortedFeatures.forEach(f => getOrResolveSTT(f.id));

    return featureNumberMap;
};

export const getNextFeatureDisplayOrder = (
    featuresMap: FeaturesMapType,
    groupId: string | null | undefined,
    parentFeatureId?: string | null
): string => {
    const features = Object.entries(featuresMap)
        .map(([id, feature]) => ({ id, ...feature } as FeatureState))
        .sort((a, b) => String(a.id || '').localeCompare(String(b.id || ''), undefined, { numeric: true, sensitivity: 'base' }));
    const currentNumbers = calculateFeatureNumbers(features, featuresMap);

    if (parentFeatureId && featuresMap[parentFeatureId]) {
        const parentNumber = currentNumbers[parentFeatureId] || "1";
        const prefix = `${parentNumber}_`;
        const maxChildNumber = features.reduce((max, feature) => {
            const meta = getParsedMetadata(feature);
            if (meta.parent_feature_id !== parentFeatureId) return max;

            const displayNumber = currentNumbers[feature.id] || "";
            if (!displayNumber.startsWith(prefix)) return max;

            const childNumber = Number.parseInt(displayNumber.slice(prefix.length), 10);
            return Number.isFinite(childNumber) ? Math.max(max, childNumber) : max;
        }, 0);

        return `${parentNumber}_${maxChildNumber + 1}`;
    }

    const maxRootNumber = features.reduce((max, feature) => {
        if ((feature.group_id || null) !== (groupId || null)) return max;

        const meta = getParsedMetadata(feature);
        if (meta.parent_feature_id) return max;

        const displayNumber = currentNumbers[feature.id] || "";
        if (!/^\d+$/.test(displayNumber)) return max;

        return Math.max(max, Number.parseInt(displayNumber, 10));
    }, 0);

    return `${maxRootNumber + 1}`;
};

/**
 * Checks if a feature matches the search query
 */
export const isMatchSearch = (
    feature: { name: unknown; id: string; metadata?: unknown },
    query: string,
    featureNumbers?: Record<string, string>
): boolean => {
    if (!query) return false;
    const qOrig = query.toLowerCase().trim();
    const qNoTone = removeVietnameseTones(qOrig);

    const checkMatch = (val: unknown) => {
        if (!val) return false;
        const s = safeString(val).toLowerCase();
        return s.includes(qOrig) || removeVietnameseTones(s).includes(qNoTone);
    };

    if (checkMatch(feature.name) || checkMatch(feature.id)) return true;
    if (featureNumbers && featureNumbers[feature.id] && checkMatch(featureNumbers[feature.id])) return true;

    const meta = getParsedMetadata(feature);
    const sttValues = [
        meta.display_order, meta.stt, meta.STT, meta.code, meta.label, meta.type,
        meta['MÃ HIỆU (STT)'], meta['Mã hiệu (STT)'], meta['mã hiệu (stt)']
    ];

    for (const val of sttValues) {
        if (checkMatch(val)) return true;
    }

    if (checkMatch(getFeatureNote(feature))) return true;

    return false;
};

/**
 * Calculates points for a FOV (Field Of View) cone polygon
 * @param center [lng, lat]
 * @param radius distance in meters
 * @param rotation center angle in degrees (North is 0, clockwise)
 * @param fovAngle opening angle in degrees
 */
export const calculateFOVPoints = (center: [number, number], radius: number, rotation: number, fovAngle: number): [number, number][] => {
    if (!center || center.length < 2) return [];

    const [lng, lat] = center;
    const points: [number, number][] = [[lat, lng]]; // Leaflet uses [lat, lng]

    // Apply +90 offset because 0 degrees in compass math is North, 
    // but icons are now aligned to point East (Right) at 0 UI rotation.
    const effectiveRotation = rotation + 90;
    const startAngle = effectiveRotation - fovAngle / 2;
    const endAngle = effectiveRotation + fovAngle / 2;
    const steps = 20; // Number of points to approximate the arc

    // Approximation for meters to degrees
    // 1 degree latitude ~= 111,320 meters
    // 1 degree longitude ~= 111,320 * cos(lat) meters
    const latOffsetPerMeter = 1 / 111319.9;
    const lngOffsetPerMeter = 1 / (111319.9 * Math.cos(lat * Math.PI / 180));

    for (let i = 0; i <= steps; i++) {
        const currentAngle = startAngle + (endAngle - startAngle) * (i / steps);
        // Compass coordinate system: 0 is North (up), increases clockwise
        // Math coordinate system: 0 is East (right), increases counter-clockwise
        // math_angle = 90 - compass_angle
        const rad = (90 - currentAngle) * Math.PI / 180;

        const pLat = lat + (radius * latOffsetPerMeter) * Math.sin(rad);
        const pLng = lng + (radius * lngOffsetPerMeter) * Math.cos(rad);
        points.push([pLat, pLng]);
    }

    points.push([lat, lng]); // Close the polygon back to center
    return points;
};

/**
 * Finds the nearest road segment and calculates the angle for the camera to face it.
 * AI feature for auto-rotation.
 * @param point [lng, lat] of the camera
 * @param features all features to search for roads (polylines)
 * @returns angle in degrees (0 = North) or null if no roads found
 */
export const calculateNearestRoadAngle = (point: [number, number], features: FeatureState[]): number | null => {
    if (!point || point.length < 2 || !features || features.length === 0) return null;

    const [pLng, pLat] = point;
    const roads = features.filter(f =>
        (f.geom_type || '').toUpperCase() === 'LINESTRING' ||
        (f.geom_type || '').toUpperCase() === 'POLYLINE'
    );

    if (roads.length === 0) return null;

    let minDistanceSq = Infinity;
    let selectedAngle = null;

    // Approximation for meters
    const latScale = 111319.9;
    const lngScale = 111319.9 * Math.cos(pLat * Math.PI / 180);

    for (const road of roads) {
        const coords = getParsedCoordinates(road);
        if (!coords || !Array.isArray(coords) || coords.length < 2) continue;

        for (let i = 0; i < coords.length - 1; i++) {
            const p1 = coords[i];
            const p2 = coords[i + 1];

            if (!Array.isArray(p1) || !Array.isArray(p2)) continue;

            const [x1, y1] = p1 as [number, number];
            const [x2, y2] = p2 as [number, number];

            // Convert everything to local Cartesian meters relative to point
            const dx1 = (x1 - pLng) * lngScale;
            const dy1 = (y1 - pLat) * latScale;
            const dx2 = (x2 - pLng) * lngScale;
            const dy2 = (y2 - pLat) * latScale;

            // Distance from (0,0) to segment
            const l2 = (dx2 - dx1) ** 2 + (dy2 - dy1) ** 2;
            let t = ((-dx1) * (dx2 - dx1) + (-dy1) * (dy2 - dy1)) / l2;
            t = Math.max(0, Math.min(1, t));
            const distSq = (-(dx1 + t * (dx2 - dx1))) ** 2 + (-(dy1 + t * (dy2 - dy1))) ** 2;

            if (distSq < minDistanceSq) {
                minDistanceSq = distSq;

                // Angle of the road segment
                const segmentAngleRad = Math.atan2(dy2 - dy1, dx2 - dx1);
                const segmentAngleDeg = segmentAngleRad * 180 / Math.PI;

                // Compass heading (0 North, clockwise): 90 - math_deg
                const roadHeading = (90 - segmentAngleDeg + 360) % 360;

                // Parallel orientation:
                // We have two choices: roadHeading or roadHeading + 180.
                // For now, let's pick the one that points "forward" along the road vector
                // or just pick the base roadHeading.
                selectedAngle = roadHeading;
            }
        }
    }

    // Threshold: only rotate if within 200 meters
    if (minDistanceSq > 200 * 200) return null;

    return selectedAngle !== null ? Math.round(selectedAngle) : null;
};

/**
 * Metadata Utility functions for Features.
 * Handles parsing, caching, and retrieving metadata values.
 */

import { FeatureState, FeatureProperties } from '@CONTRACT/types';

type ParsedMetadata = Record<string, unknown>;
type MetadataCarrier = { metadata?: unknown; properties?: FeatureProperties };

// Cache to avoid repeated JSON parsing
const metadataCache = new Map<string, ParsedMetadata>();

/**
 * Ensures the value is a string, handles specialized object cases (like Protobuf {@type, value})
 */
export const safeString = (value: unknown): string => {
    if (value === null || value === undefined) return "";
    if (typeof value === 'string') return value;

    if (typeof value === 'object') {
        const obj = value as Record<string, unknown>;
        if (obj.value !== undefined && obj.value !== null) {
            return safeString(obj.value);
        }
        try {
            if (Object.keys(obj).length === 0) return "";
            return JSON.stringify(obj);
        } catch {
            return "[Object]";
        }
    }

    return String(value as any);
};

/**
 * Safely parses feature metadata
 */
export const getParsedMetadata = (feature: FeatureState | MetadataCarrier | null | undefined): ParsedMetadata => {
    if (!feature) return {};
    const metaStr = feature.metadata;
    if (!metaStr) return {};
    if (typeof metaStr !== 'string') return metaStr as ParsedMetadata;

    // Cache by the actual metadata string, not by length.
    // Using length caused stale metadata when two different JSON payloads had the same size,
    // which made the second save appear to "not sync" in the map and Project Explorer.
    const cacheKey = `m::${metaStr}`;
    const cached = metadataCache.get(cacheKey);
    if (cached !== undefined) return cached;

    try {
        let cleanStr = metaStr.trim();

        // Handle double-quoted JSON strings (common in some bridge/serialization cases)
        if (cleanStr.startsWith('"') && cleanStr.endsWith('"') && cleanStr.length > 2) {
            try {
                const inner = JSON.parse(cleanStr);
                if (typeof inner === 'object' && inner !== null) {
                    metadataCache.set(cacheKey, inner);
                    return inner;
                }
                if (typeof inner === 'string') {
                    cleanStr = inner.trim();
                }
            } catch { /* ignore */ }
        }

        if (!cleanStr || cleanStr === 'null' || cleanStr === 'undefined') return {};

        const parsed = JSON.parse(cleanStr);

        // Final safety check: if parsed is null (valid JSON but not what we want), return {}
        if (parsed === null || typeof parsed !== 'object') {
            return {};
        }

        metadataCache.set(cacheKey, parsed);

        // Efficient cache eviction (FIFO)
        if (metadataCache.size > 5000) {
            const firstKey = metadataCache.keys().next().value;
            if (firstKey) metadataCache.delete(firstKey);
        }

        return parsed;
    } catch (e) {
        // Only log if it's not a trivially empty or standard null-like string
        if (metaStr && metaStr !== 'null' && metaStr !== 'undefined' && metaStr !== '{}') {
            console.warn(`[Metadata] Failed to parse: "${metaStr.substring(0, 100)}${metaStr.length > 100 ? '...' : ''}"`, e);
        }
        return {};
    }
};

/**
 * Gets a value from metadata supporting nested paths (e.g. gis.abc) and legacy fallbacks
 */
export const getFeatureMetadataValue = (
    feature: FeatureState | MetadataCarrier | null | undefined,
    path: string,
    legacyKey?: string,
    providedMetadata?: ParsedMetadata
): unknown => {
    const meta = providedMetadata || getParsedMetadata(feature);
    if (!meta) return undefined;

    const parts = path.split('.');
    let current: unknown = meta;
    for (const part of parts) {
        if (current === undefined || current === null || typeof current !== 'object') {
            current = undefined;
            break;
        }
        current = (current as Record<string, unknown>)[part];
    }

    if (current !== undefined && current !== null && current !== '') return current;

    if (legacyKey && meta[legacyKey] !== undefined && meta[legacyKey] !== null && meta[legacyKey] !== '') {
        return meta[legacyKey];
    }

    return undefined;
};

/**
 * Retrieves notes from metadata using various common field names
 */
export const getFeatureNote = (feature: FeatureState | MetadataCarrier | null | undefined): string => {
    const meta = getParsedMetadata(feature);
    const rawNote = meta.description || meta.notes || meta.ghi_chu || meta.note || "";
    return safeString(rawNote);
};
/**
 * Retrieves the effective mounting height for a feature, prioritizing feature metadata,
 * then project settings, and finally a hardcoded default.
 */
type ProjectSettings = Record<string, unknown>;

export const getEffectiveMountingHeight = (
    feature: FeatureState | MetadataCarrier | null | undefined,
    settings?: ProjectSettings,
    providedMetadata?: ParsedMetadata
): number => {
    if (!feature) return parseFloat((settings?.default_install_height as number | string | undefined)?.toString() ?? '3.5');

    // 1. Feature specific metadata
    const featureHeight = getFeatureMetadataValue(feature, 'specs.install_height', 'installHeight', providedMetadata);
    if (featureHeight !== undefined && featureHeight !== null && featureHeight !== '') {
        return parseFloat(String(featureHeight as any));
    }

    // 2. Project global setting
    if (settings?.default_install_height !== undefined && settings?.default_install_height !== null) {
        return parseFloat(String(settings.default_install_height as any));
    }

    // 3. Last resort fallback
    return 3.5;
};

/**
 * Retrieves the effective camera specifications for a feature, prioritizing feature metadata,
 * then project's camera presets based on feature type, and finally hardcoded defaults.
 */
type CameraPresets = Record<string, {
    focal_length?: number;
    sensor_size?: string;
    resolution_x?: number;
    resolution_y?: number;
}>;

export const getEffectiveCameraSpecs = (
    feature: FeatureState | MetadataCarrier | null | undefined,
    settings?: ProjectSettings & { camera_presets?: CameraPresets },
    providedMetadata?: ParsedMetadata
): { focalLength: number, sensorSize: string, resolutionX: number, resolutionY: number } => {
    if (!feature) {
        const preset = settings?.camera_presets?.['default'];
        return {
            focalLength: preset?.focal_length ?? 3.6,
            sensorSize: preset?.sensor_size ?? '1/3"',
            resolutionX: preset?.resolution_x ?? 1920,
            resolutionY: preset?.resolution_y ?? 1080
        };
    }

    const meta = providedMetadata || getParsedMetadata(feature);
    const iconKey = typeof feature?.properties?.iconKey === 'string' ? feature.properties.iconKey : 'default';
    const type = (meta.type as string) || iconKey || 'default';
    const preset = settings?.camera_presets?.[type] || settings?.camera_presets?.['default'];

    return {
        focalLength: parseFloat(String((getFeatureMetadataValue(feature, 'specs.focal_length', 'focalLength', providedMetadata) ?? preset?.focal_length ?? 3.6) as any)),
        sensorSize: (getFeatureMetadataValue(feature, 'specs.sensor_size', 'sensorSize', providedMetadata) as string) ?? preset?.sensor_size ?? '1/3"',
        resolutionX: parseInt(String((getFeatureMetadataValue(feature, 'specs.resolution_x', 'resolutionX', providedMetadata) ?? preset?.resolution_x ?? 1920) as any)),
        resolutionY: parseInt(String((getFeatureMetadataValue(feature, 'specs.resolution_y', 'resolutionY', providedMetadata) ?? preset?.resolution_y ?? 1080) as any))
    };
};

import type { FeatureCoordinates, FeatureMetadata, FeatureProperties, IconType } from '@CONTRACT/types';
import { syncDisplayOrderAliases } from './featureMapping';

type FeaturePayloadBase = {
  id: string;
  layer_id: string;
  group_id: string | null;
  name: string;
  geom_type: string;
};

type FeatureCreatePayloadInput = FeaturePayloadBase & {
  coordinates: FeatureCoordinates;
  metadata: FeatureMetadata;
  properties?: FeatureProperties;
};

const getNormalizedIcon = (icon: unknown): IconType => {
  switch (icon) {
    case 'cctv':
    case 'ptz':
    case 'speed':
    case 'lpr':
    case 'intersection':
      return icon;
    default:
      return 'default';
  }
};

export const getTypeForIcon = (icon: IconType): string => {
  switch (icon) {
    case 'cctv':
      return 'cctv';
    case 'ptz':
      return 'ptz';
    case 'speed':
      return 'speed';
    case 'lpr':
      return 'lpr';
    case 'intersection':
      return 'intersection';
    default:
      return 'point';
  }
};

export const normalizeFeatureMetadataForPersistence = (
  metadata: FeatureMetadata,
  properties?: FeatureProperties
): FeatureMetadata => {
  const normalizedIcon = getNormalizedIcon(metadata.icon);
  const nextType = typeof metadata.type === 'string' && metadata.type ? metadata.type : getTypeForIcon(normalizedIcon);

  return syncDisplayOrderAliases(
    {
      ...metadata,
      icon: normalizedIcon,
      type: nextType,
    },
    metadata.display_order ?? metadata.stt ?? metadata.STT,
    properties as Record<string, unknown> | undefined,
  ) as FeatureMetadata;
};

export const buildFeaturePropertiesForPersistence = (
  properties: FeatureProperties | undefined,
  metadata: FeatureMetadata
): FeatureProperties => {
  const normalizedMetadata = normalizeFeatureMetadataForPersistence(metadata, properties);
  const nextIcon = getNormalizedIcon(normalizedMetadata.icon);
  const nextType = typeof normalizedMetadata.type === 'string' && normalizedMetadata.type
    ? normalizedMetadata.type
    : getTypeForIcon(nextIcon);

  return {
    ...(properties || {}),
    icon: nextIcon,
    iconKey: nextIcon,
    type: nextType,
  };
};

export const buildFeatureCreatedPayload = ({
  id,
  layer_id,
  group_id,
  name,
  geom_type,
  coordinates,
  metadata,
  properties,
}: FeatureCreatePayloadInput) => {
  const normalizedMetadata = normalizeFeatureMetadataForPersistence(metadata, properties);
  const nextProperties = buildFeaturePropertiesForPersistence(properties, normalizedMetadata);

  return {
    id,
    layer_id,
    group_id,
    name,
    geom_type,
    coordinates: JSON.stringify(coordinates),
    metadata: JSON.stringify(normalizedMetadata),
    properties: nextProperties,
  };
};

export const isRenderableFeatureGeometry = (geomType: string | null | undefined, coordinates: FeatureCoordinates): boolean => {
  const normalizedGeomType = String(geomType || 'Point').toLowerCase();

  if (normalizedGeomType === 'point' || normalizedGeomType === 'default') {
    return Array.isArray(coordinates)
      && coordinates.length >= 2
      && Number.isFinite(Number(coordinates[0]))
      && Number.isFinite(Number(coordinates[1]));
  }

  if (normalizedGeomType === 'linestring' || normalizedGeomType === 'polyline' || normalizedGeomType === 'line') {
    return Array.isArray(coordinates)
      && coordinates.length >= 2
      && coordinates.every((point) => Array.isArray(point) && point.length >= 2);
  }

  if (normalizedGeomType === 'polygon') {
    return Array.isArray(coordinates)
      && coordinates.length > 0
      && coordinates.every(
        (ring) => Array.isArray(ring)
          && ring.length >= 3
          && ring.every((point) => Array.isArray(point) && point.length >= 2)
      );
  }

  return Array.isArray(coordinates) && coordinates.length > 0;
};

/**
 * Google Maps Loader - Direct Script Injection (No library dependency)
 * 
 * This bypasses @googlemaps/js-api-loader entirely to ensure
 * the API key is ALWAYS present in the script URL.
 */
import { getGoogleMapsApiKey } from './googleMapsRuntime';

let loadPromise: Promise<void> | null = null;
let isLoaded = false;

const GOOGLE_MAPS_CALLBACK = '__googleMapsInitCallback';

/**
 * Ensures Google Maps SDK is loaded with the API key via direct <script> tag injection.
 */
export const initGoogleMaps = (apiKey?: string): boolean => {
    const finalKey = (apiKey || getGoogleMapsApiKey()).trim();

    if (!finalKey || finalKey.length < 20 || finalKey === 'undefined') {
        console.error('[GoogleMapsLoader] ❌ Invalid API Key! Check VITE_GOOGLE_MAPS_API_KEY in .env');
        return false;
    }

    if (isLoaded && (window as any).google?.maps) {
        return true;
    }

    const existingScripts = document.querySelectorAll('script[src*="maps.googleapis.com"]');
    if (existingScripts.length > 0) {
        const hasKey = Array.from(existingScripts).some(s =>
            s.getAttribute('src')?.includes(`key=${finalKey}`)
        );

        if (hasKey && (window as any).google?.maps) {
            isLoaded = true;
            return true;
        }

        if (!hasKey) {
            console.warn('[GoogleMapsLoader] ⚠️ Cleaning up stale Google Maps scripts...');
            existingScripts.forEach(s => s.remove());
            delete (window as any).google;
        }
    }

    const script = document.createElement('script');
    // StreetView is part of maps core. Removing unknown library param to fix console warning.
    script.src = `https://maps.googleapis.com/maps/api/js?key=${finalKey}&language=vi&v=weekly&loading=async&callback=${GOOGLE_MAPS_CALLBACK}`;
    script.async = true;
    script.defer = true;

    (window as any)[GOOGLE_MAPS_CALLBACK] = () => {
        isLoaded = true;
        delete (window as any)[GOOGLE_MAPS_CALLBACK];
    };

    script.onerror = () => {
    };

    document.head.appendChild(script);
    return true;
};

/**
 * Checks if Street View metadata is available for a location
 */
export const checkStreetViewMetadata = async (lat: number, lng: number, apiKey: string): Promise<{ ok: boolean, status: string, panoId?: string }> => {
    const trimmedKey = apiKey.trim();
    if (!trimmedKey || trimmedKey === 'undefined') {
        return { ok: false, status: 'API_KEY_MISSING' };
    }

    try {
        const response = await fetch(`https://maps.googleapis.com/maps/api/streetview/metadata?location=${lat},${lng}&key=${trimmedKey}`);
        const data = await response.json();

        if (data.status === 'OK') {
            return { ok: true, status: 'OK', panoId: data.pano_id };
        } else {
            console.warn(`[StreetView] Metadata check failed: ${data.status}`);
            return { ok: false, status: data.status };
        }
    } catch (err) {
        console.error('[StreetView] Metadata request error:', err);
        return { ok: false, status: 'NETWORK_ERROR' };
    }
};

export const waitForGoogleMaps = (): Promise<void> => {
    if ((window as any).google?.maps) return Promise.resolve();
    if (loadPromise) return loadPromise;

    loadPromise = new Promise((resolve, reject) => {
        const maxWait = 15000;
        const interval = 100;
        let elapsed = 0;

        const check = () => {
            if ((window as any).google?.maps) {
                loadPromise = null;
                resolve();
                return;
            }
            elapsed += interval;
            if (elapsed >= maxWait) {
                loadPromise = null;
                reject(new Error('Google Maps SDK Timeout'));
                return;
            }
            setTimeout(check, interval);
        };
        check();
    });

    return loadPromise;
};

export interface GoogleMapsRuntimeDetails {
    origin: string;
    protocol: string;
    host: string;
    isTauri: boolean;
    isHttpOrigin: boolean;
    recommendedReferrers: string[];
}

const unique = (values: string[]) => Array.from(new Set(values.filter(Boolean)));

export const getGoogleMapsApiKey = (): string => {
    const key = import.meta.env.VITE_GOOGLE_MAPS_API_KEY;
    return typeof key === 'string' ? key.trim() : '';
};

export const getGoogleMapsRuntimeDetails = (): GoogleMapsRuntimeDetails => {
    if (typeof window === 'undefined') {
        return {
            origin: '',
            protocol: '',
            host: '',
            isTauri: false,
            isHttpOrigin: false,
            recommendedReferrers: []
        };
    }

    const { origin, protocol, hostname, host, port, href } = window.location;
    const normalizedOrigin = origin && origin !== 'null' ? origin : href;
    const normalizedProtocol = protocol.replace(/:$/, '');
    const isHttpOrigin = normalizedProtocol === 'http' || normalizedProtocol === 'https';
    const isTauri = Boolean((window as any).__TAURI_INTERNALS__ || (window as any).__TAURI__);

    const recommendedReferrers = unique([
        isHttpOrigin ? `${normalizedOrigin}/*` : '',
        hostname === '127.0.0.1' && port ? `http://localhost:${port}/*` : '',
        hostname === 'localhost' && port ? `http://127.0.0.1:${port}/*` : '',
        isTauri ? 'http://tauri.localhost/*' : '',
        isTauri ? 'https://tauri.localhost/*' : ''
    ]);

    return {
        origin: normalizedOrigin,
        protocol: normalizedProtocol,
        host,
        isTauri,
        isHttpOrigin,
        recommendedReferrers
    };
};

