        { key: 'line_role', label: 'Vai trò', type: 'select', groupId: 'general', order: 20, showInPalette: true, showInAnalysis: true, options: ['backbone', 'access', 'link'] },
        { key: 'cable_type', label: 'Loại cáp', type: 'text', groupId: 'cable', order: 10, showInPalette: true, showInAnalysis: true },
        { key: 'core_count', label: 'Số lõi', type: 'number', groupId: 'cable', order: 20, showInPalette: true, showInAnalysis: true, defaultValue: 0 },
        { key: 'bandwidth', label: 'Băng thông', type: 'text', groupId: 'cable', order: 30, showInPalette: true, showInAnalysis: true },
      ],
    ),
  },
};

const isCameraPreset = (value: unknown): value is CameraPreset => (
  !!value
  && typeof value === 'object'
  && typeof (value as CameraPreset).sensor_size === 'string'
  && typeof (value as CameraPreset).focal_length === 'number'
  && typeof (value as CameraPreset).resolution_x === 'number'
  && typeof (value as CameraPreset).resolution_y === 'number'
);

const normalizeObjectDataTemplates = (value: unknown): ObjectDataTemplateSettings => {
  const source = value && typeof value === 'object' ? value as Partial<ObjectDataTemplateSettings> : {};
  const types = source.types && typeof source.types === 'object' ? source.types as Partial<Record<ObjectDataTemplateTypeId, Partial<ObjectDataTemplateType>>> : {};

  const normalizedTypes = (['intersection', 'camera', 'line'] as ObjectDataTemplateTypeId[]).reduce<Record<ObjectDataTemplateTypeId, ObjectDataTemplateType>>((acc, typeId) => {
    const fallback = DEFAULT_OBJECT_DATA_TEMPLATES.types[typeId];
    const rawType = types[typeId];
    const groups = Array.isArray(rawType?.groups) && rawType?.groups.length > 0
      ? rawType.groups
          .filter((group): group is ObjectDataTemplateGroup => !!group && typeof group === 'object' && typeof group.id === 'string' && typeof group.label === 'string')
          .map((group, index) => ({
            id: normalizeSchemaFieldKey(group.id || group.label) || `${typeId}_group_${index + 1}`,
            label: group.label || fallback.groups[index]?.label || group.id,
            order: typeof group.order === 'number' ? group.order : (index + 1) * 10,
          }))
      : fallback.groups;

    const groupIds = new Set(groups.map((group) => group.id));
    const fields = Array.isArray(rawType?.fields) && rawType?.fields.length > 0
      ? rawType.fields
          .filter((field): field is ObjectDataTemplateField => !!field && typeof field === 'object' && typeof field.key === 'string')
          .map((field, index) => ({
            key: normalizeSchemaFieldKey(field.key),
            label: field.label || field.key,
            type: (['text', 'number', 'boolean', 'select'].includes(field.type) ? field.type : 'text') as ObjectDataFieldType,
            groupId: groupIds.has(field.groupId) ? field.groupId : groups[0]?.id || 'general',
            order: typeof field.order === 'number' ? field.order : (index + 1) * 10,
            showInPalette: field.showInPalette !== false,
            showInAnalysis: field.showInAnalysis !== false,
            options: Array.isArray(field.options) ? field.options.filter((option): option is string => typeof option === 'string') : undefined,
            defaultValue: field.defaultValue,
          }))
      : fallback.fields;

    acc[typeId] = {
      id: typeId,
      label: typeof rawType?.label === 'string' ? rawType.label : fallback.label,
      appliesTo: Array.isArray(rawType?.appliesTo) && rawType?.appliesTo.length > 0
        ? rawType.appliesTo.filter((item): item is string => typeof item === 'string')
        : fallback.appliesTo,
      groups: groups.sort((left, right) => left.order - right.order),
      fields: fields.sort((left, right) => left.order - right.order),
    };
    return acc;
  }, {} as Record<ObjectDataTemplateTypeId, ObjectDataTemplateType>);

  return {
    version: 1,
    types: normalizedTypes,
  };
};

export const normalizeProjectSettings = (value: unknown): ProjectSettingsSchema => {
  const source = value && typeof value === 'object' ? value as Record<string, unknown> : {};
  const cameraPresets = source.camera_presets && typeof source.camera_presets === 'object'
    ? Object.entries(source.camera_presets as Record<string, unknown>).reduce<Record<string, CameraPreset>>((acc, [key, preset]) => {
      if (isCameraPreset(preset)) {
        acc[key] = preset;
      }
      return acc;
    }, {})
    : {};

  return {
    default_install_height: typeof source.default_install_height === 'number' ? source.default_install_height : 5,
    camera_presets: {
      ...DEFAULT_CAMERA_PRESETS,
      ...cameraPresets,
    },
    object_data_templates: normalizeObjectDataTemplates(source.object_data_templates),
  };
};

export const getTemplateTypeIdForFeature = (
  feature: FeatureState | null | undefined,
  options?: {
    isCamera?: boolean;
    isIntersection?: boolean;
  },
): ObjectDataTemplateTypeId | null => {
  if (!feature) return null;
  if (options?.isIntersection) return 'intersection';

  const geomType = String(feature.geom_type || '').toLowerCase();
  if (geomType.includes('line')) return 'line';
  if (options?.isCamera) return 'camera';
  return null;
};

export const getTemplateFieldValue = (
  feature: FeatureState | null | undefined,
  key: string,
) => {
  if (!feature) return undefined;

  const metadata = typeof feature.metadata === 'string'
    ? (() => {
      try {
        return JSON.parse(feature.metadata || '{}') as Record<string, unknown>;
      } catch {
        return {};
      }
    })()
    : (feature.metadata as Record<string, unknown> | undefined) || {};

  if (Object.prototype.hasOwnProperty.call(metadata, key)) {
    return metadata[key];
  }

  const props = feature.properties as Record<string, unknown> | undefined;
  if (props && Object.prototype.hasOwnProperty.call(props, key)) {
    return props[key];
  }

  return undefined;
};

export const getAnalysisTemplateColumnKeys = (settings: ProjectSettingsSchema): string[] => {
  const keys = new Set<string>();
  (Object.values(settings.object_data_templates.types) as ObjectDataTemplateType[]).forEach((type) => {
    type.fields.forEach((field) => {
      if (field.showInAnalysis) {
        keys.add(field.key);
      }
    });
  });
  return Array.from(keys).sort((left, right) => left.localeCompare(right));
};

export const getAnalysisTemplateGroups = (settings: ProjectSettingsSchema) => (
  Object.values(settings.object_data_templates.types)
    .sort((left, right) => left.label.localeCompare(right.label))
    .map((type) => ({
      id: type.id,
      label: type.label,
      groups: type.groups,
      fields: type.fields.filter((field) => field.showInAnalysis),
    }))
    .filter((item) => item.fields.length > 0)
);

/**
 * Polyline Diagnostic Tool - Run in browser console
 * 
 * This tool will help identify exactly where polylines are failing to display.
 * It checks coordinates, metadata, visibility, and rendering state.
 */

export const runPolylineDiagnostic = () => {
  console.log('🔍 === POLYLINE DIAGNOSTIC START ===\n');

  // Get store state
  const store = (window as any).__DESIGN_SYNC_STORE__;
  if (!store) {
    console.error('❌ Cannot access useDesignSync store');
    return null;
  }

  const state = store.getState()?.state;
  if (!state) {
    console.error('❌ No state loaded');
    return null;
  }

  console.log('📊 Total features:', Object.keys(state.features).length);

  // Find all polyline features
  const polylineFeatures = Object.values(state.features).filter((f: any) => {
    const geomType = (f.geom_type || '').toLowerCase();
    return geomType === 'linestring' || geomType === 'polyline' || geomType === 'line';
  });

  console.log('📏 Polyline features found:', polylineFeatures.length, '\n');

  if (polylineFeatures.length === 0) {
    console.warn('⚠️ No polyline features found!');
    console.log('Available geom_types:', [...new Set(Object.values(state.features).map((f: any) => f.geom_type))]);
    return null;
  }

  // Analyze each polyline
  polylineFeatures.forEach((f: any, idx: number) => {
    console.group(`📐 Polyline #${idx + 1}: ${f.name || f.id}`);

    // 1. Basic info
    console.log('ID:', f.id);
    console.log('Name:', f.name);
    console.log('geom_type:', f.geom_type);
    console.log('group_id:', f.group_id);
    console.log('layer_id:', f.layer_id);

    // 2. Parse coordinates
    let coords: any = f.coordinates;
    try {
      if (typeof coords === 'string') {
        coords = JSON.parse(coords);
      }
    } catch (e) {
      console.error('❌ Failed to parse coordinates:', e);
    }

    console.log('\n📍 Coordinates:');
    console.log('  Type:', typeof coords);
    console.log('  Is array:', Array.isArray(coords));
    console.log('  Length:', Array.isArray(coords) ? coords.length : 'N/A');

    if (Array.isArray(coords) && coords.length > 0) {
      if (Array.isArray(coords[0])) {
        console.log('  Format: Multi-point [[lng, lat], ...]');
        console.log('  First 3 points:', coords.slice(0, 3));
      } else if (coords.length > 2 && typeof coords[0] === 'number') {
        console.log('  Format: Flat array [lng, lat, lng, lat, ...]');
        console.log('  First 6 values:', coords.slice(0, 6));
        console.log('  Would create', Math.floor(coords.length / 2), 'points');
      } else {
        console.log('  Format: Single point [lng, lat]');
        console.log('  Value:', coords);
      }

      // Validate coordinate ranges
      const firstPoint = Array.isArray(coords[0]) ? coords[0] : coords;
      if (firstPoint.length >= 2) {
        const [lng, lat] = firstPoint;
        if (lng < -180 || lng > 180) console.warn('  ⚠️ Invalid longitude:', lng);
        if (lat < -90 || lat > 90) console.warn('  ⚠️ Invalid latitude:', lat);
        console.log('  First point:', { lng, lat });
      }
    } else {
      console.error('  ❌ Coordinates are invalid or empty');
      console.log('  Raw value:', f.coordinates);
    }

    // 3. Parse metadata
    let metadata: any = {};
    try {
      metadata = typeof f.metadata === 'string' ? JSON.parse(f.metadata || '{}') : (f.metadata || {});
    } catch (e) {
      console.error('❌ Failed to parse metadata:', e);
    }

    console.log('\n📝 Metadata:');
    console.log('  size/stroke:', metadata.size);
    console.log('  weight:', metadata.weight);
    console.log('  color:', metadata.color);
    console.log('  Full metadata:', metadata);

    // 4. Check group and layer visibility
    const group = f.group_id ? state.feature_groups?.[f.group_id] : null;
    const layer = group ? state.layers?.[group.layer_id] : null;

    console.log('\n👁️ Visibility:');
    console.log('  Group:', group?.name || 'None');
    console.log('  Layer:', layer?.name || 'None');
    console.log('  Group is_visible:', group?.is_visible);
    console.log('  Layer is_visible:', layer?.is_visible);
    console.log('  Metadata is_visible:', metadata.is_visible);

    // 5. Check if hidden
    const mapHiddenIds = store.getState()?.mapHiddenIds || new Set();
    const isHidden = mapHiddenIds.has(f.id) ||
      (f.group_id && mapHiddenIds.has(f.group_id)) ||
      (layer && mapHiddenIds.has(layer.id));
    console.log('  Hidden by mapHiddenIds:', isHidden);

    // 6. Expected rendering
    const expectedWeight = Number(metadata.weight || metadata.size) || 5;
    console.log('\n🎨 Expected rendering:');
    console.log('  Weight:', expectedWeight, 'px');
    console.log('  Color:', metadata.color || '#3B82F6');
    console.log('  Should be visible:', expectedWeight > 0 && !isHidden);

    console.groupEnd();
    console.log('');
  });

  // Summary
  console.log('📊 === SUMMARY ===');
  console.log('Total polyline features:', polylineFeatures.length);

  const validCoords = polylineFeatures.filter((f: any) => {
    let coords = f.coordinates;
    try { coords = typeof coords === 'string' ? JSON.parse(coords) : coords; } catch { return false; }
    return Array.isArray(coords) && coords.length > 0;
  }).length;
  console.log('✅ Features with valid coords:', validCoords);

  const withSize = polylineFeatures.filter((f: any) => {
    let meta: any = {};
    try { meta = typeof f.metadata === 'string' ? JSON.parse(f.metadata) : f.metadata; } catch { return false; }
    return meta.size !== undefined && meta.size > 0;
  }).length;
  console.log('✅ Features with size metadata:', withSize);

  const hiddenCount = polylineFeatures.filter((f: any) => {
    const mapHiddenIds = store.getState()?.mapHiddenIds || new Set();
    return mapHiddenIds.has(f.id) || (f.group_id && mapHiddenIds.has(f.group_id));
  }).length;
  console.log('⚠️ Hidden features:', hiddenCount);
  console.log('✅ Visible features:', polylineFeatures.length - hiddenCount);

  console.log('\n🔍 === DIAGNOSTIC END ===');
  console.log('\n💡 Common issues:');
  if (validCoords === 0) console.log('  ❌ No valid coordinates - check coordinate parsing');
  if (withSize === 0) console.log('  ❌ No size metadata - metadata not being saved');
  if (hiddenCount > 0) console.log('  ⚠️ Some features hidden - check visibility settings');
  if (validCoords > 0 && withSize > 0 && hiddenCount === 0) {
    console.log('  ✅ All looks good - issue might be in rendering layer');
  }

  return polylineFeatures;
};

// Make it globally accessible
if (typeof window !== 'undefined') {
  (window as any).runPolylineDiagnostic = runPolylineDiagnostic;
  console.log('✅ Polyline diagnostic tool loaded. Run: window.runPolylineDiagnostic()');
}

import { FeatureState } from "@CONTRACT/types";
import { getFeatureDisplayInfo, getFeatureNote, safeString } from "@TOOL/utils/featureUtils";

export type FeatureBounds = [number, number, number, number]; // [minLng, minLat, maxLng, maxLat]

export type NormalizedSelectionItem = {
  id: string;
  name: string;
  geomType: string;
  displayType: string;
  lng: number;
  lat: number;
  note: string;
  groupId: string;
};

// Cache để tránh parse JSON lặp lại cho cùng một feature version
const coordCache = new Map<string, any>();

export function parseCoordinates(feature: FeatureState): any | null {
  if (!feature) return null;

  // Nếu coordinates đã là object/array thì dùng luôn
  if (typeof feature.coordinates !== 'string') return feature.coordinates;

  const cacheKey = `${feature.id}_${(feature.coordinates as string).length}`;
  const cached = coordCache.get(cacheKey);
  if (cached !== undefined) return cached;

  try {
    const parsed = JSON.parse(feature.coordinates);
    coordCache.set(cacheKey, parsed);
    // Giới hạn size cache
    if (coordCache.size > 10000) {
      const keys = Array.from(coordCache.keys());
      for (let i = 0; i < 100; i++) coordCache.delete(keys[i]);
    }
    return parsed;
  } catch {
    return null;
  }
}

export function getFeatureBounds(feature: FeatureState): FeatureBounds | null {
  const geomType = (feature.geom_type || "").toLowerCase();
  const coords = parseCoordinates(feature);
  if (!coords) return null;

  if (geomType === "point" || geomType === "") {
    if (Array.isArray(coords) && coords.length >= 2) {
      const lng = Number(coords[0]) || 0;
      const lat = Number(coords[1]) || 0;
      return [lng, lat, lng, lat];
    }
    return null;
  }

  if (geomType === "linestring" || geomType === "polyline") {
    if (!Array.isArray(coords)) return null;
    let minLng = Number.POSITIVE_INFINITY;
    let minLat = Number.POSITIVE_INFINITY;
    let maxLng = Number.NEGATIVE_INFINITY;
    let maxLat = Number.NEGATIVE_INFINITY;
    let count = 0;

    for (const p of coords) {
      if (Array.isArray(p) && p.length >= 2) {
        const lng = Number(p[0]) || 0;
        const lat = Number(p[1]) || 0;
        minLng = Math.min(minLng, lng);
        maxLng = Math.max(maxLng, lng);
        minLat = Math.min(minLat, lat);
        maxLat = Math.max(maxLat, lat);
        count += 1;
      }
    }

    if (count === 0) return null;
    return [minLng, minLat, maxLng, maxLat];
  }

  if (geomType === "polygon") {
    if (!Array.isArray(coords)) return null;
    let minLng = Number.POSITIVE_INFINITY;
    let minLat = Number.POSITIVE_INFINITY;
    let maxLng = Number.NEGATIVE_INFINITY;
    let maxLat = Number.NEGATIVE_INFINITY;
    let count = 0;

    for (const ring of coords) {
      if (!Array.isArray(ring)) continue;
      for (const p of ring) {
        if (Array.isArray(p) && p.length >= 2) {
          const lng = Number(p[0]) || 0;
          const lat = Number(p[1]) || 0;
          minLng = Math.min(minLng, lng);
          maxLng = Math.max(maxLng, lng);
          minLat = Math.min(minLat, lat);
          maxLat = Math.max(maxLat, lat);
          count += 1;
        }
      }
    }

    if (count === 0) return null;
    return [minLng, minLat, maxLng, maxLat];
  }

  if (geomType === "rect") {
    if (coords && typeof coords === "object") {
      const x = Number(coords.x) || 0;
      const y = Number(coords.y) || 0;
      const width = Number(coords.width) || 0;
      const height = Number(coords.height) || 0;
      return [x, y, x + width, y + height];
    }
  }

  return null;
}

export function intersectsBounds(a: FeatureBounds, b: FeatureBounds): boolean {
  return !(a[2] < b[0] || a[0] > b[2] || a[3] < b[1] || a[1] > b[3]);
}

export function normalizeFeatureForSummary(
  feature: FeatureState,
  groupType?: string,
  groupName?: string
): NormalizedSelectionItem {
  const coords = parseCoordinates(feature);
  const geomType = (feature.geom_type || "POINT").toUpperCase();
  let lng = 0;
  let lat = 0;

  if (geomType === "POINT") {
    if (Array.isArray(coords) && coords.length >= 2) {
      lng = Number(coords[0]) || 0;
      lat = Number(coords[1]) || 0;
    }
  } else if (geomType === "POLYGON") {
    const first = Array.isArray(coords) ? coords[0]?.[0] : null;
    if (Array.isArray(first) && first.length >= 2) {
      lng = Number(first[0]) || 0;
      lat = Number(first[1]) || 0;
    }
  } else {
    const first = Array.isArray(coords) ? coords[0] : null;
    if (Array.isArray(first) && first.length >= 2) {
      lng = Number(first[0]) || 0;
      lat = Number(first[1]) || 0;
    }
  }

  const typeInfo = getFeatureDisplayInfo(feature, groupType, groupName);
  const note = getFeatureNote(feature);

  return {
    id: feature.id,
    name: safeString(feature.name || feature.id),
    geomType,
    displayType: typeInfo.label,
    lng,
    lat,
    note,
    groupId: feature.group_id || ""
  };
}
